-- 2. Verificar parcelas (gastos com descrição contendo "Parcela" e "empréstimo") SELECT ef.id, ef.data_evento, ef.descricao, ef.valor, ef.tipo, ed.titulo_gasto FROM evento_financeiro ef LEFT JOIN evento_detalhe ed ON ed.fk_evento = ef.id WHERE ef.tipo = 'Gasto' AND ef.descricao LIKE '%Parcela%empréstimo%' ORDER BY ef.data_evento;
