package controle.api.back_end.strategy.eventoFinanceiro;
import controle.api.back_end.model.categoria.Categoria;
import controle.api.back_end.model.categoria.CategoriaUsuario;
import controle.api.back_end.model.eventoFinanceiro.EventoDetalhe;
import controle.api.back_end.model.eventoFinanceiro.EventoFinanceiro;
import controle.api.back_end.model.eventoFinanceiro.EventoInstituicao;
import controle.api.back_end.model.eventoFinanceiro.Tipo;
import controle.api.back_end.repository.categoria.CategoriaRepository;
import controle.api.back_end.repository.categoria.CategoriaUsuarioRepository;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
@Component
public class EmprestimoEvento implements EventoFinanceiroStrategy {
    private final CategoriaRepository categoriaRepository;
    private final CategoriaUsuarioRepository categoriaUsuarioRepository;
    public EmprestimoEvento(CategoriaRepository categoriaRepository,
                           CategoriaUsuarioRepository categoriaUsuarioRepository) {
        this.categoriaRepository = categoriaRepository;
        this.categoriaUsuarioRepository = categoriaUsuarioRepository;
    }
    @Override
    public Registro processar(EventoFinanceiro evento,
                              List&lt;EventoInstituicao&gt; eventoInstituicoes,
                              EventoDetalhe eventoDetalhe) {
        List&lt;EventoFinanceiro&gt; eventos = new ArrayList&lt;&gt;();
        Map&lt;EventoFinanceiro, List&lt;EventoInstituicao&gt;&gt; instituicoesPorEvento = new HashMap&lt;&gt;();
        Map&lt;EventoFinanceiro, EventoDetalhe&gt; detalhePorEvento = new HashMap&lt;&gt;();
        // Crédito principal
        EventoFinanceiro credito = new EventoFinanceiro();
        credito.setUsuario(evento.getUsuario());
        credito.setTipo(Tipo.Recebimento);
        credito.setValor(evento.getValor());
        credito.setDescricao("Crédito de empréstimo recebido");
        credito.setDataEvento(evento.getDataEvento());
        credito.setDataRegistro(LocalDateTime.now());
        eventos.add(credito);
        List&lt;EventoInstituicao&gt; instsCredito = new ArrayList&lt;&gt;();
        if (!eventoInstituicoes.isEmpty()) {
            EventoInstituicao instCredito = new EventoInstituicao();
            instCredito.setEventoFinanceiro(credito);
            instCredito.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
            instCredito.setTipoMovimento(eventoInstituicoes.getFirst().getTipoMovimento());
            instCredito.setValor(evento.getValor());
            instCredito.setParcelas(1);
            instsCredito.add(instCredito);
            instituicoesPorEvento.put(credito, instsCredito);
        }
        // Detalhe único vinculado ao crédito
        if (eventoDetalhe != null) {
            detalhePorEvento.put(credito, eventoDetalhe);
        }
        // Parcelas de débito — calcula valor total a pagar levando em conta a taxa
        if (!eventoInstituicoes.isEmpty()) {
            int parcelas = eventoInstituicoes.getFirst().getParcelas();
            // taxaRendimento = taxa de juros total em % (ex: 33.33 significa pagar 33,33% a mais)
            double taxaPercentual = evento.getTaxaRendimento() != null ? evento.getTaxaRendimento() : 0.0;
            double valorTotal = evento.getValor() * (1.0 + taxaPercentual / 100.0);
            BigDecimal valorParcela = BigDecimal.valueOf(valorTotal)
                    .divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_UP);
            // Busca ou cria a categoria "Parcela Empréstimo" para o usuário
            CategoriaUsuario categoriaParcelaEmprestimo = obterOuCriarCategoriaParcelaEmprestimo(evento);
            for (int i = 1; i &lt;= parcelas; i++) {
                EventoFinanceiro debito = new EventoFinanceiro();
                debito.setUsuario(evento.getUsuario());
                debito.setTipo(Tipo.Gasto);
                debito.setValor(valorParcela.doubleValue());
                debito.setDescricao("Parcela " + i + "/" + parcelas + " do empréstimo");
                debito.setDataEvento(evento.getDataEvento().plusMonths(i));
                debito.setDataRegistro(LocalDateTime.now());
                eventos.add(debito);
                List&lt;EventoInstituicao&gt; instsDebito = new ArrayList&lt;&gt;();
                EventoInstituicao instDebito = new EventoInstituicao();
                instDebito.setEventoFinanceiro(debito);
                instDebito.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
                instDebito.setTipoMovimento(eventoInstituicoes.getFirst().getTipoMovimento());
                instDebito.setValor(valorParcela.doubleValue());
                instDebito.setParcelas(i);
                instsDebito.add(instDebito);
                instituicoesPorEvento.put(debito, instsDebito);
                // Cria um EventoDetalhe específico para cada parcela com a categoria "Parcela Empréstimo"
                EventoDetalhe detalheParcela = new EventoDetalhe();
                detalheParcela.setEventoFinanceiro(debito);
                detalheParcela.setTituloGasto("Parcela " + i + "/" + parcelas + " do empréstimo");
                detalheParcela.setCategoriaUsuario(List.of(categoriaParcelaEmprestimo));
                detalhePorEvento.put(debito, detalheParcela);
            }
        }
        return new Registro(eventos, instituicoesPorEvento, detalhePorEvento);
    }
    /**
     * Busca ou cria a CategoriaUsuario "Parcela Empréstimo" para o usuário.
     * Se a categoria não existir no sistema, será criada.
     * Se o usuário não tiver essa categoria associada, será criada a associação.
     */
    private CategoriaUsuario obterOuCriarCategoriaParcelaEmprestimo(EventoFinanceiro evento) {
        String tituloCat = "Parcela Empréstimo";
        // Busca a categoria "Parcela Empréstimo" no sistema
        Categoria categoria = categoriaRepository.findAll().stream()
                .filter(c -&gt; tituloCat.equals(c.getTitulo()))
                .findFirst()
                .orElseGet(() -&gt; {
                    // Se não existe, cria a categoria
                    Categoria novaCat = new Categoria();
                    novaCat.setTitulo(tituloCat);
                    return categoriaRepository.save(novaCat);
                });
        // Busca se o usuário já tem essa categoria associada
        return categoriaUsuarioRepository
                .findByUsuario_IdAndCategoria_Titulo(evento.getUsuario().getId(), tituloCat)
                .orElseGet(() -&gt; {
                    // Se não tem, cria a associação
                    CategoriaUsuario categoriaUsuario = new CategoriaUsuario();
                    categoriaUsuario.setUsuario(evento.getUsuario());
                    categoriaUsuario.setCategoria(categoria);
                    categoriaUsuario.setAtivo(true);
                    categoriaUsuario.setUltimaAtualizacao(LocalDateTime.now());
                    return categoriaUsuarioRepository.save(categoriaUsuario);
                });
    }
}

package controle.api.back_end.strategy.eventoFinanceiro;

import controle.api.back_end.model.categoria.Categoria;
import controle.api.back_end.model.categoria.CategoriaUsuario;
import controle.api.back_end.model.eventoFinanceiro.EventoDetalhe;
import controle.api.back_end.model.eventoFinanceiro.EventoFinanceiro;
import controle.api.back_end.model.eventoFinanceiro.EventoInstituicao;
import controle.api.back_end.model.eventoFinanceiro.Tipo;
import controle.api.back_end.repository.categoria.CategoriaRepository;
import controle.api.back_end.repository.categoria.CategoriaUsuarioRepository;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Component
public class EmprestimoEvento implements EventoFinanceiroStrategy {

    private final CategoriaRepository categoriaRepository;
    private final CategoriaUsuarioRepository categoriaUsuarioRepository;

    public EmprestimoEvento(CategoriaRepository categoriaRepository,
                           CategoriaUsuarioRepository categoriaUsuarioRepository) {
        this.categoriaRepository = categoriaRepository;
        this.categoriaUsuarioRepository = categoriaUsuarioRepository;
    }

    @Override
    public Registro processar(EventoFinanceiro evento,
                              List<EventoInstituicao> eventoInstituicoes,
                              EventoDetalhe eventoDetalhe) {

        List<EventoFinanceiro> eventos = new ArrayList<>();
        Map<EventoFinanceiro, List<EventoInstituicao>> instituicoesPorEvento = new HashMap<>();
        Map<EventoFinanceiro, EventoDetalhe> detalhePorEvento = new HashMap<>();

        // Crédito principal
        EventoFinanceiro credito = new EventoFinanceiro();
        credito.setUsuario(evento.getUsuario());
        credito.setTipo(Tipo.Recebimento);
        credito.setValor(evento.getValor());
        credito.setDescricao("Crédito de empréstimo recebido");
        credito.setDataEvento(evento.getDataEvento());
        credito.setDataRegistro(LocalDateTime.now());
        eventos.add(credito);

        List<EventoInstituicao> instsCredito = new ArrayList<>();
        if (!eventoInstituicoes.isEmpty()) {
            EventoInstituicao instCredito = new EventoInstituicao();
            instCredito.setEventoFinanceiro(credito);
            instCredito.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
            instCredito.setTipoMovimento(eventoInstituicoes.getFirst().getTipoMovimento());
            instCredito.setValor(evento.getValor());
            instCredito.setParcelas(1);
            instsCredito.add(instCredito);

            instituicoesPorEvento.put(credito, instsCredito);
        }

        // Detalhe único vinculado ao crédito
        if (eventoDetalhe != null) {
            detalhePorEvento.put(credito, eventoDetalhe);
        }

        // Parcelas de débito — calcula valor total a pagar levando em conta a taxa
        if (!eventoInstituicoes.isEmpty()) {
            int parcelas = eventoInstituicoes.getFirst().getParcelas();
            // taxaRendimento = taxa de juros total em % (ex: 33.33 significa pagar 33,33% a mais)
            double taxaPercentual = evento.getTaxaRendimento() != null ? evento.getTaxaRendimento() : 0.0;
            double valorTotal = evento.getValor() * (1.0 + taxaPercentual / 100.0);
            BigDecimal valorParcela = BigDecimal.valueOf(valorTotal)
                    .divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_UP);

            // Busca ou cria a categoria "Parcela Empréstimo" para o usuário
            CategoriaUsuario categoriaParcelaEmprestimo = obterOuCriarCategoriaParcelaEmprestimo(evento);

            for (int i = 1; i <= parcelas; i++) {
                EventoFinanceiro debito = new EventoFinanceiro();
                debito.setUsuario(evento.getUsuario());
                debito.setTipo(Tipo.Gasto);
                debito.setValor(valorParcela.doubleValue());
                debito.setDescricao("Parcela " + i + "/" + parcelas + " do empréstimo");
                // Primeira parcela no mesmo mês, demais nos meses seguintes
                debito.setDataEvento(evento.getDataEvento().plusMonths(i - 1));
                debito.setDataRegistro(LocalDateTime.now());
                eventos.add(debito);

                List<EventoInstituicao> instsDebito = new ArrayList<>();
                EventoInstituicao instDebito = new EventoInstituicao();
                instDebito.setEventoFinanceiro(debito);
                instDebito.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
                instDebito.setTipoMovimento(eventoInstituicoes.getFirst().getTipoMovimento());
                instDebito.setValor(valorParcela.doubleValue());
                instDebito.setParcelas(i);
                instsDebito.add(instDebito);

                instituicoesPorEvento.put(debito, instsDebito);

                // Cria um EventoDetalhe específico para cada parcela com a categoria "Parcela Empréstimo"
                EventoDetalhe detalheParcela = new EventoDetalhe();
                detalheParcela.setEventoFinanceiro(debito);
                detalheParcela.setTituloGasto("Parcela " + i + "/" + parcelas + " do empréstimo");
                detalheParcela.setCategoriaUsuario(List.of(categoriaParcelaEmprestimo));
                detalhePorEvento.put(debito, detalheParcela);
            }
        }
        return new Registro(eventos, instituicoesPorEvento, detalhePorEvento);
    }

    /**
     * Busca ou cria a CategoriaUsuario "Parcela Empréstimo" para o usuário.
     * Se a categoria não existir no sistema, será criada.
     * Se o usuário não tiver essa categoria associada, será criada a associação.
     */
    private CategoriaUsuario obterOuCriarCategoriaParcelaEmprestimo(EventoFinanceiro evento) {
        String tituloCat = "Parcela Empréstimo";

        // Busca a categoria "Parcela Empréstimo" no sistema
        Categoria categoria = categoriaRepository.findAll().stream()
                .filter(c -> tituloCat.equals(c.getTitulo()))
                .findFirst()
                .orElseGet(() -> {
                    // Se não existe, cria a categoria
                    Categoria novaCat = new Categoria();
                    novaCat.setTitulo(tituloCat);
                    return categoriaRepository.save(novaCat);
                });

        // Busca se o usuário já tem essa categoria associada
        return categoriaUsuarioRepository
                .findByUsuario_IdAndCategoria_Titulo(evento.getUsuario().getId(), tituloCat)
                .orElseGet(() -> {
                    // Se não tem, cria a associação
                    CategoriaUsuario categoriaUsuario = new CategoriaUsuario();
                    categoriaUsuario.setUsuario(evento.getUsuario());
                    categoriaUsuario.setCategoria(categoria);
                    categoriaUsuario.setAtivo(true);
                    categoriaUsuario.setUltimaAtualizacao(LocalDateTime.now());
                    return categoriaUsuarioRepository.save(categoriaUsuario);
                });
    }
}

package controle.api.back_end.strategy.eventoFinanceiro;

import controle.api.back_end.model.eventoFinanceiro.EventoDetalhe;
import controle.api.back_end.model.eventoFinanceiro.EventoFinanceiro;
import controle.api.back_end.model.eventoFinanceiro.EventoInstituicao;
import controle.api.back_end.model.eventoFinanceiro.Tipo;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Component
public class PoupancaEvento implements EventoFinanceiroStrategy {

    @Override
    public Registro processar(EventoFinanceiro evento,
                              List<EventoInstituicao> eventoInstituicoes,
                              EventoDetalhe eventoDetalhe) {

        List<EventoFinanceiro> eventos = new ArrayList<>();
        Map<EventoFinanceiro, List<EventoInstituicao>> instituicoesPorEvento = new HashMap<>();
        Map<EventoFinanceiro, EventoDetalhe> detalhePorEvento = new HashMap<>();

        // 1. Evento inicial (aplicação)
        EventoFinanceiro aplicacao = new EventoFinanceiro();
        aplicacao.setUsuario(evento.getUsuario());
        aplicacao.setTipo(Tipo.Poupanca);
        aplicacao.setValor(evento.getValor());
        aplicacao.setDescricao("Aplicação em poupança");
        aplicacao.setDataEvento(evento.getDataEvento());
        aplicacao.setDataRegistro(LocalDateTime.now());
        eventos.add(aplicacao);

        // Instituições vinculadas à aplicação
        List<EventoInstituicao> instsAplicacao = new ArrayList<>();
        if (!eventoInstituicoes.isEmpty()) {
            EventoInstituicao instAplicacao = eventoInstituicoes.getFirst();
            instAplicacao.setEventoFinanceiro(aplicacao);
            instAplicacao.setValor(evento.getValor());
            instAplicacao.setParcelas(1);
            instsAplicacao.add(instAplicacao);
        }
        instituicoesPorEvento.put(aplicacao, instsAplicacao);

        // Detalhe único vinculado à aplicação
        if (eventoDetalhe != null) {
            eventoDetalhe.setEventoFinanceiro(aplicacao);
            detalhePorEvento.put(aplicacao, eventoDetalhe);
        }

        // 2. Projeção de rendimento
        double principal = evento.getValor();
        double taxa = evento.getTaxaRendimento(); // informado pelo usuário
        int tempoProjecao = evento.getTempoProjecao();   // em meses

        for (int mes = 1; mes <= tempoProjecao; mes++) {
            double montante = principal * Math.pow(1 + taxa, mes);
            double rendimento = montante - principal;

            EventoFinanceiro rendimentoEvento = new EventoFinanceiro();
            rendimentoEvento.setUsuario(evento.getUsuario());
            rendimentoEvento.setTipo(Tipo.Recebimento);
            rendimentoEvento.setValor(rendimento);
            rendimentoEvento.setDescricao("Rendimento projetado mês " + mes);
            rendimentoEvento.setDataEvento(evento.getDataEvento().plusMonths(mes));
            rendimentoEvento.setDataRegistro(LocalDateTime.now());
            eventos.add(rendimentoEvento);

            // Instituições vinculadas ao rendimento
            List<EventoInstituicao> instsRendimento = new ArrayList<>();
            if (!eventoInstituicoes.isEmpty()) {
                EventoInstituicao instRendimento = new EventoInstituicao();
                instRendimento.setEventoFinanceiro(rendimentoEvento);
                instRendimento.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
                instRendimento.setValor(rendimento);
                instRendimento.setParcelas(1);
                instsRendimento.add(instRendimento);
            }
            instituicoesPorEvento.put(rendimentoEvento, instsRendimento);

            // Detalhe único vinculado ao rendimento (se necessário)
            if (eventoDetalhe != null) {
                detalhePorEvento.put(rendimentoEvento, eventoDetalhe);
            }
        }

        // 3. Retornar registro completo
        return new Registro(eventos, instituicoesPorEvento, detalhePorEvento);
    }
}

package controle.api.back_end.strategy.eventoFinanceiro;

import controle.api.back_end.model.eventoFinanceiro.EventoDetalhe;
import controle.api.back_end.model.eventoFinanceiro.EventoFinanceiro;
import controle.api.back_end.model.eventoFinanceiro.EventoInstituicao;
import controle.api.back_end.model.eventoFinanceiro.Tipo;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Component
public class PoupancaEvento implements EventoFinanceiroStrategy {

    @Override
    public Registro processar(EventoFinanceiro evento,
                              List<EventoInstituicao> eventoInstituicoes,
                              EventoDetalhe eventoDetalhe) {

        List<EventoFinanceiro> eventos = new ArrayList<>();
        Map<EventoFinanceiro, List<EventoInstituicao>> instituicoesPorEvento = new HashMap<>();
        Map<EventoFinanceiro, EventoDetalhe> detalhePorEvento = new HashMap<>();

        // 1. Evento inicial (aplicação)
        EventoFinanceiro aplicacao = new EventoFinanceiro();
        aplicacao.setUsuario(evento.getUsuario());
        aplicacao.setTipo(Tipo.Poupanca);
        aplicacao.setValor(evento.getValor());
        aplicacao.setDescricao("Aplicação em poupança");
        aplicacao.setDataEvento(evento.getDataEvento());
        aplicacao.setDataRegistro(LocalDateTime.now());
        // Vincular à caixinha, se informada
        if (evento.getCaixinha() != null) {
            aplicacao.setCaixinha(evento.getCaixinha());
        }
        eventos.add(aplicacao);

        // Instituições vinculadas à aplicação
        List<EventoInstituicao> instsAplicacao = new ArrayList<>();
        if (!eventoInstituicoes.isEmpty()) {
            EventoInstituicao instAplicacao = eventoInstituicoes.getFirst();
            instAplicacao.setEventoFinanceiro(aplicacao);
            instAplicacao.setValor(evento.getValor());
            instAplicacao.setParcelas(1);
            instsAplicacao.add(instAplicacao);
        }
        instituicoesPorEvento.put(aplicacao, instsAplicacao);

        // Detalhe único vinculado à aplicação
        if (eventoDetalhe != null) {
            eventoDetalhe.setEventoFinanceiro(aplicacao);
            detalhePorEvento.put(aplicacao, eventoDetalhe);
        }

        // 2. Projeção de rendimento (opcional — só executa se taxa e prazo foram informados)
        Double taxaRaw    = evento.getTaxaRendimento();
        Integer tempoRaw  = evento.getTempoProjecao();
        double taxa       = (taxaRaw != null) ? taxaRaw : 0.0;
        int tempoProjecao = (tempoRaw != null) ? tempoRaw : 0;

        if (taxa > 0 && tempoProjecao > 0) {
            double principal = evento.getValor();
            for (int mes = 1; mes <= tempoProjecao; mes++) {
                double montante  = principal * Math.pow(1 + taxa, mes);
                double rendimento = montante - principal;

                EventoFinanceiro rendimentoEvento = new EventoFinanceiro();
                rendimentoEvento.setUsuario(evento.getUsuario());
                rendimentoEvento.setTipo(Tipo.Recebimento);
                rendimentoEvento.setValor(rendimento);
                rendimentoEvento.setDescricao("Rendimento projetado mês " + mes);
                rendimentoEvento.setDataEvento(evento.getDataEvento().plusMonths(mes));
                rendimentoEvento.setDataRegistro(LocalDateTime.now());
                eventos.add(rendimentoEvento);

                // Instituições vinculadas ao rendimento
                List<EventoInstituicao> instsRendimento = new ArrayList<>();
                if (!eventoInstituicoes.isEmpty()) {
                    EventoInstituicao instRendimento = new EventoInstituicao();
                    instRendimento.setEventoFinanceiro(rendimentoEvento);
                    instRendimento.setInstituicaoUsuario(eventoInstituicoes.getFirst().getInstituicaoUsuario());
                    instRendimento.setValor(rendimento);
                    instRendimento.setParcelas(1);
                    instsRendimento.add(instRendimento);
                }
                instituicoesPorEvento.put(rendimentoEvento, instsRendimento);
            }
        }

        // 3. Retornar registro completo
        return new Registro(eventos, instituicoesPorEvento, detalhePorEvento);
    }
}

package controle.api.back_end.update;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Job agendado que verifica atualizações automaticamente.
 * 
 * <ul>
 *   <li>Verificação à noite: Todos os dias às 02:00 (horário de menor uso)</li>
 *   <li>Verificação ao iniciar: 5 minutos após o startup da aplicação</li>
 *   <li>Limpeza automática: Remove pending-update.jar corrompido ou antigo</li>
 * </ul>
 */
@Component
public class AutoUpdateJob {

    private static final Logger log = LoggerFactory.getLogger(AutoUpdateJob.class);

    private final UpdateService updateService;

    @Value("${app.update.enabled:true}")
    private boolean updateEnabled;

    @Value("${app.update.auto-download:false}")
    private boolean autoDownload;

    public AutoUpdateJob(UpdateService updateService) {
        this.updateService = updateService;
    }

    /**
     * Executa 5 minutos após o startup para verificar se há atualização pendente
     * que não foi aplicada corretamente.
     */
    @EventListener(ApplicationReadyEvent.class)
    public void verificarAtualizacaoPendenteNoStartup() {
        new Thread(() -> {
            try {
                Thread.sleep(5 * 60 * 1000); // 5 minutos
                verificarELimparPendingUpdate();
            } catch (Exception e) {
                log.error("[AutoUpdateJob] Erro na verificação de startup: {}", e.getMessage());
            }
        }).start();
    }

    /**
     * Verificação automática agendada: Todos os dias às 02:00 (horário de menor uso).
     * 
     * Cron: "0 0 2 * * *" = segundo 0, minuto 0, hora 2, todos os dias
     */
    @Scheduled(cron = "0 0 2 * * *")
    public void verificarAtualizacaoAutomatica() {
        if (!updateEnabled) {
            log.debug("[AutoUpdateJob] Verificação automática desabilitada");
            return;
        }

        log.info("[AutoUpdateJob] ========================================");
        log.info("[AutoUpdateJob] Iniciando verificação automática de atualização (02:00)");
        log.info("[AutoUpdateJob] ========================================");

        try {
            UpdateInfo info = updateService.checkForUpdate();

            if (!info.hasUpdate()) {
                log.info("[AutoUpdateJob] Sistema já está atualizado (versão {})", info.currentVersion());
                return;
            }

            log.info("[AutoUpdateJob] Nova versão disponível: {} -> {}", 
                     info.currentVersion(), info.latestVersion());

            if (autoDownload && info.downloadUrl() != null && !info.downloadUrl().isBlank()) {
                log.info("[AutoUpdateJob] Auto-download ATIVADO. Iniciando download automático...");
                log.warn("[AutoUpdateJob] ATENÇÃO: A aplicação será reiniciada automaticamente!");

                // Aguarda 10 segundos antes de iniciar (permite cancelar se necessário)
                Thread.sleep(10000);

                updateService.applyUpdate(info.downloadUrl());
            } else {
                log.info("[AutoUpdateJob] Auto-download DESATIVADO. Notificação será exibida ao usuário.");
                log.info("[AutoUpdateJob] Para ativar download automático, defina: app.update.auto-download=true");
            }

        } catch (Exception e) {
            log.error("[AutoUpdateJob] Erro durante verificação automática: {}", e.getMessage(), e);
        }

        log.info("[AutoUpdateJob] ========================================");
        log.info("[AutoUpdateJob] Verificação automática concluída");
        log.info("[AutoUpdateJob] ========================================");
    }

    /**
     * Verifica e limpa pending-update.jar corrompido ou antigo.
     * 
     * Remove o arquivo se:
     * - Tamanho menor que 10 MB (provavelmente corrompido)
     * - Mais de 7 dias desde a última modificação (usuário ignorou)
     */
    private void verificarELimparPendingUpdate() {
        try {
            Path myfinanceDir = Path.of(System.getProperty("user.home"), ".myfinance");
            Path pendingJar = myfinanceDir.resolve("pending-update.jar");

            if (!Files.exists(pendingJar)) {
                log.debug("[AutoUpdateJob] Nenhuma atualização pendente encontrada");
                return;
            }

            long size = Files.size(pendingJar);
            long ageMillis = System.currentTimeMillis() - Files.getLastModifiedTime(pendingJar).toMillis();
            long ageDays = ageMillis / (1000 * 60 * 60 * 24);

            log.warn("[AutoUpdateJob] Atualização pendente detectada:");
            log.warn("[AutoUpdateJob] - Tamanho: {} MB", String.format("%.2f", size / 1048576.0));
            log.warn("[AutoUpdateJob] - Idade: {} dias", ageDays);

            boolean shouldDelete = false;
            String reason = "";

            if (size < 10 * 1024 * 1024) {
                shouldDelete = true;
                reason = "tamanho inválido (< 10 MB)";
            } else if (ageDays > 7) {
                shouldDelete = true;
                reason = "arquivo antigo (> 7 dias)";
            }

            if (shouldDelete) {
                log.warn("[AutoUpdateJob] Removendo pending-update.jar: {}", reason);
                Files.delete(pendingJar);
                log.info("[AutoUpdateJob] Arquivo removido com sucesso");

                // Remove também o log de atualização antigo
                Path updateLog = myfinanceDir.resolve("update.log");
                if (Files.exists(updateLog)) {
                    Files.delete(updateLog);
                }
            } else {
                log.info("[AutoUpdateJob] Atualização pendente válida. Aguardando aplicação pelo usuário.");
            }

        } catch (Exception e) {
            log.error("[AutoUpdateJob] Erro ao verificar/limpar pending-update.jar: {}", e.getMessage());
        }
    }
}

package controle.api.back_end.update;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/api/update")
public class UpdateController {

    private final UpdateService updateService;

    public UpdateController(UpdateService updateService) {
        this.updateService = updateService;
    }

    /**
     * GET /api/update/check
     * Consulta o GitHub Releases e retorna se há uma versão mais nova disponível.
     */
    @GetMapping("/check")
    public ResponseEntity<?> checkUpdate() {
        try {
            UpdateInfo info = updateService.checkForUpdate();
            return ResponseEntity.ok(info);
        } catch (Exception e) {
            System.err.println("[Update] Erro ao verificar atualizações: " + e.getMessage());
            // Retorna "sem atualização" em caso de falha (ex: sem internet)
            return ResponseEntity.ok(
                    new UpdateInfo(false, updateService.getCurrentVersion(),
                            updateService.getCurrentVersion(), null, null, null)
            );
        }
    }

    /**
     * POST /api/update/apply
     * Inicia o download e reinicialização da aplicação com a nova versão.
     * Body: { "downloadUrl": "https://..." }
     */
    @PostMapping("/apply")
    public ResponseEntity<?> applyUpdate(@RequestBody Map<String, String> body) {
        String downloadUrl = body.get("downloadUrl");
        if (downloadUrl == null || downloadUrl.isBlank()) {
            return ResponseEntity.badRequest()
                    .body(Map.of("error", "O campo 'downloadUrl' é obrigatório."));
        }

        // Executa em thread separada para que a resposta HTTP seja enviada antes de o app fechar
        Thread updateThread = new Thread(() -> {
            try {
                Thread.sleep(800); // Aguarda a resposta ser despachada
                updateService.applyUpdate(downloadUrl);
            } catch (Exception e) {
                System.err.println("[Update] Falha ao aplicar atualização: " + e.getMessage());
            }
        });
        updateThread.setDaemon(true);
        updateThread.start();

        return ResponseEntity.ok(Map.of(
                "status", "iniciado",
                "message", "Atualização em andamento. A aplicação será reiniciada em instantes."
        ));
    }
}

package controle.api.back_end.update;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/api/update")
public class UpdateController {

    private static final Logger log = LoggerFactory.getLogger(UpdateController.class);
    private final UpdateService updateService;

    public UpdateController(UpdateService updateService) {
        this.updateService = updateService;
    }

    /**
     * GET /api/update/check
     * Consulta o GitHub Releases e retorna se há uma versão mais nova disponível.
     */
    @GetMapping("/check")
    public ResponseEntity<?> checkUpdate() {
        try {
            UpdateInfo info = updateService.checkForUpdate();
            return ResponseEntity.ok(info);
        } catch (Exception e) {
            log.error("[UpdateController] Erro ao verificar atualizações: {}", e.getMessage(), e);
            // Retorna "sem atualização" em caso de falha (ex: sem internet)
            return ResponseEntity.ok(
                    new UpdateInfo(false, updateService.getCurrentVersion(),
                            updateService.getCurrentVersion(), null, null, null)
            );
        }
    }

    /**
     * POST /api/update/apply
     * Inicia o download e reinicialização da aplicação com a nova versão.
     * Body: { "downloadUrl": "https://..." }
     */
    @PostMapping("/apply")
    public ResponseEntity<?> applyUpdate(@RequestBody Map<String, String> body) {
        String downloadUrl = body.get("downloadUrl");
        if (downloadUrl == null || downloadUrl.isBlank()) {
            log.warn("[UpdateController] Tentativa de atualização sem URL");
            return ResponseEntity.badRequest()
                    .body(Map.of("error", "O campo 'downloadUrl' é obrigatório."));
        }

        log.info("[UpdateController] Requisição de atualização recebida. URL: {}", downloadUrl);

        // Executa em thread separada para que a resposta HTTP seja enviada antes de o app fechar
        Thread updateThread = new Thread(() -> {
            try {
                Thread.sleep(800); // Aguarda a resposta ser despachada
                updateService.applyUpdate(downloadUrl);
            } catch (Exception e) {
                log.error("[UpdateController] Falha ao aplicar atualização: {}", e.getMessage(), e);
            }
        });
        updateThread.setDaemon(true);
        updateThread.setName("update-applier");
        updateThread.start();

        return ResponseEntity.ok(Map.of(
                "status", "iniciado",
                "message", "Atualização em andamento. A aplicação será reiniciada em instantes."
        ));
    }
}

