let _alertaTimer = null;

/* ══════════════════════════════════════════════════
   Alertas
══════════════════════════════════════════════════ */
function habilitarFecharAlertaAoClicarFora() {
    const divAl = document.getElementById("div_alerta");
    const contAl = document.getElementById("conteudoAlerta");
    if (!divAl || !contAl || divAl.dataset.closeOutsideBound === "1") return;
    divAl.dataset.closeOutsideBound = "1";
    divAl.addEventListener("click", (event) => {
        if (event.target === divAl) {
            divAl.style.display = "none";
            if (_alertaTimer) { clearTimeout(_alertaTimer); _alertaTimer = null; }
        }
    });
}

function alerta(texto, duracaoMs = 4000) {
    const divAl = document.getElementById("div_alerta");
    const contAl = document.getElementById("conteudoAlerta");
    habilitarFecharAlertaAoClicarFora();
    if (divAl) divAl.style.display = "flex";
    if (contAl) contAl.innerHTML = texto;
    if (_alertaTimer) clearTimeout(_alertaTimer);
    if (duracaoMs > 0) {
        _alertaTimer = setTimeout(() => {
            if (divAl) divAl.style.display = "none";
            _alertaTimer = null;
        }, duracaoMs);
    }
}

/* ══════════════════════════════════════════════════
   Clear-on-focus (campos mantidos após registro)
══════════════════════════════════════════════════ */
function setupClearOnFocus() {
    const ids = ['ipt_nome','ipt_valor','ipt_desc','ipt_multi_nome','ipt_multi_valor','ipt_multi_desc'];
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        el.addEventListener('focus', function () {
            if (this.dataset.pendingClear !== 'true') return;
            if (this.id === 'ipt_valor' || this.id === 'ipt_multi_valor') {
                if (window.MainAPI && window.MainAPI.resetarMascaraMoeda) {
                    window.MainAPI.resetarMascaraMoeda(this);
                } else {
                    this.value = '';
                }
            } else {
                this.value = '';
            }
            delete this.dataset.pendingClear;
            this.classList.remove('ar-field-submitted');
        });
    });
}

function markFieldsForClear(ids) {
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (el && el.value) {
            el.dataset.pendingClear = 'true';
            el.classList.add('ar-field-submitted');
        }
    });
}

/* ══════════════════════════════════════════════════
   Tag Picker system
══════════════════════════════════════════════════ */
const _tp = {}; // id -> { options, selected, placeholder, onchange }

function initTagPicker(id, options, placeholder, onchange) {
    if (_tp[id]) {
        // Reload: preserve selected, update options
        _tp[id].options = options;
        _tp[id].selected = _tp[id].selected.filter(s =>
            options.some(o => String(o.id) === String(s.id))
        );
        if (onchange) _tp[id].onchange = onchange;
    } else {
        _tp[id] = { options, selected: [], placeholder: placeholder || 'Selecionar...', onchange: onchange || null };
    }
    _renderTagPicker(id);
}

function openTagPicker(event, id) {
    event.stopPropagation();
    const dd = document.getElementById('tp-dd-' + id);
    const display = dd ? dd.previousElementSibling : null;
    if (!dd) return;
    const isOpen = dd.style.display !== 'none';
    // Close all
    document.querySelectorAll('.ar-tp-dd').forEach(el => {
        el.style.display = 'none';
        if (el.previousElementSibling) el.previousElementSibling.classList.remove('open');
    });
    if (!isOpen) {
        dd.style.display = '';
        if (display) display.classList.add('open');
    }
}

function _toggleTagItem(id, itemId, itemLabel) {
    const state = _tp[id];
    if (!state) return;
    const idx = state.selected.findIndex(s => String(s.id) === String(itemId));
    if (idx >= 0) {
        state.selected.splice(idx, 1);
    } else {
        state.selected.push({ id: itemId, label: itemLabel });
    }
    _renderTagPicker(id);
    if (state.onchange) state.onchange(state.selected);
}

function _removeTagItem(id, itemId) {
    const state = _tp[id];
    if (!state) return;
    state.selected = state.selected.filter(s => String(s.id) !== String(itemId));
    _renderTagPicker(id);
    if (state.onchange) state.onchange(state.selected);
}

function _renderTagPicker(id) {
    const state = _tp[id];
    const tagsEl = document.getElementById('tp-tags-' + id);
    const ddEl   = document.getElementById('tp-dd-'   + id);
    if (!tagsEl || !ddEl) return;

    // Tags display
    if (state.selected.length === 0) {
        tagsEl.innerHTML = `<span class="ar-tp-ph">${state.placeholder}</span>`;
    } else {
        tagsEl.innerHTML = state.selected.map(s =>
            `<span class="ar-tp-tag">${s.label}<button type="button" class="ar-tp-tag-rm"
                onclick="event.stopPropagation();_removeTagItem('${id}','${s.id}')">×</button></span>`
        ).join('');
    }

    // Dropdown options
    ddEl.innerHTML = '';
    state.options.forEach(opt => {
        const sel = state.selected.some(s => String(s.id) === String(opt.id));
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ar-tp-option' + (sel ? ' ar-tp-option-sel' : '');
        const check = document.createElement('span');
        check.className = 'ar-tp-opt-check';
        check.textContent = sel ? '✓' : '';
        btn.appendChild(check);
        btn.appendChild(document.createTextNode(opt.label));
        btn.addEventListener('click', e => {
            e.stopPropagation();
            _toggleTagItem(id, opt.id, opt.label);
        });
        ddEl.appendChild(btn);
    });
}

// Close all dropdowns when clicking outside
document.addEventListener('click', () => {
    document.querySelectorAll('.ar-tp-dd').forEach(dd => {
        dd.style.display = 'none';
        if (dd.previousElementSibling) dd.previousElementSibling.classList.remove('open');
    });
});

/* ── Institution amounts handler ── */
function _onInstChange(pickerId, selected) {
    const amountsId   = pickerId === 'inst' ? 'inst-amounts'   : 'm-inst-amounts';
    const wrapValorId = pickerId === 'inst' ? 'wrap_valor'      : 'wrap_multi_valor';

    const amountsEl   = document.getElementById(amountsId);
    const wrapValorEl = document.getElementById(wrapValorId);

    if (selected.length > 1) {
        // Esconde o campo de valor único
        if (wrapValorEl) wrapValorEl.style.display = 'none';

        // Mostra painel de valor por instituição
        if (amountsEl) {
            amountsEl.style.display = '';
            // Mantém o título, remove linhas antigas
            while (amountsEl.children.length > 1) amountsEl.removeChild(amountsEl.lastChild);
            selected.forEach(s => {
                const row = document.createElement('div');
                row.className = 'ar-inst-amount-row';
                const nameEl = document.createElement('span');
                nameEl.className = 'ar-inst-name';
                nameEl.textContent = s.label;
                const inp = document.createElement('input');
                inp.type = 'text';
                inp.id = `inst-amt-${pickerId}-${s.id}`;
                inp.className = 'ar-inst-amt-input';
                inp.setAttribute('inputmode', 'numeric');
                inp.setAttribute('autocomplete', 'off');
                row.appendChild(nameEl);
                row.appendChild(inp);
                amountsEl.appendChild(row);
                // Aplica máscara APÓS o elemento estar no DOM
                if (window.MainAPI && window.MainAPI.aplicarMascaraMoeda) {
                    window.MainAPI.aplicarMascaraMoeda(inp);
                }
            });
        }
    } else {
        // Mostra o campo de valor único novamente
        if (wrapValorEl) wrapValorEl.style.display = '';

        // Esconde painel de valor por instituição
        if (amountsEl) {
            amountsEl.style.display = 'none';
            while (amountsEl.children.length > 1) amountsEl.removeChild(amountsEl.lastChild);
        }
    }

    // Saldo display (formulário único apenas)
    if (pickerId === 'inst') {
        if (selected.length === 1) {
            atualizarSaldoDisplay(selected[0].id);
        } else {
            const saldoEl = document.getElementById('saldo_display');
            if (saldoEl) saldoEl.style.display = 'none';
        }
    }
}

/* ══════════════════════════════════════════════════
   Recurring section
══════════════════════════════════════════════════ */
let _isRecorrente = false;
let _periodicidade = null;
let _diasSemana    = [];
let _diaMes        = null;
let _mesAnual      = null;
let _diaAnual      = null;
let _dataFimRecorrente = null;

// Mapeamento: índice do botão DOM (0=Dom, 1=Seg, …, 6=Sáb) → DayOfWeek do Java
const _DOW_MAP = ['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'];
const _DOW_LABEL = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const _MESES_LABEL = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

function _atualizarResumoRecorrencia() {
    const el = document.getElementById('ar-recorrente-resumo');
    if (!el) return;
    if (!_isRecorrente || !_periodicidade) { el.style.display = 'none'; el.textContent = ''; return; }
    const partes = [_periodicidade.charAt(0).toUpperCase() + _periodicidade.slice(1)];
    if (_periodicidade === 'semanal' && _diasSemana.length > 0)
        partes.push(_diasSemana.map(d => _DOW_LABEL[d]).join(', '));
    if (_periodicidade === 'mensal' && _diaMes)
        partes.push(`Dia ${_diaMes}`);
    if (_periodicidade === 'anual') {
        if (_mesAnual) partes.push(_MESES_LABEL[_mesAnual - 1]);
        if (_diaAnual) partes.push(`Dia ${_diaAnual}`);
    }
    if (_dataFimRecorrente) partes.push(`até ${_dataFimRecorrente.split('-').reverse().join('/')}`);
    el.textContent = partes.join(' · ');
    el.style.display = '';
}

function toggleRecorrente() {
    _isRecorrente = !_isRecorrente;
    if (!_isRecorrente) {
        _periodicidade = null; _diasSemana = []; _diaMes = null; _mesAnual = null; _diaAnual = null; _dataFimRecorrente = null;
        const fim = document.getElementById('rec-data-fim');
        if (fim) fim.value = '';
        _atualizarResumoRecorrencia();
    }    const btn  = document.getElementById('ar-recorrente-btn');
    const icon = document.getElementById('ar-recorrente-icon');
    const opts = document.getElementById('recurring-options');
    if (btn)  btn.classList.toggle('active', _isRecorrente);
    if (icon) icon.style.display = _isRecorrente ? '' : 'none';
    if (opts) opts.style.display = _isRecorrente ? '' : 'none';
    if (!_isRecorrente) {
        ['rec-semanal','rec-mensal','rec-anual'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });
        document.querySelectorAll('.ar-pill[data-period]').forEach(p => p.classList.remove('active'));
    }
}

function setPeriodicity(p) {
    _periodicidade = p;
    _diasSemana = []; _diaMes = null; _mesAnual = null; _diaAnual = null;
    document.querySelectorAll('.ar-pill[data-period]').forEach(pill =>
        pill.classList.toggle('active', pill.dataset.period === p)
    );
    document.getElementById('rec-semanal').style.display = p === 'semanal' ? '' : 'none';
    document.getElementById('rec-mensal').style.display  = p === 'mensal'  ? '' : 'none';
    document.getElementById('rec-anual').style.display   = p === 'anual'   ? '' : 'none';
    document.querySelectorAll('.ar-pill[data-day]').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#rec-mensal-days .ar-pill').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#rec-anual-months .ar-pill').forEach(p => p.classList.remove('active'));
    _atualizarResumoRecorrencia();
}

function toggleWeekDay(day) {
    const idx = _diasSemana.indexOf(day);
    if (idx >= 0) _diasSemana.splice(idx, 1); else _diasSemana.push(day);
    const pill = document.querySelector(`.ar-pill[data-day="${day}"]`);
    if (pill) pill.classList.toggle('active', _diasSemana.includes(day));
    _atualizarResumoRecorrencia();
}

function setMonthDay(day) {
    _diaMes = (_diaMes === day) ? null : day;
    document.querySelectorAll('#rec-mensal-days .ar-pill').forEach(p =>
        p.classList.toggle('active', Number(p.dataset.monthday) === _diaMes)
    );
    _atualizarResumoRecorrencia();
}

function setAnnualMonth(month) {
    _mesAnual = (_mesAnual === month) ? null : month;
    document.querySelectorAll('#rec-anual-months .ar-pill').forEach(p =>
        p.classList.toggle('active', Number(p.dataset.annualmonth) === _mesAnual)
    );
    _atualizarResumoRecorrencia();
}

function _initRecurringSubOptions() {
    // Monthly days 1-31
    const mensal = document.getElementById('rec-mensal-days');
    if (mensal && mensal.children.length === 0) {
        for (let d = 1; d <= 31; d++) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'ar-pill ar-pill-sm';
            btn.dataset.monthday = d;
            btn.textContent = d;
            btn.addEventListener('click', () => setMonthDay(d));
            mensal.appendChild(btn);
        }
    }
    // Annual months
    const MONTHS = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
    const anualMonths = document.getElementById('rec-anual-months');
    if (anualMonths && anualMonths.children.length === 0) {
        MONTHS.forEach((m, i) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'ar-pill';
            btn.dataset.annualmonth = i + 1;
            btn.textContent = m;
            btn.addEventListener('click', () => setAnnualMonth(i + 1));
            anualMonths.appendChild(btn);
        });
    }
    // Annual day select
    const anualDay = document.getElementById('rec-anual-day');
    if (anualDay && anualDay.options.length <= 1) {
        for (let d = 1; d <= 31; d++) {
            const opt = document.createElement('option');
            opt.value = d; opt.textContent = `Dia ${d}`;
            anualDay.appendChild(opt);
        }
        anualDay.addEventListener('change', () => { _diaAnual = anualDay.value ? parseInt(anualDay.value) : null; });
    }

    // Campo de data final da recorrência — mesmo estilo da tela de filtros (dd/mm/aaaa)
    const recurringOpts = document.getElementById('recurring-options');
    if (recurringOpts && !document.getElementById('rec-data-fim')) {
        const grp = document.createElement('div');
        grp.className = 'ar-recurring-group';
        grp.id = 'rec-data-fim-group';
        grp.innerHTML = `
            <span class="ar-group-label">Data final da recorrência</span>
            <div style="margin-top:6px;display:flex;align-items:center;gap:8px;">
                <input type="text" id="rec-data-fim" class="ar-select-small"
                       placeholder="dd/mm/aaaa" maxlength="10" inputmode="numeric"
                       style="min-width:180px;max-width:220px;cursor:text;">
            </div>
        `;
        recurringOpts.appendChild(grp);

        const inputDataFim = document.getElementById('rec-data-fim');
        // Aplica a mesma máscara usada no filtro de registros
        if (window.MainAPI && window.MainAPI.aplicarMascaraData) {
            window.MainAPI.aplicarMascaraData(inputDataFim);
        }
        // Converte dd/mm/aaaa → aaaa-mm-dd para o backend
        inputDataFim.addEventListener('input', function () {
            _dataFimRecorrente = (window.MainAPI && window.MainAPI.dataParaISO)
                ? window.MainAPI.dataParaISO(this.value)
                : null;
            _atualizarResumoRecorrencia();
        });
    }
} // fim _initRecurringSubOptions

/* ══════════════════════════════════════════════════
   Painel de Poupança (Caixinha)
══════════════════════════════════════════════════ */
let _caixinhas = [];
let _caixinhaSelecionadaId = null;

async function _carregarCaixinhas() {
    if (!userId) return;
    try {
        _caixinhas = await MainAPI.getCaixinhas(userId);
    } catch (e) {
        _caixinhas = [];
    }
}

function _renderPainelPoupanca(show) {
    let painel = document.getElementById('ar-poupanca-painel');
    if (!show) {
        if (painel) painel.style.display = 'none';
        _caixinhaSelecionadaId = null;
        return;
    }
    if (!painel) {
        // Cria o painel dinamicamente na primeira vez
        painel = document.createElement('div');
        painel.id = 'ar-poupanca-painel';
        painel.className = 'ar-recurring-wrap ar-span-3';
        // Insere após o bloco de tipo de movimento
        const movWrap = document.getElementById('select_movimento')?.closest('.ar-field-wrap');
        if (movWrap && movWrap.parentNode) {
            movWrap.parentNode.insertBefore(painel, movWrap.nextSibling);
        }
    }
    painel.style.display = '';

    if (_caixinhas.length === 0) {
        painel.innerHTML = `
            <div style="background:var(--cor-tinte-suave);border-radius:12px;padding:14px 16px;border:1px solid var(--cor-tinte-borda);">
                <p style="margin:0;color:var(--cor-texto-secundario);font-size:0.92rem;">
                    <i class='bx bx-info-circle' style="color:var(--cor-principal);"></i>
                    Nenhuma caixinha ativa encontrada. 
                    <strong>Registre o aporte mesmo assim</strong> — ele aparecerá como Poupança sem caixinha vinculada.
                </p>
            </div>`;
        _caixinhaSelecionadaId = null;
        return;
    }

    const opts = _caixinhas.map(c => {
        const pct   = c.percentualAtingido != null ? `${c.percentualAtingido.toFixed(1)}%` : '—';
        const prazo = c.dataPrazo ? ` · prazo ${c.dataPrazo}` : '';
        return `<option value="${c.id}">${c.nome} (${pct} atingido${prazo})</option>`;
    }).join('');

    painel.innerHTML = `
        <div style="background:var(--cor-tinte-suave);border-radius:12px;padding:14px 16px;border:1px solid var(--cor-tinte-borda);display:flex;flex-direction:column;gap:10px;">
            <span style="font-size:0.82rem;font-weight:700;color:var(--cor-texto-secundario);text-transform:uppercase;letter-spacing:0.5px;">Vincular a uma Caixinha</span>
            <select id="ar-select-caixinha" style="background:var(--cor-fundo-card);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:8px 12px;color:var(--cor-texto-principal);font-size:0.95rem;">
                <option value="">Sem caixinha (aporte avulso)</option>
                ${opts}
            </select>
            <div id="ar-caixinha-info" style="display:none;font-size:0.87rem;color:var(--cor-texto-secundario);line-height:1.6;padding:8px 10px;background:var(--cor-fundo-campo);border-radius:8px;"></div>
        </div>`;

    document.getElementById('ar-select-caixinha').addEventListener('change', function () {
        _caixinhaSelecionadaId = this.value || null;
        const info = document.getElementById('ar-caixinha-info');
        if (!_caixinhaSelecionadaId) { info.style.display = 'none'; return; }
        const cx = _caixinhas.find(c => c.id === _caixinhaSelecionadaId);
        if (!cx) { info.style.display = 'none'; return; }
        const fmt = v => v != null ? `R$ ${Number(v).toFixed(2)}` : '—';
        const pct = cx.percentualAtingido != null ? `${cx.percentualAtingido.toFixed(1)}%` : '—';
        info.style.display = '';
        info.innerHTML = `
            <b>${cx.nome}</b><br>
            Meta: <b>${fmt(cx.valorMeta)}</b> · Acumulado: <b>${fmt(cx.valorAtual)}</b> (${pct})<br>
            ${cx.aporteMensalSugerido != null ? `Aporte mensal sugerido: <b style="color:var(--cor-principal)">${fmt(cx.aporteMensalSugerido)}</b>` : ''}
            ${cx.mesesRestantes != null ? ` · ${cx.mesesRestantes} meses restantes` : ''}`;
    });
}

function _onTipoChange() {
    const tipo = document.getElementById('select_tipo')?.value;
    _renderPainelPoupanca(tipo === 'Poupanca');
    _renderPainelEmprestimo(tipo === 'Emprestimo');
    _renderPainelTransferencia(tipo === 'Transferencia');

    // Para Empréstimo, força parcelas sempre visíveis independente do movimento
    if (tipo === 'Emprestimo') {
        const wrap = document.getElementById('wrap_parcelas');
        if (wrap) wrap.style.display = '';
    }
}

/* ══════════════════════════════════════════════════
   Inicialização
══════════════════════════════════════════════════ */
function gerarInformacoes() {
    // Init tag pickers (empty – options loaded async)
    initTagPicker('inst',   [], 'Escolha instituições...', sel => _onInstChange('inst',   sel));
    initTagPicker('cat',    [], 'Escolha categorias...',   null);
    initTagPicker('m-inst', [], 'Escolha...',              sel => _onInstChange('m-inst', sel));
    initTagPicker('m-cat',  [], 'Escolha...',              null);

    // Apply money mask
    const iV  = document.getElementById('ipt_valor');
    const imV = document.getElementById('ipt_multi_valor');
    if (iV  && window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(iV);
    if (imV && window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(imV);

    // Recurring sub-option builders
    _initRecurringSubOptions();

    // Clear-on-focus for text fields
    setupClearOnFocus();

    // Poupança: carrega caixinhas e escuta mudança de tipo
    _carregarCaixinhas();
    const selectTipo = document.getElementById('select_tipo');
    if (selectTipo) selectTipo.addEventListener('change', _onTipoChange);

    // Load data from API
    gerarCategorias();
    gerarInstituicao();
}

async function atualizarSaldoDisplay(instituicaoUsuarioId) {
    const el = document.getElementById('saldo_display');
    if (!el) return;
    if (!instituicaoUsuarioId || instituicaoUsuarioId === '#') { el.style.display = 'none'; return; }
    try {
        const res = await fetch(`http://localhost:8080/instituicoes/saldo/${Number(instituicaoUsuarioId)}`);
        if (!res.ok) { el.style.display = 'none'; return; }
        const saldo = await res.json();
        const valor = Number(saldo);
        el.textContent = `Saldo disponível: R$ ${valor.toFixed(2)}`;
        // Usa variáveis CSS para cores de saldo
        el.style.color = valor <= 0 ? 'var(--red-700)' : 'var(--cor-principal)';
        el.style.display = '';
    } catch (e) { el.style.display = 'none'; }
}

function toggleParcelas(inputId, movimento) {
    const requer = movimento === 'Credito' || movimento === 'Boleto';
    const wrapId = inputId === 'ipt_parcelas' ? 'wrap_parcelas' : 'wrap_multi_parcelas';
    const wrap  = document.getElementById(wrapId);
    const input = document.getElementById(inputId);
    if (wrap)  wrap.style.display  = requer ? '' : 'none';
    if (input && !requer) input.value = '1';
}

function gerarCategorias() {
    if (!userId) return;
    MainAPI.getTipos(userId)
        .then(json => {
            const options = json.map(c => ({ id: c.id, label: c.categoria.titulo }));
            initTagPicker('cat',   options, 'Escolha categorias...');
            initTagPicker('m-cat', options, 'Escolha...');
        })
        .catch(() => alerta("Não foi possível carregar as categorias. Tente novamente."));
}

const gerarTipos = gerarCategorias;

async function gerarInstituicao() {
    if (!userId) return;
    try {
        const json = await MainAPI.getInstituicoes(userId);
        const options = json.map(i => ({ id: i.id, label: i.intituicao.nome }));
        initTagPicker('inst',   options, 'Escolha instituições...', sel => _onInstChange('inst',   sel));
        initTagPicker('m-inst', options, 'Escolha...',              sel => _onInstChange('m-inst', sel));
        // Atualiza também o picker de destino se já existir
        if (_tp['dest']) initTagPicker('dest', options, 'Escolha a instituição destino...');
    } catch (e) {
        alerta("Não foi possível carregar as instituições. Tente novamente.");
    }
}

/* ══════════════════════════════════════════════════
   Registrar (formulário único)
══════════════════════════════════════════════════ */
async function registrar() {
    const valorInput = document.getElementById('ipt_valor');
    const valor      = window.MainAPI ? window.MainAPI.obterValorMoeda(valorInput) : Number(valorInput.value);
    const titulo     = document.getElementById('ipt_nome').value;
    const tipo       = document.getElementById('select_tipo').value;
    const descRaw    = document.getElementById('ipt_desc').value;
    const Desc       = descRaw || 'Nenhuma descrição fornecida';
    const movimento  = document.getElementById('select_movimento').value;
    const parcelas   = Number(document.getElementById('ipt_parcelas').value) || 1;
    const data       = dataGasto;

    const selectedInst = _tp['inst'] ? _tp['inst'].selected : [];
    const selectedCat  = _tp['cat']  ? _tp['cat'].selected  : [];

    // Para Empréstimo: parcelas obrigatório, taxa opcional
    const taxaEmprestimo = tipo === 'Emprestimo'
        ? (Number(document.getElementById('ar-emprestimo-taxa')?.value) || 0)
        : null;

    // Para Transferência: instituição destino obrigatória
    const selectedDest = _tp['dest'] ? _tp['dest'].selected : [];

    if (!data || data === 0)         return alerta("Data inválida");
    if (!titulo)                     return alerta("Título inválido");
    if (tipo === '#')                return alerta("Escolha o tipo do evento");
    if (selectedCat.length === 0)    return alerta("Escolha uma categoria");
    if (selectedInst.length === 0)   return alerta("Escolha uma instituição");
    if (movimento === '#')           return alerta("Escolha o tipo de movimento");
    if ((movimento === 'Credito' || movimento === 'Boleto') && (parcelas < 1 || isNaN(parcelas)))
        return alerta("Informe a quantidade de parcelas (mínimo 1)");
    if (tipo === 'Emprestimo' && (parcelas < 1 || isNaN(parcelas)))
        return alerta("Informe a quantidade de parcelas do empréstimo (mínimo 1)");
    if (tipo === 'Transferencia' && selectedDest.length === 0)
        return alerta("Escolha a instituição de destino para a transferência");

    // Validação de valor: quando múltiplas instituições o campo único fica oculto
    if (selectedInst.length <= 1) {
        if (valor <= 0 || !valor) return alerta("Valor inválido");
    } else {
        const algumValor = selectedInst.some(s => {
            const ai = document.getElementById(`inst-amt-inst-${s.id}`);
            return ai && (window.MainAPI ? window.MainAPI.obterValorMoeda(ai) : 0) > 0;
        });
        if (!algumValor) return alerta("Informe o valor para cada instituição");
    }

    // Verificar saldo quando o tipo exige débito
    if ((tipo === 'Gasto' || tipo === 'Transferencia') && selectedInst.length === 1) {
        try {
            const resSaldo = await fetch(`http://localhost:8080/instituicoes/saldo/${Number(selectedInst[0].id)}`);
            if (resSaldo.ok) {
                const saldo = await resSaldo.json();
                if (Number(saldo) < valor)
                    return alerta(`Saldo insuficiente. Disponível: R$ ${Number(saldo).toFixed(2)}`);
            }
        } catch (e) { console.warn("Não foi possível verificar saldo:", e); }
    }

    // Montar lista de instituições (com valor individual quando múltiplas)
    const instituicaoList = selectedInst.map(s => {
        let instValor = valor;
        if (selectedInst.length > 1) {
            const amtInput = document.getElementById(`inst-amt-inst-${s.id}`);
            if (amtInput) {
                const v = window.MainAPI ? window.MainAPI.obterValorMoeda(amtInput) : Number(amtInput.value);
                if (v > 0) instValor = v;
            }
        }
        return { instituicaoUsuario_id: Number(s.id), tipoMovimento: movimento, valor: instValor, parcelas };
    });

    // Para Transferência: adiciona destino como segunda instituição
    if (tipo === 'Transferencia' && selectedDest.length > 0) {
        const dest = selectedDest[0];
        instituicaoList.push({ instituicaoUsuario_id: Number(dest.id), tipoMovimento: movimento, valor, parcelas: 1 });
    }

    // Quando múltiplas instituições, valor total = soma dos valores individuais
    const valorTotal = selectedInst.length > 1
        ? instituicaoList.filter(i => !selectedDest.some(d => Number(d.id) === i.instituicaoUsuario_id))
              .reduce((acc, i) => acc + i.valor, 0)
        : valor;

    // Dados de recorrência — se ativada, usa endpoint /registros/recorrente
    if (_isRecorrente) {
        // Validações extras de recorrência
        if (tipo !== 'Gasto' && tipo !== 'Recebimento')
            return alerta("Recorrência disponível apenas para Gasto e Recebimento");
        if (!_periodicidade)
            return alerta("Escolha a periodicidade da recorrência");
        if (_periodicidade === 'semanal' && _diasSemana.length === 0)
            return alerta("Escolha pelo menos um dia da semana");
        if (_periodicidade === 'mensal' && !_diaMes)
            return alerta("Escolha o dia do mês");
        if (_periodicidade === 'anual' && (!_mesAnual || !_diaAnual))
            return alerta("Escolha o mês e o dia do ano");
        if (!_dataFimRecorrente)
            return alerta("Informe a data final da recorrência");

        // Capitalizar primeira letra do periodicidade (ex: 'semanal' → 'Semanal')
        const periodicidade = _periodicidade.charAt(0).toUpperCase() + _periodicidade.slice(1);

        // Mapear índices numéricos para DayOfWeek Java
        const diasDaSemana = _diasSemana.map(n => _DOW_MAP[n]);

        // Dia do mês ou do ano
        const dia = _diaMes || _diaAnual || null;

        alerta(`Registrando recorrência...
            <div class="glaceonCorrendoDiv">
                <img class="glaceon correndo" src="/assets/gif/glaceon-correndo-unscreen.gif" alt="">
            </div>`, 0);

        MainAPI.registrarRecorrente({
            financeiro: {
                usuario_id: userId,
                tipo,
                valor: valorTotal,
                descricao: Desc,
                dataEvento: data,          // data de início
                periodicidade,             // Diario | Semanal | Mensal | Anual
                diasDaSemana,              // ["MONDAY", "FRIDAY", ...]
                dia,                       // dia do mês ou do ano
                dataFim: _dataFimRecorrente, // data final
                intervalo: 1
            },
            instituicao: instituicaoList,
            detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo }
        }).then(async (response) => {
            if (response.ok) {
                window.dispatchEvent(new Event('xp:refresh'));
                markFieldsForClear(['ipt_nome', 'ipt_valor', 'ipt_desc']);
                alerta('✔ Recorrência registrada com sucesso!', 3000);
            } else {
                let detalhe = "";
                try { const corpo = await response.json(); detalhe = corpo.message || corpo.error || JSON.stringify(corpo); }
                catch (_) { detalhe = `HTTP ${response.status}`; }
                alerta(`Erro ao registrar recorrência (${response.status}): ${detalhe}`);
            }
        }).catch(err => {
            console.error("Erro de rede:", err);
            alerta("Erro de conexão ao registrar recorrência.");
        });
        return; // não continua para o registro normal
    }

    alerta(`Registrando...
        <div class="glaceonCorrendoDiv">
            <img class="glaceon correndo" src="/assets/gif/glaceon-correndo-unscreen.gif" alt="">
        </div>`, 0);

    MainAPI.registrarGasto({
        financeiro: {
            usuario_id: userId,
            tipo,
            valor: valorTotal,
            descricao: Desc,
            dataEvento: data,
            ...(tipo === 'Poupanca' && _caixinhaSelecionadaId ? { caixinha_id: _caixinhaSelecionadaId } : {}),
            ...(tipo === 'Emprestimo' && taxaEmprestimo != null ? { taxaRendimento: taxaEmprestimo } : {})
        },
        instituicao: instituicaoList,
        detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo }
    }).then(async (response) => {
        if (response.ok) {
            window.dispatchEvent(new Event('xp:refresh'));
            if (selectedInst.length === 1) atualizarSaldoDisplay(selectedInst[0].id);
            // Manter campos – marcar para limpar ao clicar
            markFieldsForClear(['ipt_nome', 'ipt_valor', 'ipt_desc']);
            alerta('✔ Registro realizado com sucesso!<br><small>Clique nos campos de texto para editá-los.</small>', 3000);
        } else {
            let detalhe = "";
            try { const corpo = await response.json(); detalhe = corpo.message || corpo.error || JSON.stringify(corpo); }
            catch (_) { detalhe = `HTTP ${response.status}`; }
            alerta(`Erro ao registrar (${response.status}): ${detalhe}`);
        }
    }).catch(err => {
        console.error("Erro de rede:", err);
        alerta("Erro de conexão ao registrar.");
    });
}

function atualizarSaldo(valor, instituicao) {
    MainAPI.atualizarSaldo({ valorServer: valor, instituicaoServer: instituicao })
        .then(resposta => {
            if (!resposta.ok) console.error("Erro ao atualizar saldo", resposta);
        });
}

function adicionarTipos() {
    if (!userId) return alerta(`Nenhum usuário logado. <button onclick='div_alerta.style.display="none"'>OK</button>`);
    const titulo = document.getElementById("ipt_tituloTipo").value.trim();
    if (!titulo) return alerta(`Digite um nome para o tipo <button onclick='div_alerta.style.display="none"'>OK</button>`);
    MainAPI.adicionarTipo({ titulo }, userId).then(resposta => {
        if (resposta.ok) {
            gerarTipos();
            adicionarTipo.close();
            alerta(`Tipo adicionado com sucesso!<br><button onclick="div_alerta.style.display='none'">OK</button>`);
        } else {
            alerta(`Houve um erro ao adicionar tipo <button onclick='div_alerta.style.display="none"'>OK</button>`);
        }
    }).catch(() => alerta(`Erro ao conectar ao servidor. <button onclick='div_alerta.style.display="none"'>OK</button>`));
}

/* ══════════════════════════════════════════════════
   Calendário
══════════════════════════════════════════════════ */
const btnAbrir    = document.getElementById("calendario");
const modal       = document.getElementById("modal");
const fechar      = document.getElementById("fechar");
const dias        = document.getElementById("dias");
const mesAno      = document.getElementById("mesAno");
const gastosDoDia = document.getElementById("gastosDoDia");
const confirmar   = document.getElementById("confirmar");
const btnAnterior = document.getElementById("btnAnterior");
const btnProximo  = document.getElementById("btnProximo");

let dataSelecionada = null;
let hoje     = new Date();
let mesAtual = hoje.getMonth();
let anoAtual = hoje.getFullYear();
let modalAbertoPor = 'single';
let lote = [];

// O botão #calendario abre o modal para selecionar a data do evento único
btnAbrir.onclick = () => { modalAbertoPor = 'single'; modal.style.display = "flex"; };

function abrirCalendarioMulti() { modalAbertoPor = 'multi'; modal.style.display = 'flex'; }
fechar.onclick    = () => modal.style.display = "none";
btnAnterior.onclick = () => {
    mesAtual--; if (mesAtual < 0) { mesAtual = 11; anoAtual--; } gerarCalendario();
};
btnProximo.onclick = () => {
    mesAtual++; if (mesAtual > 11) { mesAtual = 0; anoAtual++; } gerarCalendario();
};

async function buscarGastosDia(dataSelecionada) {
    const json = await MainAPI.buscarRegistrosPorData(userId, dataSelecionada);
    let listaGastos = [];
    for (let c = 0; c < json.length; c++) {
        const data = new Date(json[c].dataGasto);
        if (data.toISOString().split("T")[0] === dataSelecionada) listaGastos.push(json[c]);
    }
    return listaGastos;
}

function gerarCalendario() {
    dias.innerHTML = "";
    let primeiroDia = new Date(anoAtual, mesAtual, 1).getDay();
    let totalDias   = new Date(anoAtual, mesAtual + 1, 0).getDate();
    mesAno.innerText = new Date(anoAtual, mesAtual).toLocaleString("pt-BR", { month: "long", year: "numeric" });
    for (let i = 0; i < primeiroDia; i++) dias.innerHTML += `<span></span>`;
    for (let dia = 1; dia <= totalDias; dia++) {
        let dataFormatada = `${anoAtual}-${String(mesAtual + 1).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
        let span = document.createElement("span");
        span.innerText = dia;
        span.onclick = () => selecionarDia(dataFormatada, span);
        dias.appendChild(span);
    }
}

async function selecionarDia(data, elemento) {
    dataSelecionada = data;
    document.querySelectorAll(".diaSelecionado").forEach(e => e.classList.remove("diaSelecionado"));
    elemento.classList.add("diaSelecionado");
    confirmar.disabled = false;
    try {
        const listaGastos = await buscarGastosDia(data);
        const gastosDia = document.getElementById('gastosDia');
        if (listaGastos.length > 0) {
            const dataRegistro = listaGastos[0].eventoFinanceiro?.dataEvento ?? listaGastos[0].dataGasto;
            const novaData     = new Date(dataRegistro);
            const dataFmt = isNaN(novaData.getTime()) ? formatarDataBR(data) : novaData.toLocaleDateString("pt-BR");
            gastosDia.innerHTML = `<b>Gastos de ${dataFmt}:</b><br>`;
            listaGastos.forEach(g => {
                const titulo = g.gastoDetalhe?.tituloGasto ?? g.tituloGasto;
                const valor  = g.eventoFinanceiro?.valor ?? g.valor;
                gastosDia.innerHTML += `<b>${titulo} - R$${valor}</b><br>`;
            });
        } else {
            gastosDia.innerHTML = "<i>Nenhum gasto neste dia.</i>";
        }
    } catch (e) {
        const gastosDia = document.getElementById('gastosDia');
        if (gastosDia) gastosDia.innerHTML = "";
    }
}

confirmar.onclick = () => {
    modal.style.display = "none";
    const dataFormatada = formatarDataBR(dataSelecionada);
    if (modalAbertoPor === 'multi') {
        const label  = document.getElementById('multi_data_label');
        const hidden = document.getElementById('multi_data');
        if (label)  { label.textContent = "Dia: " + dataFormatada; label.classList.remove('hidden'); label.style.display = ''; }
        if (hidden) hidden.value = dataSelecionada;
    } else {
        const dataEl = document.getElementById('data');
        if (dataEl) { dataEl.style.display = ''; dataEl.textContent = dataFormatada; dataEl.classList.remove('hidden'); }
        dataGasto = dataSelecionada;
    }
};

gerarCalendario();

function formatarDataBR(dataISO) {
    const [ano, mes, dia] = dataISO.split("-");
    return `${dia}/${mes}/${ano}`;
}

/* ══════════════════════════════════════════════════
   Múltiplos Registros
══════════════════════════════════════════════════ */
function adicionarAoLote() {
    const titulo    = document.getElementById('ipt_multi_nome').value.trim();
    const tipo      = document.getElementById('multi_select_tipo').value;
    const movimento = document.getElementById('multi_select_movimento').value;
    const parcelas  = Number(document.getElementById('ipt_multi_parcelas').value) || 1;
    const valorInput = document.getElementById('ipt_multi_valor');
    const valor     = window.MainAPI ? window.MainAPI.obterValorMoeda(valorInput) : Number(valorInput.value);
    const descRaw   = document.getElementById('ipt_multi_desc').value.trim();
    const desc      = descRaw || 'Nenhuma descrição fornecida';
    const data      = document.getElementById('multi_data').value;

    const selectedInst = _tp['m-inst'] ? _tp['m-inst'].selected : [];
    const selectedCat  = _tp['m-cat']  ? _tp['m-cat'].selected  : [];

    if (!titulo)                   return alerta('Título inválido');
    if (tipo === '#')              return alerta('Escolha o tipo do evento');
    if (selectedCat.length === 0)  return alerta('Escolha uma categoria');
    if (selectedInst.length === 0) return alerta('Escolha uma instituição');
    if (movimento === '#')         return alerta('Escolha o tipo de movimento');
    if ((movimento === 'Credito' || movimento === 'Boleto') && (parcelas < 1 || isNaN(parcelas)))
        return alerta('Informe a quantidade de parcelas (mínimo 1)');
    if (!data)                      return alerta('Escolha uma data');

    // Validação de valor: múltiplas instituições têm campos próprios
    if (selectedInst.length <= 1) {
        if (valor <= 0 || isNaN(valor)) return alerta('Valor inválido');
    } else {
        const algumValor = selectedInst.some(s => {
            const ai = document.getElementById(`inst-amt-m-inst-${s.id}`);
            return ai && (window.MainAPI ? window.MainAPI.obterValorMoeda(ai) : 0) > 0;
        });
        if (!algumValor) return alerta('Informe o valor para cada instituição');
    }

    const instituicaoList = selectedInst.map(s => {
        let instValor = valor;
        if (selectedInst.length > 1) {
            const amtInput = document.getElementById(`inst-amt-m-inst-${s.id}`);
            if (amtInput) {
                const v = window.MainAPI ? window.MainAPI.obterValorMoeda(amtInput) : Number(amtInput.value);
                if (v > 0) instValor = v;
            }
        }
        return { instituicaoUsuario_id: Number(s.id), tipoMovimento: movimento, valor: instValor, parcelas };
    });

    const valorTotal = selectedInst.length > 1
        ? instituicaoList.reduce((acc, i) => acc + i.valor, 0)
        : valor;

    lote.push({
        financeiro: { usuario_id: userId, tipo, valor: valorTotal, descricao: desc, dataEvento: data },
        instituicao: instituicaoList,
        detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo },
        _display: {
            titulo, tipo, movimento,
            instNome: selectedInst.map(s => s.label).join(', '),
            categorias: selectedCat.map(s => s.label).join(', '),
            valor: valorTotal
        }
    });

    renderizarLote();

    // Manter campos – marcar para limpar ao clicar
    markFieldsForClear(['ipt_multi_nome', 'ipt_multi_valor', 'ipt_multi_desc']);
}

function renderizarLote() {
    const tbody = document.getElementById('corpoLote');
    if (lote.length === 0) {
        tbody.innerHTML = `<tr id="loteVazio"><td colspan="6" class="ar-lote-vazio">Nenhum registro adicionado ainda.</td></tr>`;
        return;
    }
    tbody.innerHTML = '';
    lote.forEach((item, i) => {
        const d = item._display;
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td>${d.titulo}</td>
            <td>${d.tipo}</td>
            <td>${d.movimento}</td>
            <td>${d.instNome}</td>
            <td>R$ ${d.valor.toFixed(2)}</td>
            <td>
                <div class="ar-lote-actions">
                    <button class="ar-lote-btn edit" onclick="editarDoLote(${i})" title="Editar">✏</button>
                    <button class="ar-lote-btn delete" onclick="removerDoLote(${i})" title="Remover">✕</button>
                </div>
            </td>`;
        tbody.appendChild(tr);
    });
}

function removerDoLote(i) {
    lote.splice(i, 1);
    renderizarLote();
}

function editarDoLote(i) {
    const item = lote[i];
    const d    = item._display;

    // Preencher campos do formulário
    document.getElementById('ipt_multi_nome').value = d.titulo;
    document.getElementById('multi_select_tipo').value = item.financeiro.tipo || '#';
    document.getElementById('multi_select_movimento').value = item.instituicao[0]?.tipoMovimento || '#';
    toggleParcelas('ipt_multi_parcelas', item.instituicao[0]?.tipoMovimento || '#');

    const valInput = document.getElementById('ipt_multi_valor');
    valInput.value = d.valor.toFixed(2).replace('.', ',');
    // Reaplica máscara se disponível
    if (window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(valInput);

    document.getElementById('ipt_multi_desc').value =
        item.financeiro.descricao !== 'Nenhuma descrição fornecida' ? item.financeiro.descricao : '';

    // Restaurar tag pickers de instituição
    if (_tp['m-inst']) {
        _tp['m-inst'].selected = item.instituicao.map(inst => {
            const opt = _tp['m-inst'].options.find(o => String(o.id) === String(inst.instituicaoUsuario_id));
            return opt || { id: inst.instituicaoUsuario_id, label: String(inst.instituicaoUsuario_id) };
        });
        _renderTagPicker('m-inst');
        _onInstChange('m-inst', _tp['m-inst'].selected);
    }

    // Restaurar tag pickers de categoria
    if (_tp['m-cat']) {
        _tp['m-cat'].selected = item.detalhe.categoriaUsuario_id.map(catId => {
            const opt = _tp['m-cat'].options.find(o => String(o.id) === String(catId));
            return opt || { id: catId, label: String(catId) };
        });
        _renderTagPicker('m-cat');
    }

    // Remover do lote e atualizar tabela
    lote.splice(i, 1);
    renderizarLote();

    // Scroll até o formulário
    const form = document.querySelector('#multiplosRegistros .multi-form');
    if (form) form.scrollIntoView({ behavior: 'smooth', block: 'start' });

    alerta('Registro movido para edição. Altere e clique em Adicionar.', 3000);
}

function salvarLote() {
    if (lote.length === 0) return alerta('Nenhum registro no lote');
    alerta(`Salvando ${lote.length} registro(s)...`, 0);
    const promessas = lote.map(item => MainAPI.registrarGasto({
        financeiro: item.financeiro,
        instituicao: item.instituicao,
        detalhe: item.detalhe
    }));
    Promise.all(promessas).then(respostas => {
        const erros = respostas.filter(r => !r.ok).length;
        if (erros === 0) {
            window.dispatchEvent(new Event('xp:refresh'));
            lote = [];
            renderizarLote();
            alerta(`${respostas.length} registro(s) salvos com sucesso!<br><button onclick="document.getElementById('div_alerta').style.display='none'">OK</button>`, 0);
        } else {
            alerta(`${erros} erro(s) ao salvar. Verifique e tente novamente.`);
        }
    }).catch(() => alerta('Erro ao conectar ao servidor'));
}

/* ══════════════════════════════════════════════════
   Troca de aba
══════════════════════════════════════════════════ */
function trocarFormulario(tela) {
    const cardUnico    = document.getElementById("cardUnico");
    const cardMultiplo = document.getElementById("multiplosRegistros");
    const tabUnico     = document.getElementById("tabUnico");
    const tabMultiplo  = document.getElementById("tabMultiplo");
    if (tela === "multiplosRegistros") {
        if (cardUnico)    cardUnico.style.display    = "none";
        if (cardMultiplo) cardMultiplo.style.display = "flex";
        if (tabUnico)     tabUnico.classList.remove("ativo");
        if (tabMultiplo)  tabMultiplo.classList.add("ativo");
    } else {
        if (cardUnico)    cardUnico.style.display    = "";
        if (cardMultiplo) cardMultiplo.style.display = "none";
        if (tabUnico)     tabUnico.classList.add("ativo");
        if (tabMultiplo)  tabMultiplo.classList.remove("ativo");
    }
}

/* Header titulos (mantido para compatibilidade) */
const titulos = document.querySelectorAll(".headerFormulario .titulo");
titulos.forEach(item => {
    item.addEventListener("click", () => {
        titulos.forEach(e => e.classList.remove("ativo"));
        item.classList.add("ativo");
    });
});

const _divAlerta = document.getElementById('div_alerta');
if (_divAlerta) _divAlerta.style.display = 'none';

// Máscara monetária (aplicada depois do DOM carregar via gerarInformacoes)
let dataGasto;
const usuarioLogado = JSON.parse(localStorage.getItem("usuarioLogado") || "null");
const userId = usuarioLogado ? usuarioLogado.id : null;
let _alertaTimer = null;

/* ══════════════════════════════════════════════════
   Alertas
══════════════════════════════════════════════════ */
function habilitarFecharAlertaAoClicarFora() {
    const divAl = document.getElementById("div_alerta");
    const contAl = document.getElementById("conteudoAlerta");
    if (!divAl || !contAl || divAl.dataset.closeOutsideBound === "1") return;
    divAl.dataset.closeOutsideBound = "1";
    divAl.addEventListener("click", (event) => {
        if (event.target === divAl) {
            divAl.style.display = "none";
            if (_alertaTimer) { clearTimeout(_alertaTimer); _alertaTimer = null; }
        }
    });
}

function alerta(texto, duracaoMs = 4000) {
    const divAl = document.getElementById("div_alerta");
    const contAl = document.getElementById("conteudoAlerta");
    habilitarFecharAlertaAoClicarFora();
    if (divAl) divAl.style.display = "flex";
    if (contAl) contAl.innerHTML = texto;
    if (_alertaTimer) clearTimeout(_alertaTimer);
    if (duracaoMs > 0) {
        _alertaTimer = setTimeout(() => {
            if (divAl) divAl.style.display = "none";
            _alertaTimer = null;
        }, duracaoMs);
    }
}

/* ══════════════════════════════════════════════════
   Clear-on-focus (campos mantidos após registro)
══════════════════════════════════════════════════ */
function setupClearOnFocus() {
    const ids = ['ipt_nome','ipt_valor','ipt_desc','ipt_multi_nome','ipt_multi_valor','ipt_multi_desc'];
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        el.addEventListener('focus', function () {
            if (this.dataset.pendingClear !== 'true') return;
            if (this.id === 'ipt_valor' || this.id === 'ipt_multi_valor') {
                if (window.MainAPI && window.MainAPI.resetarMascaraMoeda) {
                    window.MainAPI.resetarMascaraMoeda(this);
                } else {
                    this.value = '';
                }
            } else {
                this.value = '';
            }
            delete this.dataset.pendingClear;
            this.classList.remove('ar-field-submitted');
        });
    });
}

function markFieldsForClear(ids) {
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (el && el.value) {
            el.dataset.pendingClear = 'true';
            el.classList.add('ar-field-submitted');
        }
    });
}

/* ══════════════════════════════════════════════════
   Tag Picker system
══════════════════════════════════════════════════ */
const _tp = {}; // id -> { options, selected, placeholder, onchange }

function initTagPicker(id, options, placeholder, onchange) {
    if (_tp[id]) {
        // Reload: preserve selected, update options
        _tp[id].options = options;
        _tp[id].selected = _tp[id].selected.filter(s =>
            options.some(o => String(o.id) === String(s.id))
        );
        if (onchange) _tp[id].onchange = onchange;
    } else {
        _tp[id] = { options, selected: [], placeholder: placeholder || 'Selecionar...', onchange: onchange || null };
    }
    _renderTagPicker(id);
}

function openTagPicker(event, id) {
    event.stopPropagation();
    const dd = document.getElementById('tp-dd-' + id);
    const display = dd ? dd.previousElementSibling : null;
    if (!dd) return;
    const isOpen = dd.style.display !== 'none';
    // Close all
    document.querySelectorAll('.ar-tp-dd').forEach(el => {
        el.style.display = 'none';
        if (el.previousElementSibling) el.previousElementSibling.classList.remove('open');
    });
    if (!isOpen) {
        dd.style.display = '';
        if (display) display.classList.add('open');
    }
}

function _toggleTagItem(id, itemId, itemLabel) {
    const state = _tp[id];
    if (!state) return;
    const idx = state.selected.findIndex(s => String(s.id) === String(itemId));
    if (idx >= 0) {
        state.selected.splice(idx, 1);
    } else {
        state.selected.push({ id: itemId, label: itemLabel });
    }
    _renderTagPicker(id);
    if (state.onchange) state.onchange(state.selected);
}

function _removeTagItem(id, itemId) {
    const state = _tp[id];
    if (!state) return;
    state.selected = state.selected.filter(s => String(s.id) !== String(itemId));
    _renderTagPicker(id);
    if (state.onchange) state.onchange(state.selected);
}

function _renderTagPicker(id) {
    const state = _tp[id];
    const tagsEl = document.getElementById('tp-tags-' + id);
    const ddEl   = document.getElementById('tp-dd-'   + id);
    if (!tagsEl || !ddEl) return;

    // Tags display
    if (state.selected.length === 0) {
        tagsEl.innerHTML = `<span class="ar-tp-ph">${state.placeholder}</span>`;
    } else {
        tagsEl.innerHTML = state.selected.map(s =>
            `<span class="ar-tp-tag">${s.label}<button type="button" class="ar-tp-tag-rm"
                onclick="event.stopPropagation();_removeTagItem('${id}','${s.id}')">×</button></span>`
        ).join('');
    }

    // Dropdown options
    ddEl.innerHTML = '';
    state.options.forEach(opt => {
        const sel = state.selected.some(s => String(s.id) === String(opt.id));
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ar-tp-option' + (sel ? ' ar-tp-option-sel' : '');
        const check = document.createElement('span');
        check.className = 'ar-tp-opt-check';
        check.textContent = sel ? '✓' : '';
        btn.appendChild(check);
        btn.appendChild(document.createTextNode(opt.label));
        btn.addEventListener('click', e => {
            e.stopPropagation();
            _toggleTagItem(id, opt.id, opt.label);
        });
        ddEl.appendChild(btn);
    });

    // Botão "Criar novo" para pickers de inst e cat
    const _isInstPicker = (id === 'inst' || id === 'm-inst');
    const _isCatPicker  = (id === 'cat'  || id === 'm-cat');
    if (_isInstPicker || _isCatPicker) {
        const sep = document.createElement('div');
        sep.className = 'ar-tp-separator';
        ddEl.appendChild(sep);

        const newBtn = document.createElement('button');
        newBtn.type = 'button';
        newBtn.className = 'ar-tp-option ar-tp-new-btn';
        const newCheck = document.createElement('span');
        newCheck.className = 'ar-tp-opt-check ar-tp-new-icon';
        newCheck.textContent = '+';
        newBtn.appendChild(newCheck);
        newBtn.appendChild(document.createTextNode(
            _isInstPicker ? 'Nova instituição...' : 'Nova categoria...'
        ));
        newBtn.addEventListener('click', e => {
            e.stopPropagation();
            _abrirFormularioNova(id);
        });
        ddEl.appendChild(newBtn);
    }
}

// Close all dropdowns when clicking outside
document.addEventListener('click', () => {
    document.querySelectorAll('.ar-tp-dd').forEach(dd => {
        dd.style.display = 'none';
        if (dd.previousElementSibling) dd.previousElementSibling.classList.remove('open');
    });
});

/* ══════════════════════════════════════════════════
   Vincular / Criar inline de Instituição / Categoria
══════════════════════════════════════════════════ */

// Passo 1: mostra as disponíveis no banco que o usuário ainda não vinculou
async function _abrirFormularioNova(id) {
    const ddEl = document.getElementById('tp-dd-' + id);
    if (!ddEl) return;
    const isInst = (id === 'inst' || id === 'm-inst');

    ddEl.innerHTML = `<div class="ar-tp-new-form" style="text-align:center;padding:12px 0;">
        <span style="color:var(--cor-texto-secundario);font-size:0.88rem;">Carregando...</span>
    </div>`;

    try {
        let disponiveis = [];
        if (isInst) {
            const [todas, vinculadas] = await Promise.all([
                MainAPI.getTodasInstituicoes(),
                MainAPI.getInstituicoes(userId)
            ]);
            const vinculadasIds = new Set(vinculadas.map(v => String(v.intituicao?.id)));
            disponiveis = todas
                .filter(i => !vinculadasIds.has(String(i.id)))
                .map(i => ({ id: i.id, label: i.nome }));
        } else {
            const [todas, vinculadas] = await Promise.all([
                MainAPI.getTodasCategorias(),
                MainAPI.getTipos(userId)
            ]);
            const vinculadasIds = new Set(vinculadas.map(c => String(c.categoria?.id)));
            disponiveis = todas
                .filter(c => !vinculadasIds.has(String(c.id)))
                .map(c => ({ id: c.id, label: c.titulo }));
        }

        ddEl.innerHTML = '';

        if (disponiveis.length > 0) {
            const header = document.createElement('div');
            header.style.cssText = 'padding:6px 10px 2px;font-size:0.75rem;font-weight:700;color:var(--cor-texto-secundario);text-transform:uppercase;letter-spacing:0.5px;';
            header.textContent = isInst ? 'Vincular instituição existente' : 'Vincular categoria existente';
            ddEl.appendChild(header);

            disponiveis.forEach(item => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'ar-tp-option';
                const icon = document.createElement('span');
                icon.className = 'ar-tp-opt-check ar-tp-new-icon';
                icon.textContent = '+';
                btn.appendChild(icon);
                btn.appendChild(document.createTextNode(item.label));
                btn.addEventListener('click', async e => {
                    e.stopPropagation();
                    await _vincularESelecionarExistente(id, item.id, item.label, isInst);
                });
                ddEl.appendChild(btn);
            });

            const sep = document.createElement('div');
            sep.className = 'ar-tp-separator';
            ddEl.appendChild(sep);
        }

        // Botão criar nova (personalizada)
        const newBtn = document.createElement('button');
        newBtn.type = 'button';
        newBtn.className = 'ar-tp-option ar-tp-new-btn';
        const newIcon = document.createElement('span');
        newIcon.className = 'ar-tp-opt-check ar-tp-new-icon';
        newIcon.textContent = '+';
        newBtn.appendChild(newIcon);
        newBtn.appendChild(document.createTextNode(
            isInst ? 'Criar nova instituição...' : 'Criar nova categoria...'
        ));
        newBtn.addEventListener('click', e => { e.stopPropagation(); _mostrarFormCriarNova(id, isInst); });
        ddEl.appendChild(newBtn);

        // Botão voltar
        const backBtn = document.createElement('button');
        backBtn.type = 'button';
        backBtn.className = 'ar-tp-option';
        backBtn.style.cssText = 'color:var(--cor-texto-secundario);font-size:0.85rem;';
        backBtn.textContent = '← Voltar';
        backBtn.addEventListener('click', e => { e.stopPropagation(); _renderTagPicker(id); });
        ddEl.appendChild(backBtn);

    } catch (err) {
        console.error('[_abrirFormularioNova]', err);
        alerta('Erro ao carregar opções disponíveis');
        _renderTagPicker(id);
    }
}

// Passo 2a: vincular uma existente do banco e selecioná-la no picker
async function _vincularESelecionarExistente(id, globalId, label, isInst) {
    if (!userId) return alerta('Nenhum usuário logado');
    const ddEl = document.getElementById('tp-dd-' + id);
    if (ddEl) ddEl.innerHTML = `
        <div class="ar-tp-new-form" style="text-align:center;padding:14px 0;">
            <span style="color:var(--cor-principal);font-size:0.9rem;">
                Vinculando ${isInst ? 'instituição' : 'categoria'}...
            </span>
        </div>`;
    try {
        let novoId, novoLabel;
        if (isInst) {
            const res = await MainAPI.vincularInstituicaoUsuario(globalId, userId);
            if (!res.ok) { const c = await res.json().catch(()=>({})); throw new Error(c.message || `HTTP ${res.status}`); }
            const data = await res.json();
            novoId = data.id; novoLabel = data.intituicao?.nome || label;
        } else {
            const res = await MainAPI.vincularCategoriaUsuario(globalId, userId);
            if (!res.ok) { const c = await res.json().catch(()=>({})); throw new Error(c.message || `HTTP ${res.status}`); }
            const data = await res.json();
            novoId = data.id; novoLabel = data.categoria?.titulo || label;
        }
        const twin = id.startsWith('m-') ? id.slice(2) : 'm-' + id;
        [id, twin].forEach(pid => {
            const st = _tp[pid];
            if (!st) return;
            if (!st.options.some(o => String(o.id) === String(novoId)))
                st.options.push({ id: novoId, label: novoLabel });
        });
        _toggleTagItem(id, novoId, novoLabel);
        if (ddEl) ddEl.style.display = 'none';
        const display = ddEl ? ddEl.previousElementSibling : null;
        if (display) display.classList.remove('open');
        alerta(`✔ ${isInst ? 'Instituição' : 'Categoria'} "${novoLabel}" vinculada e selecionada!`, 3000);
    } catch (err) {
        console.error('[vincularESelecionarExistente]', err);
        alerta(`Erro ao vincular: ${err.message}`);
        _renderTagPicker(id);
    }
}

// Passo 2b: mostrar formulário para criar uma personalizada (não existe no banco)
function _mostrarFormCriarNova(id, isInst) {
    const ddEl = document.getElementById('tp-dd-' + id);
    if (!ddEl) return;
    const placeholder = isInst ? 'Nome da instituição' : 'Nome da categoria';
    const maxLen = isInst ? 50 : 30;

    ddEl.innerHTML = `
        <div class="ar-tp-new-form">
            <input type="text" id="tp-new-input-${id}"
                   class="ar-tp-new-input"
                   placeholder="${placeholder}"
                   maxlength="${maxLen}"
                   autocomplete="off">
            <div class="ar-tp-new-btns">
                <button type="button" class="ar-tp-new-confirm">Criar</button>
                <button type="button" class="ar-tp-new-cancel">← Voltar</button>
            </div>
        </div>`;

    const input = document.getElementById(`tp-new-input-${id}`);
    if (input) setTimeout(() => input.focus(), 50);

    ddEl.querySelector('.ar-tp-new-confirm').addEventListener('click', async e => {
        e.stopPropagation();
        const nome = input ? input.value.trim() : '';
        if (!nome) return alerta(isInst ? 'Digite o nome da instituição' : 'Digite o nome da categoria');
        await _criarESelecionarNova(id, nome);
    });
    ddEl.querySelector('.ar-tp-new-cancel').addEventListener('click', e => {
        e.stopPropagation();
        _abrirFormularioNova(id);
    });
    if (input) {
        input.addEventListener('keydown', async e => {
            e.stopPropagation();
            if (e.key === 'Enter') { const nome = input.value.trim(); if (nome) await _criarESelecionarNova(id, nome); }
            else if (e.key === 'Escape') _abrirFormularioNova(id);
        });
        input.addEventListener('click', e => e.stopPropagation());
    }
}

async function _criarESelecionarNova(id, nome) {
    if (!userId) return alerta('Nenhum usuário logado');

    const ddEl  = document.getElementById('tp-dd-' + id);
    const isInst = (id === 'inst' || id === 'm-inst');

    // Spinner enquanto cria
    if (ddEl) ddEl.innerHTML = `
        <div class="ar-tp-new-form" style="text-align:center;padding:14px 0;">
            <span style="color:var(--cor-principal);font-size:0.9rem;">
                Criando ${isInst ? 'instituição' : 'categoria'}...
            </span>
        </div>`;

    try {
        let novoId, novoLabel;

        if (isInst) {
            // 1. Criar a instituição global
            const resInst = await MainAPI.criarInstituicao(nome);
            if (!resInst.ok) {
                const corpo = await resInst.json().catch(() => ({}));
                throw new Error(corpo.message || `HTTP ${resInst.status}`);
            }
            const instData = await resInst.json();
            const instituicaoId = instData.id;

            // 2. Vincular ao usuário
            const resLink = await MainAPI.vincularInstituicaoUsuario(instituicaoId, userId);
            if (!resLink.ok) {
                const corpo = await resLink.json().catch(() => ({}));
                throw new Error(corpo.message || `HTTP ${resLink.status}`);
            }
            const linkData = await resLink.json();
            novoId    = linkData.id;                      // instUsuario_id
            novoLabel = linkData.intituicao?.nome || nome;

        } else {
            // Criar categoria e já associar ao usuário (atômico)
            const resCat = await MainAPI.adicionarTipo({ titulo: nome }, userId);
            if (!resCat.ok) {
                const corpo = await resCat.json().catch(() => ({}));
                throw new Error(corpo.message || `HTTP ${resCat.status}`);
            }
            const catData = await resCat.json();
            novoId    = catData.id;                       // categoriaUsuario_id
            novoLabel = catData.categoria?.titulo || nome;
        }

        // Adicionar às opções do picker atual e do picker irmão
        const twin = id.startsWith('m-') ? id.slice(2) : 'm-' + id;
        [id, twin].forEach(pickerId => {
            const st = _tp[pickerId];
            if (!st) return;
            if (!st.options.some(o => String(o.id) === String(novoId))) {
                st.options.push({ id: novoId, label: novoLabel });
            }
        });

        // Selecionar automaticamente no picker atual
        // (_toggleTagItem chama _renderTagPicker internamente e reconstrói o dropdown)
        _toggleTagItem(id, novoId, novoLabel);

        // Fechar dropdown (conteúdo já foi reconstruído pelo _renderTagPicker acima)
        if (ddEl) ddEl.style.display = 'none';
        const display = ddEl ? ddEl.previousElementSibling : null;
        if (display) display.classList.remove('open');

        alerta(`✔ ${isInst ? 'Instituição' : 'Categoria'} "${novoLabel}" criada e selecionada!`, 3000);

    } catch (err) {
        console.error('[criarESelecionarNova]', err);
        alerta(`Erro ao criar ${isInst ? 'instituição' : 'categoria'}: ${err.message}`);
        _renderTagPicker(id); // Restaura o dropdown normal
    }
}

/* ── Institution amounts handler ── */
function _onInstChange(pickerId, selected) {
    const amountsId   = pickerId === 'inst' ? 'inst-amounts'   : 'm-inst-amounts';
    const wrapValorId = pickerId === 'inst' ? 'wrap_valor'      : 'wrap_multi_valor';

    const amountsEl   = document.getElementById(amountsId);
    const wrapValorEl = document.getElementById(wrapValorId);

    if (selected.length > 1) {
        // Esconde o campo de valor único
        if (wrapValorEl) wrapValorEl.style.display = 'none';

        // Mostra painel de valor por instituição
        if (amountsEl) {
            amountsEl.style.display = '';
            // Mantém o título, remove linhas antigas
            while (amountsEl.children.length > 1) amountsEl.removeChild(amountsEl.lastChild);
            selected.forEach(s => {
                const row = document.createElement('div');
                row.className = 'ar-inst-amount-row';
                const nameEl = document.createElement('span');
                nameEl.className = 'ar-inst-name';
                nameEl.textContent = s.label;
                const inp = document.createElement('input');
                inp.type = 'text';
                inp.id = `inst-amt-${pickerId}-${s.id}`;
                inp.className = 'ar-inst-amt-input';
                inp.setAttribute('inputmode', 'numeric');
                inp.setAttribute('autocomplete', 'off');
                row.appendChild(nameEl);
                row.appendChild(inp);
                amountsEl.appendChild(row);
                // Aplica máscara APÓS o elemento estar no DOM
                if (window.MainAPI && window.MainAPI.aplicarMascaraMoeda) {
                    window.MainAPI.aplicarMascaraMoeda(inp);
                }
            });
        }
    } else {
        // Mostra o campo de valor único novamente
        if (wrapValorEl) wrapValorEl.style.display = '';

        // Esconde painel de valor por instituição
        if (amountsEl) {
            amountsEl.style.display = 'none';
            while (amountsEl.children.length > 1) amountsEl.removeChild(amountsEl.lastChild);
        }
    }

    // Saldo display (formulário único apenas)
    if (pickerId === 'inst') {
        if (selected.length === 1) {
            atualizarSaldoDisplay(selected[0].id);
        } else {
            const saldoEl = document.getElementById('saldo_display');
            if (saldoEl) saldoEl.style.display = 'none';
        }
    }
}

/* ══════════════════════════════════════════════════
   Recurring section
══════════════════════════════════════════════════ */
let _isRecorrente = false;
let _periodicidade = null;
let _diasSemana    = [];
let _diaMes        = null;
let _mesAnual      = null;
let _diaAnual      = null;
let _dataFimRecorrente = null;

// Mapeamento: índice do botão DOM (0=Dom, 1=Seg, …, 6=Sáb) → DayOfWeek do Java
const _DOW_MAP = ['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'];
const _DOW_LABEL = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const _MESES_LABEL = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

function _atualizarResumoRecorrencia() {
    const el = document.getElementById('ar-recorrente-resumo');
    if (!el) return;
    if (!_isRecorrente || !_periodicidade) { el.style.display = 'none'; el.textContent = ''; return; }
    const partes = [_periodicidade.charAt(0).toUpperCase() + _periodicidade.slice(1)];
    if (_periodicidade === 'semanal' && _diasSemana.length > 0)
        partes.push(_diasSemana.map(d => _DOW_LABEL[d]).join(', '));
    if (_periodicidade === 'mensal' && _diaMes)
        partes.push(`Dia ${_diaMes}`);
    if (_periodicidade === 'anual') {
        if (_mesAnual) partes.push(_MESES_LABEL[_mesAnual - 1]);
        if (_diaAnual) partes.push(`Dia ${_diaAnual}`);
    }
    if (_dataFimRecorrente) partes.push(`até ${_dataFimRecorrente.split('-').reverse().join('/')}`);
    el.textContent = partes.join(' · ');
    el.style.display = '';
}

function toggleRecorrente() {
    _isRecorrente = !_isRecorrente;
    if (!_isRecorrente) {
        _periodicidade = null; _diasSemana = []; _diaMes = null; _mesAnual = null; _diaAnual = null; _dataFimRecorrente = null;
        const fim = document.getElementById('rec-data-fim');
        if (fim) fim.value = '';
        _atualizarResumoRecorrencia();
    }    const btn  = document.getElementById('ar-recorrente-btn');
    const icon = document.getElementById('ar-recorrente-icon');
    const opts = document.getElementById('recurring-options');
    if (btn)  btn.classList.toggle('active', _isRecorrente);
    if (icon) icon.style.display = _isRecorrente ? '' : 'none';
    if (opts) opts.style.display = _isRecorrente ? '' : 'none';
    if (!_isRecorrente) {
        ['rec-semanal','rec-mensal','rec-anual'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });
        document.querySelectorAll('.ar-pill[data-period]').forEach(p => p.classList.remove('active'));
    }
}

function setPeriodicity(p) {
    _periodicidade = p;
    _diasSemana = []; _diaMes = null; _mesAnual = null; _diaAnual = null;
    document.querySelectorAll('.ar-pill[data-period]').forEach(pill =>
        pill.classList.toggle('active', pill.dataset.period === p)
    );
    document.getElementById('rec-semanal').style.display = p === 'semanal' ? '' : 'none';
    document.getElementById('rec-mensal').style.display  = p === 'mensal'  ? '' : 'none';
    document.getElementById('rec-anual').style.display   = p === 'anual'   ? '' : 'none';
    document.querySelectorAll('.ar-pill[data-day]').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#rec-mensal-days .ar-pill').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#rec-anual-months .ar-pill').forEach(p => p.classList.remove('active'));
    _atualizarResumoRecorrencia();
}

function toggleWeekDay(day) {
    const idx = _diasSemana.indexOf(day);
    if (idx >= 0) _diasSemana.splice(idx, 1); else _diasSemana.push(day);
    const pill = document.querySelector(`.ar-pill[data-day="${day}"]`);
    if (pill) pill.classList.toggle('active', _diasSemana.includes(day));
    _atualizarResumoRecorrencia();
}

function setMonthDay(day) {
    _diaMes = (_diaMes === day) ? null : day;
    document.querySelectorAll('#rec-mensal-days .ar-pill').forEach(p =>
        p.classList.toggle('active', Number(p.dataset.monthday) === _diaMes)
    );
    _atualizarResumoRecorrencia();
}

function setAnnualMonth(month) {
    _mesAnual = (_mesAnual === month) ? null : month;
    document.querySelectorAll('#rec-anual-months .ar-pill').forEach(p =>
        p.classList.toggle('active', Number(p.dataset.annualmonth) === _mesAnual)
    );
    _atualizarResumoRecorrencia();
}

function _initRecurringSubOptions() {
    // Monthly days 1-31
    const mensal = document.getElementById('rec-mensal-days');
    if (mensal && mensal.children.length === 0) {
        for (let d = 1; d <= 31; d++) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'ar-pill ar-pill-sm';
            btn.dataset.monthday = d;
            btn.textContent = d;
            btn.addEventListener('click', () => setMonthDay(d));
            mensal.appendChild(btn);
        }
    }
    // Annual months
    const MONTHS = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
    const anualMonths = document.getElementById('rec-anual-months');
    if (anualMonths && anualMonths.children.length === 0) {
        MONTHS.forEach((m, i) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'ar-pill';
            btn.dataset.annualmonth = i + 1;
            btn.textContent = m;
            btn.addEventListener('click', () => setAnnualMonth(i + 1));
            anualMonths.appendChild(btn);
        });
    }
    // Annual day select
    const anualDay = document.getElementById('rec-anual-day');
    if (anualDay && anualDay.options.length <= 1) {
        for (let d = 1; d <= 31; d++) {
            const opt = document.createElement('option');
            opt.value = d; opt.textContent = `Dia ${d}`;
            anualDay.appendChild(opt);
        }
        anualDay.addEventListener('change', () => { _diaAnual = anualDay.value ? parseInt(anualDay.value) : null; });
    }

    // Campo de data final da recorrência — mesmo estilo da tela de filtros (dd/mm/aaaa)
    const recurringOpts = document.getElementById('recurring-options');
    if (recurringOpts && !document.getElementById('rec-data-fim')) {
        const grp = document.createElement('div');
        grp.className = 'ar-recurring-group';
        grp.id = 'rec-data-fim-group';
        grp.innerHTML = `
            <span class="ar-group-label">Data final da recorrência</span>
            <div style="margin-top:6px;display:flex;align-items:center;gap:8px;">
                <input type="text" id="rec-data-fim" class="ar-select-small"
                       placeholder="dd/mm/aaaa" maxlength="10" inputmode="numeric"
                       style="min-width:180px;max-width:220px;cursor:text;">
            </div>
        `;
        recurringOpts.appendChild(grp);

        const inputDataFim = document.getElementById('rec-data-fim');
        // Aplica a mesma máscara usada no filtro de registros
        if (window.MainAPI && window.MainAPI.aplicarMascaraData) {
            window.MainAPI.aplicarMascaraData(inputDataFim);
        }
        // Converte dd/mm/aaaa → aaaa-mm-dd para o backend
        inputDataFim.addEventListener('input', function () {
            _dataFimRecorrente = (window.MainAPI && window.MainAPI.dataParaISO)
                ? window.MainAPI.dataParaISO(this.value)
                : null;
            _atualizarResumoRecorrencia();
        });
    }
} // fim _initRecurringSubOptions

/* ══════════════════════════════════════════════════
   Painel de Poupança (Caixinha)
══════════════════════════════════════════════════ */
let _caixinhas = [];
let _caixinhaSelecionadaId = null;

async function _carregarCaixinhas() {
    if (!userId) return;
    try {
        _caixinhas = await MainAPI.getCaixinhas(userId);
    } catch (e) {
        _caixinhas = [];
    }
}

function _renderPainelPoupanca(show) {
    let painel = document.getElementById('ar-poupanca-painel');
    if (!show) {
        if (painel) painel.style.display = 'none';
        _caixinhaSelecionadaId = null;
        return;
    }
    if (!painel) {
        // Cria o painel dinamicamente na primeira vez
        painel = document.createElement('div');
        painel.id = 'ar-poupanca-painel';
        painel.className = 'ar-recurring-wrap ar-span-3';
        // Insere após o bloco de tipo de movimento
        const movWrap = document.getElementById('select_movimento')?.closest('.ar-field-wrap');
        if (movWrap && movWrap.parentNode) {
            movWrap.parentNode.insertBefore(painel, movWrap.nextSibling);
        }
    }
    painel.style.display = '';

    if (_caixinhas.length === 0) {
        painel.innerHTML = `
            <div style="background:var(--cor-tinte-suave);border-radius:12px;padding:14px 16px;border:1px solid var(--cor-tinte-borda);">
                <p style="margin:0;color:var(--cor-texto-secundario);font-size:0.92rem;">
                    <i class='bx bx-info-circle' style="color:var(--cor-principal);"></i>
                    Nenhuma caixinha ativa encontrada. 
                    <strong>Registre o aporte mesmo assim</strong> — ele aparecerá como Poupança sem caixinha vinculada.
                </p>
            </div>`;
        _caixinhaSelecionadaId = null;
        return;
    }

    const opts = _caixinhas.map(c => {
        const pct   = c.percentualAtingido != null ? `${c.percentualAtingido.toFixed(1)}%` : '—';
        const prazo = c.dataPrazo ? ` · prazo ${c.dataPrazo}` : '';
        return `<option value="${c.id}">${c.nome} (${pct} atingido${prazo})</option>`;
    }).join('');

    painel.innerHTML = `
        <div style="background:var(--cor-tinte-suave);border-radius:12px;padding:14px 16px;border:1px solid var(--cor-tinte-borda);display:flex;flex-direction:column;gap:10px;">
            <span style="font-size:0.82rem;font-weight:700;color:var(--cor-texto-secundario);text-transform:uppercase;letter-spacing:0.5px;">Vincular a uma Caixinha</span>
            <select id="ar-select-caixinha" style="background:var(--cor-fundo-card);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:8px 12px;color:var(--cor-texto-principal);font-size:0.95rem;">
                <option value="">Sem caixinha (aporte avulso)</option>
                ${opts}
            </select>
            <div id="ar-caixinha-info" style="display:none;font-size:0.87rem;color:var(--cor-texto-secundario);line-height:1.6;padding:8px 10px;background:var(--cor-fundo-campo);border-radius:8px;"></div>
        </div>`;

    document.getElementById('ar-select-caixinha').addEventListener('change', function () {
        _caixinhaSelecionadaId = this.value || null;
        const info = document.getElementById('ar-caixinha-info');
        if (!_caixinhaSelecionadaId) { info.style.display = 'none'; return; }
        const cx = _caixinhas.find(c => c.id === _caixinhaSelecionadaId);
        if (!cx) { info.style.display = 'none'; return; }
        const fmt = v => v != null ? `R$ ${Number(v).toFixed(2)}` : '—';
        const pct = cx.percentualAtingido != null ? `${cx.percentualAtingido.toFixed(1)}%` : '—';
        info.style.display = '';
        info.innerHTML = `
            <b>${cx.nome}</b><br>
            Meta: <b>${fmt(cx.valorMeta)}</b> · Acumulado: <b>${fmt(cx.valorAtual)}</b> (${pct})<br>
            ${cx.aporteMensalSugerido != null ? `Aporte mensal sugerido: <b style="color:var(--cor-principal)">${fmt(cx.aporteMensalSugerido)}</b>` : ''}
            ${cx.mesesRestantes != null ? ` · ${cx.mesesRestantes} meses restantes` : ''}`;
    });
}

function _onTipoChange() {
    const tipo = document.getElementById('select_tipo')?.value;
    _renderPainelPoupanca(tipo === 'Poupanca');
    _renderPainelEmprestimo(tipo === 'Emprestimo');
    _renderPainelTransferencia(tipo === 'Transferencia');

    // Para Empréstimo, força parcelas sempre visíveis independente do movimento
    if (tipo === 'Emprestimo') {
        const wrap = document.getElementById('wrap_parcelas');
        if (wrap) wrap.style.display = '';
    }
}

/* ══════════════════════════════════════════════════
   Inicialização
══════════════════════════════════════════════════ */
function gerarInformacoes() {
    // Init tag pickers (empty – options loaded async)
    initTagPicker('inst',   [], 'Escolha instituições...', sel => _onInstChange('inst',   sel));
    initTagPicker('cat',    [], 'Escolha categorias...',   null);
    initTagPicker('m-inst', [], 'Escolha...',              sel => _onInstChange('m-inst', sel));
    initTagPicker('m-cat',  [], 'Escolha...',              null);

    // Apply money mask
    const iV  = document.getElementById('ipt_valor');
    const imV = document.getElementById('ipt_multi_valor');
    if (iV  && window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(iV);
    if (imV && window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(imV);

    // Recurring sub-option builders
    _initRecurringSubOptions();

    // Clear-on-focus for text fields
    setupClearOnFocus();

    // Poupança: carrega caixinhas e escuta mudança de tipo
    _carregarCaixinhas();
    const selectTipo = document.getElementById('select_tipo');
    if (selectTipo) selectTipo.addEventListener('change', _onTipoChange);

    // Atualiza saldo display quando o tipo de movimento muda
    // (crédito mostra limite disponível; débito mostra saldo de caixa)
    const selectMov = document.getElementById('select_movimento');
    if (selectMov) selectMov.addEventListener('change', () => {
        const selectedInst = _tp['inst']?.selected || [];
        if (selectedInst.length === 1) atualizarSaldoDisplay(selectedInst[0].id);
    });

    // Load data from API
    gerarCategorias();
    gerarInstituicao();
}

async function atualizarSaldoDisplay(instituicaoUsuarioId) {
    const el = document.getElementById('saldo_display');
    if (!el) return;
    if (!instituicaoUsuarioId || instituicaoUsuarioId === '#') { el.style.display = 'none'; return; }
    try {
        const res = await fetch(`http://localhost:8080/instituicoes/saldo/${Number(instituicaoUsuarioId)}`);
        if (!res.ok) { el.style.display = 'none'; return; }
        const saldo = await res.json();
        const valor = Number(saldo);
        el.textContent = `Saldo disponível: R$ ${valor.toFixed(2)}`;
        // Usa variáveis CSS para cores de saldo
        el.style.color = valor <= 0 ? 'var(--red-700)' : 'var(--cor-principal)';
        el.style.display = '';
    } catch (e) { el.style.display = 'none'; }
}

function toggleParcelas(inputId, movimento) {
    const requer = movimento === 'Credito' || movimento === 'Boleto';
    const wrapId = inputId === 'ipt_parcelas' ? 'wrap_parcelas' : 'wrap_multi_parcelas';
    const wrap  = document.getElementById(wrapId);
    const input = document.getElementById(inputId);
    if (wrap)  wrap.style.display  = requer ? '' : 'none';
    if (input && !requer) input.value = '1';
}

function gerarCategorias() {
    if (!userId) return;
    MainAPI.getTipos(userId)
        .then(json => {
            const options = json.map(c => ({ id: c.id, label: c.categoria.titulo }));
            initTagPicker('cat',   options, 'Escolha categorias...');
            initTagPicker('m-cat', options, 'Escolha...');
        })
        .catch(() => alerta("Não foi possível carregar as categorias. Tente novamente."));
}

const gerarTipos = gerarCategorias;

async function gerarInstituicao() {
    if (!userId) return;
    try {
        const json = await MainAPI.getInstituicoes(userId);
        const options = json.map(i => ({ id: i.id, label: i.intituicao.nome }));
        initTagPicker('inst',   options, 'Escolha instituições...', sel => _onInstChange('inst',   sel));
        initTagPicker('m-inst', options, 'Escolha...',              sel => _onInstChange('m-inst', sel));
        // Atualiza também o picker de destino se já existir
        if (_tp['dest']) initTagPicker('dest', options, 'Escolha a instituição destino...');
    } catch (e) {
        alerta("Não foi possível carregar as instituições. Tente novamente.");
    }
}

/* ══════════════════════════════════════════════════
   Registrar (formulário único)
══════════════════════════════════════════════════ */
async function registrar() {
    const valorInput = document.getElementById('ipt_valor');
    const valor      = window.MainAPI ? window.MainAPI.obterValorMoeda(valorInput) : Number(valorInput.value);
    const titulo     = document.getElementById('ipt_nome').value;
    const tipo       = document.getElementById('select_tipo').value;
    const descRaw    = document.getElementById('ipt_desc').value;
    const Desc       = descRaw || 'Nenhuma descrição fornecida';
    const movimento  = document.getElementById('select_movimento').value;
    const parcelas   = Number(document.getElementById('ipt_parcelas').value) || 1;
    const data       = dataGasto;

    const selectedInst = _tp['inst'] ? _tp['inst'].selected : [];
    const selectedCat  = _tp['cat']  ? _tp['cat'].selected  : [];

    // Para Empréstimo: parcelas obrigatório, taxa opcional
    const taxaEmprestimo = tipo === 'Emprestimo'
        ? (Number(document.getElementById('ar-emprestimo-taxa')?.value) || 0)
        : null;

    // Para Transferência: instituição destino obrigatória
    const selectedDest = _tp['dest'] ? _tp['dest'].selected : [];

    if (!data || data === 0)         return alerta("Data inválida");
    if (!titulo)                     return alerta("Título inválido");
    if (tipo === '#')                return alerta("Escolha o tipo do evento");
    if (selectedCat.length === 0)    return alerta("Escolha uma categoria");
    if (selectedInst.length === 0)   return alerta("Escolha uma instituição");
    if (movimento === '#')           return alerta("Escolha o tipo de movimento");
    if ((movimento === 'Credito' || movimento === 'Boleto') && (parcelas < 1 || isNaN(parcelas)))
        return alerta("Informe a quantidade de parcelas (mínimo 1)");
    if (tipo === 'Emprestimo' && (parcelas < 1 || isNaN(parcelas)))
        return alerta("Informe a quantidade de parcelas do empréstimo (mínimo 1)");
    if (tipo === 'Transferencia' && selectedDest.length === 0)
        return alerta("Escolha a instituição de destino para a transferência");

    // Validação de valor: quando múltiplas instituições o campo único fica oculto
    if (selectedInst.length <= 1) {
        if (valor <= 0 || !valor) return alerta("Valor inválido");
    } else {
        const algumValor = selectedInst.some(s => {
            const ai = document.getElementById(`inst-amt-inst-${s.id}`);
            return ai && (window.MainAPI ? window.MainAPI.obterValorMoeda(ai) : 0) > 0;
        });
        if (!algumValor) return alerta("Informe o valor para cada instituição");
    }

    // Verificar saldo quando o tipo exige débito (exceto crédito, que não debita imediatamente)
    // Usa saldo-debito para não considerar o limite de crédito em transações de débito
    if ((tipo === 'Gasto' || tipo === 'Transferencia') && selectedInst.length === 1 && movimento !== 'Credito') {
        try {
            const resSaldo = await fetch(`http://localhost:8080/instituicoes/saldo-debito/${Number(selectedInst[0].id)}`);
            if (resSaldo.ok) {
                const saldo = await resSaldo.json();
                if (Number(saldo) < valor)
                    return alerta(`Saldo insuficiente. Disponível: R$ ${Number(saldo).toFixed(2)}`);
            }
        } catch (e) { console.warn("Não foi possível verificar saldo:", e); }
    }

    // Montar lista de instituições (com valor individual quando múltiplas)
    const instituicaoList = selectedInst.map(s => {
        let instValor = valor;
        if (selectedInst.length > 1) {
            const amtInput = document.getElementById(`inst-amt-inst-${s.id}`);
            if (amtInput) {
                const v = window.MainAPI ? window.MainAPI.obterValorMoeda(amtInput) : Number(amtInput.value);
                if (v > 0) instValor = v;
            }
        }
        return { instituicaoUsuario_id: Number(s.id), tipoMovimento: movimento, valor: instValor, parcelas };
    });

    // Para Transferência: adiciona destino como segunda instituição
    if (tipo === 'Transferencia' && selectedDest.length > 0) {
        const dest = selectedDest[0];
        instituicaoList.push({ instituicaoUsuario_id: Number(dest.id), tipoMovimento: movimento, valor, parcelas: 1 });
    }

    // Quando múltiplas instituições, valor total = soma dos valores individuais
    const valorTotal = selectedInst.length > 1
        ? instituicaoList.filter(i => !selectedDest.some(d => Number(d.id) === i.instituicaoUsuario_id))
              .reduce((acc, i) => acc + i.valor, 0)
        : valor;

    // Dados de recorrência — se ativada, usa endpoint /registros/recorrente
    if (_isRecorrente) {
        // Validações extras de recorrência
        if (tipo !== 'Gasto' && tipo !== 'Recebimento')
            return alerta("Recorrência disponível apenas para Gasto e Recebimento");
        if (!_periodicidade)
            return alerta("Escolha a periodicidade da recorrência");
        if (_periodicidade === 'semanal' && _diasSemana.length === 0)
            return alerta("Escolha pelo menos um dia da semana");
        if (_periodicidade === 'mensal' && !_diaMes)
            return alerta("Escolha o dia do mês");
        if (_periodicidade === 'anual' && (!_mesAnual || !_diaAnual))
            return alerta("Escolha o mês e o dia do ano");
        if (!_dataFimRecorrente)
            return alerta("Informe a data final da recorrência");

        // Capitalizar primeira letra do periodicidade (ex: 'semanal' → 'Semanal')
        const periodicidade = _periodicidade.charAt(0).toUpperCase() + _periodicidade.slice(1);

        // Mapear índices numéricos para DayOfWeek Java
        const diasDaSemana = _diasSemana.map(n => _DOW_MAP[n]);

        // Dia do mês ou do ano
        const dia = _diaMes || _diaAnual || null;

        alerta(`Registrando recorrência...
            <div class="glaceonCorrendoDiv">
                <img class="glaceon correndo" src="/assets/gif/glaceon-correndo-unscreen.gif" alt="">
            </div>`, 0);

        MainAPI.registrarRecorrente({
            financeiro: {
                usuario_id: userId,
                tipo,
                valor: valorTotal,
                descricao: Desc,
                dataEvento: data,          // data de início
                periodicidade,             // Diario | Semanal | Mensal | Anual
                diasDaSemana,              // ["MONDAY", "FRIDAY", ...]
                dia,                       // dia do mês ou do ano
                dataFim: _dataFimRecorrente, // data final
                intervalo: 1
            },
            instituicao: instituicaoList,
            detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo }
        }).then(async (response) => {
            if (response.ok) {
                window.dispatchEvent(new Event('xp:refresh'));
                markFieldsForClear(['ipt_nome', 'ipt_valor', 'ipt_desc']);
                alerta('✔ Recorrência registrada com sucesso!', 3000);
            } else {
                let detalhe = "";
                try { const corpo = await response.json(); detalhe = corpo.message || corpo.error || JSON.stringify(corpo); }
                catch (_) { detalhe = `HTTP ${response.status}`; }
                alerta(`Erro ao registrar recorrência (${response.status}): ${detalhe}`);
            }
        }).catch(err => {
            console.error("Erro de rede:", err);
            alerta("Erro de conexão ao registrar recorrência.");
        });
        return; // não continua para o registro normal
    }

    alerta(`Registrando...
        <div class="glaceonCorrendoDiv">
            <img class="glaceon correndo" src="/assets/gif/glaceon-correndo-unscreen.gif" alt="">
        </div>`, 0);

    MainAPI.registrarGasto({
        financeiro: {
            usuario_id: userId,
            tipo,
            valor: valorTotal,
            descricao: Desc,
            dataEvento: data,
            ...(tipo === 'Poupanca' && _caixinhaSelecionadaId ? { caixinha_id: _caixinhaSelecionadaId } : {}),
            ...(tipo === 'Emprestimo' && taxaEmprestimo != null ? { taxaRendimento: taxaEmprestimo } : {})
        },
        instituicao: instituicaoList,
        detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo }
    }).then(async (response) => {
        if (response.ok) {
            window.dispatchEvent(new Event('xp:refresh'));
            if (selectedInst.length === 1) atualizarSaldoDisplay(selectedInst[0].id);
            // Manter campos – marcar para limpar ao clicar
            markFieldsForClear(['ipt_nome', 'ipt_valor', 'ipt_desc']);
            alerta('✔ Registro realizado com sucesso!<br><small>Clique nos campos de texto para editá-los.</small>', 3000);
        } else {
            let detalhe = "";
            try { const corpo = await response.json(); detalhe = corpo.message || corpo.error || JSON.stringify(corpo); }
            catch (_) { detalhe = `HTTP ${response.status}`; }
            alerta(`Erro ao registrar (${response.status}): ${detalhe}`);
        }
    }).catch(err => {
        console.error("Erro de rede:", err);
        alerta("Erro de conexão ao registrar.");
    });
}

function atualizarSaldo(valor, instituicao) {
    MainAPI.atualizarSaldo({ valorServer: valor, instituicaoServer: instituicao })
        .then(resposta => {
            if (!resposta.ok) console.error("Erro ao atualizar saldo", resposta);
        });
}

function adicionarTipos() {
    if (!userId) return alerta(`Nenhum usuário logado. <button onclick='div_alerta.style.display="none"'>OK</button>`);
    const titulo = document.getElementById("ipt_tituloTipo").value.trim();
    if (!titulo) return alerta(`Digite um nome para o tipo <button onclick='div_alerta.style.display="none"'>OK</button>`);
    MainAPI.adicionarTipo({ titulo }, userId).then(resposta => {
        if (resposta.ok) {
            gerarTipos();
            adicionarTipo.close();
            alerta(`Tipo adicionado com sucesso!<br><button onclick="div_alerta.style.display='none'">OK</button>`);
        } else {
            alerta(`Houve um erro ao adicionar tipo <button onclick='div_alerta.style.display="none"'>OK</button>`);
        }
    }).catch(() => alerta(`Erro ao conectar ao servidor. <button onclick='div_alerta.style.display="none"'>OK</button>`));
}

/* ══════════════════════════════════════════════════
   Calendário
══════════════════════════════════════════════════ */
const btnAbrir    = document.getElementById("calendario");
const modal       = document.getElementById("modal");
const fechar      = document.getElementById("fechar");
const dias        = document.getElementById("dias");
const mesAno      = document.getElementById("mesAno");
const gastosDoDia = document.getElementById("gastosDoDia");
const confirmar   = document.getElementById("confirmar");
const btnAnterior = document.getElementById("btnAnterior");
const btnProximo  = document.getElementById("btnProximo");

let dataSelecionada = null;
let hoje     = new Date();
let mesAtual = hoje.getMonth();
let anoAtual = hoje.getFullYear();
let modalAbertoPor = 'single';
let lote = [];

// O botão #calendario abre o modal para selecionar a data do evento único
btnAbrir.onclick = () => { modalAbertoPor = 'single'; modal.style.display = "flex"; };

function abrirCalendarioMulti() { modalAbertoPor = 'multi'; modal.style.display = 'flex'; }
fechar.onclick    = () => modal.style.display = "none";
btnAnterior.onclick = () => {
    mesAtual--; if (mesAtual < 0) { mesAtual = 11; anoAtual--; } gerarCalendario();
};
btnProximo.onclick = () => {
    mesAtual++; if (mesAtual > 11) { mesAtual = 0; anoAtual++; } gerarCalendario();
};

async function buscarGastosDia(dataSelecionada) {
    const json = await MainAPI.buscarRegistrosPorData(userId, dataSelecionada);
    let listaGastos = [];
    for (let c = 0; c < json.length; c++) {
        const data = new Date(json[c].dataGasto);
        if (data.toISOString().split("T")[0] === dataSelecionada) listaGastos.push(json[c]);
    }
    return listaGastos;
}

function gerarCalendario() {
    dias.innerHTML = "";
    let primeiroDia = new Date(anoAtual, mesAtual, 1).getDay();
    let totalDias   = new Date(anoAtual, mesAtual + 1, 0).getDate();
    mesAno.innerText = new Date(anoAtual, mesAtual).toLocaleString("pt-BR", { month: "long", year: "numeric" });
    for (let i = 0; i < primeiroDia; i++) dias.innerHTML += `<span></span>`;
    for (let dia = 1; dia <= totalDias; dia++) {
        let dataFormatada = `${anoAtual}-${String(mesAtual + 1).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
        let span = document.createElement("span");
        span.innerText = dia;
        span.onclick = () => selecionarDia(dataFormatada, span);
        dias.appendChild(span);
    }
}

async function selecionarDia(data, elemento) {
    dataSelecionada = data;
    document.querySelectorAll(".diaSelecionado").forEach(e => e.classList.remove("diaSelecionado"));
    elemento.classList.add("diaSelecionado");
    confirmar.disabled = false;
    try {
        const listaGastos = await buscarGastosDia(data);
        const gastosDia = document.getElementById('gastosDia');
        if (listaGastos.length > 0) {
            const dataRegistro = listaGastos[0].eventoFinanceiro?.dataEvento ?? listaGastos[0].dataGasto;
            const novaData     = new Date(dataRegistro);
            const dataFmt = isNaN(novaData.getTime()) ? formatarDataBR(data) : novaData.toLocaleDateString("pt-BR");
            gastosDia.innerHTML = `<b>Gastos de ${dataFmt}:</b><br>`;
            listaGastos.forEach(g => {
                const titulo = g.gastoDetalhe?.tituloGasto ?? g.tituloGasto;
                const valor  = g.eventoFinanceiro?.valor ?? g.valor;
                gastosDia.innerHTML += `<b>${titulo} - R$${valor}</b><br>`;
            });
        } else {
            gastosDia.innerHTML = "<i>Nenhum gasto neste dia.</i>";
        }
    } catch (e) {
        const gastosDia = document.getElementById('gastosDia');
        if (gastosDia) gastosDia.innerHTML = "";
    }
}

confirmar.onclick = () => {
    modal.style.display = "none";
    const dataFormatada = formatarDataBR(dataSelecionada);
    if (modalAbertoPor === 'multi') {
        const label  = document.getElementById('multi_data_label');
        const hidden = document.getElementById('multi_data');
        if (label)  { label.textContent = "Dia: " + dataFormatada; label.classList.remove('hidden'); label.style.display = ''; }
        if (hidden) hidden.value = dataSelecionada;
    } else {
        const dataEl = document.getElementById('data');
        if (dataEl) { dataEl.style.display = ''; dataEl.textContent = dataFormatada; dataEl.classList.remove('hidden'); }
        dataGasto = dataSelecionada;
    }
};

gerarCalendario();

function formatarDataBR(dataISO) {
    const [ano, mes, dia] = dataISO.split("-");
    return `${dia}/${mes}/${ano}`;
}

/* ══════════════════════════════════════════════════
   Múltiplos Registros
══════════════════════════════════════════════════ */
function adicionarAoLote() {
    const titulo    = document.getElementById('ipt_multi_nome').value.trim();
    const tipo      = document.getElementById('multi_select_tipo').value;
    const movimento = document.getElementById('multi_select_movimento').value;
    const parcelas  = Number(document.getElementById('ipt_multi_parcelas').value) || 1;
    const valorInput = document.getElementById('ipt_multi_valor');
    const valor     = window.MainAPI ? window.MainAPI.obterValorMoeda(valorInput) : Number(valorInput.value);
    const descRaw   = document.getElementById('ipt_multi_desc').value.trim();
    const desc      = descRaw || 'Nenhuma descrição fornecida';
    const data      = document.getElementById('multi_data').value;

    const selectedInst = _tp['m-inst'] ? _tp['m-inst'].selected : [];
    const selectedCat  = _tp['m-cat']  ? _tp['m-cat'].selected  : [];

    if (!titulo)                   return alerta('Título inválido');
    if (tipo === '#')              return alerta('Escolha o tipo do evento');
    if (selectedCat.length === 0)  return alerta('Escolha uma categoria');
    if (selectedInst.length === 0) return alerta('Escolha uma instituição');
    if (movimento === '#')         return alerta('Escolha o tipo de movimento');
    if ((movimento === 'Credito' || movimento === 'Boleto') && (parcelas < 1 || isNaN(parcelas)))
        return alerta('Informe a quantidade de parcelas (mínimo 1)');
    if (!data)                      return alerta('Escolha uma data');

    // Validação de valor: múltiplas instituições têm campos próprios
    if (selectedInst.length <= 1) {
        if (valor <= 0 || isNaN(valor)) return alerta('Valor inválido');
    } else {
        const algumValor = selectedInst.some(s => {
            const ai = document.getElementById(`inst-amt-m-inst-${s.id}`);
            return ai && (window.MainAPI ? window.MainAPI.obterValorMoeda(ai) : 0) > 0;
        });
        if (!algumValor) return alerta('Informe o valor para cada instituição');
    }

    const instituicaoList = selectedInst.map(s => {
        let instValor = valor;
        if (selectedInst.length > 1) {
            const amtInput = document.getElementById(`inst-amt-m-inst-${s.id}`);
            if (amtInput) {
                const v = window.MainAPI ? window.MainAPI.obterValorMoeda(amtInput) : Number(amtInput.value);
                if (v > 0) instValor = v;
            }
        }
        return { instituicaoUsuario_id: Number(s.id), tipoMovimento: movimento, valor: instValor, parcelas };
    });

    const valorTotal = selectedInst.length > 1
        ? instituicaoList.reduce((acc, i) => acc + i.valor, 0)
        : valor;

    lote.push({
        financeiro: { usuario_id: userId, tipo, valor: valorTotal, descricao: desc, dataEvento: data },
        instituicao: instituicaoList,
        detalhe: { categoriaUsuario_id: selectedCat.map(s => Number(s.id)), tituloGasto: titulo },
        _display: {
            titulo, tipo, movimento,
            instNome: selectedInst.map(s => s.label).join(', '),
            categorias: selectedCat.map(s => s.label).join(', '),
            valor: valorTotal
        }
    });

    renderizarLote();

    // Manter campos – marcar para limpar ao clicar
    markFieldsForClear(['ipt_multi_nome', 'ipt_multi_valor', 'ipt_multi_desc']);
}

function renderizarLote() {
    const tbody = document.getElementById('corpoLote');
    if (lote.length === 0) {
        tbody.innerHTML = `<tr id="loteVazio"><td colspan="6" class="ar-lote-vazio">Nenhum registro adicionado ainda.</td></tr>`;
        return;
    }
    tbody.innerHTML = '';
    lote.forEach((item, i) => {
        const d = item._display;
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td>${d.titulo}</td>
            <td>${d.tipo}</td>
            <td>${d.movimento}</td>
            <td>${d.instNome}</td>
            <td>R$ ${d.valor.toFixed(2)}</td>
            <td>
                <div class="ar-lote-actions">
                    <button class="ar-lote-btn edit" onclick="editarDoLote(${i})" title="Editar">✏</button>
                    <button class="ar-lote-btn delete" onclick="removerDoLote(${i})" title="Remover">✕</button>
                </div>
            </td>`;
        tbody.appendChild(tr);
    });
}

function removerDoLote(i) {
    lote.splice(i, 1);
    renderizarLote();
}

function editarDoLote(i) {
    const item = lote[i];
    const d    = item._display;

    // Preencher campos do formulário
    document.getElementById('ipt_multi_nome').value = d.titulo;
    document.getElementById('multi_select_tipo').value = item.financeiro.tipo || '#';
    document.getElementById('multi_select_movimento').value = item.instituicao[0]?.tipoMovimento || '#';
    toggleParcelas('ipt_multi_parcelas', item.instituicao[0]?.tipoMovimento || '#');

    const valInput = document.getElementById('ipt_multi_valor');
    valInput.value = d.valor.toFixed(2).replace('.', ',');
    // Reaplica máscara se disponível
    if (window.MainAPI?.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(valInput);

    document.getElementById('ipt_multi_desc').value =
        item.financeiro.descricao !== 'Nenhuma descrição fornecida' ? item.financeiro.descricao : '';

    // Restaurar tag pickers de instituição
    if (_tp['m-inst']) {
        _tp['m-inst'].selected = item.instituicao.map(inst => {
            const opt = _tp['m-inst'].options.find(o => String(o.id) === String(inst.instituicaoUsuario_id));
            return opt || { id: inst.instituicaoUsuario_id, label: String(inst.instituicaoUsuario_id) };
        });
        _renderTagPicker('m-inst');
        _onInstChange('m-inst', _tp['m-inst'].selected);
    }

    // Restaurar tag pickers de categoria
    if (_tp['m-cat']) {
        _tp['m-cat'].selected = item.detalhe.categoriaUsuario_id.map(catId => {
            const opt = _tp['m-cat'].options.find(o => String(o.id) === String(catId));
            return opt || { id: catId, label: String(catId) };
        });
        _renderTagPicker('m-cat');
    }

    // Remover do lote e atualizar tabela
    lote.splice(i, 1);
    renderizarLote();

    // Scroll até o formulário
    const form = document.querySelector('#multiplosRegistros .multi-form');
    if (form) form.scrollIntoView({ behavior: 'smooth', block: 'start' });

    alerta('Registro movido para edição. Altere e clique em Adicionar.', 3000);
}

function salvarLote() {
    if (lote.length === 0) return alerta('Nenhum registro no lote');
    alerta(`Salvando ${lote.length} registro(s)...`, 0);
    const promessas = lote.map(item => MainAPI.registrarGasto({
        financeiro: item.financeiro,
        instituicao: item.instituicao,
        detalhe: item.detalhe
    }));
    Promise.all(promessas).then(respostas => {
        const erros = respostas.filter(r => !r.ok).length;
        if (erros === 0) {
            window.dispatchEvent(new Event('xp:refresh'));
            lote = [];
            renderizarLote();
            alerta(`${respostas.length} registro(s) salvos com sucesso!<br><button onclick="document.getElementById('div_alerta').style.display='none'">OK</button>`, 0);
        } else {
            alerta(`${erros} erro(s) ao salvar. Verifique e tente novamente.`);
        }
    }).catch(() => alerta('Erro ao conectar ao servidor'));
}

/* ══════════════════════════════════════════════════
   Troca de aba
══════════════════════════════════════════════════ */
function trocarFormulario(tela) {
    const cardUnico    = document.getElementById("cardUnico");
    const cardMultiplo = document.getElementById("multiplosRegistros");
    const tabUnico     = document.getElementById("tabUnico");
    const tabMultiplo  = document.getElementById("tabMultiplo");
    if (tela === "multiplosRegistros") {
        if (cardUnico)    cardUnico.style.display    = "none";
        if (cardMultiplo) cardMultiplo.style.display = "flex";
        if (tabUnico)     tabUnico.classList.remove("ativo");
        if (tabMultiplo)  tabMultiplo.classList.add("ativo");
    } else {
        if (cardUnico)    cardUnico.style.display    = "";
        if (cardMultiplo) cardMultiplo.style.display = "none";
        if (tabUnico)     tabUnico.classList.add("ativo");
        if (tabMultiplo)  tabMultiplo.classList.remove("ativo");
    }
}

/* Header titulos (mantido para compatibilidade) */
const titulos = document.querySelectorAll(".headerFormulario .titulo");
titulos.forEach(item => {
    item.addEventListener("click", () => {
        titulos.forEach(e => e.classList.remove("ativo"));
        item.classList.add("ativo");
    });
});

/* ═══════════════════════════════════════════════════════════════
   caixinhas.js — Lógica completa da tela de Poupança/Caixinhas
   ═══════════════════════════════════════════════════════════════ */

'use strict';

// ── Estado ────────────────────────────────────────────────────
let _usuario        = null;
let _caixinhas      = [];          // cache de todas as caixinhas carregadas
let _filtroAtivo    = 'ativas';    // 'ativas' | 'encerradas' | 'todas'
let _caixinhaAtual  = null;        // caixinha aberta no modal de detalhes
let _editandoId     = null;        // id sendo editado (null = criar)
let _tipoRendimento = 'CDI';       // tipo selecionado no form
let _instsSelecionadas = new Set(); // ids de instituicaoUsuario selecionados
let _todasInstituicoes = [];       // lista de instituições do usuário

// ── Defaults de taxa por tipo ──────────────────────────────────
const TAXA_DEFAULTS = {
    CDI:          10.40,
    SELIC:        10.75,
    POUPANCA:     10.75,
    PREFIXADO:    null,
    PERSONALIZADO: null
};

// ════════════════════════════════════════════════════════════════
// INIT
// ════════════════════════════════════════════════════════════════
async function iniciarPagina() {
    // Recuperar usuário logado
    _usuario = JSON.parse(localStorage.getItem('usuarioLogado') || 'null');
    if (!_usuario || !_usuario.id) {
        window.location.href = 'index.html';
        return;
    }

    // Aplicar tema do localStorage
    const temaSalvo = localStorage.getItem('tema');
    const modoSalvo = localStorage.getItem('modo');
    if (temaSalvo) document.body.setAttribute('data-tema', temaSalvo);
    if (modoSalvo) document.body.setAttribute('data-mode', modoSalvo);

    // Aplicar máscara de moeda
    MainAPI.aplicarMascaraMoeda(document.getElementById('inputValorMeta'));
    // Aplicar máscara de data
    MainAPI.aplicarMascaraData(document.getElementById('inputDataPrazo'));

    // Carregar dados em paralelo
    await Promise.all([
        carregarKPIs(),
        carregarCaixinhas(_filtroAtivo),
        carregarInstituicoes()
    ]);
}

// ════════════════════════════════════════════════════════════════
// KPIs
// ════════════════════════════════════════════════════════════════
async function carregarKPIs() {
    const uid = _usuario.id;
    try {
        const [resTA, resPG, resRM, resST] = await Promise.allSettled([
            MainAPI.request(`/caixinhas/kpi/total-acumulado/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/progresso-geral/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/rendimento-estimado-mes/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/status/usuarios/${uid}`).then(r => r.ok ? r.json() : null)
        ]);

        // KPI 1 — Total Acumulado
        if (resTA.status === 'fulfilled' && resTA.value) {
            document.getElementById('kpiTotalAcumulado').textContent = formatarMoeda(resTA.value.totalAcumulado ?? 0);
            document.getElementById('kpiQtdAtivas').textContent = `${resTA.value.quantidadeAtivas ?? 0} caixinha(s) ativa(s)`;
        }

        // KPI 2 — Progresso Geral
        if (resPG.status === 'fulfilled' && resPG.value) {
            const pg = resPG.value;
            const pct = pg.percentualGeral ?? 0;
            document.getElementById('kpiProgressoPct').textContent = `${pct.toFixed(1)}%`;
            document.getElementById('kpiProgressoSub').textContent = 'da meta total atingida';

            // Atualizar barra consolidada
            const fillPct = Math.min(100, pct);
            document.getElementById('cxhProgressoFill').style.width = `${fillPct}%`;
            document.getElementById('cxhProgressoPctBar').textContent = `${pct.toFixed(1)}%`;
            document.getElementById('cxhProgressoValAtual').textContent = `${formatarMoeda(pg.totalAcumulado ?? 0)} acumulados`;
            document.getElementById('cxhProgressoValMeta').textContent = `Meta: ${formatarMoeda(pg.totalMetas ?? 0)}`;
        }

        // KPI 3 — Rendimento Estimado
        if (resRM.status === 'fulfilled' && resRM.value) {
            document.getElementById('kpiRendimento').textContent = formatarMoeda(resRM.value.rendimentoEstimadoMes ?? 0);
        }

        // KPI 4 — Status
        if (resST.status === 'fulfilled' && resST.value) {
            const st = resST.value;
            document.getElementById('kpiStatusAtivas').textContent = `${st.quantidadeAtivas ?? 0} ativas`;
            document.getElementById('kpiStatusSub').textContent = `${st.quantidadeEncerradas ?? 0} encerradas`;
        }
    } catch (e) {
        console.error('Erro ao carregar KPIs:', e);
    }
}

// ════════════════════════════════════════════════════════════════
// CAIXINHAS
// ════════════════════════════════════════════════════════════════
async function carregarCaixinhas(filtro) {
    _filtroAtivo = filtro;
    mostrarLoading(true);

    try {
        const uid = _usuario.id;
        let endpoint;
        if (filtro === 'ativas') {
            endpoint = `/caixinhas/ativas/usuarios/${uid}`;
        } else {
            endpoint = `/caixinhas/usuarios/${uid}`;
        }

        const res = await MainAPI.request(endpoint);
        if (res.status === 204) {
            _caixinhas = [];
        } else if (res.ok) {
            _caixinhas = await res.json();
            if (!Array.isArray(_caixinhas)) _caixinhas = [];
        } else {
            _caixinhas = [];
        }

        // Filtrar encerradas no cliente quando necessário
        let lista = _caixinhas;
        if (filtro === 'encerradas') {
            lista = _caixinhas.filter(c => !c.isAtiva);
        }

        renderizarCards(lista);
        mostrarInsight(lista);
    } catch (e) {
        console.error('Erro ao carregar caixinhas:', e);
        _caixinhas = [];
        renderizarCards([]);
    } finally {
        mostrarLoading(false);
    }
}

function mostrarLoading(show) {
    document.getElementById('cxhLoading').style.display = show ? 'flex' : 'none';
    if (show) {
        document.getElementById('cxhGrid').style.display = 'none';
        document.getElementById('cxhVazio').style.display = 'none';
        document.getElementById('cxhInsight').style.display = 'none';
    }
}

function renderizarCards(lista) {
    const grid  = document.getElementById('cxhGrid');
    const vazio = document.getElementById('cxhVazio');

    if (!lista || lista.length === 0) {
        grid.style.display  = 'none';
        vazio.style.display = 'flex';
        return;
    }

    vazio.style.display = 'none';
    grid.style.display  = 'grid';

    grid.innerHTML = lista.map(c => gerarCardHTML(c)).join('');

    // Adicionar listeners de clique
    grid.querySelectorAll('.cxh-card').forEach(card => {
        const id = card.dataset.id;
        card.addEventListener('click', () => {
            const caixinha = _caixinhas.find(c => c.id === id)
                || lista.find(c => c.id === id);
            if (caixinha) abrirModalDetalhes(caixinha);
        });
    });
}

function gerarCardHTML(c) {
    const pct     = Math.min(100, c.percentualAtingido ?? 0);
    const atingida = pct >= 100;
    const tipo    = c.tipoRendimento || 'CDI';
    const encerrada = !c.isAtiva;

    const alcancavel = c.metaAlcancavel;
    const alcancavelHTML = typeof alcancavel === 'boolean'
        ? `<span class="cxh-card-meta-alcancavel ${alcancavel ? '' : 'nao'}">
               <i class='bx ${alcancavel ? 'bx-check-circle' : 'bx-x-circle'}'></i>
               ${alcancavel ? 'Meta alcançável' : 'Aporte insuficiente'}
           </span>`
        : '';

    const mesesTxt = c.mesesRestantes != null ? `${c.mesesRestantes} meses restantes` : '–';
    const prazoTxt = c.dataPrazo ? formatarData(c.dataPrazo) : '–';

    return `
    <div class="cxh-card ${encerrada ? 'encerrada' : ''}" data-id="${c.id}">
        <div class="cxh-card-header">
            <div>
                <div class="cxh-card-nome">${escHtml(c.nome)}</div>
                ${c.descricao ? `<div class="cxh-card-desc">${escHtml(c.descricao)}</div>` : ''}
            </div>
            <span class="cxh-badge cxh-badge-${tipo}">${labelTipo(tipo)}</span>
        </div>

        <div class="cxh-card-valores">
            <span class="cxh-card-valor-atual">${formatarMoeda(c.valorAtual ?? 0)}</span>
            <span class="cxh-card-meta">/ ${formatarMoeda(c.valorMeta ?? 0)}</span>
        </div>

        <div>
            <div class="cxh-card-progress-track">
                <div class="cxh-card-progress-fill ${atingida ? 'atingida' : ''}" style="width:${pct}%"></div>
            </div>
            <div class="cxh-card-progress-info">
                <span class="cxh-card-pct">${pct.toFixed(1)}%</span>
                <span>${mesesTxt}</span>
            </div>
        </div>

        <div class="cxh-card-footer">
            ${alcancavelHTML}
            <span>${prazoTxt}</span>
        </div>
    </div>`;
}

// ════════════════════════════════════════════════════════════════
// FILTROS / ABAS
// ════════════════════════════════════════════════════════════════
function trocarFiltro(filtro, btnEl) {
    document.querySelectorAll('.cxh-filtro-btn').forEach(b => b.classList.remove('ativo'));
    btnEl.classList.add('ativo');
    carregarCaixinhas(filtro);
}

// ════════════════════════════════════════════════════════════════
// MODAL DETALHES
// ════════════════════════════════════════════════════════════════
function abrirModalDetalhes(c) {
    _caixinhaAtual = c;
    const encerrada = !c.isAtiva;

    // Cabeçalho
    document.getElementById('detNome').textContent    = c.nome;
    document.getElementById('detDesc').textContent    = c.descricao || '';
    document.getElementById('detBadge').className     = `cxh-badge cxh-badge-${c.tipoRendimento || 'CDI'}`;
    document.getElementById('detBadge').textContent   = labelTipo(c.tipoRendimento);
    document.getElementById('detStatusBadge').innerHTML = encerrada
        ? `<span style="font-size:0.7rem;font-weight:700;padding:3px 9px;border-radius:12px;background:var(--cor-fundo-inativo);color:var(--cor-texto-secundario);">Encerrada</span>`
        : `<span style="font-size:0.7rem;font-weight:700;padding:3px 9px;border-radius:12px;background:var(--green-100);color:var(--green-700);">Ativa</span>`;

    // Stats
    document.getElementById('detValorAtual').textContent  = formatarMoeda(c.valorAtual ?? 0);
    document.getElementById('detMeta').textContent        = formatarMoeda(c.valorMeta ?? 0);
    document.getElementById('detFalta').textContent       = formatarMoeda(c.faltaParaMeta ?? 0);
    const pct = c.percentualAtingido ?? 0;
    document.getElementById('detPct').textContent         = `${pct.toFixed(1)}%`;
    document.getElementById('detMeses').textContent       = c.mesesRestantes != null ? `${c.mesesRestantes} meses` : '–';
    document.getElementById('detPrazo').textContent       = c.dataPrazo ? formatarData(c.dataPrazo) : '–';
    document.getElementById('detAporte').textContent      = c.aporteMensalSugerido != null ? formatarMoeda(c.aporteMensalSugerido) : '–';
    document.getElementById('detTaxaMensal').textContent  = c.taxaMensalEfetiva != null
        ? `${(c.taxaMensalEfetiva * 100).toFixed(4)}% a.m.`
        : '–';

    // Barra de progresso
    const fillPct = Math.min(100, pct);
    document.getElementById('detProgressoFill').style.width = `${fillPct}%`;
    document.getElementById('detPctBar').textContent = `${pct.toFixed(1)}%`;

    // Meta alcançável
    const alcDiv = document.getElementById('detAlcancavel');
    if (typeof c.metaAlcancavel === 'boolean') {
        alcDiv.innerHTML = `
            <span class="cxh-det-alcancavel ${c.metaAlcancavel ? '' : 'nao'}">
                <i class='bx ${c.metaAlcancavel ? 'bx-check-circle' : 'bx-x-circle'}'></i>
                ${c.metaAlcancavel ? 'Meta alcançável com aportes sugeridos' : 'Meta pode não ser atingida com os aportes atuais'}
            </span>`;
    } else {
        alcDiv.innerHTML = '';
    }

    // Projeção
    document.getElementById('detProjecao').innerHTML = gerarTextoProjecao(c);

    // Instituições
    const instLista = document.getElementById('detInstLista');
    const instSection = document.getElementById('detInstSection');
    if (c.instituicoes && c.instituicoes.length > 0) {
        instSection.style.display = '';
        instLista.innerHTML = c.instituicoes.map(inst =>
            `<div class="cxh-det-inst-item">
                <span class="cxh-det-inst-nome"><i class='bx bx-buildings'></i> ${escHtml(inst.nome || 'Instituição')}</span>
                <span class="cxh-det-inst-val">${formatarMoeda(inst.valorAportado ?? 0)}</span>
            </div>`
        ).join('');
    } else {
        instSection.style.display = 'none';
    }

    // Botões: desabilitar encerrar se já encerrada
    document.getElementById('btnDetEncerrar').disabled = encerrada;
    document.getElementById('btnDetEncerrar').style.opacity = encerrada ? '0.4' : '1';

    document.getElementById('modalDetOverlay').classList.add('aberto');
}

function fecharModalDet() {
    document.getElementById('modalDetOverlay').classList.remove('aberto');
    _caixinhaAtual = null;
}

function fecharModalDetOutside(e) {
    if (e.target === document.getElementById('modalDetOverlay')) fecharModalDet();
}

function gerarTextoProjecao(c) {
    const semAportes = c.montanteProjetadoSemAportes;
    const comAportes = c.montanteProjetadoComAportes;
    const aporte     = c.aporteMensalSugerido;
    const meses      = c.mesesRestantes;
    const taxa       = c.taxaMensalEfetiva;

    // Calcular projeção localmente se os dados do servidor estiverem ausentes
    const r = taxa != null ? taxa : 0;
    const n = meses != null ? meses : 0;
    const VA = c.valorAtual ?? 0;

    // Projeção sem aportes: VA * (1+r)^n
    const projSemAp = semAportes != null ? semAportes : (r > 0 ? VA * Math.pow(1 + r, n) : VA);
    // Projeção com aportes sugeridos
    const ap = aporte != null ? aporte : 0;
    const projComAp = comAportes != null ? comAportes
        : (r > 0 ? projSemAp + ap * ((Math.pow(1 + r, n) - 1) / r)
                 : projSemAp + ap * n);

    return `
        <strong>Sem novos aportes:</strong> você terá <strong>${formatarMoeda(projSemAp)}</strong> no prazo.<br>
        <strong>Com aporte de ${formatarMoeda(ap)}/mês:</strong> você terá <strong>${formatarMoeda(projComAp)}</strong>.<br>
        <strong>Meta:</strong> ${formatarMoeda(c.valorMeta ?? 0)}&nbsp;·&nbsp;
        <strong>Falta:</strong> ${formatarMoeda(c.faltaParaMeta ?? 0)}&nbsp;·&nbsp;
        <strong>Taxa mensal:</strong> ${r > 0 ? (r * 100).toFixed(4) + '% a.m.' : 'sem rendimento definido'}
    `;
}

// ── Ações do modal de detalhes ─────────────────────────────────
function editarCaixinhaAtual() {
    if (!_caixinhaAtual) return;
    const c = _caixinhaAtual; // salva referência ANTES de fechar (fecharModalDet zera _caixinhaAtual)
    fecharModalDet();
    abrirModalEditar(c);
}

async function encerrarCaixinhaAtual() {
    if (!_caixinhaAtual) return;
    const c = _caixinhaAtual;
    if (!confirm(`Encerrar a caixinha "${c.nome}"? Esta ação não pode ser desfeita.`)) return;
    fecharModalDet();
    await encerrarCaixinha(c.id);
}

async function deletarCaixinhaAtual() {
    if (!_caixinhaAtual) return;
    const c = _caixinhaAtual;
    if (!confirm(`Deletar permanentemente a caixinha "${c.nome}"? Esta ação não pode ser desfeita.`)) return;
    fecharModalDet();
    await deletarCaixinha(c.id);
}

// ════════════════════════════════════════════════════════════════
// MODAL CRIAR / EDITAR
// ════════════════════════════════════════════════════════════════
function abrirModalCriar() {
    _editandoId = null;
    document.getElementById('modalCriarTitulo').innerHTML = "<i class='bx bx-plus-circle'></i> Nova Caixinha";
    resetarFormulario();
    document.getElementById('modalCriarOverlay').classList.add('aberto');
    validarBotaoSalvar();
}

function abrirModalEditar(c) {
    _editandoId = c.id;
    document.getElementById('modalCriarTitulo').innerHTML = "<i class='bx bx-edit'></i> Editar Caixinha";
    preencherFormulario(c);
    document.getElementById('modalCriarOverlay').classList.add('aberto');
    validarBotaoSalvar();
}

function fecharModalCriar() {
    document.getElementById('modalCriarOverlay').classList.remove('aberto');
}

function fecharModalCriarOutside(e) {
    if (e.target === document.getElementById('modalCriarOverlay')) fecharModalCriar();
}

function resetarFormulario() {
    document.getElementById('inputNome').value        = '';
    document.getElementById('inputDescricao').value   = '';
    MainAPI.resetarMascaraMoeda(document.getElementById('inputValorMeta'));
    document.getElementById('inputDataPrazo').value   = '';
    document.getElementById('inputPctRendimento').value  = '';
    document.getElementById('inputTaxaRef').value        = '';
    document.getElementById('inputTaxaRefPoupanca').value = '';
    document.getElementById('inputTaxaAnual').value      = '';
    _instsSelecionadas.clear();
    selecionarTipoRendimento('CDI');
    renderizarInstituicoes();
    document.getElementById('taxaResumo').style.display = 'none';
}

function preencherFormulario(c) {
    document.getElementById('inputNome').value      = c.nome || '';
    document.getElementById('inputDescricao').value = c.descricao || '';

    // Valor meta
    const inputMeta = document.getElementById('inputValorMeta');
    const centavos  = Math.round((c.valorMeta ?? 0) * 100);
    inputMeta.dataset.centavos = String(centavos);
    const reais = Math.floor(centavos / 100);
    const cts   = String(centavos % 100).padStart(2, '0');
    const reaisStr = String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    inputMeta.value = `R$ ${reaisStr},${cts}`;

    // Data prazo — backend pode retornar string "aaaa-mm-dd" ou array [ano, mes, dia]
    if (c.dataPrazo) {
        let iso = c.dataPrazo;
        if (Array.isArray(iso) && iso.length >= 3) {
            iso = `${iso[0]}-${String(iso[1]).padStart(2,'0')}-${String(iso[2]).padStart(2,'0')}`;
        }
        document.getElementById('inputDataPrazo').value = MainAPI.dataDeISO(String(iso));
    }

    // Tipo de rendimento
    const tipo = c.tipoRendimento || 'CDI';
    selecionarTipoRendimento(tipo);

    if (tipo === 'CDI' || tipo === 'SELIC') {
        document.getElementById('inputPctRendimento').value  = c.percentualRendimento ?? 100;
        document.getElementById('inputTaxaRef').value        = c.taxaReferenciaAtual ?? TAXA_DEFAULTS[tipo];
    } else if (tipo === 'POUPANCA') {
        document.getElementById('inputTaxaRefPoupanca').value = c.taxaReferenciaAtual ?? TAXA_DEFAULTS.POUPANCA;
    } else {
        document.getElementById('inputTaxaAnual').value = c.taxaAnualPersonalizada ?? '';
    }

    calcularTaxaEfetiva();

    // Instituições
    _instsSelecionadas.clear();
    if (c.instituicoes && Array.isArray(c.instituicoes)) {
        c.instituicoes.forEach(inst => {
            // inst.id pode ser o id da vinculação (instituicaoUsuarioId)
            _instsSelecionadas.add(inst.id);
        });
    }
    renderizarInstituicoes();
}

// ── Tipo de rendimento ─────────────────────────────────────────
function selecionarTipoRendimento(tipo) {
    _tipoRendimento = tipo;

    // Atualizar botões
    document.querySelectorAll('.cxh-rend-btn').forEach(btn => {
        btn.className = 'cxh-rend-btn';
        if (btn.dataset.tipo === tipo) btn.classList.add(`ativo-${tipo}`);
    });

    // Mostrar campos corretos
    ['camposCdiSelic', 'camposPoupanca', 'camposPrefixado'].forEach(id => {
        document.getElementById(id).classList.remove('visivel');
    });

    if (tipo === 'CDI' || tipo === 'SELIC') {
        document.getElementById('camposCdiSelic').classList.add('visivel');
        const lbl = document.getElementById('labelPctCdi');
        const lbl2 = document.getElementById('labelTaxaRef');
        lbl.textContent  = tipo === 'CDI' ? '% do CDI' : '% da SELIC';
        lbl2.textContent = tipo === 'CDI' ? 'Taxa CDI atual (% a.a.)' : 'Taxa SELIC atual (% a.a.)';
        // Preencher default se vazio
        const inp = document.getElementById('inputTaxaRef');
        if (!inp.value) inp.value = TAXA_DEFAULTS[tipo];
        const inpPct = document.getElementById('inputPctRendimento');
        if (!inpPct.value) inpPct.value = 100;
    } else if (tipo === 'POUPANCA') {
        document.getElementById('camposPoupanca').classList.add('visivel');
        const inp = document.getElementById('inputTaxaRefPoupanca');
        if (!inp.value) inp.value = TAXA_DEFAULTS.POUPANCA;
    } else {
        document.getElementById('camposPrefixado').classList.add('visivel');
    }

    calcularTaxaEfetiva();
}

// ── Calcular taxa efetiva ──────────────────────────────────────
function calcularTaxaEfetiva() {
    const tipo = _tipoRendimento;
    let taxaAnual = 0;

    if (tipo === 'CDI' || tipo === 'SELIC') {
        const pct     = parseFloat(document.getElementById('inputPctRendimento').value) || 100;
        const taxaRef = parseFloat(document.getElementById('inputTaxaRef').value) || 0;
        taxaAnual = taxaRef * (pct / 100);
    } else if (tipo === 'POUPANCA') {
        const taxaRef = parseFloat(document.getElementById('inputTaxaRefPoupanca').value) || 0;
        taxaAnual = taxaRef * 0.70;
    } else {
        taxaAnual = parseFloat(document.getElementById('inputTaxaAnual').value) || 0;
    }

    const taxaMensal = taxaAnual > 0 ? (Math.pow(1 + taxaAnual / 100, 1 / 12) - 1) * 100 : 0;

    const resumo = document.getElementById('taxaResumo');
    const txt    = document.getElementById('taxaResumoTexto');

    if (taxaAnual > 0) {
        resumo.style.display = 'flex';
        txt.innerHTML = `Taxa efetiva: <strong>${taxaAnual.toFixed(2)}% a.a.</strong> · <strong>${taxaMensal.toFixed(4)}% a.m.</strong>`;

        // Verificar alcançabilidade em tempo real
        const meta    = MainAPI.obterValorMoeda(document.getElementById('inputValorMeta'));
        const prazoTxt = document.getElementById('inputDataPrazo').value;
        if (meta > 0 && prazoTxt && prazoTxt.length === 10) {
            const prazoISO = MainAPI.dataParaISO(prazoTxt);
            if (prazoISO) {
                const hoje    = new Date();
                const prazo   = new Date(prazoISO);
                const diffMs  = prazo - hoje;
                const meses   = Math.max(0, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 30.4)));
                if (meses > 0) {
                    const r   = taxaMensal / 100;
                    const VA  = 0; // sem valor atual inicial no form
                    const projSem = r > 0 ? VA * Math.pow(1 + r, meses) : VA;
                    const aporteNecessario = r > 0
                        ? ((meta - projSem) * r) / (Math.pow(1 + r, meses) - 1)
                        : (meta - projSem) / meses;
                    if (aporteNecessario > 0) {
                        txt.innerHTML += ` · Aporte necessário: <strong>${formatarMoeda(aporteNecessario)}/mês</strong> por <strong>${meses} meses</strong>`;
                    }
                }
            }
        }
    } else {
        resumo.style.display = 'none';
    }
}

// ── Instituições ───────────────────────────────────────────────
async function carregarInstituicoes() {
    try {
        _todasInstituicoes = await MainAPI.getInstituicoes(_usuario.id);
        if (!Array.isArray(_todasInstituicoes)) _todasInstituicoes = [];
        renderizarInstituicoes();
    } catch (e) {
        console.error('Erro ao carregar instituições:', e);
        _todasInstituicoes = [];
    }
}

function renderizarInstituicoes() {
    const grid = document.getElementById('instGrid');
    if (_todasInstituicoes.length === 0) {
        grid.innerHTML = '<span style="font-size:0.82rem;color:var(--cor-texto-secundario);">Nenhuma instituição vinculada. <a href="configurações.html" style="color:var(--cor-principal);">Configurar</a></span>';
        return;
    }

    grid.innerHTML = _todasInstituicoes.map(inst => {
        const selecionada = _instsSelecionadas.has(inst.id);
        return `
        <div class="cxh-inst-item ${selecionada ? 'selecionada' : ''}" 
             data-instid="${inst.id}"
             onclick="toggleInstituicao(${inst.id}, this)">
            <span class="cxh-inst-check">${selecionada ? '✓' : ''}</span>
            <span>${escHtml(inst.intituicao?.nome || inst.instituicao?.nome || inst.nomeInstituicao || inst.nome || `Inst. ${inst.id}`)}</span>
        </div>`;
    }).join('');
}

function toggleInstituicao(instId, el) {
    if (_instsSelecionadas.has(instId)) {
        _instsSelecionadas.delete(instId);
        el.classList.remove('selecionada');
        el.querySelector('.cxh-inst-check').textContent = '';
    } else {
        _instsSelecionadas.add(instId);
        el.classList.add('selecionada');
        el.querySelector('.cxh-inst-check').textContent = '✓';
    }
    validarBotaoSalvar();
}

// ── Validar botão salvar ───────────────────────────────────────
function validarBotaoSalvar() {
    const nome    = (document.getElementById('inputNome').value || '').trim();
    const temInst = _instsSelecionadas.size > 0;
    const btn     = document.getElementById('btnSalvarCaixinha');
    const aviso   = document.getElementById('instAviso');

    btn.disabled = !(nome && temInst);
    if (aviso) aviso.style.display = (!temInst && nome) ? '' : 'none';
}

// ════════════════════════════════════════════════════════════════
// SALVAR (POST / PUT)
// ════════════════════════════════════════════════════════════════
async function salvarCaixinha() {
    const nome     = document.getElementById('inputNome').value.trim();
    const descricao = document.getElementById('inputDescricao').value.trim();
    const valorMeta = MainAPI.obterValorMoeda(document.getElementById('inputValorMeta'));
    const prazoTxt  = document.getElementById('inputDataPrazo').value;
    const tipo      = _tipoRendimento;

    if (!nome) { mostrarToast('Informe o nome da caixinha.', 'erro'); return; }
    if (_instsSelecionadas.size === 0) { mostrarToast('Selecione ao menos uma instituição.', 'erro'); return; }

    // Montar payload
    const payload = {
        usuarioId:    _usuario.id,
        nome,
        descricao:    descricao || null,
        valorMeta:    valorMeta > 0 ? valorMeta : null,
        dataPrazo:    prazoTxt ? MainAPI.dataParaISO(prazoTxt) : null,
        tipoRendimento: tipo,
        isCompartilhada: false,
        instituicaoUsuarioIds: Array.from(_instsSelecionadas)
    };

    // Campos condicionais de rendimento
    if (tipo === 'CDI' || tipo === 'SELIC') {
        payload.percentualRendimento  = parseFloat(document.getElementById('inputPctRendimento').value) || 100;
        payload.taxaReferenciaAtual   = parseFloat(document.getElementById('inputTaxaRef').value) || TAXA_DEFAULTS[tipo];
        payload.taxaAnualPersonalizada = null;
    } else if (tipo === 'POUPANCA') {
        payload.percentualRendimento  = 70;
        payload.taxaReferenciaAtual   = parseFloat(document.getElementById('inputTaxaRefPoupanca').value) || TAXA_DEFAULTS.POUPANCA;
        payload.taxaAnualPersonalizada = null;
    } else {
        payload.percentualRendimento  = 100;
        payload.taxaReferenciaAtual   = null;
        payload.taxaAnualPersonalizada = parseFloat(document.getElementById('inputTaxaAnual').value) || null;
    }

    const btn = document.getElementById('btnSalvarCaixinha');
    btn.disabled = true;
    btn.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Salvando...";

    try {
        let res;
        if (_editandoId) {
            res = await MainAPI.request(`/caixinhas/${_editandoId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
        } else {
            res = await MainAPI.request('/caixinhas', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
        }

        if (res.ok || res.status === 201) {
            fecharModalCriar();
            mostrarToast(_editandoId ? 'Caixinha atualizada com sucesso!' : 'Caixinha criada com sucesso!', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            const err = await res.text().catch(() => '');
            mostrarToast(`Erro ao salvar: ${res.status}. ${err}`, 'erro');
        }
    } catch (e) {
        console.error('Erro ao salvar caixinha:', e);
        mostrarToast('Erro de conexão ao salvar.', 'erro');
    } finally {
        btn.disabled = false;
        btn.innerHTML = "<i class='bx bx-save'></i> Salvar";
        validarBotaoSalvar();
    }
}

// ════════════════════════════════════════════════════════════════
// ENCERRAR / DELETAR
// ════════════════════════════════════════════════════════════════
async function encerrarCaixinha(id) {
    try {
        const res = await MainAPI.request(`/caixinhas/${id}/encerrar`, { method: 'PATCH' });
        if (res.ok) {
            mostrarToast('Caixinha encerrada.', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            mostrarToast(`Erro ao encerrar: ${res.status}`, 'erro');
        }
    } catch (e) {
        mostrarToast('Erro de conexão ao encerrar.', 'erro');
    }
}

async function deletarCaixinha(id) {
    try {
        const res = await MainAPI.request(`/caixinhas/${id}`, { method: 'DELETE' });
        if (res.ok || res.status === 204) {
            mostrarToast('Caixinha deletada.', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            mostrarToast(`Erro ao deletar: ${res.status}`, 'erro');
        }
    } catch (e) {
        mostrarToast('Erro de conexão ao deletar.', 'erro');
    }
}

// ════════════════════════════════════════════════════════════════
// INSIGHT
// ════════════════════════════════════════════════════════════════
function mostrarInsight(lista) {
    const insightEl = document.getElementById('cxhInsight');
    const textoEl   = document.getElementById('cxhInsightTexto');

    if (!lista || lista.length === 0) {
        insightEl.style.display = 'none';
        return;
    }

    const ativas  = lista.filter(c => c.isAtiva);
    const qtd     = ativas.length;
    const alcanc  = ativas.filter(c => c.metaAlcancavel === true).length;
    const proxima = [...ativas].sort((a, b) => (a.faltaParaMeta ?? 0) - (b.faltaParaMeta ?? 0))[0];

    let texto = `Você tem <strong>${qtd}</strong> caixinha(s) ativa(s). `;
    if (alcanc > 0) texto += `<strong>${alcanc}</strong> delas com meta alcançável no prazo. `;
    if (proxima) texto += `A mais próxima da meta é <strong>"${escHtml(proxima.nome)}"</strong> (${(proxima.percentualAtingido ?? 0).toFixed(1)}% atingido, faltam ${formatarMoeda(proxima.faltaParaMeta ?? 0)}).`;

    textoEl.innerHTML = texto;
    insightEl.style.display = 'flex';
}

// ════════════════════════════════════════════════════════════════
// UTILITÁRIOS
// ════════════════════════════════════════════════════════════════
function formatarMoeda(valor) {
    const n = Number(valor) || 0;
    return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function formatarData(iso) {
    if (!iso) return '–';
    // Suporta array [ano,mes,dia] ou string "aaaa-mm-dd"
    if (Array.isArray(iso) && iso.length >= 3) {
        return `${String(iso[2]).padStart(2,'0')}/${String(iso[1]).padStart(2,'0')}/${iso[0]}`;
    }
    const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return `${m[3]}/${m[2]}/${m[1]}`;
    return iso;
}

function labelTipo(tipo) {
    const map = {
        CDI: 'CDI', SELIC: 'SELIC', POUPANCA: 'Poupança',
        PREFIXADO: 'Prefixado', PERSONALIZADO: 'Personalizado'
    };
    return map[tipo] || tipo;
}

function escHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

// Toast
function mostrarToast(msg, tipo) {
    const existing = document.querySelector('.cxh-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = `cxh-toast ${tipo || ''}`;
    toast.innerHTML = `<i class='bx ${tipo === 'sucesso' ? 'bx-check-circle' : 'bx-error-circle'}'></i> ${escHtml(msg)}`;
    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.transition = 'opacity 0.3s';
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 320);
    }, 3500);
}

/* ═══════════════════════════════════════════════════════════════
   caixinhas.js — Lógica completa da tela de Poupança/Caixinhas
   ═══════════════════════════════════════════════════════════════ */

'use strict';

// ── Estado ────────────────────────────────────────────────────
let _usuario        = null;
let _caixinhas      = [];          // cache de todas as caixinhas carregadas
let _filtroAtivo    = 'ativas';    // 'ativas' | 'encerradas' | 'todas'
let _caixinhaAtual  = null;        // caixinha aberta no modal de detalhes
let _editandoId     = null;        // id sendo editado (null = criar)
let _tipoRendimento = 'CDI';       // tipo selecionado no form
let _instsSelecionadas = new Set(); // ids de instituicaoUsuario selecionados
let _todasInstituicoes = [];       // lista de instituições do usuário

// ── Defaults de taxa por tipo ──────────────────────────────────
const TAXA_DEFAULTS = {
    CDI:          10.40,
    SELIC:        10.75,
    POUPANCA:     10.75,
    PREFIXADO:    null,
    PERSONALIZADO: null
};

// ════════════════════════════════════════════════════════════════
// INIT
// ════════════════════════════════════════════════════════════════
async function iniciarPagina() {
    // Recuperar usuário logado
    _usuario = JSON.parse(localStorage.getItem('usuarioLogado') || 'null');
    if (!_usuario || !_usuario.id) {
        window.location.href = 'index.html';
        return;
    }

    // Aplicar tema do localStorage
    const temaSalvo = localStorage.getItem('tema');
    const modoSalvo = localStorage.getItem('modo');
    if (temaSalvo) document.body.setAttribute('data-tema', temaSalvo);
    if (modoSalvo) document.body.setAttribute('data-mode', modoSalvo);

    // Aplicar máscara de moeda
    MainAPI.aplicarMascaraMoeda(document.getElementById('inputValorMeta'));
    // Aplicar máscara de data
    MainAPI.aplicarMascaraData(document.getElementById('inputDataPrazo'));

    // Carregar dados em paralelo
    await Promise.all([
        carregarKPIs(),
        carregarCaixinhas(_filtroAtivo),
        carregarInstituicoes()
    ]);
}

// ════════════════════════════════════════════════════════════════
// KPIs
// ════════════════════════════════════════════════════════════════
async function carregarKPIs() {
    const uid = _usuario.id;
    try {
        const [resTA, resPG, resRM, resST] = await Promise.allSettled([
            MainAPI.request(`/caixinhas/kpi/total-acumulado/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/progresso-geral/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/rendimento-estimado-mes/usuarios/${uid}`).then(r => r.ok ? r.json() : null),
            MainAPI.request(`/caixinhas/kpi/status/usuarios/${uid}`).then(r => r.ok ? r.json() : null)
        ]);

        // KPI 1 — Total Acumulado
        if (resTA.status === 'fulfilled' && resTA.value) {
            document.getElementById('kpiTotalAcumulado').textContent = formatarMoeda(resTA.value.totalAcumulado ?? 0);
            document.getElementById('kpiQtdAtivas').textContent = `${resTA.value.quantidadeAtivas ?? 0} caixinha(s) ativa(s)`;
        }

        // KPI 2 — Progresso Geral
        if (resPG.status === 'fulfilled' && resPG.value) {
            const pg = resPG.value;
            const pct = pg.percentualGeral ?? 0;
            document.getElementById('kpiProgressoPct').textContent = `${pct.toFixed(1)}%`;
            document.getElementById('kpiProgressoSub').textContent = 'da meta total atingida';

            // Atualizar barra consolidada
            const fillPct = Math.min(100, pct);
            document.getElementById('cxhProgressoFill').style.width = `${fillPct}%`;
            document.getElementById('cxhProgressoPctBar').textContent = `${pct.toFixed(1)}%`;
            document.getElementById('cxhProgressoValAtual').textContent = `${formatarMoeda(pg.totalAcumulado ?? 0)} acumulados`;
            document.getElementById('cxhProgressoValMeta').textContent = `Meta: ${formatarMoeda(pg.totalMetas ?? 0)}`;
        }

        // KPI 3 — Rendimento Estimado
        if (resRM.status === 'fulfilled' && resRM.value) {
            document.getElementById('kpiRendimento').textContent = formatarMoeda(resRM.value.rendimentoEstimadoMes ?? 0);
        }

        // KPI 4 — Status
        if (resST.status === 'fulfilled' && resST.value) {
            const st = resST.value;
            document.getElementById('kpiStatusAtivas').textContent = `${st.quantidadeAtivas ?? 0} ativas`;
            document.getElementById('kpiStatusSub').textContent = `${st.quantidadeEncerradas ?? 0} encerradas`;
        }
    } catch (e) {
        console.error('Erro ao carregar KPIs:', e);
    }
}

// ════════════════════════════════════════════════════════════════
// CAIXINHAS
// ════════════════════════════════════════════════════════════════
async function carregarCaixinhas(filtro) {
    _filtroAtivo = filtro;
    mostrarLoading(true);

    try {
        const uid = _usuario.id;
        let endpoint;
        if (filtro === 'ativas') {
            endpoint = `/caixinhas/ativas/usuarios/${uid}`;
        } else {
            endpoint = `/caixinhas/usuarios/${uid}`;
        }

        const res = await MainAPI.request(endpoint);
        if (res.status === 204) {
            _caixinhas = [];
        } else if (res.ok) {
            _caixinhas = await res.json();
            if (!Array.isArray(_caixinhas)) _caixinhas = [];
        } else {
            _caixinhas = [];
        }

        // Filtrar encerradas no cliente quando necessário
        let lista = _caixinhas;
        if (filtro === 'encerradas') {
            lista = _caixinhas.filter(c => !c.isAtiva);
        }

        renderizarCards(lista);
        mostrarInsight(lista);
    } catch (e) {
        console.error('Erro ao carregar caixinhas:', e);
        _caixinhas = [];
        renderizarCards([]);
    } finally {
        mostrarLoading(false);
    }
}

function mostrarLoading(show) {
    document.getElementById('cxhLoading').style.display = show ? 'flex' : 'none';
    if (show) {
        document.getElementById('cxhGrid').style.display = 'none';
        document.getElementById('cxhVazio').style.display = 'none';
        document.getElementById('cxhInsight').style.display = 'none';
    }
}

function renderizarCards(lista) {
    const grid  = document.getElementById('cxhGrid');
    const vazio = document.getElementById('cxhVazio');

    if (!lista || lista.length === 0) {
        grid.style.display  = 'none';
        vazio.style.display = 'flex';
        return;
    }

    vazio.style.display = 'none';
    grid.style.display  = 'grid';

    grid.innerHTML = lista.map(c => gerarCardHTML(c)).join('');

    // Adicionar listeners de clique
    grid.querySelectorAll('.cxh-card').forEach(card => {
        const id = card.dataset.id;
        card.addEventListener('click', () => {
            const caixinha = _caixinhas.find(c => c.id === id)
                || lista.find(c => c.id === id);
            if (caixinha) abrirModalDetalhes(caixinha);
        });
    });
}

function gerarCardHTML(c) {
    const pct     = Math.min(100, c.percentualAtingido ?? 0);
    const atingida = pct >= 100;
    const tipo    = c.tipoRendimento || 'CDI';
    const encerrada = !c.isAtiva;

    const alcancavel = c.metaAlcancavel;
    const alcancavelHTML = typeof alcancavel === 'boolean'
        ? `<span class="cxh-card-meta-alcancavel ${alcancavel ? '' : 'nao'}">
               <i class='bx ${alcancavel ? 'bx-check-circle' : 'bx-x-circle'}'></i>
               ${alcancavel ? 'Meta alcançável' : 'Aporte insuficiente'}
           </span>`
        : '';

    const mesesTxt = c.mesesRestantes != null ? `${c.mesesRestantes} meses restantes` : '–';
    const prazoTxt = c.dataPrazo ? formatarData(c.dataPrazo) : '–';

    return `
    <div class="cxh-card ${encerrada ? 'encerrada' : ''}" data-id="${c.id}">
        <div class="cxh-card-header">
            <div>
                <div class="cxh-card-nome">${escHtml(c.nome)}</div>
                ${c.descricao ? `<div class="cxh-card-desc">${escHtml(c.descricao)}</div>` : ''}
            </div>
            <span class="cxh-badge cxh-badge-${tipo}">${labelTipo(tipo)}</span>
        </div>

        <div class="cxh-card-valores">
            <span class="cxh-card-valor-atual">${formatarMoeda(c.valorAtual ?? 0)}</span>
            <span class="cxh-card-meta">/ ${formatarMoeda(c.valorMeta ?? 0)}</span>
        </div>

        <div>
            <div class="cxh-card-progress-track">
                <div class="cxh-card-progress-fill ${atingida ? 'atingida' : ''}" style="width:${pct}%"></div>
            </div>
            <div class="cxh-card-progress-info">
                <span class="cxh-card-pct">${pct.toFixed(1)}%</span>
                <span>${mesesTxt}</span>
            </div>
        </div>

        <div class="cxh-card-footer">
            ${alcancavelHTML}
            <span>${prazoTxt}</span>
        </div>
    </div>`;
}

// ════════════════════════════════════════════════════════════════
// FILTROS / ABAS
// ════════════════════════════════════════════════════════════════
function trocarFiltro(filtro, btnEl) {
    document.querySelectorAll('.cxh-filtro-btn').forEach(b => b.classList.remove('ativo'));
    btnEl.classList.add('ativo');
    carregarCaixinhas(filtro);
}

// ════════════════════════════════════════════════════════════════
// MODAL DETALHES
// ════════════════════════════════════════════════════════════════
function abrirModalDetalhes(c) {
    _caixinhaAtual = c;
    const encerrada = !c.isAtiva;

    // Cabeçalho
    document.getElementById('detNome').textContent    = c.nome;
    document.getElementById('detDesc').textContent    = c.descricao || '';
    document.getElementById('detBadge').className     = `cxh-badge cxh-badge-${c.tipoRendimento || 'CDI'}`;
    document.getElementById('detBadge').textContent   = labelTipo(c.tipoRendimento);
    document.getElementById('detStatusBadge').innerHTML = encerrada
        ? `<span style="font-size:0.7rem;font-weight:700;padding:3px 9px;border-radius:12px;background:var(--cor-fundo-inativo);color:var(--cor-texto-secundario);">Encerrada</span>`
        : `<span style="font-size:0.7rem;font-weight:700;padding:3px 9px;border-radius:12px;background:var(--green-100);color:var(--green-700);">Ativa</span>`;

    // Stats
    document.getElementById('detValorAtual').textContent  = formatarMoeda(c.valorAtual ?? 0);
    document.getElementById('detMeta').textContent        = formatarMoeda(c.valorMeta ?? 0);
    document.getElementById('detFalta').textContent       = formatarMoeda(c.faltaParaMeta ?? 0);
    const pct = c.percentualAtingido ?? 0;
    document.getElementById('detPct').textContent         = `${pct.toFixed(1)}%`;
    document.getElementById('detMeses').textContent       = c.mesesRestantes != null ? `${c.mesesRestantes} meses` : '–';
    document.getElementById('detPrazo').textContent       = c.dataPrazo ? formatarData(c.dataPrazo) : '–';
    document.getElementById('detAporte').textContent      = c.aporteMensalSugerido != null ? formatarMoeda(c.aporteMensalSugerido) : '–';
    document.getElementById('detTaxaMensal').textContent  = c.taxaMensalEfetiva != null
        ? `${(c.taxaMensalEfetiva * 100).toFixed(4)}% a.m.`
        : '–';

    // Barra de progresso
    const fillPct = Math.min(100, pct);
    document.getElementById('detProgressoFill').style.width = `${fillPct}%`;
    document.getElementById('detPctBar').textContent = `${pct.toFixed(1)}%`;

    // Meta alcançável
    const alcDiv = document.getElementById('detAlcancavel');
    if (typeof c.metaAlcancavel === 'boolean') {
        alcDiv.innerHTML = `
            <span class="cxh-det-alcancavel ${c.metaAlcancavel ? '' : 'nao'}">
                <i class='bx ${c.metaAlcancavel ? 'bx-check-circle' : 'bx-x-circle'}'></i>
                ${c.metaAlcancavel ? 'Meta alcançável com aportes sugeridos' : 'Meta pode não ser atingida com os aportes atuais'}
            </span>`;
    } else {
        alcDiv.innerHTML = '';
    }

    // Projeção
    document.getElementById('detProjecao').innerHTML = gerarTextoProjecao(c);

    // Instituições
    const instLista = document.getElementById('detInstLista');
    const instSection = document.getElementById('detInstSection');
    if (c.instituicoes && c.instituicoes.length > 0) {
        instSection.style.display = '';
        instLista.innerHTML = c.instituicoes.map(inst =>
            `<div class="cxh-det-inst-item">
                <span class="cxh-det-inst-nome"><i class='bx bx-buildings'></i> ${escHtml(inst.nome || 'Instituição')}</span>
                <span class="cxh-det-inst-val">${formatarMoeda(inst.valorAportado ?? 0)}</span>
            </div>`
        ).join('');
    } else {
        instSection.style.display = 'none';
    }

    // Botões: mostrar Encerrar OU Reabrir conforme status
    const btnEnc = document.getElementById('btnDetEncerrar');
    const btnReab = document.getElementById('btnDetReabrir');
    if (encerrada) {
        btnEnc.style.display  = 'none';
        btnReab.style.display = '';
    } else {
        btnEnc.style.display  = '';
        btnReab.style.display = 'none';
    }

    document.getElementById('modalDetOverlay').classList.add('aberto');
}

function fecharModalDet() {
    document.getElementById('modalDetOverlay').classList.remove('aberto');
    // Resetar footer de confirmação
    const fnormal = document.getElementById('detFooterNormal');
    const fconf   = document.getElementById('detFooterConfirmacao');
    if (fnormal) fnormal.style.display = 'flex';
    if (fconf)   fconf.style.display   = 'none';
    _caixinhaAtual = null;
}

function fecharModalDetOutside(e) {
    if (e.target === document.getElementById('modalDetOverlay')) fecharModalDet();
}

function gerarTextoProjecao(c) {
    const semAportes = c.montanteProjetadoSemAportes;
    const comAportes = c.montanteProjetadoComAportes;
    const aporte     = c.aporteMensalSugerido;
    const meses      = c.mesesRestantes;
    const taxa       = c.taxaMensalEfetiva;

    // Calcular projeção localmente se os dados do servidor estiverem ausentes
    const r = taxa != null ? taxa : 0;
    const n = meses != null ? meses : 0;
    const VA = c.valorAtual ?? 0;

    // Projeção sem aportes: VA * (1+r)^n
    const projSemAp = semAportes != null ? semAportes : (r > 0 ? VA * Math.pow(1 + r, n) : VA);
    // Projeção com aportes sugeridos
    const ap = aporte != null ? aporte : 0;
    const projComAp = comAportes != null ? comAportes
        : (r > 0 ? projSemAp + ap * ((Math.pow(1 + r, n) - 1) / r)
                 : projSemAp + ap * n);

    return `
        <strong>Sem novos aportes:</strong> você terá <strong>${formatarMoeda(projSemAp)}</strong> no prazo.<br>
        <strong>Com aporte de ${formatarMoeda(ap)}/mês:</strong> você terá <strong>${formatarMoeda(projComAp)}</strong>.<br>
        <strong>Meta:</strong> ${formatarMoeda(c.valorMeta ?? 0)}&nbsp;·&nbsp;
        <strong>Falta:</strong> ${formatarMoeda(c.faltaParaMeta ?? 0)}&nbsp;·&nbsp;
        <strong>Taxa mensal:</strong> ${r > 0 ? (r * 100).toFixed(4) + '% a.m.' : 'sem rendimento definido'}
    `;
}

// ── Ações do modal de detalhes ─────────────────────────────────
function editarCaixinhaAtual() {
    if (!_caixinhaAtual) return;
    const c = _caixinhaAtual; // salva referência ANTES de fechar (fecharModalDet zera _caixinhaAtual)
    fecharModalDet();
    abrirModalEditar(c);
}

// Exibe confirmação inline (sem confirm() nativo)
function pedirConfirmacaoReabrir() {
    if (!_caixinhaAtual) return;
    document.getElementById('detConfirmacaoTexto').textContent =
        `Reabrir "${_caixinhaAtual.nome}"? A caixinha voltará a aparecer como ativa.`;
    document.getElementById('btnConfirmarAcao').className = 'btn-cxh-reabrir-confirmar';
    document.getElementById('btnConfirmarAcao').onclick = confirmarReabrir;
    document.getElementById('detFooterNormal').style.display = 'none';
    document.getElementById('detFooterConfirmacao').style.display = 'flex';
}

async function confirmarReabrir() {
    const c = _caixinhaAtual;
    if (!c) return;
    cancelarConfirmacao();
    fecharModalDet();
    await reabrirCaixinha(c.id);
}

async function reabrirCaixinha(id) {
    try {
        const res = await MainAPI.request(`/caixinhas/${id}/reabrir`, { method: 'PATCH' });
        if (res.ok) {
            mostrarToast('Caixinha reaberta com sucesso!', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            mostrarToast(`Erro ao reabrir: ${res.status}`, 'erro');
        }
    } catch (e) {
        mostrarToast('Erro de conexão ao reabrir.', 'erro');
    }
}

function pedirConfirmacaoEncerrar() {
    if (!_caixinhaAtual) return;
    document.getElementById('detConfirmacaoTexto').textContent =
        `Encerrar "${_caixinhaAtual.nome}"? Os dados serão mantidos.`;
    document.getElementById('btnConfirmarAcao').className = 'btn-cxh-encerrar-confirmar';
    document.getElementById('btnConfirmarAcao').onclick = confirmarEncerrar;
    document.getElementById('detFooterNormal').style.display = 'none';
    document.getElementById('detFooterConfirmacao').style.display = 'flex';
}

function pedirConfirmacaoDeletar() {
    if (!_caixinhaAtual) return;
    document.getElementById('detConfirmacaoTexto').textContent =
        `Deletar permanentemente "${_caixinhaAtual.nome}"? Ação irreversível.`;
    document.getElementById('btnConfirmarAcao').className = 'btn-cxh-deletar-confirmar';
    document.getElementById('btnConfirmarAcao').onclick = confirmarDeletar;
    document.getElementById('detFooterNormal').style.display = 'none';
    document.getElementById('detFooterConfirmacao').style.display = 'flex';
}

function cancelarConfirmacao() {
    document.getElementById('detFooterNormal').style.display = 'flex';
    document.getElementById('detFooterConfirmacao').style.display = 'none';
}

async function confirmarEncerrar() {
    const c = _caixinhaAtual;
    if (!c) return;
    cancelarConfirmacao();
    fecharModalDet();
    await encerrarCaixinha(c.id);
}

async function confirmarDeletar() {
    const c = _caixinhaAtual;
    if (!c) return;
    cancelarConfirmacao();
    fecharModalDet();
    await deletarCaixinha(c.id);
}

// Mantidas por compatibilidade (não usam mais confirm() nativo)
async function encerrarCaixinhaAtual() { pedirConfirmacaoEncerrar(); }
async function deletarCaixinhaAtual()  { pedirConfirmacaoDeletar(); }

// ════════════════════════════════════════════════════════════════
// MODAL CRIAR / EDITAR
// ════════════════════════════════════════════════════════════════
function abrirModalCriar() {
    _editandoId = null;
    document.getElementById('modalCriarTitulo').innerHTML = "<i class='bx bx-plus-circle'></i> Nova Caixinha";
    resetarFormulario();
    document.getElementById('modalCriarOverlay').classList.add('aberto');
    validarBotaoSalvar();
}

function abrirModalEditar(c) {
    _editandoId = c.id;
    document.getElementById('modalCriarTitulo').innerHTML = "<i class='bx bx-edit'></i> Editar Caixinha";
    preencherFormulario(c);
    document.getElementById('modalCriarOverlay').classList.add('aberto');
    validarBotaoSalvar();
}

function fecharModalCriar() {
    document.getElementById('modalCriarOverlay').classList.remove('aberto');
}

function fecharModalCriarOutside(e) {
    if (e.target === document.getElementById('modalCriarOverlay')) fecharModalCriar();
}

function resetarFormulario() {
    document.getElementById('inputNome').value        = '';
    document.getElementById('inputDescricao').value   = '';
    MainAPI.resetarMascaraMoeda(document.getElementById('inputValorMeta'));
    document.getElementById('inputDataPrazo').value   = '';
    document.getElementById('inputPctRendimento').value  = '';
    document.getElementById('inputTaxaRef').value        = '';
    document.getElementById('inputTaxaRefPoupanca').value = '';
    document.getElementById('inputTaxaAnual').value      = '';
    _instsSelecionadas.clear();
    selecionarTipoRendimento('CDI');
    renderizarInstituicoes();
    document.getElementById('taxaResumo').style.display = 'none';
}

function preencherFormulario(c) {
    document.getElementById('inputNome').value      = c.nome || '';
    document.getElementById('inputDescricao').value = c.descricao || '';

    // Valor meta
    const inputMeta = document.getElementById('inputValorMeta');
    const centavos  = Math.round((c.valorMeta ?? 0) * 100);
    inputMeta.dataset.centavos = String(centavos);
    const reais = Math.floor(centavos / 100);
    const cts   = String(centavos % 100).padStart(2, '0');
    const reaisStr = String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    inputMeta.value = `R$ ${reaisStr},${cts}`;

    // Data prazo — backend pode retornar string "aaaa-mm-dd" ou array [ano, mes, dia]
    if (c.dataPrazo) {
        let iso = c.dataPrazo;
        if (Array.isArray(iso) && iso.length >= 3) {
            iso = `${iso[0]}-${String(iso[1]).padStart(2,'0')}-${String(iso[2]).padStart(2,'0')}`;
        }
        document.getElementById('inputDataPrazo').value = MainAPI.dataDeISO(String(iso));
    }

    // Tipo de rendimento
    const tipo = c.tipoRendimento || 'CDI';
    selecionarTipoRendimento(tipo);

    if (tipo === 'CDI' || tipo === 'SELIC') {
        document.getElementById('inputPctRendimento').value  = c.percentualRendimento ?? 100;
        document.getElementById('inputTaxaRef').value        = c.taxaReferenciaAtual ?? TAXA_DEFAULTS[tipo];
    } else if (tipo === 'POUPANCA') {
        document.getElementById('inputTaxaRefPoupanca').value = c.taxaReferenciaAtual ?? TAXA_DEFAULTS.POUPANCA;
    } else {
        document.getElementById('inputTaxaAnual').value = c.taxaAnualPersonalizada ?? '';
    }

    calcularTaxaEfetiva();

    // Instituições
    _instsSelecionadas.clear();
    if (c.instituicoes && Array.isArray(c.instituicoes)) {
        c.instituicoes.forEach(inst => {
            // inst.id pode ser o id da vinculação (instituicaoUsuarioId)
            _instsSelecionadas.add(inst.id);
        });
    }
    renderizarInstituicoes();
}

// ── Tipo de rendimento ─────────────────────────────────────────
function selecionarTipoRendimento(tipo) {
    _tipoRendimento = tipo;

    // Atualizar botões
    document.querySelectorAll('.cxh-rend-btn').forEach(btn => {
        btn.className = 'cxh-rend-btn';
        if (btn.dataset.tipo === tipo) btn.classList.add(`ativo-${tipo}`);
    });

    // Mostrar campos corretos
    ['camposCdiSelic', 'camposPoupanca', 'camposPrefixado'].forEach(id => {
        document.getElementById(id).classList.remove('visivel');
    });

    if (tipo === 'CDI' || tipo === 'SELIC') {
        document.getElementById('camposCdiSelic').classList.add('visivel');
        const lbl = document.getElementById('labelPctCdi');
        const lbl2 = document.getElementById('labelTaxaRef');
        lbl.textContent  = tipo === 'CDI' ? '% do CDI' : '% da SELIC';
        lbl2.textContent = tipo === 'CDI' ? 'Taxa CDI atual (% a.a.)' : 'Taxa SELIC atual (% a.a.)';
        // Preencher default se vazio
        const inp = document.getElementById('inputTaxaRef');
        if (!inp.value) inp.value = TAXA_DEFAULTS[tipo];
        const inpPct = document.getElementById('inputPctRendimento');
        if (!inpPct.value) inpPct.value = 100;
    } else if (tipo === 'POUPANCA') {
        document.getElementById('camposPoupanca').classList.add('visivel');
        const inp = document.getElementById('inputTaxaRefPoupanca');
        if (!inp.value) inp.value = TAXA_DEFAULTS.POUPANCA;
    } else {
        document.getElementById('camposPrefixado').classList.add('visivel');
    }

    calcularTaxaEfetiva();
}

// ── Calcular taxa efetiva ──────────────────────────────────────
function calcularTaxaEfetiva() {
    const tipo = _tipoRendimento;
    let taxaAnual = 0;

    if (tipo === 'CDI' || tipo === 'SELIC') {
        const pct     = parseFloat(document.getElementById('inputPctRendimento').value) || 100;
        const taxaRef = parseFloat(document.getElementById('inputTaxaRef').value) || 0;
        taxaAnual = taxaRef * (pct / 100);
    } else if (tipo === 'POUPANCA') {
        const taxaRef = parseFloat(document.getElementById('inputTaxaRefPoupanca').value) || 0;
        taxaAnual = taxaRef * 0.70;
    } else {
        taxaAnual = parseFloat(document.getElementById('inputTaxaAnual').value) || 0;
    }

    const taxaMensal = taxaAnual > 0 ? (Math.pow(1 + taxaAnual / 100, 1 / 12) - 1) * 100 : 0;

    const resumo = document.getElementById('taxaResumo');
    const txt    = document.getElementById('taxaResumoTexto');

    if (taxaAnual > 0) {
        resumo.style.display = 'flex';
        txt.innerHTML = `Taxa efetiva: <strong>${taxaAnual.toFixed(2)}% a.a.</strong> · <strong>${taxaMensal.toFixed(4)}% a.m.</strong>`;

        // Verificar alcançabilidade em tempo real
        const meta    = MainAPI.obterValorMoeda(document.getElementById('inputValorMeta'));
        const prazoTxt = document.getElementById('inputDataPrazo').value;
        if (meta > 0 && prazoTxt && prazoTxt.length === 10) {
            const prazoISO = MainAPI.dataParaISO(prazoTxt);
            if (prazoISO) {
                const hoje    = new Date();
                const prazo   = new Date(prazoISO);
                const diffMs  = prazo - hoje;
                const meses   = Math.max(0, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 30.4)));
                if (meses > 0) {
                    const r   = taxaMensal / 100;
                    const VA  = 0; // sem valor atual inicial no form
                    const projSem = r > 0 ? VA * Math.pow(1 + r, meses) : VA;
                    const aporteNecessario = r > 0
                        ? ((meta - projSem) * r) / (Math.pow(1 + r, meses) - 1)
                        : (meta - projSem) / meses;
                    if (aporteNecessario > 0) {
                        txt.innerHTML += ` · Aporte necessário: <strong>${formatarMoeda(aporteNecessario)}/mês</strong> por <strong>${meses} meses</strong>`;
                    }
                }
            }
        }
    } else {
        resumo.style.display = 'none';
    }
}

// ── Instituições ───────────────────────────────────────────────
async function carregarInstituicoes() {
    try {
        _todasInstituicoes = await MainAPI.getInstituicoes(_usuario.id);
        if (!Array.isArray(_todasInstituicoes)) _todasInstituicoes = [];
        renderizarInstituicoes();
    } catch (e) {
        console.error('Erro ao carregar instituições:', e);
        _todasInstituicoes = [];
    }
}

function renderizarInstituicoes() {
    const grid = document.getElementById('instGrid');
    if (_todasInstituicoes.length === 0) {
        grid.innerHTML = '<span style="font-size:0.82rem;color:var(--cor-texto-secundario);">Nenhuma instituição vinculada. <a href="configurações.html" style="color:var(--cor-principal);">Configurar</a></span>';
        return;
    }

    grid.innerHTML = _todasInstituicoes.map(inst => {
        const selecionada = _instsSelecionadas.has(inst.id);
        return `
        <div class="cxh-inst-item ${selecionada ? 'selecionada' : ''}" 
             data-instid="${inst.id}"
             onclick="toggleInstituicao(${inst.id}, this)">
            <span class="cxh-inst-check">${selecionada ? '✓' : ''}</span>
            <span>${escHtml(inst.intituicao?.nome || inst.instituicao?.nome || inst.nomeInstituicao || inst.nome || `Inst. ${inst.id}`)}</span>
        </div>`;
    }).join('');
}

function toggleInstituicao(instId, el) {
    if (_instsSelecionadas.has(instId)) {
        _instsSelecionadas.delete(instId);
        el.classList.remove('selecionada');
        el.querySelector('.cxh-inst-check').textContent = '';
    } else {
        _instsSelecionadas.add(instId);
        el.classList.add('selecionada');
        el.querySelector('.cxh-inst-check').textContent = '✓';
    }
    validarBotaoSalvar();
}

// ── Validar botão salvar ───────────────────────────────────────
function validarBotaoSalvar() {
    const nome    = (document.getElementById('inputNome').value || '').trim();
    const temInst = _instsSelecionadas.size > 0;
    const btn     = document.getElementById('btnSalvarCaixinha');
    const aviso   = document.getElementById('instAviso');

    btn.disabled = !(nome && temInst);
    if (aviso) aviso.style.display = (!temInst && nome) ? '' : 'none';
}

// ════════════════════════════════════════════════════════════════
// SALVAR (POST / PUT)
// ════════════════════════════════════════════════════════════════
async function salvarCaixinha() {
    const nome     = document.getElementById('inputNome').value.trim();
    const descricao = document.getElementById('inputDescricao').value.trim();
    const valorMeta = MainAPI.obterValorMoeda(document.getElementById('inputValorMeta'));
    const prazoTxt  = document.getElementById('inputDataPrazo').value;
    const tipo      = _tipoRendimento;

    if (!nome) { mostrarToast('Informe o nome da caixinha.', 'erro'); return; }
    if (_instsSelecionadas.size === 0) { mostrarToast('Selecione ao menos uma instituição.', 'erro'); return; }

    // Montar payload
    const payload = {
        usuarioId:    _usuario.id,
        nome,
        descricao:    descricao || null,
        valorMeta:    valorMeta > 0 ? valorMeta : null,
        dataPrazo:    prazoTxt ? MainAPI.dataParaISO(prazoTxt) : null,
        tipoRendimento: tipo,
        isCompartilhada: false,
        instituicaoUsuarioIds: Array.from(_instsSelecionadas)
    };

    // Campos condicionais de rendimento
    if (tipo === 'CDI' || tipo === 'SELIC') {
        payload.percentualRendimento  = parseFloat(document.getElementById('inputPctRendimento').value) || 100;
        payload.taxaReferenciaAtual   = parseFloat(document.getElementById('inputTaxaRef').value) || TAXA_DEFAULTS[tipo];
        payload.taxaAnualPersonalizada = null;
    } else if (tipo === 'POUPANCA') {
        payload.percentualRendimento  = 70;
        payload.taxaReferenciaAtual   = parseFloat(document.getElementById('inputTaxaRefPoupanca').value) || TAXA_DEFAULTS.POUPANCA;
        payload.taxaAnualPersonalizada = null;
    } else {
        payload.percentualRendimento  = 100;
        payload.taxaReferenciaAtual   = null;
        payload.taxaAnualPersonalizada = parseFloat(document.getElementById('inputTaxaAnual').value) || null;
    }

    const btn = document.getElementById('btnSalvarCaixinha');
    btn.disabled = true;
    btn.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Salvando...";

    try {
        let res;
        if (_editandoId) {
            res = await MainAPI.request(`/caixinhas/${_editandoId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
        } else {
            res = await MainAPI.request('/caixinhas', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
        }

        if (res.ok || res.status === 201) {
            fecharModalCriar();
            mostrarToast(_editandoId ? 'Caixinha atualizada com sucesso!' : 'Caixinha criada com sucesso!', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            const err = await res.text().catch(() => '');
            mostrarToast(`Erro ao salvar: ${res.status}. ${err}`, 'erro');
        }
    } catch (e) {
        console.error('Erro ao salvar caixinha:', e);
        mostrarToast('Erro de conexão ao salvar.', 'erro');
    } finally {
        btn.disabled = false;
        btn.innerHTML = "<i class='bx bx-save'></i> Salvar";
        validarBotaoSalvar();
    }
}

// ════════════════════════════════════════════════════════════════
// ENCERRAR / DELETAR
// ════════════════════════════════════════════════════════════════
async function encerrarCaixinha(id) {
    try {
        const res = await MainAPI.request(`/caixinhas/${id}/encerrar`, { method: 'PATCH' });
        if (res.ok) {
            mostrarToast('Caixinha encerrada.', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            mostrarToast(`Erro ao encerrar: ${res.status}`, 'erro');
        }
    } catch (e) {
        mostrarToast('Erro de conexão ao encerrar.', 'erro');
    }
}

async function deletarCaixinha(id) {
    try {
        const res = await MainAPI.request(`/caixinhas/${id}`, { method: 'DELETE' });
        if (res.ok || res.status === 204) {
            mostrarToast('Caixinha deletada.', 'sucesso');
            await Promise.all([carregarKPIs(), carregarCaixinhas(_filtroAtivo)]);
        } else {
            mostrarToast(`Erro ao deletar: ${res.status}`, 'erro');
        }
    } catch (e) {
        mostrarToast('Erro de conexão ao deletar.', 'erro');
    }
}

// ════════════════════════════════════════════════════════════════
// INSIGHT
// ════════════════════════════════════════════════════════════════
function mostrarInsight(lista) {
    const insightEl = document.getElementById('cxhInsight');
    const textoEl   = document.getElementById('cxhInsightTexto');

    if (!lista || lista.length === 0) {
        insightEl.style.display = 'none';
        return;
    }

    const ativas  = lista.filter(c => c.isAtiva);
    const qtd     = ativas.length;
    const alcanc  = ativas.filter(c => c.metaAlcancavel === true).length;
    const proxima = [...ativas].sort((a, b) => (a.faltaParaMeta ?? 0) - (b.faltaParaMeta ?? 0))[0];

    let texto = `Você tem <strong>${qtd}</strong> caixinha(s) ativa(s). `;
    if (alcanc > 0) texto += `<strong>${alcanc}</strong> delas com meta alcançável no prazo. `;
    if (proxima) texto += `A mais próxima da meta é <strong>"${escHtml(proxima.nome)}"</strong> (${(proxima.percentualAtingido ?? 0).toFixed(1)}% atingido, faltam ${formatarMoeda(proxima.faltaParaMeta ?? 0)}).`;

    textoEl.innerHTML = texto;
    insightEl.style.display = 'flex';
}

// ════════════════════════════════════════════════════════════════
// UTILITÁRIOS
// ════════════════════════════════════════════════════════════════
function formatarMoeda(valor) {
    const n = Number(valor) || 0;
    return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function formatarData(iso) {
    if (!iso) return '–';
    // Suporta array [ano,mes,dia] ou string "aaaa-mm-dd"
    if (Array.isArray(iso) && iso.length >= 3) {
        return `${String(iso[2]).padStart(2,'0')}/${String(iso[1]).padStart(2,'0')}/${iso[0]}`;
    }
    const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return `${m[3]}/${m[2]}/${m[1]}`;
    return iso;
}

function labelTipo(tipo) {
    const map = {
        CDI: 'CDI', SELIC: 'SELIC', POUPANCA: 'Poupança',
        PREFIXADO: 'Prefixado', PERSONALIZADO: 'Personalizado'
    };
    return map[tipo] || tipo;
}

function escHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

// Toast
function mostrarToast(msg, tipo) {
    const existing = document.querySelector('.cxh-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = `cxh-toast ${tipo || ''}`;
    toast.innerHTML = `<i class='bx ${tipo === 'sucesso' ? 'bx-check-circle' : 'bx-error-circle'}'></i> ${escHtml(msg)}`;
    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.transition = 'opacity 0.3s';
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 320);
    }, 3500);
}

// ============================================================================
// EMPRÉSTIMOS - JavaScript
// ============================================================================

const API_BASE = 'http://localhost:8080';
let usuarioLogado = null;
let emprestimos = [];
let emprestimoEmEdicao = null;
let emprestimoParaPagamento = null;
let filtroAtual = 'todos';
let _instituicoes = [];

// Bancários
let bancarios = [];
let bancarioParaPagamento = null;
let filtroBancarioAtual = 'todos';

// ── Inicialização ──
window.addEventListener('DOMContentLoaded', () => {
    const userData = localStorage.getItem('usuarioLogado');
    if (!userData) { window.location.href = 'index.html'; return; }
    usuarioLogado = JSON.parse(userData);

    // Aplicar máscaras - pessoais
    const aplicarMascara = (id, fn) => { const el = document.getElementById(id); if (el && window.MainAPI?.[fn]) window.MainAPI[fn](el); };
    aplicarMascara('inputValor', 'aplicarMascaraMoeda');
    aplicarMascara('inputDataPrevisao', 'aplicarMascaraData');
    aplicarMascara('inputDataEmprestimo', 'aplicarMascaraData');
    aplicarMascara('inputValorPagamento', 'aplicarMascaraMoeda');
    aplicarMascara('inputDataPagamento', 'aplicarMascaraData');
    // Máscaras bancários
    aplicarMascara('bInputPrincipal', 'aplicarMascaraMoeda');
    aplicarMascara('bInputContratacao', 'aplicarMascaraData');
    aplicarMascara('bInputPrimeiraParcela', 'aplicarMascaraData');
    aplicarMascara('bPagDataPagamento', 'aplicarMascaraData');

    // Auto-calcular parcela ao digitar
    ['bInputPrincipal','bInputTaxa','bInputParcelas'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', calcularParcelaEstimada);
    });

    carregarInstituicoes();
    carregarResumo();
    carregarEmprestimos();
    carregarBancarios();
});

// ── Tabs ──
function trocarAba(aba) {
    document.getElementById('abaPessoais').style.display = aba === 'pessoais' ? '' : 'none';
    document.getElementById('abaBancarios').style.display = aba === 'bancarios' ? '' : 'none';
    document.getElementById('tabPessoais').classList.toggle('ativo', aba === 'pessoais');
    document.getElementById('tabBancarios').classList.toggle('ativo', aba === 'bancarios');
}

// ============================================================================
// INSTITUIÇÕES
// ============================================================================

async function carregarInstituicoes() {
    try {
        _instituicoes = await window.MainAPI.getInstituicoes(usuarioLogado.id);
        popularSelectInstituicoes('inputInstituicao');
        popularSelectInstituicoes('inputInstituicaoPagamento');
    } catch (e) {
        console.error('Erro ao carregar instituições:', e);
    }
}

function popularSelectInstituicoes(selectId) {
    const sel = document.getElementById(selectId);
    if (!sel) return;
    sel.innerHTML = '<option value="">Selecione a conta...</option>';
    _instituicoes.forEach(inst => {
        const opt = document.createElement('option');
        opt.value = inst.id;
        opt.textContent = inst.intituicao.nome;
        sel.appendChild(opt);
    });
}

function atualizarLabelInstituicao() {
    const tipo = document.getElementById('inputTipo')?.value;
    const label = document.getElementById('labelInstituicao');
    if (!label) return;
    if (tipo === 'EMPRESTEI') {
        label.textContent = 'Conta de onde sairá o dinheiro *';
    } else if (tipo === 'PEDI_EMPRESTADO') {
        label.textContent = 'Conta onde o dinheiro será recebido *';
    } else {
        label.textContent = 'Conta *';
    }
}

// ============================================================================
// CARREGAR DADOS
// ============================================================================

async function carregarResumo() {
    try {
        const response = await fetch(`${API_BASE}/emprestimos/usuarios/${usuarioLogado.id}/resumo`);
        if (!response.ok) throw new Error('Erro ao carregar resumo');

        const resumo = await response.json();

        document.getElementById('valorAReceber').textContent = formatarMoeda(resumo.valorTotalAReceber);
        document.getElementById('detalhesReceber').textContent =
            `${resumo.quantidadePessoasDevem} pessoa(s)`;

        document.getElementById('valorAPagar').textContent = formatarMoeda(resumo.valorTotalAPagar);
        document.getElementById('detalhesPagar').textContent =
            `${resumo.quantidadePessoasDevo} pessoa(s)`;
    } catch (error) {
        console.error('Erro ao carregar resumo:', error);
        mostrarNotificacao('Erro ao carregar resumo', 'erro');
    }
}

async function carregarEmprestimos() {
    try {
        const response = await fetch(`${API_BASE}/emprestimos/usuarios/${usuarioLogado.id}`);

        if (response.status === 204) {
            emprestimos = [];
            renderizarEmprestimos();
            return;
        }

        if (!response.ok) throw new Error('Erro ao carregar empréstimos');

        emprestimos = await response.json();
        renderizarEmprestimos();
    } catch (error) {
        console.error('Erro ao carregar empréstimos:', error);
        mostrarNotificacao('Erro ao carregar empréstimos', 'erro');
    }
}

// ============================================================================
// RENDERIZAÇÃO
// ============================================================================

function renderizarEmprestimos() {
    const container = document.getElementById('listaEmprestimos');

    let emprestimosFiltrados = [...emprestimos];

    // Aplicar filtros
    switch (filtroAtual) {
        case 'EMPRESTEI':
            emprestimosFiltrados = emprestimos.filter(e => e.tipo === 'EMPRESTEI');
            break;
        case 'PEDI_EMPRESTADO':
            emprestimosFiltrados = emprestimos.filter(e => e.tipo === 'PEDI_EMPRESTADO');
            break;
        case 'pendentes':
            emprestimosFiltrados = emprestimos.filter(e =>
                e.status === 'PENDENTE' || e.status === 'PAGO_PARCIAL');
            break;
        case 'quitados':
            emprestimosFiltrados = emprestimos.filter(e => e.status === 'QUITADO');
            break;
    }

    if (emprestimosFiltrados.length === 0) {
        container.innerHTML = `
            <div class="estado-vazio">
                <i class='bx bx-wallet'></i>
                <h3>Nenhum empréstimo encontrado</h3>
                <p>Clique em "Novo Empréstimo" para registrar um empréstimo.</p>
            </div>
        `;
        return;
    }

    container.innerHTML = emprestimosFiltrados.map(e => criarCardEmprestimo(e)).join('');
}

function criarCardEmprestimo(emprestimo) {
    const tipoClass = emprestimo.tipo === 'EMPRESTEI' ? 'emprestei' : 'pedi-emprestado';
    const tipoLabel = emprestimo.tipo === 'EMPRESTEI' ? 'Emprestei' : 'Peguei Emprestado';
    const tipoIcon = emprestimo.tipo === 'EMPRESTEI' ? 'bx-down-arrow-circle' : 'bx-up-arrow-circle';

    const statusClass = emprestimo.status.toLowerCase().replace('_', '-');
    const statusLabel = formatarStatus(emprestimo.status);
    const statusIcon = getStatusIcon(emprestimo.status);

    const isQuitado = emprestimo.status === 'QUITADO';

    let dataInfo = '';
    if (emprestimo.dataEmprestimo) {
        dataInfo += `
            <div class="emprestimo-data">
                <i class='bx bx-calendar-check'></i>
                Emprestado em: ${formatarData(emprestimo.dataEmprestimo)}
            </div>
        `;
    }
    if (emprestimo.dataPrevisao) {
        const dataPrevisao = new Date(emprestimo.dataPrevisao);
        const hoje = new Date();
        const atrasado = !isQuitado && dataPrevisao < hoje;
        const icon = atrasado ? 'bx-error-circle' : 'bx-calendar';
        const classe = atrasado ? 'style="color: #ef4444;"' : '';
        dataInfo += `
            <div class="emprestimo-data" ${classe}>
                <i class='bx ${icon}'></i>
                Previsão: ${formatarData(emprestimo.dataPrevisao)}
                ${atrasado ? '(Atrasado!)' : ''}
            </div>
        `;
    }

    const progressoHtml = emprestimo.status !== 'QUITADO' ? `
        <div class="emprestimo-progresso">
            <div class="progresso-bar-container">
                <div class="progresso-bar" style="width: ${emprestimo.percentualPago}%"></div>
            </div>
            <div class="progresso-texto">
                ${emprestimo.percentualPago.toFixed(1)}% pago
            </div>
        </div>
    ` : '';

    const observacoesHtml = emprestimo.observacoes ? `
        <div class="emprestimo-observacoes">
            <strong>Observações:</strong> ${emprestimo.observacoes}
        </div>
    ` : '';

    const botoesAcao = isQuitado ? `
        <button class="btn-acao reabrir" onclick="reabrirEmprestimo('${emprestimo.id}')">
            <i class='bx bx-refresh'></i> Reabrir
        </button>
        <button class="btn-acao deletar" onclick="confirmarDeletar('${emprestimo.id}')">
            <i class='bx bx-trash'></i> Deletar
        </button>
    ` : `
        <button class="btn-acao registrar" onclick="abrirModalPagamento('${emprestimo.id}')">
            <i class='bx bx-money'></i> Registrar Pagamento
        </button>
        <button class="btn-acao quitar" onclick="quitarEmprestimo('${emprestimo.id}')">
            <i class='bx bx-check-circle'></i> Quitar
        </button>
        <button class="btn-acao editar" onclick="editarEmprestimo('${emprestimo.id}')">
            <i class='bx bx-edit'></i> Editar
        </button>
        <button class="btn-acao deletar" onclick="confirmarDeletar('${emprestimo.id}')">
            <i class='bx bx-trash'></i> Deletar
        </button>
    `;

    return `
        <div class="emprestimo-item ${tipoClass} ${isQuitado ? 'quitado' : ''}">
            <div class="emprestimo-header">
                <div class="emprestimo-info">
                    <div class="emprestimo-tipo ${tipoClass}">
                        <i class='bx ${tipoIcon}'></i>
                        ${tipoLabel}
                    </div>
                    <h3 class="emprestimo-pessoa">${emprestimo.pessoaOuGrupo}</h3>
                    ${dataInfo}
                </div>
                <div class="emprestimo-status ${statusClass}">
                    <i class='bx ${statusIcon}'></i>
                    ${statusLabel}
                </div>
            </div>

            <div class="emprestimo-valores">
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Total</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorTotal)}</span>
                </div>
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Pago</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorPago)}</span>
                </div>
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Restante</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorRestante)}</span>
                </div>
            </div>

            ${progressoHtml}
            ${observacoesHtml}

            <div class="emprestimo-acoes-item">
                ${botoesAcao}
            </div>
        </div>
    `;
}

// ============================================================================
// FILTROS
// ============================================================================

function filtrarEmprestimos(filtro) {
    filtroAtual = filtro;

    // Atualizar botões ativos
    document.querySelectorAll('.btn-filtro').forEach(btn => {
        btn.classList.remove('ativo');
    });
    document.querySelector(`[data-filtro="${filtro}"]`).classList.add('ativo');

    renderizarEmprestimos();
}

// ============================================================================
// MODAIS
// ============================================================================

function abrirModalNovoEmprestimo() {
    emprestimoEmEdicao = null;
    document.getElementById('modalTitulo').textContent = 'Novo Empréstimo Pessoal';
    document.getElementById('formEmprestimo').reset();
    const iValor = document.getElementById('inputValor');
    if (iValor && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iValor);
    // Pré-preenche data do empréstimo com hoje
    const iDataEmpNovo = document.getElementById('inputDataEmprestimo');
    if (iDataEmpNovo) {
        const hoje = new Date();
        iDataEmpNovo.value = String(hoje.getDate()).padStart(2,'0') + '/' +
            String(hoje.getMonth()+1).padStart(2,'0') + '/' + hoje.getFullYear();
    }
    popularSelectInstituicoes('inputInstituicao');
    atualizarLabelInstituicao();
    document.getElementById('modalEmprestimo').classList.add('aberto');
}

function editarEmprestimo(emprestimoId) {
    emprestimoEmEdicao = emprestimos.find(e => e.id === emprestimoId);
    if (!emprestimoEmEdicao) return;

    document.getElementById('modalTitulo').textContent = 'Editar Empréstimo';
    document.getElementById('inputTipo').value    = emprestimoEmEdicao.tipo;
    document.getElementById('inputPessoa').value  = emprestimoEmEdicao.pessoaOuGrupo;
    document.getElementById('inputObservacoes').value = emprestimoEmEdicao.observacoes || '';

    // Valor com máscara
    const iValor = document.getElementById('inputValor');
    const cents  = Math.round((emprestimoEmEdicao.valorTotal || 0) * 100);
    iValor.dataset.centavos = String(cents);
    const reais = Math.floor(cents / 100);
    iValor.value = 'R$ ' + String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + String(cents % 100).padStart(2, '0');

    // Data do empréstimo
    const iDataEmpEdit = document.getElementById('inputDataEmprestimo');
    iDataEmpEdit.value = (window.MainAPI?.dataDeISO && emprestimoEmEdicao.dataEmprestimo)
        ? window.MainAPI.dataDeISO(emprestimoEmEdicao.dataEmprestimo)
        : '';

    // Data com máscara (ISO → dd/mm/aaaa)
    const iData = document.getElementById('inputDataPrevisao');
    iData.value = (window.MainAPI?.dataDeISO && emprestimoEmEdicao.dataPrevisao)
        ? window.MainAPI.dataDeISO(emprestimoEmEdicao.dataPrevisao)
        : '';

    document.getElementById('modalEmprestimo').classList.add('aberto');
}

function fecharModalEmprestimo() {
    document.getElementById('modalEmprestimo').classList.remove('aberto');
    emprestimoEmEdicao = null;
}

function abrirModalPagamento(emprestimoId) {
    emprestimoParaPagamento = emprestimos.find(e => e.id === emprestimoId);
    if (!emprestimoParaPagamento) return;

    document.getElementById('infoPagamento').innerHTML = `
        <strong>Empréstimo:</strong> ${emprestimoParaPagamento.pessoaOuGrupo}<br>
        <strong>Valor Total:</strong> ${formatarMoeda(emprestimoParaPagamento.valorTotal)}<br>
        <strong>Já Pago:</strong> ${formatarMoeda(emprestimoParaPagamento.valorPago)}<br>
        <strong>Restante:</strong> ${formatarMoeda(emprestimoParaPagamento.valorRestante)}
    `;

    // Atualizar label da conta conforme o tipo
    const labelPag = document.getElementById('labelInstituicaoPagamento');
    if (labelPag) {
        labelPag.textContent = emprestimoParaPagamento.tipo === 'EMPRESTEI'
            ? 'Conta onde receberá o pagamento *'
            : 'Conta de onde sairá o pagamento *';
    }

    document.getElementById('formPagamento').reset();
    const iPag = document.getElementById('inputValorPagamento');
    if (iPag && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iPag);
    // Pré-preenche data do pagamento com hoje
    const iDataPagModal = document.getElementById('inputDataPagamento');
    if (iDataPagModal) {
        const hoje = new Date();
        iDataPagModal.value = String(hoje.getDate()).padStart(2,'0') + '/' +
            String(hoje.getMonth()+1).padStart(2,'0') + '/' + hoje.getFullYear();
    }
    popularSelectInstituicoes('inputInstituicaoPagamento');
    document.getElementById('modalPagamento').classList.add('aberto');
}

function fecharModalPagamento() {
    document.getElementById('modalPagamento').classList.remove('aberto');
    emprestimoParaPagamento = null;
}

// ============================================================================
// OPERAÇÕES
// ============================================================================

async function salvarEmprestimo(event) {
    event.preventDefault();

    const iValor = document.getElementById('inputValor');
    const iData  = document.getElementById('inputDataPrevisao');
    const iDataEmp = document.getElementById('inputDataEmprestimo');
    const valorTotal = window.MainAPI ? window.MainAPI.obterValorMoeda(iValor) : parseFloat(iValor.value);
    const dataISO    = window.MainAPI ? window.MainAPI.dataParaISO(iData.value) : iData.value;
    const dataEmpISO = window.MainAPI ? window.MainAPI.dataParaISO(iDataEmp?.value || '') : null;
    const instituicaoUsuarioId = parseInt(document.getElementById('inputInstituicao').value);

    if (!instituicaoUsuarioId) return mostrarNotificacao('Selecione uma conta!', 'erro');

    const dados = {
        usuarioId: usuarioLogado.id,
        tipo: document.getElementById('inputTipo').value,
        pessoaOuGrupo: document.getElementById('inputPessoa').value,
        valorTotal,
        instituicaoUsuarioId,
        dataEmprestimo: dataEmpISO || null,
        dataPrevisao: dataISO || null,
        observacoes: document.getElementById('inputObservacoes').value || null
    };

    try {
        let response;
        if (emprestimoEmEdicao) {
            response = await fetch(`${API_BASE}/emprestimos/${emprestimoEmEdicao.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(dados)
            });
        } else {
            response = await fetch(`${API_BASE}/emprestimos`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(dados)
            });
        }

        if (!response.ok) throw new Error('Erro ao salvar empréstimo');

        mostrarNotificacao(
            emprestimoEmEdicao ? 'Empréstimo atualizado!' : 'Empréstimo criado!',
            'sucesso'
        );

        fecharModalEmprestimo();
        await carregarResumo();
        await carregarEmprestimos();
    } catch (error) {
        console.error('Erro ao salvar:', error);
        mostrarNotificacao('Erro ao salvar empréstimo', 'erro');
    }
}

async function salvarPagamento(event) {
    event.preventDefault();

    const iPag = document.getElementById('inputValorPagamento');
    const valorPagamento = window.MainAPI ? window.MainAPI.obterValorMoeda(iPag) : parseFloat(iPag.value);
    const instituicaoUsuarioId = parseInt(document.getElementById('inputInstituicaoPagamento').value);

    if (!instituicaoUsuarioId) return mostrarNotificacao('Selecione uma conta!', 'erro');

    if (valorPagamento > emprestimoParaPagamento.valorRestante) {
        mostrarNotificacao('Valor não pode ser maior que o restante!', 'erro');
        return;
    }

    try {
        const response = await fetch(
            `${API_BASE}/emprestimos/${emprestimoParaPagamento.id}/pagamento-parcial`,
            {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    valorPago: valorPagamento,
                    instituicaoUsuarioId,
                    dataPagamento: window.MainAPI?.dataParaISO(document.getElementById('inputDataPagamento')?.value) || null
                })
            }
        );

        if (!response.ok) throw new Error('Erro ao registrar pagamento');

        mostrarNotificacao('Pagamento registrado!', 'sucesso');
        fecharModalPagamento();
        await carregarResumo();
        await carregarEmprestimos();
    } catch (error) {
        console.error('Erro ao registrar pagamento:', error);
        mostrarNotificacao('Erro ao registrar pagamento', 'erro');
    }
}

async function quitarEmprestimo(emprestimoId) {
    const emprestimo = emprestimos.find(e => e.id === emprestimoId);
    const tipoLabel = emprestimo?.tipo === 'EMPRESTEI' ? 'receberá o valor restante' : 'pagará o valor restante';

    _abrirSeletorInstituicaoEQuitar(emprestimoId, tipoLabel, emprestimo);
}

function _abrirSeletorInstituicaoEQuitar(emprestimoId, tipoLabel, emprestimo) {
    const div = document.getElementById('div_alerta');
    const conteudo = document.getElementById('conteudoAlerta');
    if (!div || !conteudo) return;

    conteudo.innerHTML = '';

    const msg = document.createElement('p');
    msg.style.cssText = 'margin-bottom:10px;text-align:center;line-height:1.5;';
    msg.textContent = `Em qual conta ${tipoLabel}?`;
    conteudo.appendChild(msg);

    const sel = document.createElement('select');
    sel.style.cssText = 'width:100%;padding:8px;border-radius:8px;border:1px solid var(--cor-principal);background:var(--cor-fundo-campo,#fff);color:var(--cor-texto-principal);margin-bottom:12px;';
    sel.innerHTML = '<option value="">Selecione a conta...</option>';
    _instituicoes.forEach(inst => {
        const opt = document.createElement('option');
        opt.value = inst.id;
        opt.textContent = inst.intituicao.nome;
        sel.appendChild(opt);
    });
    conteudo.appendChild(sel);

    const btns = document.createElement('div');
    btns.style.cssText = 'display:flex;gap:8px;justify-content:center;';

    const btnNao = document.createElement('button');
    btnNao.textContent = 'Cancelar';
    btnNao.style.cssText = 'background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid var(--cor-tinte-borda,#ccc);';
    btnNao.onclick = () => { div.style.display = 'none'; };

    const btnSim = document.createElement('button');
    btnSim.textContent = 'Quitar';
    btnSim.onclick = async () => {
        const instId = parseInt(sel.value);
        if (!instId) { mostrarNotificacao('Selecione uma conta!', 'erro'); return; }
        div.style.display = 'none';
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}/quitar`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ instituicaoUsuarioId: instId })
            });
            if (!response.ok) {
                const err = await response.json().catch(() => ({}));
                throw new Error(err.message || `HTTP ${response.status}`);
            }
            mostrarNotificacao('Empréstimo quitado!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao quitar:', error);
            mostrarNotificacao('Erro ao quitar: ' + error.message, 'erro');
        }
    };

    btns.appendChild(btnNao);
    btns.appendChild(btnSim);
    conteudo.appendChild(btns);
    div.style.display = 'flex';
}

async function reabrirEmprestimo(emprestimoId) {
    confirmar('Deseja reabrir este empréstimo?', async () => {
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}/reabrir`, {
                method: 'PATCH'
            });
            if (!response.ok) throw new Error('Erro ao reabrir empréstimo');
            mostrarNotificacao('Empréstimo reaberto!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao reabrir:', error);
            mostrarNotificacao('Erro ao reabrir empréstimo', 'erro');
        }
    });
}

async function confirmarDeletar(emprestimoId) {
    confirmar('Deseja realmente deletar este empréstimo? Esta ação não pode ser desfeita.', async () => {
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}`, {
                method: 'DELETE'
            });
            if (!response.ok) throw new Error('Erro ao deletar empréstimo');
            mostrarNotificacao('Empréstimo deletado!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao deletar:', error);
            mostrarNotificacao('Erro ao deletar empréstimo', 'erro');
        }
    });
}

// ============================================================================
// UTILITÁRIOS
// ============================================================================

function formatarMoeda(valor) {
    return new Intl.NumberFormat('pt-BR', {
        style: 'currency',
        currency: 'BRL'
    }).format(valor);
}

function formatarData(dataStr) {
    if (!dataStr) return '';
    const data = new Date(dataStr + 'T00:00:00');
    return data.toLocaleDateString('pt-BR');
}

function formatarStatus(status) {
    const statusMap = {
        'PENDENTE': 'Pendente',
        'PAGO_PARCIAL': 'Pago Parcial',
        'QUITADO': 'Quitado'
    };
    return statusMap[status] || status;
}

function getStatusIcon(status) {
    const iconMap = {
        'PENDENTE': 'bx-time-five',
        'PAGO_PARCIAL': 'bx-info-circle',
        'QUITADO': 'bx-check-circle'
    };
    return iconMap[status] || 'bx-info-circle';
}

function confirmar(mensagem, onConfirm) {
    const div = document.getElementById('div_alerta');
    const conteudo = document.getElementById('conteudoAlerta');
    if (!div || !conteudo) { if (window.confirm(mensagem)) onConfirm(); return; }

    conteudo.innerHTML = '';

    const msg = document.createElement('p');
    msg.style.cssText = 'margin-bottom:16px;text-align:center;line-height:1.5;';
    msg.textContent = mensagem;

    const btns = document.createElement('div');
    btns.style.cssText = 'display:flex;gap:8px;justify-content:center;';

    const btnNao = document.createElement('button');
    btnNao.textContent = 'Cancelar';
    btnNao.style.cssText = 'background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid var(--cor-tinte-borda,#ccc);';
    btnNao.onclick = () => { div.style.display = 'none'; };

    const btnSim = document.createElement('button');
    btnSim.textContent = 'Confirmar';
    btnSim.onclick = () => { div.style.display = 'none'; onConfirm(); };

    btns.appendChild(btnNao);
    btns.appendChild(btnSim);
    conteudo.appendChild(msg);
    conteudo.appendChild(btns);
    div.style.display = 'flex';
}

function mostrarNotificacao(mensagem, tipo = 'info') {
    // Criar elemento de notificação
    const notif = document.createElement('div');
    notif.className = `notificacao notif-${tipo}`;
    notif.innerHTML = `
        <i class='bx ${tipo === 'sucesso' ? 'bx-check-circle' : 'bx-error-circle'}'></i>
        <span>${mensagem}</span>
    `;

    // Adicionar estilos inline
    Object.assign(notif.style, {
        position: 'fixed',
        top: '20px',
        right: '20px',
        zIndex: '99999',
        background: tipo === 'sucesso' ? '#10b981' : '#ef4444',
        color: '#fff',
        padding: '1rem 1.5rem',
        borderRadius: '10px',
        boxShadow: '0 8px 24px rgba(0,0,0,0.2)',
        display: 'flex',
        alignItems: 'center',
        gap: '0.75rem',
        fontSize: '0.95rem',
        fontWeight: '600',
        animation: 'slideInRight 0.3s ease'
    });

    document.body.appendChild(notif);

    setTimeout(() => {
        notif.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => notif.remove(), 300);
    }, 3000);
}

// Adicionar estilos de animação
const style = document.createElement('style');
style.textContent = `
    @keyframes slideInRight {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }
    @keyframes slideOutRight {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);

// ============================================================================
// EMPRéSTIMOS BANCáRIOS
// ============================================================================
async function carregarBancarios() {
    try {
        const r = await fetch(API_BASE + '/emprestimos-bancarios/usuarios/' + usuarioLogado.id);
        if (r.status === 204) { bancarios = []; renderizarBancarios(); atualizarResumoBancarios(); return; }
        if (!r.ok) throw new Error('Erro');
        bancarios = await r.json();
        renderizarBancarios(); atualizarResumoBancarios();
    } catch(err) { console.error(err); mostrarNotificacao('Erro ao carregar empréstimos bancários', 'erro'); }
}
function atualizarResumoBancarios() {
    const ativos = bancarios.filter(b => b.status === 'ATIVO');
    document.getElementById('bancarioContratosAtivos').textContent = ativos.length;
    const saldo = ativos.reduce((s, b) => s + (b.saldoDevedor || 0), 0);
    document.getElementById('bancarioSaldoDevedor').textContent = 'Saldo devedor: ' + formatarMoeda(saldo);
    const comData = ativos.filter(b => b.proximaParcela).sort((a, b) => new Date(a.proximaParcela) - new Date(b.proximaParcela));
    if (comData.length > 0) {
        document.getElementById('bancarioProximaParcelaValor').textContent = formatarMoeda(comData[0].valorParcela);
        document.getElementById('bancarioProximaParcelaData').textContent = formatarData(comData[0].proximaParcela);
    } else {
        document.getElementById('bancarioProximaParcelaValor').textContent = 'R$ 0,00';
        document.getElementById('bancarioProximaParcelaData').textContent = '-';
    }
}
function filtrarBancarios(filtro) {
    filtroBancarioAtual = filtro;
    document.querySelectorAll('[data-filtro-b]').forEach(btn => btn.classList.remove('ativo'));
    document.querySelector('[data-filtro-b="' + filtro + '"]').classList.add('ativo');
    renderizarBancarios();
}
function renderizarBancarios() {
    const container = document.getElementById('listaBancarios');
    let lista = [...bancarios];
    if (filtroBancarioAtual === 'ATIVO') lista = lista.filter(b => b.status === 'ATIVO');
    else if (filtroBancarioAtual === 'QUITADO') lista = lista.filter(b => b.status === 'QUITADO');
    if (lista.length === 0) { container.innerHTML = '<div class="estado-vazio"><i class=\'bx bx-bank\'></i><h3>Nenhum empréstimo bancário</h3></div>'; return; }
    container.innerHTML = lista.map(b => criarCardBancario(b)).join('');
}
const _modLabel = { PESSOAL: 'Crédito Pessoal', VEICULO: 'Financ. Veículo', IMOVEL: 'Financ. Imóvel', CONSIGNADO: 'Consignado', CAPITAL_DE_GIRO: 'Capital de Giro' };
function criarCardBancario(b) {
    const isQ = b.status === 'QUITADO', atr = b.atrasado && !isQ;
    const pct = b.totalParcelas > 0 ? (b.parcelasPagas / b.totalParcelas * 100).toFixed(1) : 0;
    const sc = isQ ? 'quitado' : (atr ? 'atrasado' : 'ativo'), sl = isQ ? 'Quitado' : (atr ? 'Atrasado' : 'Ativo'), si = isQ ? 'bx-check-circle' : (atr ? 'bx-error-circle' : 'bx-time-five');
    const ph = b.proximaParcela ? '<div class="emprestimo-data"' + (atr ? ' style="color:#ef4444;"' : '') + '><i class=\'bx ' + (atr ? 'bx-error-circle' : 'bx-calendar') + '\'></i> ' + (atr ? 'Vencida: ' : 'Próxima: ') + formatarData(b.proximaParcela) + '</div>' : '';
    const ch = b.dataContratacao ? '<div class="emprestimo-data"><i class=\'bx bx-calendar-check\'></i> Contratado: ' + formatarData(b.dataContratacao) + '</div>' : '';
    const ba = isQ ? '<button class="btn-acao deletar" onclick="confirmarDeletarBancario(\'' + b.id + '\')"><i class=\'bx bx-trash\'></i> Deletar</button>'
        : '<button class="btn-acao registrar" onclick="abrirModalPagarParcela(\'' + b.id + '\')"><i class=\'bx bx-money\'></i> Pagar Parcela</button><button class="btn-acao quitar" onclick="quitarBancario(\'' + b.id + '\')"><i class=\'bx bx-check-circle\'></i> Quitar</button><button class="btn-acao deletar" onclick="confirmarDeletarBancario(\'' + b.id + '\')"><i class=\'bx bx-trash\'></i> Deletar</button>';
    return '<div class="emprestimo-item emprestei' + (isQ ? ' quitado' : '') + '"><div class="emprestimo-header"><div class="emprestimo-info"><div class="emprestimo-tipo emprestei"><i class=\'bx bx-bank\'></i> ' + (_modLabel[b.modalidade] || b.modalidade) + '</div><h3 class="emprestimo-pessoa">' + b.bancoNome + '</h3>' + ch + ph + '</div><div class="emprestimo-status ' + sc + '"><i class=\'bx ' + si + '\'></i> ' + sl + '</div></div><div class="emprestimo-valores"><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Valor Contratado</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.valorPrincipal) + '</span></div><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Parcela (' + b.taxaJurosMensal + '% a.m.)</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.valorParcela) + '</span></div><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Saldo Devedor</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.saldoDevedor) + '</span></div></div>' + (!isQ ? '<div class="emprestimo-progresso"><div class="progresso-bar-container"><div class="progresso-bar" style="width:' + pct + '%"></div></div><div class="progresso-texto">' + b.parcelasPagas + '/' + b.totalParcelas + ' parcelas (' + pct + '%)</div></div>' : '') + (b.observacoes ? '<div class="emprestimo-observacoes"><strong>Obs:</strong> ' + b.observacoes + '</div>' : '') + '<div class="emprestimo-acoes-item">' + ba + '</div></div>';
}
function calcularParcelaEstimada() {
    const pv = window.MainAPI ? window.MainAPI.obterValorMoeda(document.getElementById('bInputPrincipal')) : 0;
    const tx = parseFloat(document.getElementById('bInputTaxa')?.value?.replace(',','.')) || 0;
    const n = parseInt(document.getElementById('bInputParcelas')?.value) || 0;
    const el = document.getElementById('bParcelaEstimada'); if (!el) return;
    if (pv <= 0 || n <= 0) { el.textContent = 'R$ 0,00'; return; }
    const pmt = tx <= 0 ? pv/n : (() => { const i=tx/100; const f=Math.pow(1+i,n); return pv*(i*f)/(f-1); })();
    el.textContent = formatarMoeda(pmt);
}
function abrirModalNovoBancario() {
    document.getElementById('formBancario').reset();
    const iv = document.getElementById('bInputPrincipal'); if (iv && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iv);
    document.getElementById('bParcelaEstimada').textContent = 'R$ 0,00';
    const h = new Date(); const hs = String(h.getDate()).padStart(2,'0') + '/' + String(h.getMonth()+1).padStart(2,'0') + '/' + h.getFullYear();
    const bc = document.getElementById('bInputContratacao'); if (bc) bc.value = hs;
    ['bInputPrincipal','bInputContratacao','bInputPrimeiraParcela'].forEach(id => { const el=document.getElementById(id); if(el && window.MainAPI) { if(id==='bInputPrincipal' && window.MainAPI.aplicarMascaraMoeda) window.MainAPI.aplicarMascaraMoeda(el); else if(window.MainAPI.aplicarMascaraData) window.MainAPI.aplicarMascaraData(el); } });
    popularSelectInstituicoes('bInputInstituicao');
    ['bInputTaxa','bInputParcelas'].forEach(id => { const el=document.getElementById(id); if(el) el.addEventListener('input', calcularParcelaEstimada); });
    document.getElementById('modalBancario').classList.add('aberto');
}
function fecharModalBancario() { document.getElementById('modalBancario').classList.remove('aberto'); }
async function salvarBancario(event) {
    event.preventDefault();
    const pv = window.MainAPI ? window.MainAPI.obterValorMoeda(document.getElementById('bInputPrincipal')) : 0;
    const tx = parseFloat(document.getElementById('bInputTaxa').value?.replace(',','.')) || 0;
    const n = parseInt(document.getElementById('bInputParcelas').value);
    const instId = parseInt(document.getElementById('bInputInstituicao').value) || null;
    const dataC = window.MainAPI?.dataParaISO(document.getElementById('bInputContratacao').value) || null;
    const dataP = window.MainAPI?.dataParaISO(document.getElementById('bInputPrimeiraParcela').value) || null;
    const dados = { usuarioId: usuarioLogado.id, bancoNome: document.getElementById('bInputBanco').value, modalidade: document.getElementById('bInputModalidade').value, valorPrincipal: pv, taxaJurosMensal: tx, totalParcelas: n, dataContratacao: dataC, dataPrimeiraParcela: dataP, instituicaoUsuarioId: instId, observacoes: document.getElementById('bInputObs').value || null };
    try {
        const resp = await fetch(API_BASE + '/emprestimos-bancarios', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(dados) });
        if (!resp.ok) { const err = await resp.json().catch(() => ({})); throw new Error(err.message || 'HTTP ' + resp.status); }
        mostrarNotificacao('Empréstimo bancário registrado!', 'sucesso'); fecharModalBancario(); await carregarBancarios();
    } catch(err) { mostrarNotificacao('Erro: ' + err.message, 'erro'); }
}
function abrirModalPagarParcela(bid) {
    bancarioParaPagamento = bancarios.find(b => b.id === bid); if (!bancarioParaPagamento) return;
    document.getElementById('infoPagarParcela').innerHTML = '<strong>Banco:</strong> ' + bancarioParaPagamento.bancoNome + '<br><strong>Parcela:</strong> ' + (bancarioParaPagamento.parcelasPagas+1) + '/' + bancarioParaPagamento.totalParcelas + '<br><strong>Valor:</strong> ' + formatarMoeda(bancarioParaPagamento.valorParcela);
    document.getElementById('formPagarParcela').reset();
    const h = new Date(); const hs = String(h.getDate()).padStart(2,'0')+'/'+String(h.getMonth()+1).padStart(2,'0')+'/'+h.getFullYear();
    const bd = document.getElementById('bPagDataPagamento'); if (bd) bd.value = hs;
    popularSelectInstituicoes('bPagInstituicao');
    document.getElementById('modalPagarParcela').classList.add('aberto');
}
function fecharModalPagarParcela() { document.getElementById('modalPagarParcela').classList.remove('aberto'); bancarioParaPagamento = null; }
async function confirmarPagarParcela(event) {
    event.preventDefault();
    const instId = parseInt(document.getElementById('bPagInstituicao').value) || null;
    const dp = window.MainAPI?.dataParaISO(document.getElementById('bPagDataPagamento').value) || null;
    try {
        const resp = await fetch(API_BASE+'/emprestimos-bancarios/'+bancarioParaPagamento.id+'/pagar-parcela', { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify({instituicaoUsuarioId:instId,dataPagamento:dp}) });
        if (!resp.ok) throw new Error('Erro'); mostrarNotificacao('Parcela paga!','sucesso'); fecharModalPagarParcela(); await carregarBancarios();
    } catch(err) { mostrarNotificacao('Erro: '+err.message,'erro'); }
}
function quitarBancario(bid) {
    const b = bancarios.find(b => b.id === bid);
    const div = document.getElementById('div_alerta'), cnt = document.getElementById('conteudoAlerta');
    cnt.innerHTML = '';
    const msg = document.createElement('p'); msg.style.cssText='margin-bottom:10px;text-align:center;line-height:1.5;';
    msg.innerHTML = '<strong>Quitar:</strong> ' + b?.bancoNome + '<br>' + b?.parcelasRestantes + ' parcelas restantes x ' + formatarMoeda(b?.valorParcela);
    cnt.appendChild(msg);
    const sel = document.createElement('select'); sel.style.cssText='width:100%;padding:8px;border-radius:8px;border:1px solid var(--cor-principal);background:var(--cor-fundo-campo,#fff);color:var(--cor-texto-principal);margin-bottom:12px;';
    sel.innerHTML='<option value="">Selecione a conta...</option>'; _instituicoes.forEach(inst => { const o=document.createElement('option'); o.value=inst.id; o.textContent=inst.intituicao.nome; sel.appendChild(o); }); cnt.appendChild(sel);
    const btns=document.createElement('div'); btns.style.cssText='display:flex;gap:8px;justify-content:center;';
    const bn=document.createElement('button'); bn.textContent='Cancelar'; bn.style.cssText='background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid #ccc;'; bn.onclick=()=>{div.style.display='none';};
    const bs=document.createElement('button'); bs.textContent='Confirmar';
    bs.onclick=async()=>{ const ii=parseInt(sel.value)||null; div.style.display='none'; try { const resp=await fetch(API_BASE+'/emprestimos-bancarios/'+bid+'/quitar',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({instituicaoUsuarioId:ii,dataPagamento:null})}); if(!resp.ok) throw new Error('Erro'); mostrarNotificacao('Quitado!','sucesso'); await carregarBancarios(); } catch(err){mostrarNotificacao('Erro: '+err.message,'erro');} };
    btns.appendChild(bn); btns.appendChild(bs); cnt.appendChild(btns); div.style.display='flex';
}
function confirmarDeletarBancario(bid) {
    confirmar('Deletar este empréstimo bancário?', async () => {
        try { const r=await fetch(API_BASE+'/emprestimos-bancarios/'+bid,{method:'DELETE'}); if(!r.ok) throw new Error('Erro'); mostrarNotificacao('Deletado!','sucesso'); await carregarBancarios(); }
        catch(err) { mostrarNotificacao('Erro: '+err.message,'erro'); }
    });
}
// Fechar modal ao clicar fora
window.onclick = function(event) {
    [['modalEmprestimo',fecharModalEmprestimo],['modalPagamento',fecharModalPagamento],['modalBancario',fecharModalBancario],['modalPagarParcela',fecharModalPagarParcela]]
        .forEach(([id,fn]) => { const m=document.getElementById(id); if(event.target===m) fn(); });
};

// ============================================================================
// EMPRÉSTIMOS - JavaScript
// ============================================================================

const API_BASE = 'http://localhost:8080';
let usuarioLogado = null;
let emprestimos = [];
let emprestimoEmEdicao = null;
let emprestimoParaPagamento = null;
let filtroAtual = 'todos';
let _instituicoes = [];

// Bancários
let bancarios = [];
let bancarioParaPagamento = null;
let filtroBancarioAtual = 'todos';
let parcelasCarregadas = {};
let parcelasPaginaAtual = 1;
let parcelasPorPagina = 5;
let emprestimoIdAtualParcelas = null;

// ── Inicialização ──
window.addEventListener('DOMContentLoaded', () => {
    const userData = localStorage.getItem('usuarioLogado');
    if (!userData) { window.location.href = 'index.html'; return; }
    usuarioLogado = JSON.parse(userData);

    // Aplicar máscaras - pessoais
    const aplicarMascara = (id, fn) => { const el = document.getElementById(id); if (el && window.MainAPI?.[fn]) window.MainAPI[fn](el); };
    aplicarMascara('inputValor', 'aplicarMascaraMoeda');
    aplicarMascara('inputDataPrevisao', 'aplicarMascaraData');
    aplicarMascara('inputDataEmprestimo', 'aplicarMascaraData');
    aplicarMascara('inputValorPagamento', 'aplicarMascaraMoeda');
    aplicarMascara('inputDataPagamento', 'aplicarMascaraData');
    // Máscaras bancários
    aplicarMascara('bInputPrincipal', 'aplicarMascaraMoeda');
    aplicarMascara('bInputContratacao', 'aplicarMascaraData');
    aplicarMascara('bInputPrimeiraParcela', 'aplicarMascaraData');
    aplicarMascara('bPagDataPagamento', 'aplicarMascaraData');

    // Auto-calcular parcela ao digitar
    ['bInputPrincipal','bInputTaxa','bInputParcelas'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', calcularParcelaEstimada);
    });

    carregarInstituicoes();
    carregarResumo();
    carregarEmprestimos();
    carregarBancarios();
});

// ── Tabs ──
function trocarAba(aba) {
    document.getElementById('abaPessoais').style.display = aba === 'pessoais' ? '' : 'none';
    document.getElementById('abaBancarios').style.display = aba === 'bancarios' ? '' : 'none';
    document.getElementById('tabPessoais').classList.toggle('ativo', aba === 'pessoais');
    document.getElementById('tabBancarios').classList.toggle('ativo', aba === 'bancarios');
}

// ============================================================================
// INSTITUIÇÕES
// ============================================================================

async function carregarInstituicoes() {
    try {
        _instituicoes = await window.MainAPI.getInstituicoes(usuarioLogado.id);
        popularSelectInstituicoes('inputInstituicao');
        popularSelectInstituicoes('inputInstituicaoPagamento');
    } catch (e) {
        console.error('Erro ao carregar instituições:', e);
    }
}

function popularSelectInstituicoes(selectId) {
    const sel = document.getElementById(selectId);
    if (!sel) return;
    sel.innerHTML = '<option value="">Selecione a conta...</option>';
    _instituicoes.forEach(inst => {
        const opt = document.createElement('option');
        opt.value = inst.id;
        opt.textContent = inst.intituicao.nome;
        sel.appendChild(opt);
    });
}

function atualizarLabelInstituicao() {
    const tipo = document.getElementById('inputTipo')?.value;
    const label = document.getElementById('labelInstituicao');
    if (!label) return;
    if (tipo === 'EMPRESTEI') {
        label.textContent = 'Conta de onde sairá o dinheiro *';
    } else if (tipo === 'PEDI_EMPRESTADO') {
        label.textContent = 'Conta onde o dinheiro será recebido *';
    } else {
        label.textContent = 'Conta *';
    }
}

// ============================================================================
// CARREGAR DADOS
// ============================================================================

async function carregarResumo() {
    try {
        const response = await fetch(`${API_BASE}/emprestimos/usuarios/${usuarioLogado.id}/resumo`);
        if (!response.ok) throw new Error('Erro ao carregar resumo');

        const resumo = await response.json();

        document.getElementById('valorAReceber').textContent = formatarMoeda(resumo.valorTotalAReceber);
        document.getElementById('detalhesReceber').textContent =
            `${resumo.quantidadePessoasDevem} pessoa(s)`;

        document.getElementById('valorAPagar').textContent = formatarMoeda(resumo.valorTotalAPagar);
        document.getElementById('detalhesPagar').textContent =
            `${resumo.quantidadePessoasDevo} pessoa(s)`;
    } catch (error) {
        console.error('Erro ao carregar resumo:', error);
        mostrarNotificacao('Erro ao carregar resumo', 'erro');
    }
}

async function carregarEmprestimos() {
    try {
        const response = await fetch(`${API_BASE}/emprestimos/usuarios/${usuarioLogado.id}`);

        if (response.status === 204) {
            emprestimos = [];
            renderizarEmprestimos();
            return;
        }

        if (!response.ok) throw new Error('Erro ao carregar empréstimos');

        emprestimos = await response.json();
        renderizarEmprestimos();
    } catch (error) {
        console.error('Erro ao carregar empréstimos:', error);
        mostrarNotificacao('Erro ao carregar empréstimos', 'erro');
    }
}

// ============================================================================
// RENDERIZAÇÃO
// ============================================================================

function renderizarEmprestimos() {
    const container = document.getElementById('listaEmprestimos');

    let emprestimosFiltrados = [...emprestimos];

    // Aplicar filtros
    switch (filtroAtual) {
        case 'EMPRESTEI':
            emprestimosFiltrados = emprestimos.filter(e => e.tipo === 'EMPRESTEI');
            break;
        case 'PEDI_EMPRESTADO':
            emprestimosFiltrados = emprestimos.filter(e => e.tipo === 'PEDI_EMPRESTADO');
            break;
        case 'pendentes':
            emprestimosFiltrados = emprestimos.filter(e =>
                e.status === 'PENDENTE' || e.status === 'PAGO_PARCIAL');
            break;
        case 'quitados':
            emprestimosFiltrados = emprestimos.filter(e => e.status === 'QUITADO');
            break;
    }

    if (emprestimosFiltrados.length === 0) {
        container.innerHTML = `
            <div class="estado-vazio">
                <i class='bx bx-wallet'></i>
                <h3>Nenhum empréstimo encontrado</h3>
                <p>Clique em "Novo Empréstimo" para registrar um empréstimo.</p>
            </div>
        `;
        return;
    }

    container.innerHTML = emprestimosFiltrados.map(e => criarCardEmprestimo(e)).join('');
}

function criarCardEmprestimo(emprestimo) {
    const tipoClass = emprestimo.tipo === 'EMPRESTEI' ? 'emprestei' : 'pedi-emprestado';
    const tipoLabel = emprestimo.tipo === 'EMPRESTEI' ? 'Emprestei' : 'Peguei Emprestado';
    const tipoIcon = emprestimo.tipo === 'EMPRESTEI' ? 'bx-down-arrow-circle' : 'bx-up-arrow-circle';

    const statusClass = emprestimo.status.toLowerCase().replace('_', '-');
    const statusLabel = formatarStatus(emprestimo.status);
    const statusIcon = getStatusIcon(emprestimo.status);

    const isQuitado = emprestimo.status === 'QUITADO';

    let dataInfo = '';
    if (emprestimo.dataEmprestimo) {
        dataInfo += `
            <div class="emprestimo-data">
                <i class='bx bx-calendar-check'></i>
                Emprestado em: ${formatarData(emprestimo.dataEmprestimo)}
            </div>
        `;
    }
    if (emprestimo.dataPrevisao) {
        const dataPrevisao = new Date(emprestimo.dataPrevisao);
        const hoje = new Date();
        const atrasado = !isQuitado && dataPrevisao < hoje;
        const icon = atrasado ? 'bx-error-circle' : 'bx-calendar';
        const classe = atrasado ? 'style="color: #ef4444;"' : '';
        dataInfo += `
            <div class="emprestimo-data" ${classe}>
                <i class='bx ${icon}'></i>
                Previsão: ${formatarData(emprestimo.dataPrevisao)}
                ${atrasado ? '(Atrasado!)' : ''}
            </div>
        `;
    }

    const progressoHtml = emprestimo.status !== 'QUITADO' ? `
        <div class="emprestimo-progresso">
            <div class="progresso-bar-container">
                <div class="progresso-bar" style="width: ${emprestimo.percentualPago}%"></div>
            </div>
            <div class="progresso-texto">
                ${emprestimo.percentualPago.toFixed(1)}% pago
            </div>
        </div>
    ` : '';

    const observacoesHtml = emprestimo.observacoes ? `
        <div class="emprestimo-observacoes">
            <strong>Observações:</strong> ${emprestimo.observacoes}
        </div>
    ` : '';

    const botoesAcao = isQuitado ? `
        <button class="btn-acao reabrir" onclick="reabrirEmprestimo('${emprestimo.id}')">
            <i class='bx bx-refresh'></i> Reabrir
        </button>
        <button class="btn-acao deletar" onclick="confirmarDeletar('${emprestimo.id}')">
            <i class='bx bx-trash'></i> Deletar
        </button>
    ` : `
        <button class="btn-acao registrar" onclick="abrirModalPagamento('${emprestimo.id}')">
            <i class='bx bx-money'></i> Registrar Pagamento
        </button>
        <button class="btn-acao quitar" onclick="quitarEmprestimo('${emprestimo.id}')">
            <i class='bx bx-check-circle'></i> Quitar
        </button>
        <button class="btn-acao editar" onclick="editarEmprestimo('${emprestimo.id}')">
            <i class='bx bx-edit'></i> Editar
        </button>
        <button class="btn-acao deletar" onclick="confirmarDeletar('${emprestimo.id}')">
            <i class='bx bx-trash'></i> Deletar
        </button>
    `;

    return `
        <div class="emprestimo-item ${tipoClass} ${isQuitado ? 'quitado' : ''}">
            <div class="emprestimo-header">
                <div class="emprestimo-info">
                    <div class="emprestimo-tipo ${tipoClass}">
                        <i class='bx ${tipoIcon}'></i>
                        ${tipoLabel}
                    </div>
                    <h3 class="emprestimo-pessoa">${emprestimo.pessoaOuGrupo}</h3>
                    ${dataInfo}
                </div>
                <div class="emprestimo-status ${statusClass}">
                    <i class='bx ${statusIcon}'></i>
                    ${statusLabel}
                </div>
            </div>

            <div class="emprestimo-valores">
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Total</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorTotal)}</span>
                </div>
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Pago</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorPago)}</span>
                </div>
                <div class="emprestimo-valor-item">
                    <span class="emprestimo-valor-label">Valor Restante</span>
                    <span class="emprestimo-valor-numero">${formatarMoeda(emprestimo.valorRestante)}</span>
                </div>
            </div>

            ${progressoHtml}
            ${observacoesHtml}

            <div class="emprestimo-acoes-item">
                ${botoesAcao}
            </div>
        </div>
    `;
}

// ============================================================================
// FILTROS
// ============================================================================

function filtrarEmprestimos(filtro) {
    filtroAtual = filtro;

    // Atualizar botões ativos
    document.querySelectorAll('.btn-filtro').forEach(btn => {
        btn.classList.remove('ativo');
    });
    document.querySelector(`[data-filtro="${filtro}"]`).classList.add('ativo');

    renderizarEmprestimos();
}

// ============================================================================
// MODAIS
// ============================================================================

function abrirModalNovoEmprestimo() {
    emprestimoEmEdicao = null;
    document.getElementById('modalTitulo').textContent = 'Novo Empréstimo Pessoal';
    document.getElementById('formEmprestimo').reset();
    const iValor = document.getElementById('inputValor');
    if (iValor && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iValor);
    // Pré-preenche data do empréstimo com hoje
    const iDataEmpNovo = document.getElementById('inputDataEmprestimo');
    if (iDataEmpNovo) {
        const hoje = new Date();
        iDataEmpNovo.value = String(hoje.getDate()).padStart(2,'0') + '/' +
            String(hoje.getMonth()+1).padStart(2,'0') + '/' + hoje.getFullYear();
    }
    popularSelectInstituicoes('inputInstituicao');
    atualizarLabelInstituicao();
    document.getElementById('modalEmprestimo').classList.add('aberto');
}

function editarEmprestimo(emprestimoId) {
    emprestimoEmEdicao = emprestimos.find(e => e.id === emprestimoId);
    if (!emprestimoEmEdicao) return;

    document.getElementById('modalTitulo').textContent = 'Editar Empréstimo';
    document.getElementById('inputTipo').value    = emprestimoEmEdicao.tipo;
    document.getElementById('inputPessoa').value  = emprestimoEmEdicao.pessoaOuGrupo;
    document.getElementById('inputObservacoes').value = emprestimoEmEdicao.observacoes || '';

    // Valor com máscara
    const iValor = document.getElementById('inputValor');
    const cents  = Math.round((emprestimoEmEdicao.valorTotal || 0) * 100);
    iValor.dataset.centavos = String(cents);
    const reais = Math.floor(cents / 100);
    iValor.value = 'R$ ' + String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + String(cents % 100).padStart(2, '0');

    // Data do empréstimo
    const iDataEmpEdit = document.getElementById('inputDataEmprestimo');
    iDataEmpEdit.value = (window.MainAPI?.dataDeISO && emprestimoEmEdicao.dataEmprestimo)
        ? window.MainAPI.dataDeISO(emprestimoEmEdicao.dataEmprestimo)
        : '';

    // Data com máscara (ISO → dd/mm/aaaa)
    const iData = document.getElementById('inputDataPrevisao');
    iData.value = (window.MainAPI?.dataDeISO && emprestimoEmEdicao.dataPrevisao)
        ? window.MainAPI.dataDeISO(emprestimoEmEdicao.dataPrevisao)
        : '';

    document.getElementById('modalEmprestimo').classList.add('aberto');
}

function fecharModalEmprestimo() {
    document.getElementById('modalEmprestimo').classList.remove('aberto');
    emprestimoEmEdicao = null;
}

function abrirModalPagamento(emprestimoId) {
    emprestimoParaPagamento = emprestimos.find(e => e.id === emprestimoId);
    if (!emprestimoParaPagamento) return;

    document.getElementById('infoPagamento').innerHTML = `
        <strong>Empréstimo:</strong> ${emprestimoParaPagamento.pessoaOuGrupo}<br>
        <strong>Valor Total:</strong> ${formatarMoeda(emprestimoParaPagamento.valorTotal)}<br>
        <strong>Já Pago:</strong> ${formatarMoeda(emprestimoParaPagamento.valorPago)}<br>
        <strong>Restante:</strong> ${formatarMoeda(emprestimoParaPagamento.valorRestante)}
    `;

    // Atualizar label da conta conforme o tipo
    const labelPag = document.getElementById('labelInstituicaoPagamento');
    if (labelPag) {
        labelPag.textContent = emprestimoParaPagamento.tipo === 'EMPRESTEI'
            ? 'Conta onde receberá o pagamento *'
            : 'Conta de onde sairá o pagamento *';
    }

    document.getElementById('formPagamento').reset();
    const iPag = document.getElementById('inputValorPagamento');
    if (iPag && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iPag);
    // Pré-preenche data do pagamento com hoje
    const iDataPagModal = document.getElementById('inputDataPagamento');
    if (iDataPagModal) {
        const hoje = new Date();
        iDataPagModal.value = String(hoje.getDate()).padStart(2,'0') + '/' +
            String(hoje.getMonth()+1).padStart(2,'0') + '/' + hoje.getFullYear();
    }
    popularSelectInstituicoes('inputInstituicaoPagamento');
    document.getElementById('modalPagamento').classList.add('aberto');
}

function fecharModalPagamento() {
    document.getElementById('modalPagamento').classList.remove('aberto');
    emprestimoParaPagamento = null;
}

// ============================================================================
// OPERAÇÕES
// ============================================================================

async function salvarEmprestimo(event) {
    event.preventDefault();

    const iValor = document.getElementById('inputValor');
    const iData  = document.getElementById('inputDataPrevisao');
    const iDataEmp = document.getElementById('inputDataEmprestimo');
    const valorTotal = window.MainAPI ? window.MainAPI.obterValorMoeda(iValor) : parseFloat(iValor.value);
    const dataISO    = window.MainAPI ? window.MainAPI.dataParaISO(iData.value) : iData.value;
    const dataEmpISO = window.MainAPI ? window.MainAPI.dataParaISO(iDataEmp?.value || '') : null;
    const instituicaoUsuarioId = parseInt(document.getElementById('inputInstituicao').value);

    if (!instituicaoUsuarioId) return mostrarNotificacao('Selecione uma conta!', 'erro');

    const dados = {
        usuarioId: usuarioLogado.id,
        tipo: document.getElementById('inputTipo').value,
        pessoaOuGrupo: document.getElementById('inputPessoa').value,
        valorTotal,
        instituicaoUsuarioId,
        dataEmprestimo: dataEmpISO || null,
        dataPrevisao: dataISO || null,
        observacoes: document.getElementById('inputObservacoes').value || null
    };

    try {
        let response;
        if (emprestimoEmEdicao) {
            response = await fetch(`${API_BASE}/emprestimos/${emprestimoEmEdicao.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(dados)
            });
        } else {
            response = await fetch(`${API_BASE}/emprestimos`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(dados)
            });
        }

        if (!response.ok) throw new Error('Erro ao salvar empréstimo');

        mostrarNotificacao(
            emprestimoEmEdicao ? 'Empréstimo atualizado!' : 'Empréstimo criado!',
            'sucesso'
        );

        fecharModalEmprestimo();
        await carregarResumo();
        await carregarEmprestimos();
    } catch (error) {
        console.error('Erro ao salvar:', error);
        mostrarNotificacao('Erro ao salvar empréstimo', 'erro');
    }
}

async function salvarPagamento(event) {
    event.preventDefault();

    const iPag = document.getElementById('inputValorPagamento');
    const valorPagamento = window.MainAPI ? window.MainAPI.obterValorMoeda(iPag) : parseFloat(iPag.value);
    const instituicaoUsuarioId = parseInt(document.getElementById('inputInstituicaoPagamento').value);

    if (!instituicaoUsuarioId) return mostrarNotificacao('Selecione uma conta!', 'erro');

    if (valorPagamento > emprestimoParaPagamento.valorRestante) {
        mostrarNotificacao('Valor não pode ser maior que o restante!', 'erro');
        return;
    }

    try {
        const response = await fetch(
            `${API_BASE}/emprestimos/${emprestimoParaPagamento.id}/pagamento-parcial`,
            {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    valorPago: valorPagamento,
                    instituicaoUsuarioId,
                    dataPagamento: window.MainAPI?.dataParaISO(document.getElementById('inputDataPagamento')?.value) || null
                })
            }
        );

        if (!response.ok) throw new Error('Erro ao registrar pagamento');

        mostrarNotificacao('Pagamento registrado!', 'sucesso');
        fecharModalPagamento();
        await carregarResumo();
        await carregarEmprestimos();
    } catch (error) {
        console.error('Erro ao registrar pagamento:', error);
        mostrarNotificacao('Erro ao registrar pagamento', 'erro');
    }
}

async function quitarEmprestimo(emprestimoId) {
    const emprestimo = emprestimos.find(e => e.id === emprestimoId);
    const tipoLabel = emprestimo?.tipo === 'EMPRESTEI' ? 'receberá o valor restante' : 'pagará o valor restante';

    _abrirSeletorInstituicaoEQuitar(emprestimoId, tipoLabel, emprestimo);
}

function _abrirSeletorInstituicaoEQuitar(emprestimoId, tipoLabel, emprestimo) {
    const div = document.getElementById('div_alerta');
    const conteudo = document.getElementById('conteudoAlerta');
    if (!div || !conteudo) return;

    conteudo.innerHTML = '';

    const msg = document.createElement('p');
    msg.style.cssText = 'margin-bottom:10px;text-align:center;line-height:1.5;';
    msg.textContent = `Em qual conta ${tipoLabel}?`;
    conteudo.appendChild(msg);

    const sel = document.createElement('select');
    sel.style.cssText = 'width:100%;padding:8px;border-radius:8px;border:1px solid var(--cor-principal);background:var(--cor-fundo-campo,#fff);color:var(--cor-texto-principal);margin-bottom:12px;';
    sel.innerHTML = '<option value="">Selecione a conta...</option>';
    _instituicoes.forEach(inst => {
        const opt = document.createElement('option');
        opt.value = inst.id;
        opt.textContent = inst.intituicao.nome;
        sel.appendChild(opt);
    });
    conteudo.appendChild(sel);

    const btns = document.createElement('div');
    btns.style.cssText = 'display:flex;gap:8px;justify-content:center;';

    const btnNao = document.createElement('button');
    btnNao.textContent = 'Cancelar';
    btnNao.style.cssText = 'background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid var(--cor-tinte-borda,#ccc);';
    btnNao.onclick = () => { div.style.display = 'none'; };

    const btnSim = document.createElement('button');
    btnSim.textContent = 'Quitar';
    btnSim.onclick = async () => {
        const instId = parseInt(sel.value);
        if (!instId) { mostrarNotificacao('Selecione uma conta!', 'erro'); return; }
        div.style.display = 'none';
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}/quitar`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ instituicaoUsuarioId: instId })
            });
            if (!response.ok) {
                const err = await response.json().catch(() => ({}));
                throw new Error(err.message || `HTTP ${response.status}`);
            }
            mostrarNotificacao('Empréstimo quitado!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao quitar:', error);
            mostrarNotificacao('Erro ao quitar: ' + error.message, 'erro');
        }
    };

    btns.appendChild(btnNao);
    btns.appendChild(btnSim);
    conteudo.appendChild(btns);
    div.style.display = 'flex';
}

async function reabrirEmprestimo(emprestimoId) {
    confirmar('Deseja reabrir este empréstimo?', async () => {
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}/reabrir`, {
                method: 'PATCH'
            });
            if (!response.ok) throw new Error('Erro ao reabrir empréstimo');
            mostrarNotificacao('Empréstimo reaberto!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao reabrir:', error);
            mostrarNotificacao('Erro ao reabrir empréstimo', 'erro');
        }
    });
}

async function confirmarDeletar(emprestimoId) {
    confirmar('Deseja realmente deletar este empréstimo? Esta ação não pode ser desfeita.', async () => {
        try {
            const response = await fetch(`${API_BASE}/emprestimos/${emprestimoId}`, {
                method: 'DELETE'
            });
            if (!response.ok) throw new Error('Erro ao deletar empréstimo');
            mostrarNotificacao('Empréstimo deletado!', 'sucesso');
            await carregarResumo();
            await carregarEmprestimos();
        } catch (error) {
            console.error('Erro ao deletar:', error);
            mostrarNotificacao('Erro ao deletar empréstimo', 'erro');
        }
    });
}

// ============================================================================
// UTILITÁRIOS
// ============================================================================

function formatarMoeda(valor) {
    return new Intl.NumberFormat('pt-BR', {
        style: 'currency',
        currency: 'BRL'
    }).format(valor);
}

function formatarData(dataStr) {
    if (!dataStr) return '';
    const data = new Date(dataStr + 'T00:00:00');
    return data.toLocaleDateString('pt-BR');
}

function formatarStatus(status) {
    const statusMap = {
        'PENDENTE': 'Pendente',
        'PAGO_PARCIAL': 'Pago Parcial',
        'QUITADO': 'Quitado'
    };
    return statusMap[status] || status;
}

function getStatusIcon(status) {
    const iconMap = {
        'PENDENTE': 'bx-time-five',
        'PAGO_PARCIAL': 'bx-info-circle',
        'QUITADO': 'bx-check-circle'
    };
    return iconMap[status] || 'bx-info-circle';
}

function confirmar(mensagem, onConfirm) {
    const div = document.getElementById('div_alerta');
    const conteudo = document.getElementById('conteudoAlerta');
    if (!div || !conteudo) { if (window.confirm(mensagem)) onConfirm(); return; }

    conteudo.innerHTML = '';

    const msg = document.createElement('p');
    msg.style.cssText = 'margin-bottom:16px;text-align:center;line-height:1.5;';
    msg.textContent = mensagem;

    const btns = document.createElement('div');
    btns.style.cssText = 'display:flex;gap:8px;justify-content:center;';

    const btnNao = document.createElement('button');
    btnNao.textContent = 'Cancelar';
    btnNao.style.cssText = 'background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid var(--cor-tinte-borda,#ccc);';
    btnNao.onclick = () => { div.style.display = 'none'; };

    const btnSim = document.createElement('button');
    btnSim.textContent = 'Confirmar';
    btnSim.onclick = () => { div.style.display = 'none'; onConfirm(); };

    btns.appendChild(btnNao);
    btns.appendChild(btnSim);
    conteudo.appendChild(msg);
    conteudo.appendChild(btns);
    div.style.display = 'flex';
}

function mostrarNotificacao(mensagem, tipo = 'info') {
    // Criar elemento de notificação
    const notif = document.createElement('div');
    notif.className = `notificacao notif-${tipo}`;
    notif.innerHTML = `
        <i class='bx ${tipo === 'sucesso' ? 'bx-check-circle' : 'bx-error-circle'}'></i>
        <span>${mensagem}</span>
    `;

    // Adicionar estilos inline
    Object.assign(notif.style, {
        position: 'fixed',
        top: '20px',
        right: '20px',
        zIndex: '99999',
        background: tipo === 'sucesso' ? '#10b981' : '#ef4444',
        color: '#fff',
        padding: '1rem 1.5rem',
        borderRadius: '10px',
        boxShadow: '0 8px 24px rgba(0,0,0,0.2)',
        display: 'flex',
        alignItems: 'center',
        gap: '0.75rem',
        fontSize: '0.95rem',
        fontWeight: '600',
        animation: 'slideInRight 0.3s ease'
    });

    document.body.appendChild(notif);

    setTimeout(() => {
        notif.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => notif.remove(), 300);
    }, 3000);
}

// Adicionar estilos de animação
const style = document.createElement('style');
style.textContent = `
    @keyframes slideInRight {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }
    @keyframes slideOutRight {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);

// ============================================================================
// EMPRéSTIMOS BANCáRIOS
// ============================================================================
async function carregarBancarios() {
    try {
        const r = await fetch(API_BASE + '/emprestimos-bancarios/usuarios/' + usuarioLogado.id);
        if (r.status === 204) { bancarios = []; renderizarBancarios(); atualizarResumoBancarios(); return; }
        if (!r.ok) throw new Error('Erro');
        bancarios = await r.json();
        renderizarBancarios(); atualizarResumoBancarios();
    } catch(err) { console.error(err); mostrarNotificacao('Erro ao carregar empréstimos bancários', 'erro'); }
}
function atualizarResumoBancarios() {
    const ativos = bancarios.filter(b => b.status === 'ATIVO');
    document.getElementById('bancarioContratosAtivos').textContent = ativos.length;
    const saldo = ativos.reduce((s, b) => s + (b.saldoDevedor || 0), 0);
    document.getElementById('bancarioSaldoDevedor').textContent = 'Saldo devedor: ' + formatarMoeda(saldo);
    const comData = ativos.filter(b => b.proximaParcela).sort((a, b) => new Date(a.proximaParcela) - new Date(b.proximaParcela));
    if (comData.length > 0) {
        document.getElementById('bancarioProximaParcelaValor').textContent = formatarMoeda(comData[0].valorParcela);
        document.getElementById('bancarioProximaParcelaData').textContent = formatarData(comData[0].proximaParcela);
    } else {
        document.getElementById('bancarioProximaParcelaValor').textContent = 'R$ 0,00';
        document.getElementById('bancarioProximaParcelaData').textContent = '-';
    }
}
function filtrarBancarios(filtro) {
    filtroBancarioAtual = filtro;
    document.querySelectorAll('[data-filtro-b]').forEach(btn => btn.classList.remove('ativo'));
    document.querySelector('[data-filtro-b="' + filtro + '"]').classList.add('ativo');
    renderizarBancarios();
}
function renderizarBancarios() {
    const container = document.getElementById('listaBancarios');
    let lista = [...bancarios];
    if (filtroBancarioAtual === 'ATIVO') lista = lista.filter(b => b.status === 'ATIVO');
    else if (filtroBancarioAtual === 'QUITADO') lista = lista.filter(b => b.status === 'QUITADO');
    if (lista.length === 0) { container.innerHTML = '<div class="estado-vazio"><i class=\'bx bx-bank\'></i><h3>Nenhum empréstimo bancário</h3></div>'; return; }
    container.innerHTML = lista.map(b => criarCardBancario(b)).join('');
}
const _modLabel = { PESSOAL: 'Crédito Pessoal', VEICULO: 'Financ. Veículo', IMOVEL: 'Financ. Imóvel', CONSIGNADO: 'Consignado', CAPITAL_DE_GIRO: 'Capital de Giro' };
function criarCardBancario(b) {
    const isQ = b.status === 'QUITADO', atr = b.atrasado && !isQ;
    const pct = b.totalParcelas > 0 ? (b.parcelasPagas / b.totalParcelas * 100).toFixed(1) : 0;
    const sc = isQ ? 'quitado' : (atr ? 'atrasado' : 'ativo'), sl = isQ ? 'Quitado' : (atr ? 'Atrasado' : 'Ativo'), si = isQ ? 'bx-check-circle' : (atr ? 'bx-error-circle' : 'bx-time-five');
    const ph = b.proximaParcela ? '<div class="emprestimo-data"' + (atr ? ' style="color:#ef4444;"' : '') + '><i class=\'bx ' + (atr ? 'bx-error-circle' : 'bx-calendar') + '\'></i> ' + (atr ? 'Vencida: ' : 'Próxima: ') + formatarData(b.proximaParcela) + '</div>' : '';
    const ch = b.dataContratacao ? '<div class="emprestimo-data"><i class=\'bx bx-calendar-check\'></i> Contratado: ' + formatarData(b.dataContratacao) + '</div>' : '';
    const ba = isQ ? '<button class="btn-acao deletar" onclick="confirmarDeletarBancario(\'' + b.id + '\')"><i class=\'bx bx-trash\'></i> Deletar</button>'
        : '<button class="btn-acao visualizar" onclick="abrirModalParcelas(\'' + b.id + '\')"><i class=\'bx bx-list-ul\'></i> Ver Parcelas</button><button class="btn-acao registrar" onclick="abrirModalPagarParcela(\'' + b.id + '\')"><i class=\'bx bx-money\'></i> Pagar Parcela</button><button class="btn-acao quitar" onclick="quitarBancario(\'' + b.id + '\')"><i class=\'bx bx-check-circle\'></i> Quitar</button><button class="btn-acao deletar" onclick="confirmarDeletarBancario(\'' + b.id + '\')"><i class=\'bx bx-trash\'></i> Deletar</button>';

    return '<div class="emprestimo-item emprestei' + (isQ ? ' quitado' : '') + '"><div class="emprestimo-header"><div class="emprestimo-info"><div class="emprestimo-tipo emprestei"><i class=\'bx bx-bank\'></i> ' + (_modLabel[b.modalidade] || b.modalidade) + '</div><h3 class="emprestimo-pessoa">' + b.bancoNome + '</h3>' + ch + ph + '</div><div class="emprestimo-status ' + sc + '"><i class=\'bx ' + si + '\'></i> ' + sl + '</div></div><div class="emprestimo-valores"><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Valor Contratado</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.valorPrincipal) + '</span></div><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Parcela (' + b.taxaJurosMensal + '% a.m.)</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.valorParcela) + '</span></div><div class="emprestimo-valor-item"><span class="emprestimo-valor-label">Saldo Devedor</span><span class="emprestimo-valor-numero">' + formatarMoeda(b.saldoDevedor) + '</span></div></div>' + (!isQ ? '<div class="emprestimo-progresso"><div class="progresso-bar-container"><div class="progresso-bar" style="width:' + pct + '%"></div></div><div class="progresso-texto">' + b.parcelasPagas + '/' + b.totalParcelas + ' parcelas (' + pct + '%)</div></div>' : '') + (b.observacoes ? '<div class="emprestimo-observacoes"><strong>Obs:</strong> ' + b.observacoes + '</div>' : '') + '<div class="emprestimo-acoes-item">' + ba + '</div></div>';
}
function calcularParcelaEstimada() {
    const pv = window.MainAPI ? window.MainAPI.obterValorMoeda(document.getElementById('bInputPrincipal')) : 0;
    const tx = parseFloat(document.getElementById('bInputTaxa')?.value?.replace(',','.')) || 0;
    const n = parseInt(document.getElementById('bInputParcelas')?.value) || 0;
    const el = document.getElementById('bParcelaEstimada'); if (!el) return;
    if (pv <= 0 || n <= 0) { el.textContent = 'R$ 0,00'; return; }
    const pmt = tx <= 0 ? pv/n : (() => { const i=tx/100; const f=Math.pow(1+i,n); return pv*(i*f)/(f-1); })();
    el.textContent = formatarMoeda(pmt);
}
function abrirModalNovoBancario() {
    document.getElementById('formBancario').reset();
    const iv = document.getElementById('bInputPrincipal'); if (iv && window.MainAPI?.resetarMascaraMoeda) window.MainAPI.resetarMascaraMoeda(iv);
    document.getElementById('bParcelaEstimada').textContent = 'R$ 0,00';
    const h = new Date(); const hs = String(h.getDate()).padStart(2,'0') + '/' + String(h.getMonth()+1).padStart(2,'0') + '/' + h.getFullYear();
    const bc = document.getElementById('bInputContratacao'); if (bc) bc.value = hs;
    popularSelectInstituicoes('bInputInstituicao');
    document.getElementById('modalBancario').classList.add('aberto');
}
function fecharModalBancario() { document.getElementById('modalBancario').classList.remove('aberto'); }
async function salvarBancario(event) {
    event.preventDefault();
    const pv = window.MainAPI ? window.MainAPI.obterValorMoeda(document.getElementById('bInputPrincipal')) : 0;
    const tx = parseFloat(document.getElementById('bInputTaxa').value?.replace(',','.')) || 0;
    const n = parseInt(document.getElementById('bInputParcelas').value);
    const instId = parseInt(document.getElementById('bInputInstituicao').value) || null;
    const dataC = window.MainAPI?.dataParaISO(document.getElementById('bInputContratacao').value) || null;
    const dataP = window.MainAPI?.dataParaISO(document.getElementById('bInputPrimeiraParcela').value) || null;
    const dados = { usuarioId: usuarioLogado.id, bancoNome: document.getElementById('bInputBanco').value, modalidade: document.getElementById('bInputModalidade').value, valorPrincipal: pv, taxaJurosMensal: tx, totalParcelas: n, dataContratacao: dataC, dataPrimeiraParcela: dataP, instituicaoUsuarioId: instId, observacoes: document.getElementById('bInputObs').value || null };
    try {
        const resp = await fetch(API_BASE + '/emprestimos-bancarios', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(dados) });
        if (!resp.ok) { const err = await resp.json().catch(() => ({})); throw new Error(err.message || 'Erro ao registrar empréstimo bancário'); }
        mostrarNotificacao('Empréstimo bancário registrado!', 'sucesso'); fecharModalBancario(); await carregarBancarios();
    } catch(err) { mostrarNotificacao(err.message, 'erro'); }
}
function abrirModalPagarParcela(bid) {
    bancarioParaPagamento = bancarios.find(b => b.id === bid); if (!bancarioParaPagamento) return;
    document.getElementById('infoPagarParcela').innerHTML = '<strong>Banco:</strong> ' + bancarioParaPagamento.bancoNome + '<br><strong>Parcela:</strong> ' + (bancarioParaPagamento.parcelasPagas+1) + '/' + bancarioParaPagamento.totalParcelas + '<br><strong>Valor:</strong> ' + formatarMoeda(bancarioParaPagamento.valorParcela);
    document.getElementById('formPagarParcela').reset();
    const h = new Date(); const hs = String(h.getDate()).padStart(2,'0')+'/'+String(h.getMonth()+1).padStart(2,'0')+'/'+h.getFullYear();
    const bd = document.getElementById('bPagDataPagamento'); if (bd) bd.value = hs;
    popularSelectInstituicoes('bPagInstituicao');
    document.getElementById('modalPagarParcela').classList.add('aberto');
}
function fecharModalPagarParcela() { document.getElementById('modalPagarParcela').classList.remove('aberto'); bancarioParaPagamento = null; }
async function confirmarPagarParcela(event) {
    event.preventDefault();
    const instId = parseInt(document.getElementById('bPagInstituicao').value) || null;
    const dp = window.MainAPI?.dataParaISO(document.getElementById('bPagDataPagamento').value) || null;
    try {
        const resp = await fetch(API_BASE+'/emprestimos-bancarios/'+bancarioParaPagamento.id+'/pagar-parcela', { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify({instituicaoUsuarioId:instId,dataPagamento:dp}) });
        if (!resp.ok) {
            const errorData = await resp.text();
            let errorMessage = 'Erro ao pagar parcela';
            try {
                const jsonError = JSON.parse(errorData);
                errorMessage = jsonError.message || jsonError.error || errorData;
            } catch {
                errorMessage = errorData || errorMessage;
            }
            throw new Error(errorMessage);
        }
        mostrarNotificacao('Parcela paga!','sucesso');
        fecharModalPagarParcela();
        await carregarBancarios();
    } catch(err) {
        mostrarNotificacao(err.message,'erro');
    }
}
function quitarBancario(bid) {
    const b = bancarios.find(b => b.id === bid);
    const div = document.getElementById('div_alerta'), cnt = document.getElementById('conteudoAlerta');
    cnt.innerHTML = '';
    const msg = document.createElement('p'); msg.style.cssText='margin-bottom:10px;text-align:center;line-height:1.5;';
    msg.innerHTML = '<strong>Quitar:</strong> ' + b?.bancoNome + '<br>' + b?.parcelasRestantes + ' parcelas restantes x ' + formatarMoeda(b?.valorParcela);
    cnt.appendChild(msg);
    const sel = document.createElement('select'); sel.style.cssText='width:100%;padding:8px;border-radius:8px;border:1px solid var(--cor-principal);background:var(--cor-fundo-campo,#fff);color:var(--cor-texto-principal);margin-bottom:12px;';
    sel.innerHTML='<option value="">Selecione a conta...</option>'; _instituicoes.forEach(inst => { const o=document.createElement('option'); o.value=inst.id; o.textContent=inst.intituicao.nome; sel.appendChild(o); }); cnt.appendChild(sel);
    const btns=document.createElement('div'); btns.style.cssText='display:flex;gap:8px;justify-content:center;';
    const bn=document.createElement('button'); bn.textContent='Cancelar'; bn.style.cssText='background:var(--cor-fundo-pagina,#e5e7eb);color:var(--cor-texto-principal);border:1px solid #ccc;'; bn.onclick=()=>{div.style.display='none';};
    const bs=document.createElement('button'); bs.textContent='Confirmar';
    bs.onclick=async()=>{
        const ii=parseInt(sel.value)||null;
        div.style.display='none';
        try {
            const resp=await fetch(API_BASE+'/emprestimos-bancarios/'+bid+'/quitar',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({instituicaoUsuarioId:ii,dataPagamento:null})});
            if(!resp.ok) {
                const errorData = await resp.text();
                let errorMessage = 'Erro ao quitar empréstimo';
                try {
                    const jsonError = JSON.parse(errorData);
                    errorMessage = jsonError.message || jsonError.error || errorData;
                } catch {
                    errorMessage = errorData || errorMessage;
                }
                throw new Error(errorMessage);
            }
            mostrarNotificacao('Quitado!','sucesso');
            await carregarBancarios();
        } catch(err){
            mostrarNotificacao(err.message,'erro');
        }
    };
    btns.appendChild(bn); btns.appendChild(bs); cnt.appendChild(btns); div.style.display='flex';
}
function confirmarDeletarBancario(bid) {
    confirmar('Deletar este empréstimo bancário?', async () => {
        try { 
            const r=await fetch(API_BASE+'/emprestimos-bancarios/'+bid,{method:'DELETE'}); 
            if(!r.ok) {
                const errorData = await r.text();
                let errorMessage = 'Erro ao deletar empréstimo';
                try {
                    const jsonError = JSON.parse(errorData);
                    errorMessage = jsonError.message || jsonError.error || errorData;
                } catch {
                    errorMessage = errorData || errorMessage;
                }
                throw new Error(errorMessage);
            }
            mostrarNotificacao('Deletado!','sucesso'); 
            await carregarBancarios(); 
        }
        catch(err) { mostrarNotificacao(err.message,'erro'); }
    });
}

// ============================================================================
// EXPANSÃO DE PARCELAS - MODAL COM PAGINAÇÃO
// ============================================================================
function abrirModalParcelas(bid) {
    emprestimoIdAtualParcelas = bid;
    parcelasPaginaAtual = 1;

    // Busca o empréstimo para pegar o nome
    const emprestimo = bancarios.find(b => b.id === bid);
    if (emprestimo) {
        document.getElementById('modalParcelasTitulo').textContent = `Parcelas - ${emprestimo.bancoNome}`;
    }

    document.getElementById('modalParcelas').classList.add('aberto');
    carregarParcelasBancario(bid);
}

function fecharModalParcelas() {
    document.getElementById('modalParcelas').classList.remove('aberto');
    emprestimoIdAtualParcelas = null;
    parcelasCarregadas = {};
}

async function carregarParcelasBancario(bid) {
    const container = document.getElementById('parcelasModalConteudo');
    if (!container) return;

    container.innerHTML = '<div class="parcelas-loading"><i class="bx bx-loader-alt bx-spin" style="font-size:2rem;"></i><p>Carregando parcelas...</p></div>';

    try {
        const resp = await fetch(`${API_BASE}/emprestimos-bancarios/${bid}/parcelas`);
        if (!resp.ok) throw new Error('Erro ao carregar parcelas');

        const parcelas = await resp.json();
        parcelasCarregadas[bid] = parcelas;
        renderizarParcelasPaginadas(bid);
    } catch(err) {
        container.innerHTML = '<div class="parcelas-erro"><i class="bx bx-error-circle" style="font-size:2rem;color:#ef4444;"></i><p>Erro ao carregar parcelas</p></div>';
        console.error(err);
    }
}

function renderizarParcelasPaginadas(bid) {
    const container = document.getElementById('parcelasModalConteudo');
    const paginacao = document.getElementById('parcelasPaginacao');
    if (!container) return;

    const parcelas = parcelasCarregadas[bid];
    if (!parcelas || parcelas.length === 0) {
        container.innerHTML = '<div class="parcelas-vazio"><i class="bx bx-info-circle" style="font-size:2rem;"></i><p>Nenhuma parcela encontrada</p></div>';
        paginacao.style.display = 'none';
        return;
    }

    // Calcular paginação
    const totalPaginas = Math.ceil(parcelas.length / parcelasPorPagina);
    const inicio = (parcelasPaginaAtual - 1) * parcelasPorPagina;
    const fim = inicio + parcelasPorPagina;
    const parcelasPagina = parcelas.slice(inicio, fim);

    // Renderizar parcelas da página atual
    let html = '<div class="parcelas-lista">';

    parcelasPagina.forEach(p => {
        const statusClass = p.status === 'PAGA' ? 'paga' : (p.status === 'ATRASADA' ? 'atrasada' : 'a-vencer');
        const statusLabel = p.status === 'PAGA' ? 'Paga' : (p.status === 'ATRASADA' ? 'Atrasada' : 'A Vencer');
        const statusIcon = p.status === 'PAGA' ? 'bx-check-circle' : (p.status === 'ATRASADA' ? 'bx-error-circle' : 'bx-time-five');

        html += `
            <div class="parcela-item ${statusClass}">
                <div class="parcela-header">
                    <div class="parcela-numero">
                        <i class='bx ${statusIcon}'></i>
                        Parcela ${p.numeroParcela}/${p.totalParcelas}
                    </div>
                    <div class="parcela-status ${statusClass}">${statusLabel}</div>
                </div>
                <div class="parcela-info">
                    <div class="parcela-info-item">
                        <span class="parcela-label">Vencimento:</span>
                        <span class="parcela-valor">${formatarData(p.dataVencimento)}</span>
                    </div>
                    <div class="parcela-info-item">
                        <span class="parcela-label">Valor:</span>
                        <span class="parcela-valor">${formatarMoeda(p.valor)}</span>
                    </div>
                </div>
                ${p.podeSerPaga ? `
                    <div class="parcela-acao">
                        <button class="btn-pagar-parcela" onclick="pagarParcelaDoModal('${bid}')">
                            <i class='bx bx-money'></i> Pagar Esta Parcela
                        </button>
                    </div>
                ` : ''}
            </div>
        `;
    });

    html += '</div>';
    container.innerHTML = html;

    // Atualizar controles de paginação
    if (totalPaginas > 1) {
        paginacao.style.display = 'flex';
        document.getElementById('pagInfo').textContent = `Página ${parcelasPaginaAtual} de ${totalPaginas}`;
        document.getElementById('btnPagAnterior').disabled = parcelasPaginaAtual === 1;
        document.getElementById('btnPagProxima').disabled = parcelasPaginaAtual === totalPaginas;
    } else {
        paginacao.style.display = 'none';
    }
}

function mudarPaginaParcelas(direcao) {
    if (!emprestimoIdAtualParcelas) return;

    const parcelas = parcelasCarregadas[emprestimoIdAtualParcelas];
    if (!parcelas) return;

    const totalPaginas = Math.ceil(parcelas.length / parcelasPorPagina);
    parcelasPaginaAtual += direcao;

    if (parcelasPaginaAtual < 1) parcelasPaginaAtual = 1;
    if (parcelasPaginaAtual > totalPaginas) parcelasPaginaAtual = totalPaginas;

    renderizarParcelasPaginadas(emprestimoIdAtualParcelas);
}

function pagarParcelaDoModal(bid) {
    fecharModalParcelas();
    abrirModalPagarParcela(bid);
}

// Fechar modal ao clicar fora
window.onclick = function(event) {
    [['modalEmprestimo',fecharModalEmprestimo],['modalPagamento',fecharModalPagamento],['modalBancario',fecharModalBancario],['modalPagarParcela',fecharModalPagarParcela],['modalParcelas',fecharModalParcelas]]
        .forEach(([id,fn]) => { const m=document.getElementById(id); if(event.target===m) fn(); });
};

/* ================================================================
   instituicoes.js  –  Tela de Instituições Financeiras
   ================================================================ */

(function () {

    /* ─── Helpers de formatação ─────────────────────────────── */
    function fmtBRL(val) {
        const n = Number(val) || 0;
        return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    }

    function fmtNum(val) {
        return (Number(val) || 0).toLocaleString("pt-BR");
    }

    /* ─── Cores dos bancos (círculo no card) ─────────────────── */
    const COR_BANCOS = {
        "nubank":          "#820AD1",
        "itaú":            "#FF6200",
        "itau":            "#FF6200",
        "bradesco":        "#CC092F",
        "banco do brasil": "#F7CD00",
        "bb":              "#F7CD00",
        "caixa":           "#006B3F",
        "santander":       "#EC0000",
        "inter":           "#FF7A00",
        "c6":              "#1A1A2E",
        "xp":              "#000000",
        "picpay":          "#11C76F",
        "next":            "#00E64B",
        "neon":            "#00D4FF",
        "original":        "#00A651",
        "sicoob":          "#006B3F",
        "sicredi":         "#009B3A",
        "alelo":           "#F7941D",
        "aelo":            "#F7941D",
        "ticket":          "#EF3829",
        "vale":            "#009B3A",
        "pluxee":          "#6C2FF7",
        "sodexo":          "#D22630",
    };

    function corInstituicao(nome) {
        if (!nome) return "var(--cor-principal)";
        const chave = nome.toLowerCase();
        for (const [k, v] of Object.entries(COR_BANCOS)) {
            if (chave.includes(k)) return v;
        }
        // gera cor determinística baseada no nome
        let hash = 0;
        for (let i = 0; i < nome.length; i++) hash = (hash * 31 + nome.charCodeAt(i)) & 0xffffffff;
        const h = Math.abs(hash) % 360;
        return `hsl(${h},52%,42%)`;
    }

    function inicialInstituicao(nome) {
        if (!nome) return "?";
        const partes = nome.trim().split(/\s+/);
        if (partes.length >= 2) return (partes[0][0] + partes[1][0]).toUpperCase();
        return nome.slice(0, 2).toUpperCase();
    }

    /* ─── Estado Global ──────────────────────────────────────── */
    let _userId       = null;
    let _resumoList   = [];   // ResumoInstituicaoDto[]
    let _caixinhas    = [];   // CaixinhaResponseDTO[]
    let _instAtual    = null; // resumo selecionado para o modal
    let _atalhoAtivo  = null;

    /* ══════════════════════════════════════════════════════════
       PERÍODO (mesmo padrão do dashboard)
    ══════════════════════════════════════════════════════════ */
    const MESES = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                   "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    const TRIMESTRES = ["1º Trimestre","2º Trimestre","3º Trimestre","4º Trimestre"];
    const SEMESTRES  = ["1º Semestre","2º Semestre"];

    function periodoAtual() {
        const tipo = document.getElementById("select_tempo")?.value || "MENSAL";
        const ano  = parseInt(document.getElementById("select_ano")?.value  || new Date().getFullYear(), 10);
        switch (tipo) {
            case "MENSAL": {
                const mes = parseInt(document.getElementById("select_mes")?.value || (new Date().getMonth()+1), 10);
                return { tipo, ano, mes };
            }
            case "TRIMESTRAL": {
                const t = parseInt(document.getElementById("select_trimestre")?.value || 1, 10);
                return { tipo, ano, trimestre: t };
            }
            case "SEMESTRAL": {
                const s = parseInt(document.getElementById("select_semestre")?.value || 1, 10);
                return { tipo, ano, semestre: s };
            }
            case "ANUAL":
                return { tipo, ano };
        }
    }

    function labelPeriodo(p) {
        if (!p) return "–";
        switch (p.tipo) {
            case "MENSAL":     return `${MESES[(p.mes||1)-1]} / ${p.ano}`;
            case "TRIMESTRAL": return `${TRIMESTRES[(p.trimestre||1)-1]} / ${p.ano}`;
            case "SEMESTRAL":  return `${SEMESTRES[(p.semestre||1)-1]} / ${p.ano}`;
            case "ANUAL":      return `${p.ano}`;
        }
        return "–";
    }

    function buildPeriodoParams(p) {
        let url = `periodo=${p.tipo}&ano=${p.ano}`;
        if (p.tipo === "MENSAL"     && p.mes)       url += `&mes=${p.mes}`;
        if (p.tipo === "TRIMESTRAL" && p.trimestre) url += `&trimestre=${p.trimestre}`;
        if (p.tipo === "SEMESTRAL"  && p.semestre)  url += `&semestre=${p.semestre}`;
        return url;
    }

    window.atualizarSeletoresPeriodo = function () {
        const tipo  = document.getElementById("select_tempo")?.value;
        const divs  = { MENSAL:"div_mes", TRIMESTRAL:"div_trimestre", SEMESTRAL:"div_semestre", ANUAL:"div_ano" };
        const todos = ["div_mes","div_trimestre","div_semestre","div_ano"];
        todos.forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = "none";
        });
        if (divs[tipo]) {
            const el = document.getElementById(divs[tipo]);
            if (el) el.style.display = "";
        }
        document.getElementById("div_ano").style.display = "";
        marcarAtalhoAtivo(null);
        carregarInstituicoes();
    };

    window.marcarAtalhoAtivo = function (nome) {
        _atalhoAtivo = nome;
        document.querySelectorAll(".dash-atalho-btn").forEach(btn => {
            btn.classList.toggle("ativo", btn.dataset.atalho === nome);
        });
    };

    window.selecionarRapido = function (atalho) {
        const hoje = new Date();
        const anoAtual = hoje.getFullYear();
        const mesAtual = hoje.getMonth() + 1;

        const selTempo  = document.getElementById("select_tempo");
        const selMes    = document.getElementById("select_mes");
        const selAno    = document.getElementById("select_ano");

        if (!selTempo || !selMes || !selAno) return;

        if (atalho === "mes-atual") {
            selTempo.value = "MENSAL";
            selMes.value   = mesAtual;
            selAno.value   = anoAtual;
        } else if (atalho === "mes-passado") {
            const mP = mesAtual === 1 ? 12 : mesAtual - 1;
            const aP = mesAtual === 1 ? anoAtual - 1 : anoAtual;
            selTempo.value = "MENSAL";
            selMes.value   = mP;
            selAno.value   = aP;
        } else if (atalho === "ano-atual") {
            selTempo.value = "ANUAL";
            selAno.value   = anoAtual;
        } else if (atalho === "ano-passado") {
            selTempo.value = "ANUAL";
            selAno.value   = anoAtual - 1;
        }

        atualizarSeletoresPeriodo();
        marcarAtalhoAtivo(atalho);
        carregarInstituicoes();
    };

    function inicializarPeriodo() {
        const hoje = new Date();
        const selMes = document.getElementById("select_mes");
        const selAno = document.getElementById("select_ano");
        if (selMes) selMes.value = hoje.getMonth() + 1;
        if (selAno) selAno.value = hoje.getFullYear();
        atualizarSeletoresPeriodo();
        marcarAtalhoAtivo("mes-atual");
    }

    function atualizarLabelPeriodo() {
        const label = document.getElementById("labelPeriodoAtual");
        if (label) label.textContent = labelPeriodo(periodoAtual());
    }

    /* ══════════════════════════════════════════════════════════
       KPIs
    ══════════════════════════════════════════════════════════ */
    function calcularEExibirKPIs(lista) {
        if (!lista || lista.length === 0) {
            document.getElementById("kpi1Nome").textContent       = "Sem dados";
            document.getElementById("kpi1Sub").textContent        = "–";
            document.getElementById("kpi2Nome").textContent        = "Sem dados";
            document.getElementById("kpi2Valor").textContent       = "–";
            document.getElementById("kpi3Total").textContent       = "0";
            return;
        }

        // KPI 1 – Instituição mais utilizada (maior quantidadeTransacoes)
        const maisUsada = lista.reduce((a, b) =>
            (b.quantidadeTransacoes > a.quantidadeTransacoes ? b : a), lista[0]);
        document.getElementById("kpi1Nome").textContent = maisUsada.nomeInstituicao;
        document.getElementById("kpi1Sub").textContent  = `${fmtNum(maisUsada.quantidadeTransacoes)} transações`;

        // KPI 2 – Maior gasto médio / transação
        let maiorMedia = null;
        lista.forEach(inst => {
            if (!inst.quantidadeTransacoes || inst.quantidadeTransacoes === 0) return;
            const totalGasto = (Number(inst.totalCredito) || 0) + (Number(inst.totalDebito) || 0);
            const media = totalGasto / inst.quantidadeTransacoes;
            if (maiorMedia === null || media > maiorMedia.media) {
                maiorMedia = { inst, media };
            }
        });
        if (maiorMedia) {
            document.getElementById("kpi2Nome").textContent  = maiorMedia.inst.nomeInstituicao;
            // Apenas o valor — "por operação" já está no HTML como kpi-sub
            document.getElementById("kpi2Valor").textContent = fmtBRL(maiorMedia.media);
        } else {
            document.getElementById("kpi2Nome").textContent  = "Sem dados";
            document.getElementById("kpi2Valor").textContent = "–";
        }

        // KPI 3 – Total de parcelamentos ativos
        const totalParcelas = lista.reduce((acc, inst) => acc + (inst.parcelamentosAtivos || 0), 0);
        document.getElementById("kpi3Total").textContent = fmtNum(totalParcelas);
    }

    /* ══════════════════════════════════════════════════════════
       CARDS DAS INSTITUIÇÕES
    ══════════════════════════════════════════════════════════ */
    function renderizarCards(lista) {
        const grid    = document.getElementById("instituicoesGrid");
        const loading = document.getElementById("loadingInstituicoes");
        const vazio   = document.getElementById("semInstituicoes");

        if (loading) loading.style.display = "none";

        if (!lista || lista.length === 0) {
            grid.innerHTML = "";
            if (vazio) vazio.style.display = "flex";
            return;
        }

        if (vazio) vazio.style.display = "none";

        grid.innerHTML = lista.map(inst => buildCardHTML(inst)).join("");

        // Adiciona click handler em cada card
        grid.querySelectorAll(".inst-card").forEach(card => {
            card.addEventListener("click", () => {
                const id = parseInt(card.dataset.instId, 10);
                const resumo = _resumoList.find(r => r.instUsuarioId === id);
                if (resumo) abrirModalInstituicao(resumo);
            });
        });
    }

    function buildCardHTML(inst) {
        const cor     = corInstituicao(inst.nomeInstituicao);
        const inicial = inicialInstituicao(inst.nomeInstituicao);
        const pct     = Math.min(inst.percentualCreditoUtilizado || 0, 100);
        const limStr  = inst.limiteCredito > 0 ? `de ${fmtBRL(inst.limiteCredito)}` : "";
        const corBarra = pct > 80 ? "var(--red-700)" : pct > 50 ? "#f59e0b" : "var(--cor-principal)";
        const hasCred = inst.temCredito !== false;

        return `
        <div class="inst-card" data-inst-id="${inst.instUsuarioId}" title="Clique para ver detalhes">
            <!-- Cabeçalho do card -->
            <div class="inst-card-header">
                <div class="inst-card-avatar" style="background:${cor};">${inicial}</div>
                <div class="inst-card-info">
                    <span class="inst-card-nome">${inst.nomeInstituicao}</span>
                    <span class="inst-card-sub">${fmtNum(inst.quantidadeTransacoes)} transações</span>
                </div>
                <div class="inst-card-saldo-wrap">
                    <span class="inst-card-saldo-label">Saldo</span>
                    <span class="inst-card-saldo">${fmtBRL(inst.saldoDisponivel)}</span>
                </div>
            </div>

            <!-- Crédito / Débito -->
            <div class="inst-card-cd-row">
                <div class="inst-card-cd">
                    <span class="inst-cd-label">${hasCred ? "CRÉDITO" : "GASTO"}</span>
                    <span class="inst-cd-valor vermelho">${fmtBRL(inst.totalCredito)}</span>
                </div>
                <div class="inst-card-cd">
                    <span class="inst-cd-label">DÉBITO</span>
                    <span class="inst-cd-valor verde">${fmtBRL(inst.totalDebito)}</span>
                </div>
            </div>

            ${hasCred ? `
            <!-- Barra de crédito (somente para instituições com crédito) -->
            <div>
                <div class="inst-card-progress-header">
                    <span class="kpi-sub">Crédito usado</span>
                    <span class="kpi-sub"><strong>${pct}%</strong> ${limStr}</span>
                </div>
                <div class="inst-progress-track">
                    <div class="inst-progress-fill"
                         style="width:${pct}%; background:${corBarra};"></div>
                </div>
            </div>` : ""}

            <!-- Parcelas ativas -->
            ${inst.parcelamentosAtivos > 0 ? `
            <div class="inst-card-parcelas">
                <i class='bx bx-refresh'></i>
                <span>${inst.parcelamentosAtivos} parcelamento${inst.parcelamentosAtivos > 1 ? "s" : ""} ativo${inst.parcelamentosAtivos > 1 ? "s" : ""}</span>
            </div>` : ""}
        </div>`;
    }

    /* ══════════════════════════════════════════════════════════
       MODAL DE DETALHE
    ══════════════════════════════════════════════════════════ */
    let _inputLimiteCredito = null;

    function abrirModalInstituicao(resumo) {
        _instAtual = resumo;
        _parcelamentosCarregados = false; // reset lazy load
        _recorrentesCarregados   = false; // reset lazy load

        const hasCred = resumo.temCredito !== false;

        // Avatar e título
        const cor = corInstituicao(resumo.nomeInstituicao);
        const ini = inicialInstituicao(resumo.nomeInstituicao);
        document.getElementById("instModalAvatar").style.background = cor;
        document.getElementById("instModalAvatar").textContent      = ini;
        document.getElementById("instModalNome").textContent        = resumo.nomeInstituicao;

        const badge = document.getElementById("instModalBadge");
        if (hasCred) {
            const pct = resumo.percentualCreditoUtilizado || 0;
            badge.textContent = `${pct}% crédito usado`;
            badge.className   = "inst-modal-badge" + (pct > 80 ? " vermelho" : pct > 50 ? " amarelo" : "");
        } else {
            badge.textContent = "Sem crédito rotativo";
            badge.className   = "inst-modal-badge";
        }

        // Preenche aba Resumo
        document.getElementById("mdSaldo").textContent      = fmtBRL(resumo.saldoDisponivel);
        document.getElementById("mdTransacoes").textContent = fmtNum(resumo.quantidadeTransacoes);
        document.getElementById("mdCredito").textContent    = fmtBRL(resumo.totalCredito);
        document.getElementById("mdDebito").textContent     = fmtBRL(resumo.totalDebito);
        document.getElementById("mdParcelas").textContent   = fmtNum(resumo.parcelamentosAtivos);
        document.getElementById("mdTaxa").textContent       = resumo.taxaJuros != null
            ? `${Number(resumo.taxaJuros).toFixed(2)}% a.m.` : "–";

        // Seção de crédito (somente se houver crédito)
        const creditoSection = document.getElementById("mdCreditoSection");
        if (creditoSection) creditoSection.style.display = hasCred ? "" : "none";

        if (hasCred) {
            const pct = resumo.percentualCreditoUtilizado || 0;
            document.getElementById("mdCreditoPct").textContent  = `${pct}%`;
            document.getElementById("mdCreditoLimite").textContent = resumo.limiteCredito > 0
                ? `de ${fmtBRL(resumo.limiteCredito)}` : "";
            const fill = document.getElementById("mdCreditoFill");
            fill.style.width      = `${Math.min(pct, 100)}%`;
            fill.style.background = pct > 80 ? "var(--red-700)" : pct > 50 ? "#f59e0b" : "var(--cor-principal)";
        }

        // Rótulo de "Total Crédito" no resumo da aba
        const mdCreditoLabel = document.querySelector("#tab-resumo .inst-stat-card:nth-child(3) .inst-stat-label");
        if (mdCreditoLabel) mdCreditoLabel.textContent = hasCred ? "Total Crédito" : "Gastos";

        // Config tab: campo de limite de crédito
        const campLimite = document.getElementById("campLimiteCredito");
        if (campLimite) campLimite.style.display = hasCred ? "" : "none";

        // Seção de pagamento de fatura (só para instituições com crédito)
        const secFatura = document.getElementById("secaoPagarFatura");
        if (secFatura) secFatura.style.display = hasCred ? "" : "none";

        // Aplica máscara no campo de fatura se ainda não foi aplicada
        const inputFatura = document.getElementById("inputValorFatura");
        if (inputFatura && !inputFatura.dataset.mascaraAplicada) {
            MainAPI.aplicarMascaraMoeda(inputFatura);
            inputFatura.dataset.mascaraAplicada = "1";
        }
        if (inputFatura) MainAPI.resetarMascaraMoeda(inputFatura);

        // Carrega distribuição por movimento (detalhe)
        carregarDetalheInstituicao(resumo.instUsuarioId);

        // Preenche aba Config
        if (!_inputLimiteCredito) {
            _inputLimiteCredito = document.getElementById("inputLimiteCredito");
            MainAPI.aplicarMascaraMoeda(_inputLimiteCredito);
        }
        MainAPI.resetarMascaraMoeda(_inputLimiteCredito);
        if (hasCred && resumo.limiteCredito > 0) {
            const centavos = Math.round(Number(resumo.limiteCredito) * 100);
            _inputLimiteCredito.dataset.centavos = String(centavos);
            const reais = Math.floor(centavos / 100);
            const cts   = String(centavos % 100).padStart(2, "0");
            _inputLimiteCredito.value = `R$ ${String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, ".")},${cts}`;
        }
        const taxaInput = document.getElementById("inputTaxaJuros");
        if (taxaInput) taxaInput.value = resumo.taxaJuros != null ? resumo.taxaJuros : "";

        // Preenche aba Poupança
        carregarPoupancasInstituicao(resumo.instUsuarioId);

        // Feedback
        const fb = document.getElementById("configFeedback");
        if (fb) { fb.style.display = "none"; fb.textContent = ""; }

        // Abre na aba resumo
        trocarAba("resumo");

        // Exibe overlay
        const overlay = document.getElementById("instModalOverlay");
        overlay.style.display = "flex";
        document.body.style.overflow = "hidden";
    }

    async function carregarDetalheInstituicao(instUsuarioId) {
        try {
            const p = periodoAtual();
            const url = `/instituicoes/${instUsuarioId}/detalhe?${buildPeriodoParams(p)}`;
            const res = await MainAPI.request(url, { method: "GET" });
            if (!res.ok) return;
            const detalhe = await res.json();

            const sec  = document.getElementById("mdDistribuicaoSection");
            const grid = document.getElementById("mdDistribuicao");

            if (detalhe.distribuicaoPorMovimento && detalhe.distribuicaoPorMovimento.length > 0) {
                sec.style.display = "";
                grid.innerHTML = detalhe.distribuicaoPorMovimento.map(d => `
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">${d.tipoMovimento}</span>
                        <span class="inst-stat-valor">${fmtBRL(d.valorTotal)}</span>
                    </div>
                `).join("");
            } else {
                sec.style.display = "none";
            }
        } catch (e) {
            console.warn("Erro ao carregar detalhe:", e);
        }
    }

    function carregarPoupancasInstituicao(instUsuarioId) {
        const lista   = _caixinhas.filter(c => {
            if (!c.instituicoes) return false;
            return c.instituicoes.some(i => i.id === instUsuarioId);
        });

        const listaEl   = document.getElementById("poupancaLista");
        const vazioEl   = document.getElementById("poupancaVazio");
        const qtdEl     = document.getElementById("poupQtd");
        const valorEl   = document.getElementById("poupValor");
        const metaEl    = document.getElementById("poupMeta");

        const totalValor = lista.reduce((a, c) => a + (Number(c.valorAtual) || 0), 0);
        const totalMeta  = lista.reduce((a, c) => a + (Number(c.valorMeta)  || 0), 0);

        qtdEl.textContent  = lista.length;
        valorEl.textContent = fmtBRL(totalValor);
        metaEl.textContent  = fmtBRL(totalMeta);

        if (lista.length === 0) {
            listaEl.innerHTML  = "";
            vazioEl.style.display = "flex";
        } else {
            vazioEl.style.display = "none";
            listaEl.innerHTML = lista.map(c => {
                const pct     = Math.min(c.percentualAtingido || 0, 100).toFixed(1);
                const corBrr  = pct >= 100 ? "var(--cor-principal)" : pct > 60 ? "#f59e0b" : "var(--cor-principal)";
                return `
                <div class="inst-poupanca-item">
                    <div class="inst-poupanca-header">
                        <span class="inst-poupanca-nome">${c.nome}</span>
                        <span class="inst-poupanca-valor">${fmtBRL(c.valorAtual)}</span>
                    </div>
                    <div class="inst-poupanca-meta">Meta: ${fmtBRL(c.valorMeta)}</div>
                    <div class="inst-progress-track" style="margin-top:6px;">
                        <div class="inst-progress-fill"
                             style="width:${pct}%; background:${corBrr};"></div>
                    </div>
                    <div style="font-size:0.72rem; color:var(--cor-texto-secundario); margin-top:3px;">
                        ${pct}% atingido${c.mesesRestantes != null ? ` · ${c.mesesRestantes} meses restantes` : ""}
                    </div>
                </div>`;
            }).join("");
        }
    }

    window.trocarAba = function (nomAba) {
        document.querySelectorAll(".inst-tab").forEach(btn => {
            btn.classList.toggle("ativo", btn.dataset.tab === nomAba);
        });
        document.querySelectorAll(".inst-tab-panel").forEach(panel => {
            panel.classList.toggle("ativo", panel.id === `tab-${nomAba}`);
        });
        // Lazy load da aba de parcelamentos
        if (nomAba === "parcelamentos" && _instAtual) {
            carregarParcelamentos(_instAtual.instUsuarioId);
        }
        // Lazy load da aba de recorrentes
        if (nomAba === "recorrentes" && _instAtual) {
            carregarRecorrentes(_instAtual.instUsuarioId);
        }
    };

    window.fecharModalInstituicao = function (event) {
        if (event && event.target !== document.getElementById("instModalOverlay")) return;
        _fecharModal();
    };

    window.fecharModalInstituicaoBtn = function () {
        _fecharModal();
    };

    function _fecharModal() {
        const overlay = document.getElementById("instModalOverlay");
        if (overlay) overlay.style.display = "none";
        document.body.style.overflow = "";
        _instAtual = null;
    }

    /* ── Fechar com ESC ────────────────────────────────────── */
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") _fecharModal();
    });

    /* ══════════════════════════════════════════════════════════
       ABA PARCELAMENTOS
    ══════════════════════════════════════════════════════════ */
    let _parcelamentosCarregados = false;

    async function carregarParcelamentos(instUsuarioId) {
        if (_parcelamentosCarregados) return;
        _parcelamentosCarregados = true;

        const loadEl   = document.getElementById("parcelamentosLoading");
        const listaEl  = document.getElementById("parcelamentosLista");
        const vazioEl  = document.getElementById("parcelamentosVazio");
        const resumoEl = document.getElementById("parcelamentosResumo");

        if (loadEl)  loadEl.style.display  = "flex";
        if (listaEl) listaEl.innerHTML     = "";
        if (vazioEl) vazioEl.style.display = "none";
        if (resumoEl) resumoEl.innerHTML   = "";

        try {
            const res = await MainAPI.request(
                `/registros/filtro/usuarios/${_userId}?tipo=Gasto`,
                { method: "GET" }
            );

            if (loadEl) loadEl.style.display = "none";

            if (!res.ok || res.status === 204) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            const registros = await res.json();
            if (!Array.isArray(registros) || registros.length === 0) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            // Filtra apenas eventos associados a ESTA instituição E com múltiplas EIs (parcelados)
            const parcs = [];
            registros.forEach(r => {
                const eis = r.eventoInstituicao || [];
                // Filtra EIs desta instituição usando instUsuarioId
                const eisDaInst = eis.filter(e => e.instUsuarioId === instUsuarioId);
                if (eisDaInst.length === 0) return;

                // Total de parcelas = número total de EIs desta instituição neste evento
                const totalParcelas = eisDaInst.length > 1
                    ? eisDaInst.length
                    : Math.max(...eis.map(e => e.parcelas || 1));

                if (totalParcelas > 1) {
                    parcs.push({ registro: r, totalParcelas, ei: eisDaInst[0] });
                }
            });

            if (parcs.length === 0) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            // Calcula resumo
            const hoje = new Date();
            const ativos = parcs.filter(p => {
                const dataEvt = parseDateField(p.registro.eventoFinanceiro?.dataEvento);
                if (!dataEvt) return false;
                const fim = new Date(dataEvt);
                fim.setMonth(fim.getMonth() + p.totalParcelas);
                return fim >= hoje;
            }).length;

            if (resumoEl) {
                resumoEl.innerHTML = `
                <div class="inst-poupanca-resumo" style="margin-bottom:16px;">
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Total</span>
                        <span class="inst-stat-valor">${parcs.length}</span>
                    </div>
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Ativos</span>
                        <span class="inst-stat-valor" style="color:var(--cor-principal);">${ativos}</span>
                    </div>
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Encerrados</span>
                        <span class="inst-stat-valor">${parcs.length - ativos}</span>
                    </div>
                </div>`;
            }

            if (listaEl) {
                listaEl.innerHTML = parcs.map(p => buildParcelamentoItemHTML(p)).join("");
                listaEl.querySelectorAll("[data-del-evento]").forEach(btn => {
                    btn.addEventListener("click", () => {
                        const id = btn.dataset.delEvento;
                        deletarParcelamento(id, btn.closest(".inst-parc-item"));
                    });
                });
            }

        } catch (e) {
            console.error("Erro ao carregar parcelamentos:", e);
            if (loadEl) loadEl.style.display = "none";
            if (vazioEl) vazioEl.style.display = "flex";
        }
    }

    /** Converte dataEvento (array ou string) em Date */
    function parseDateField(raw) {
        if (!raw) return null;
        if (Array.isArray(raw) && raw.length >= 3) {
            return new Date(raw[0], raw[1] - 1, raw[2]);
        }
        if (typeof raw === "string") return new Date(raw);
        return null;
    }

    function buildParcelamentoItemHTML({ registro, ei, totalParcelas }) {
        const ef     = registro.eventoFinanceiro || {};
        const titulo = registro.gastoDetalhe?.tituloGasto || ef.descricao || "Sem título";
        const dataEvt = parseDateField(ef.dataEvento);
        let dataFmt = "–";
        let isAtivo = false;

        const numParcelas = totalParcelas || ei.parcelas || 1;

        if (dataEvt) {
            const dia = String(dataEvt.getDate()).padStart(2, "0");
            const mes = String(dataEvt.getMonth() + 1).padStart(2, "0");
            const ano = dataEvt.getFullYear();
            dataFmt = `${dia}/${mes}/${ano}`;
            const fim = new Date(dataEvt);
            fim.setMonth(fim.getMonth() + numParcelas);
            isAtivo = fim >= new Date();
        }

        // Valor total = soma de todos os EIs, ou valor do EI x numParcelas
        const eis = registro.eventoInstituicao || [];
        const valorTotal = eis.length > 1
            ? eis.reduce((s, e) => s + (Number(e.valor) || 0), 0)
            : (Number(ei.valor) || 0) * numParcelas;
        const valorParcela  = numParcelas > 0 ? valorTotal / numParcelas : valorTotal;
        const statusCls     = isAtivo ? "verde" : "";
        const statusTxt     = isAtivo ? "Ativo" : "Encerrado";
        const badgeCls      = isAtivo ? "ativo" : "encerrado";

        return `
        <div class="inst-parc-item">
            <div class="inst-parc-info">
                <span class="inst-parc-titulo">${titulo}</span>
                <span class="inst-parc-data">${dataFmt}</span>
            </div>
            <div class="inst-parc-valores">
                <span class="inst-stat-valor ${statusCls}">${fmtBRL(valorTotal)}</span>
                <span class="inst-parc-parcelas">${numParcelas}x de ${fmtBRL(valorParcela)}</span>
            </div>
            <div class="inst-parc-actions">
                <span class="inst-parc-badge ${badgeCls}">${statusTxt}</span>
                <button class="inst-parc-del-btn" data-del-evento="${ef.id}" title="Excluir parcelamento">
                    <i class='bx bx-trash'></i>
                </button>
            </div>
        </div>`;
    }

    async function deletarParcelamento(eventoId, itemEl) {
        if (!confirm("Tem certeza que deseja excluir este parcelamento? Todos os dados serão removidos.")) return;
        try {
            const res = await MainAPI.request(`/registros/${eventoId}`, { method: "DELETE" });
            if (res.ok || res.status === 204) {
                if (itemEl) {
                    itemEl.style.animation = "inst-parc-fade-out 0.3s forwards";
                    setTimeout(() => {
                        itemEl.remove();
                        // Atualiza lista e KPIs
                        _parcelamentosCarregados = false;
                        carregarInstituicoes();
                        carregarParcelamentos(_instAtual?.instUsuarioId);
                    }, 300);
                }
            } else {
                alert("Erro ao excluir parcelamento. Tente novamente.");
            }
        } catch (e) {
            alert("Erro de conexão ao excluir.");
        }
    }

    /* ══════════════════════════════════════════════════════════
       ABA RECORRENTES
    ══════════════════════════════════════════════════════════ */
    let _recorrentesCarregados = false;

    async function carregarRecorrentes(instUsuarioId) {
        if (_recorrentesCarregados) return;
        _recorrentesCarregados = true;

        const painel = document.getElementById("tab-recorrentes");
        if (!painel) return;

        painel.innerHTML = `
            <div class="inst-loading" style="display:flex;">
                <i class='bx bx-loader-alt bx-spin'></i> Carregando recorrentes...
            </div>`;

        try {
            const res = await MainAPI.request(
                `/registros/recorrentes/instituicoes/${instUsuarioId}`,
                { method: "GET" }
            );

            if (!res.ok || res.status === 204) {
                painel.innerHTML = buildRecorrentesVazio();
                return;
            }

            const lista = await res.json();
            if (!Array.isArray(lista) || lista.length === 0) {
                painel.innerHTML = buildRecorrentesVazio();
                return;
            }

            // Armazena no cache para usar na edição
            _recorrenciasCache = lista;

            painel.innerHTML = `
                <p class="kpi-label" style="margin-bottom:12px;">Eventos Recorrentes desta Instituição</p>
                <div class="inst-rec-lista" id="recLista">
                    ${lista.map(r => buildRecorrenteItemHTML(r)).join("")}
                </div>`;

            painel.querySelectorAll("[data-del-rec]").forEach(btn => {
                btn.addEventListener("click", () => {
                    const id = btn.dataset.delRec;
                    deletarRecorrente(id, btn.closest(".inst-rec-item"), instUsuarioId);
                });
            });

        } catch (e) {
            console.error("Erro ao carregar recorrentes:", e);
            painel.innerHTML = buildRecorrentesVazio();
        }
    }

    function buildRecorrentesVazio() {
        return `
        <div class="inst-vazio" style="display:flex; flex-direction:column; align-items:center; gap:12px; padding:32px 0;">
            <i class='bx bx-repeat' style="font-size:2.5rem; color:var(--cor-texto-secundario);"></i>
            <h3>Nenhum evento recorrente</h3>
            <p style="color:var(--cor-texto-secundario);">Nenhuma recorrência vinculada a esta instituição.</p>
            <a href="adicionarRegistros.html" class="inst-btn-recorrente">
                <i class='bx bx-plus-circle'></i> Criar Evento Recorrente
            </a>
        </div>`;
    }

    function buildRecorrenteItemHTML(r) {
        const PERIODOS = {
            Diario: 'Diário', Semanal: 'Semanal', Mensal: 'Mensal', Anual: 'Anual'
        };
        const TIPOS_LABEL = {
            Gasto: ' Gasto', Recebimento: ' Recebimento'
        };
        const per = PERIODOS[r.periodicidade] || r.periodicidade || '–';
        const tipo = TIPOS_LABEL[r.tipo] || r.tipo || '–';
        const dataInicio = r.dataInicio ? new Date(r.dataInicio).toLocaleDateString('pt-BR') : '–';
        const dataFim    = r.dataFim    ? new Date(r.dataFim).toLocaleDateString('pt-BR')    : '–';
        const valor      = r.valor != null ? fmtBRL(r.valor) : '–';
        const descricao  = r.descricao || '';

        return `
        <div class="inst-rec-item" style="background:var(--cor-fundo-card);border:1px solid var(--cor-tinte-borda);border-radius:12px;padding:14px 16px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;cursor:pointer;transition:all 0.2s;" 
             onclick="abrirDetalhesRecorrencia('${r.id}')"
             onmouseenter="this.style.transform='translateY(-2px)';this.style.boxShadow='0 4px 12px rgba(0,0,0,0.1)'"
             onmouseleave="this.style.transform='';this.style.boxShadow=''">
            <div style="flex:1;min-width:0;">
                <div style="font-weight:700;font-size:0.97rem;margin-bottom:4px;">${descricao || tipo}</div>
                <div style="font-size:0.83rem;color:var(--cor-texto-secundario);">
                    ${tipo} · ${per} · ${valor}
                </div>
                <div style="font-size:0.8rem;color:var(--cor-texto-secundario);margin-top:3px;">
                    ${dataInicio} → ${dataFim}
                </div>
            </div>
            <div style="display:flex;gap:8px;align-items:center;">
                <button class="inst-parc-del-btn" data-edit-rec="${r.id}" title="Editar recorrência" onclick="event.stopPropagation();abrirModalEditarRecorrencia('${r.id}')" style="background:var(--cor-principal);color:white;">
                    <i class='bx bx-edit'></i>
                </button>
                <button class="inst-parc-del-btn" data-del-rec="${r.id}" title="Excluir recorrência" onclick="event.stopPropagation()">
                    <i class='bx bx-trash'></i>
                </button>
            </div>
        </div>`;
    }

    async function deletarRecorrente(recorrenciaId, itemEl, instUsuarioId) {
        if (!confirm("Excluir esta recorrência? Os eventos futuros vinculados serão removidos.")) return;
        try {
            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}`,
                { method: "DELETE" }
            );
            if (res.ok || res.status === 204) {
                if (itemEl) itemEl.remove();
                _recorrentesCarregados = false;
                carregarRecorrentes(instUsuarioId);
            } else {
                alert("Erro ao excluir recorrência. Tente novamente.");
            }
        } catch (e) {
            alert("Erro de conexão ao excluir.");
        }
    }

    /* ══════════════════════════════════════════════════════════
       MODAL DE DETALHES DA RECORRÊNCIA
    ══════════════════════════════════════════════════════════ */
    window.abrirDetalhesRecorrencia = async function(recorrenciaId) {
        try {
            // Busca os eventos da recorrência
            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}/eventos`,
                { method: "GET" }
            );

            if (!res.ok && res.status !== 204) {
                alert("Erro ao carregar eventos da recorrência.");
                return;
            }

            const eventos = res.status === 204 ? [] : await res.json();

            // Cria overlay do modal
            const overlay = document.createElement('div');
            overlay.className = 'inst-modal-overlay';
            overlay.style.display = 'flex';
            overlay.id = 'recorrenciaModalOverlay';

            const hoje = new Date();
            hoje.setHours(0, 0, 0, 0);

            const eventosFuturos = eventos.filter(e => {
                const dataEvento = parseDateField(e.eventoFinanceiro.dataEvento);
                return dataEvento && dataEvento >= hoje;
            });

            const eventosPassados = eventos.filter(e => {
                const dataEvento = parseDateField(e.eventoFinanceiro.dataEvento);
                return dataEvento && dataEvento < hoje;
            });

            overlay.innerHTML = `
                <div class="inst-modal-content" style="max-width:700px;">
                    <div class="inst-modal-header">
                        <h2>Detalhes da Recorrência</h2>
                        <button class="inst-modal-close" onclick="fecharModalRecorrencia()">
                            <i class='bx bx-x'></i>
                        </button>
                    </div>

                    <div style="padding:20px;">
                        <div style="display:flex;gap:16px;margin-bottom:20px;">
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Total de Eventos</span>
                                <span class="inst-stat-valor">${eventos.length}</span>
                            </div>
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Futuros</span>
                                <span class="inst-stat-valor" style="color:var(--cor-principal);">${eventosFuturos.length}</span>
                            </div>
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Passados</span>
                                <span class="inst-stat-valor">${eventosPassados.length}</span>
                            </div>
                        </div>

                        <div style="margin-bottom:16px;">
                            <h3 style="font-size:0.95rem;margin-bottom:8px;color:var(--cor-principal);">
                                <i class='bx bx-time-five'></i> Eventos Futuros (${eventosFuturos.length})
                            </h3>
                            ${eventosFuturos.length === 0 ? 
                                '<p style="color:var(--cor-texto-secundario);font-size:0.85rem;">Nenhum evento futuro</p>' :
                                `<div style="max-height:200px;overflow-y:auto;">${eventosFuturos.map(e => buildEventoItemHTML(e)).join('')}</div>`
                            }
                        </div>

                        <div>
                            <h3 style="font-size:0.95rem;margin-bottom:8px;">
                                <i class='bx bx-check-circle'></i> Eventos Passados (${eventosPassados.length})
                            </h3>
                            ${eventosPassados.length === 0 ? 
                                '<p style="color:var(--cor-texto-secundario);font-size:0.85rem;">Nenhum evento passado</p>' :
                                `<div style="max-height:200px;overflow-y:auto;">${eventosPassados.map(e => buildEventoItemHTML(e)).join('')}</div>`
                            }
                        </div>
                    </div>
                </div>
            `;

            document.body.appendChild(overlay);
            document.body.style.overflow = 'hidden';

            overlay.addEventListener('click', function(e) {
                if (e.target === overlay) {
                    fecharModalRecorrencia();
                }
            });

        } catch (e) {
            console.error("Erro ao abrir detalhes da recorrência:", e);
            alert("Erro ao carregar detalhes da recorrência.");
        }
    };

    function buildEventoItemHTML(evento) {
        const ef = evento.eventoFinanceiro || {};
        const dataEvento = parseDateField(ef.dataEvento);
        const dataFmt = dataEvento ?
            `${String(dataEvento.getDate()).padStart(2, '0')}/${String(dataEvento.getMonth() + 1).padStart(2, '0')}/${dataEvento.getFullYear()}` :
            '–';

        const valor = ef.valor != null ? fmtBRL(ef.valor) : '–';
        const descricao = ef.descricao || evento.gastoDetalhe?.tituloGasto || 'Sem descrição';

        return `
        <div style="background:var(--cor-fundo-card);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:10px 12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;">
            <div>
                <div style="font-weight:600;font-size:0.87rem;">${descricao}</div>
                <div style="font-size:0.8rem;color:var(--cor-texto-secundario);">${dataFmt}</div>
            </div>
            <div style="font-weight:700;font-size:0.9rem;color:${ef.tipo === 'Gasto' ? 'var(--red-700)' : 'var(--cor-principal)'};">
                ${valor}
            </div>
        </div>`;
    }

    window.fecharModalRecorrencia = function() {
        const overlay = document.getElementById('recorrenciaModalOverlay');
        if (overlay) {
            overlay.remove();
            document.body.style.overflow = '';
        }
    };

    /* ══════════════════════════════════════════════════════════
       EDITAR RECORRÊNCIA
    ══════════════════════════════════════════════════════════ */
    let _recorrenciasCache = [];

    window.abrirModalEditarRecorrencia = async function(recorrenciaId) {
        // Busca a recorrência do cache
        let recorrencia = _recorrenciasCache.find(r => r.id === recorrenciaId);

        if (!recorrencia) {
            alert('Erro: recorrência não encontrada.');
            return;
        }

        const overlay = document.createElement('div');
        overlay.className = 'inst-modal-overlay';
        overlay.style.display = 'flex';
        overlay.id = 'editRecorrenciaModalOverlay';

        const PERIODOS = ['Diario', 'Semanal', 'Mensal', 'Anual'];
        const dataFim = recorrencia.dataFim ? new Date(recorrencia.dataFim).toISOString().split('T')[0] : '';

        overlay.innerHTML = `
            <div class="inst-modal-content" style="max-width:600px;">
                <div class="inst-modal-header">
                    <h2>Editar Recorrência</h2>
                    <button class="inst-modal-close" onclick="fecharModalEditarRecorrencia()">
                        <i class='bx bx-x'></i>
                    </button>
                </div>

                <div style="padding:20px;">
                    <div style="background:var(--cor-fundo-secondary);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:12px;margin-bottom:16px;">
                        <p style="font-size:0.85rem;color:var(--cor-texto-secundario);margin:0;">
                            <strong style="color:var(--cor-principal);">⚠️ Atenção:</strong> Ao editar esta recorrência, 
                            todos os eventos futuros serão recriados com os novos dados. Os eventos passados não serão alterados.
                        </p>
                    </div>

                    <form id="formEditarRecorrencia" onsubmit="salvarEdicaoRecorrencia(event, '${recorrenciaId}')">
                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Descrição</label>
                            <input type="text" id="editRecDesc" class="inst-campo-input" 
                                   value="${(recorrencia.descricao || '').replace(/"/g, '&quot;')}" placeholder="Ex: Salário mensal" />
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Valor (R$)</label>
                            <input type="number" id="editRecValor" class="inst-campo-input" 
                                   value="${recorrencia.valor || ''}" step="0.01" min="0" required />
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Periodicidade</label>
                            <select id="editRecPeriodicidade" class="inst-campo-input" required>
                                ${PERIODOS.map(p => `<option value="${p}" ${p === recorrencia.periodicidade ? 'selected' : ''}>${p}</option>`).join('')}
                            </select>
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Data Final</label>
                            <input type="date" id="editRecDataFim" class="inst-campo-input" 
                                   value="${dataFim}" />
                        </div>

                        <div class="inst-campo-wrap" id="editRecDiaWrap" style="${recorrencia.periodicidade === 'Mensal' || recorrencia.periodicidade === 'Anual' ? '' : 'display:none;'}">
                            <label class="inst-campo-label">Dia do mês</label>
                            <input type="number" id="editRecDia" class="inst-campo-input" 
                                   value="${recorrencia.dia || ''}" min="1" max="31" />
                        </div>

                        <div class="inst-campo-wrap" id="editRecIntervaloWrap" style="${recorrencia.periodicidade === 'Semanal' || recorrencia.periodicidade === 'Mensal' ? '' : 'display:none;'}">
                            <label class="inst-campo-label">Intervalo (a cada X ${recorrencia.periodicidade === 'Semanal' ? 'semanas' : 'meses'})</label>
                            <input type="number" id="editRecIntervalo" class="inst-campo-input" 
                                   value="${recorrencia.intervalo || 1}" min="1" />
                        </div>

                        <div style="display:flex;gap:12px;margin-top:20px;">
                            <button type="button" onclick="fecharModalEditarRecorrencia()" 
                                    class="inst-btn-salvar" style="background:var(--cor-texto-secundario);">
                                <i class='bx bx-x'></i> Cancelar
                            </button>
                            <button type="submit" class="inst-btn-salvar" style="flex:1;">
                                <i class='bx bx-save'></i> Salvar Alterações
                            </button>
                        </div>

                        <div id="editRecFeedback" class="inst-feedback" style="display:none;margin-top:12px;"></div>
                    </form>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);
        document.body.style.overflow = 'hidden';

        // Listener para mudar campos baseado na periodicidade
        document.getElementById('editRecPeriodicidade').addEventListener('change', function(e) {
            const val = e.target.value;
            document.getElementById('editRecDiaWrap').style.display = 
                (val === 'Mensal' || val === 'Anual') ? '' : 'none';
            document.getElementById('editRecIntervaloWrap').style.display = 
                (val === 'Semanal' || val === 'Mensal') ? '' : 'none';
        });

        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) {
                fecharModalEditarRecorrencia();
            }
        });
    };

    window.salvarEdicaoRecorrencia = async function(event, recorrenciaId) {
        event.preventDefault();

        const feedback = document.getElementById('editRecFeedback');
        const btnSalvar = event.target.querySelector('button[type="submit"]');

        try {
            btnSalvar.disabled = true;
            btnSalvar.innerHTML = '<i class="bx bx-loader-alt bx-spin"></i> Salvando...';

            const payload = {
                recorrencia: {
                    descricao: document.getElementById('editRecDesc').value || null,
                    valor: parseFloat(document.getElementById('editRecValor').value),
                    periodicidade: document.getElementById('editRecPeriodicidade').value,
                    dataFim: document.getElementById('editRecDataFim').value || null,
                    dia: parseInt(document.getElementById('editRecDia').value) || null,
                    intervalo: parseInt(document.getElementById('editRecIntervalo').value) || 1
                },
                // Nota: Para simplificar, não estamos editando instituições e categorias
                // Isso pode ser adicionado posteriormente se necessário
                instituicao: [],
                detalhe: { categoriaUsuario_id: [] }
            };

            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}`,
                {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                }
            );

            if (res.ok) {
                feedback.textContent = '✔ Recorrência atualizada com sucesso!';
                feedback.className = 'inst-feedback sucesso';
                feedback.style.display = 'block';

                setTimeout(() => {
                    fecharModalEditarRecorrencia();
                    // Recarrega a lista de recorrências
                    _recorrentesCarregados = false;
                    if (_instAtual) {
                        carregarRecorrentes(_instAtual.instUsuarioId);
                    }
                }, 1500);
            } else {
                let msg = 'Erro ao atualizar recorrência.';
                try {
                    const errorData = await res.json();
                    msg = errorData.message || errorData.error || msg;
                } catch {}

                feedback.textContent = `✘ ${msg}`;
                feedback.className = 'inst-feedback erro';
                feedback.style.display = 'block';
                btnSalvar.disabled = false;
                btnSalvar.innerHTML = '<i class="bx bx-save"></i> Salvar Alterações';
            }
        } catch (e) {
            console.error('Erro ao salvar edição:', e);
            feedback.textContent = '✘ Erro de conexão ao salvar.';
            feedback.className = 'inst-feedback erro';
            feedback.style.display = 'block';
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = '<i class="bx bx-save"></i> Salvar Alterações';
        }
    };

    window.fecharModalEditarRecorrencia = function() {
        const overlay = document.getElementById('editRecorrenciaModalOverlay');
        if (overlay) {
            overlay.remove();
            document.body.style.overflow = '';
        }
    };

    /* ══════════════════════════════════════════════════════════
       PAGAMENTO DE FATURA
    ══════════════════════════════════════════════════════════ */
    window.pagarFaturaInstituicao = async function () {
        if (!_instAtual) return;

        const inputValor = document.getElementById("inputValorFatura");
        const feedback   = document.getElementById("faturaFeedback");
        const btnPagar   = document.getElementById("btnPagarFatura");

        const valor = window.MainAPI ? window.MainAPI.obterValorMoeda(inputValor) : Number(inputValor?.value);
        if (!valor || valor <= 0) {
            if (feedback) { feedback.textContent = "Informe um valor válido."; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
            return;
        }

        if (btnPagar) { btnPagar.disabled = true; btnPagar.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Pagando..."; }

        try {
            const res = await MainAPI.request(
                `/instituicoes/${_instAtual.instUsuarioId}/pagar-fatura`,
                {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ valor })
                }
            );

            if (res.ok) {
                if (feedback) { feedback.textContent = "✔ Pagamento registrado com sucesso!"; feedback.className = "inst-feedback sucesso"; feedback.style.display = "block"; }
                // Recarrega dados
                await carregarInstituicoes();
                const novo = _resumoList.find(r => r.instUsuarioId === _instAtual.instUsuarioId);
                if (novo) {
                    _instAtual = novo;
                    const badge = document.getElementById("instModalBadge");
                    const pct = novo.percentualCreditoUtilizado || 0;
                    if (badge) { badge.textContent = `${pct}% crédito usado`; badge.className = "inst-modal-badge" + (pct > 80 ? " vermelho" : pct > 50 ? " amarelo" : ""); }
                }
            } else {
                let msg = "Erro ao processar pagamento.";
                try {
                    const errorData = await res.json();
                    msg = errorData.message || errorData.error || msg;
                } catch {
                    // Se não for JSON, tenta pegar como texto
                    try {
                        const textMsg = await res.text();
                        if (textMsg) msg = textMsg;
                    } catch {}
                }
                if (feedback) { feedback.textContent = `✘ ${msg}`; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
            }
        } catch (e) {
            if (feedback) { feedback.textContent = "✘ Erro de conexão."; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
        } finally {
            if (btnPagar) { btnPagar.disabled = false; btnPagar.innerHTML = "<i class='bx bx-credit-card'></i> Pagar Fatura"; }
        }
    };

    /* ══════════════════════════════════════════════════════════
       SALVAR CONFIGURAÇÃO
    ══════���═══════════════════════════════════════════════════ */
    window.salvarConfiguracaoInstituicao = async function () {
        if (!_instAtual) return;

        const btnSalvar = document.getElementById("btnSalvarConfig");
        const feedback  = document.getElementById("configFeedback");
        const taxaInput = document.getElementById("inputTaxaJuros");

        const limiteCredito = MainAPI.obterValorMoeda(_inputLimiteCredito);
        const taxaJuros     = taxaInput && taxaInput.value !== "" ? parseFloat(taxaInput.value) : null;

        btnSalvar.disabled = true;
        btnSalvar.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Salvando...";

        try {
            const payload = {};
            if (limiteCredito > 0) payload.limiteCredito = limiteCredito;
            if (taxaJuros !== null && !isNaN(taxaJuros)) payload.taxaJuros = taxaJuros;

            const res = await MainAPI.request(
                `/instituicoes/${_instAtual.instUsuarioId}/configurar`,
                {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload)
                }
            );

            if (res.ok) {
                exibirFeedback(feedback, "✔ Configurações salvas com sucesso!", "sucesso");
                await carregarInstituicoes();
                const novo = _resumoList.find(r => r.instUsuarioId === _instAtual.instUsuarioId);
                if (novo) _instAtual = novo;
            } else {
                const msg = await res.text().catch(() => "Erro ao salvar.");
                exibirFeedback(feedback, `✘ ${msg}`, "erro");
            }
        } catch (e) {
            exibirFeedback(feedback, "✘ Erro de conexão.", "erro");
        } finally {
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = "<i class='bx bx-save'></i> Salvar Configurações";
        }
    };

    function exibirFeedback(el, msg, tipo) {
        if (!el) return;
        el.textContent = msg;
        el.className   = `inst-feedback ${tipo}`;
        el.style.display = "block";
        setTimeout(() => { el.style.display = "none"; }, 4000);
    }

    /* ══════════════════════════════════════════════════════════
       CARREGAMENTO PRINCIPAL
    ══════════════════════════════════════════════════════════ */
    window.carregarInstituicoes = async function () {
        if (!_userId) return;

        atualizarLabelPeriodo();

        const loading = document.getElementById("loadingInstituicoes");
        const grid    = document.getElementById("instituicoesGrid");
        if (loading) loading.style.display = "flex";
        if (grid) grid.innerHTML = "";

        try {
            const p   = periodoAtual();
            const url = `/instituicoes/resumo/usuarios/${_userId}?${buildPeriodoParams(p)}`;
            const res = await MainAPI.request(url, { method: "GET" });

            if (res.status === 204 || !res.ok) {
                _resumoList = [];
            } else {
                _resumoList = await res.json();
            }

            calcularEExibirKPIs(_resumoList);
            renderizarCards(_resumoList);
        } catch (e) {
            console.error("Erro ao carregar instituições:", e);
            if (loading) loading.style.display = "none";
        }
    };

    async function carregarCaixinhas() {
        if (!_userId) return;
        try {
            _caixinhas = await MainAPI.getCaixinhas(_userId);
        } catch (e) {
            _caixinhas = [];
            console.warn("Erro ao carregar caixinhas:", e);
        }
    }

    /* ══════════════════════════════════════════════════════════
       INICIALIZAÇÃO
    ══════════════════════════════════════════════════════════ */
    window.iniciarPagina = async function () {
        const usuario = JSON.parse(localStorage.getItem("usuarioLogado") || "null");
        if (!usuario || !usuario.id) {
            window.location.href = "index.html";
            return;
        }
        _userId = usuario.id;

        // Aplica tema salvo
        const temaSalvo = localStorage.getItem("tema");
        const modoSalvo = localStorage.getItem("modo");
        if (temaSalvo) document.body.setAttribute("data-tema", temaSalvo);
        if (modoSalvo === "dark") document.body.setAttribute("data-mode", "dark");

        inicializarPeriodo();

        await Promise.all([
            carregarInstituicoes(),
            carregarCaixinhas()
        ]);
    };

})();

/* ================================================================
   instituicoes.js  –  Tela de Instituições Financeiras
   ================================================================ */

(function () {

    /* ─── Helpers de formatação ─────────────────────────────── */
    function fmtBRL(val) {
        const n = Number(val) || 0;
        return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    }

    function fmtNum(val) {
        return (Number(val) || 0).toLocaleString("pt-BR");
    }

    /* ─── Cores dos bancos (círculo no card) ─────────────────── */
    const COR_BANCOS = {
        "nubank":          "#820AD1",
        "itaú":            "#FF6200",
        "itau":            "#FF6200",
        "bradesco":        "#CC092F",
        "banco do brasil": "#F7CD00",
        "bb":              "#F7CD00",
        "caixa":           "#006B3F",
        "santander":       "#EC0000",
        "inter":           "#FF7A00",
        "c6":              "#1A1A2E",
        "xp":              "#000000",
        "picpay":          "#11C76F",
        "next":            "#00E64B",
        "neon":            "#00D4FF",
        "original":        "#00A651",
        "sicoob":          "#006B3F",
        "sicredi":         "#009B3A",
        "alelo":           "#F7941D",
        "aelo":            "#F7941D",
        "ticket":          "#EF3829",
        "vale":            "#009B3A",
        "pluxee":          "#6C2FF7",
        "sodexo":          "#D22630",
    };

    function corInstituicao(nome) {
        if (!nome) return "var(--cor-principal)";
        const chave = nome.toLowerCase();
        for (const [k, v] of Object.entries(COR_BANCOS)) {
            if (chave.includes(k)) return v;
        }
        // gera cor determinística baseada no nome
        let hash = 0;
        for (let i = 0; i < nome.length; i++) hash = (hash * 31 + nome.charCodeAt(i)) & 0xffffffff;
        const h = Math.abs(hash) % 360;
        return `hsl(${h},52%,42%)`;
    }

    function inicialInstituicao(nome) {
        if (!nome) return "?";
        const partes = nome.trim().split(/\s+/);
        if (partes.length >= 2) return (partes[0][0] + partes[1][0]).toUpperCase();
        return nome.slice(0, 2).toUpperCase();
    }

    /* ─── Estado Global ──────────────────────────────────────── */
    let _userId       = null;
    let _resumoList   = [];   // ResumoInstituicaoDto[]
    let _caixinhas    = [];   // CaixinhaResponseDTO[]
    let _instAtual    = null; // resumo selecionado para o modal
    let _atalhoAtivo  = null;

    /* ══════════════════════════════════════════════════════════
       PERÍODO (mesmo padrão do dashboard)
    ══════════════════════════════════════════════════════════ */
    const MESES = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                   "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    const TRIMESTRES = ["1º Trimestre","2º Trimestre","3º Trimestre","4º Trimestre"];
    const SEMESTRES  = ["1º Semestre","2º Semestre"];

    function periodoAtual() {
        const tipo = document.getElementById("select_tempo")?.value || "MENSAL";
        const ano  = parseInt(document.getElementById("select_ano")?.value  || new Date().getFullYear(), 10);
        switch (tipo) {
            case "MENSAL": {
                const mes = parseInt(document.getElementById("select_mes")?.value || (new Date().getMonth()+1), 10);
                return { tipo, ano, mes };
            }
            case "TRIMESTRAL": {
                const t = parseInt(document.getElementById("select_trimestre")?.value || 1, 10);
                return { tipo, ano, trimestre: t };
            }
            case "SEMESTRAL": {
                const s = parseInt(document.getElementById("select_semestre")?.value || 1, 10);
                return { tipo, ano, semestre: s };
            }
            case "ANUAL":
                return { tipo, ano };
        }
    }

    function labelPeriodo(p) {
        if (!p) return "–";
        switch (p.tipo) {
            case "MENSAL":     return `${MESES[(p.mes||1)-1]} / ${p.ano}`;
            case "TRIMESTRAL": return `${TRIMESTRES[(p.trimestre||1)-1]} / ${p.ano}`;
            case "SEMESTRAL":  return `${SEMESTRES[(p.semestre||1)-1]} / ${p.ano}`;
            case "ANUAL":      return `${p.ano}`;
        }
        return "–";
    }

    function buildPeriodoParams(p) {
        let url = `periodo=${p.tipo}&ano=${p.ano}`;
        if (p.tipo === "MENSAL"     && p.mes)       url += `&mes=${p.mes}`;
        if (p.tipo === "TRIMESTRAL" && p.trimestre) url += `&trimestre=${p.trimestre}`;
        if (p.tipo === "SEMESTRAL"  && p.semestre)  url += `&semestre=${p.semestre}`;
        return url;
    }

    window.atualizarSeletoresPeriodo = function () {
        const tipo  = document.getElementById("select_tempo")?.value;
        const divs  = { MENSAL:"div_mes", TRIMESTRAL:"div_trimestre", SEMESTRAL:"div_semestre", ANUAL:"div_ano" };
        const todos = ["div_mes","div_trimestre","div_semestre","div_ano"];
        todos.forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = "none";
        });
        if (divs[tipo]) {
            const el = document.getElementById(divs[tipo]);
            if (el) el.style.display = "";
        }
        document.getElementById("div_ano").style.display = "";
        marcarAtalhoAtivo(null);
        carregarInstituicoes();
    };

    window.marcarAtalhoAtivo = function (nome) {
        _atalhoAtivo = nome;
        document.querySelectorAll(".dash-atalho-btn").forEach(btn => {
            btn.classList.toggle("ativo", btn.dataset.atalho === nome);
        });
    };

    window.selecionarRapido = function (atalho) {
        const hoje = new Date();
        const anoAtual = hoje.getFullYear();
        const mesAtual = hoje.getMonth() + 1;

        const selTempo  = document.getElementById("select_tempo");
        const selMes    = document.getElementById("select_mes");
        const selAno    = document.getElementById("select_ano");

        if (!selTempo || !selMes || !selAno) return;

        if (atalho === "mes-atual") {
            selTempo.value = "MENSAL";
            selMes.value   = mesAtual;
            selAno.value   = anoAtual;
        } else if (atalho === "mes-passado") {
            const mP = mesAtual === 1 ? 12 : mesAtual - 1;
            const aP = mesAtual === 1 ? anoAtual - 1 : anoAtual;
            selTempo.value = "MENSAL";
            selMes.value   = mP;
            selAno.value   = aP;
        } else if (atalho === "ano-atual") {
            selTempo.value = "ANUAL";
            selAno.value   = anoAtual;
        } else if (atalho === "ano-passado") {
            selTempo.value = "ANUAL";
            selAno.value   = anoAtual - 1;
        }

        atualizarSeletoresPeriodo();
        marcarAtalhoAtivo(atalho);
        carregarInstituicoes();
    };

    function inicializarPeriodo() {
        const hoje = new Date();
        const selMes = document.getElementById("select_mes");
        const selAno = document.getElementById("select_ano");
        if (selMes) selMes.value = hoje.getMonth() + 1;
        if (selAno) selAno.value = hoje.getFullYear();
        atualizarSeletoresPeriodo();
        marcarAtalhoAtivo("mes-atual");
    }

    function atualizarLabelPeriodo() {
        const label = document.getElementById("labelPeriodoAtual");
        if (label) label.textContent = labelPeriodo(periodoAtual());
    }

    /* ══════════════════════════════════════════════════════════
       KPIs
    ══════════════════════════════════════════════════════════ */
    function calcularEExibirKPIs(lista) {
        if (!lista || lista.length === 0) {
            document.getElementById("kpi1Nome").textContent       = "Sem dados";
            document.getElementById("kpi1Sub").textContent        = "–";
            document.getElementById("kpi2Nome").textContent        = "Sem dados";
            document.getElementById("kpi2Valor").textContent       = "–";
            document.getElementById("kpi3Total").textContent       = "0";
            return;
        }

        // KPI 1 – Instituição mais utilizada (maior quantidadeTransacoes)
        const maisUsada = lista.reduce((a, b) =>
            (b.quantidadeTransacoes > a.quantidadeTransacoes ? b : a), lista[0]);
        document.getElementById("kpi1Nome").textContent = maisUsada.nomeInstituicao;
        document.getElementById("kpi1Sub").textContent  = `${fmtNum(maisUsada.quantidadeTransacoes)} transações`;

        // KPI 2 – Maior gasto médio / transação
        let maiorMedia = null;
        lista.forEach(inst => {
            if (!inst.quantidadeTransacoes || inst.quantidadeTransacoes === 0) return;
            const totalGasto = (Number(inst.totalCredito) || 0) + (Number(inst.totalDebito) || 0);
            const media = totalGasto / inst.quantidadeTransacoes;
            if (maiorMedia === null || media > maiorMedia.media) {
                maiorMedia = { inst, media };
            }
        });
        if (maiorMedia) {
            document.getElementById("kpi2Nome").textContent  = maiorMedia.inst.nomeInstituicao;
            // Apenas o valor — "por operação" já está no HTML como kpi-sub
            document.getElementById("kpi2Valor").textContent = fmtBRL(maiorMedia.media);
        } else {
            document.getElementById("kpi2Nome").textContent  = "Sem dados";
            document.getElementById("kpi2Valor").textContent = "–";
        }

        // KPI 3 – Total de parcelamentos ativos
        const totalParcelas = lista.reduce((acc, inst) => acc + (inst.parcelamentosAtivos || 0), 0);
        document.getElementById("kpi3Total").textContent = fmtNum(totalParcelas);
    }

    /* ══════════════════════════════════════════════════════════
       CARDS DAS INSTITUIÇÕES
    ══════════════════════════════════════════════════════════ */
    function renderizarCards(lista) {
        const grid    = document.getElementById("instituicoesGrid");
        const loading = document.getElementById("loadingInstituicoes");
        const vazio   = document.getElementById("semInstituicoes");

        if (loading) loading.style.display = "none";

        if (!lista || lista.length === 0) {
            grid.innerHTML = "";
            if (vazio) vazio.style.display = "flex";
            return;
        }

        if (vazio) vazio.style.display = "none";

        grid.innerHTML = lista.map(inst => buildCardHTML(inst)).join("");

        // Adiciona click handler em cada card
        grid.querySelectorAll(".inst-card").forEach(card => {
            card.addEventListener("click", () => {
                const id = parseInt(card.dataset.instId, 10);
                const resumo = _resumoList.find(r => r.instUsuarioId === id);
                if (resumo) abrirModalInstituicao(resumo);
            });
        });
    }

    function buildCardHTML(inst) {
        const cor     = corInstituicao(inst.nomeInstituicao);
        const inicial = inicialInstituicao(inst.nomeInstituicao);
        const pct     = Math.min(inst.percentualCreditoUtilizado || 0, 100);
        const limStr  = inst.limiteCredito > 0 ? `de ${fmtBRL(inst.limiteCredito)}` : "";
        const corBarra = pct > 80 ? "var(--red-700)" : pct > 50 ? "#f59e0b" : "var(--cor-principal)";
        const hasCred = inst.temCredito !== false;

        return `
        <div class="inst-card" data-inst-id="${inst.instUsuarioId}" title="Clique para ver detalhes">
            <!-- Cabeçalho do card -->
            <div class="inst-card-header">
                <div class="inst-card-avatar" style="background:${cor};">${inicial}</div>
                <div class="inst-card-info">
                    <span class="inst-card-nome">${inst.nomeInstituicao}</span>
                    <span class="inst-card-sub">${fmtNum(inst.quantidadeTransacoes)} transações</span>
                </div>
                <div class="inst-card-saldo-wrap">
                    <span class="inst-card-saldo-label">Saldo</span>
                    <span class="inst-card-saldo">${fmtBRL(inst.saldoDisponivel)}</span>
                </div>
            </div>

            <!-- Crédito / Débito -->
            <div class="inst-card-cd-row">
                <div class="inst-card-cd">
                    <span class="inst-cd-label">${hasCred ? "CRÉDITO" : "GASTO"}</span>
                    <span class="inst-cd-valor vermelho">${fmtBRL(inst.totalCredito)}</span>
                </div>
                <div class="inst-card-cd">
                    <span class="inst-cd-label">DÉBITO</span>
                    <span class="inst-cd-valor verde">${fmtBRL(inst.totalDebito)}</span>
                </div>
            </div>

            ${hasCred ? `
            <!-- Barra de crédito (somente para instituições com crédito) -->
            <div>
                <div class="inst-card-progress-header">
                    <span class="kpi-sub">Crédito usado</span>
                    <span class="kpi-sub"><strong>${pct}%</strong> ${limStr}</span>
                </div>
                <div class="inst-progress-track">
                    <div class="inst-progress-fill"
                         style="width:${pct}%; background:${corBarra};"></div>
                </div>
            </div>` : ""}

            <!-- Parcelas ativas -->
            ${inst.parcelamentosAtivos > 0 ? `
            <div class="inst-card-parcelas">
                <i class='bx bx-refresh'></i>
                <span>${inst.parcelamentosAtivos} parcelamento${inst.parcelamentosAtivos > 1 ? "s" : ""} ativo${inst.parcelamentosAtivos > 1 ? "s" : ""}</span>
            </div>` : ""}
        </div>`;
    }

    /* ══════════════════════════════════════════════════════════
       MODAL DE DETALHE
    ══════════════════════════════════════════════════════════ */
    let _inputLimiteCredito = null;

    function abrirModalInstituicao(resumo) {
        _instAtual = resumo;
        _parcelamentosCarregados = false; // reset lazy load
        _recorrentesCarregados   = false; // reset lazy load

        const hasCred = resumo.temCredito !== false;

        // Avatar e título
        const cor = corInstituicao(resumo.nomeInstituicao);
        const ini = inicialInstituicao(resumo.nomeInstituicao);
        document.getElementById("instModalAvatar").style.background = cor;
        document.getElementById("instModalAvatar").textContent      = ini;
        document.getElementById("instModalNome").textContent        = resumo.nomeInstituicao;

        const badge = document.getElementById("instModalBadge");
        if (hasCred) {
            const pct = resumo.percentualCreditoUtilizado || 0;
            badge.textContent = `${pct}% crédito usado`;
            badge.className   = "inst-modal-badge" + (pct > 80 ? " vermelho" : pct > 50 ? " amarelo" : "");
        } else {
            badge.textContent = "Sem crédito rotativo";
            badge.className   = "inst-modal-badge";
        }

        // Preenche aba Resumo
        document.getElementById("mdSaldo").textContent      = fmtBRL(resumo.saldoDisponivel);
        document.getElementById("mdTransacoes").textContent = fmtNum(resumo.quantidadeTransacoes);
        document.getElementById("mdCredito").textContent    = fmtBRL(resumo.totalCredito);
        document.getElementById("mdDebito").textContent     = fmtBRL(resumo.totalDebito);
        document.getElementById("mdParcelas").textContent   = fmtNum(resumo.parcelamentosAtivos);
        document.getElementById("mdTaxa").textContent       = resumo.taxaJuros != null
            ? `${Number(resumo.taxaJuros).toFixed(2)}% a.m.` : "–";

        // Seção de crédito (somente se houver crédito)
        const creditoSection = document.getElementById("mdCreditoSection");
        if (creditoSection) creditoSection.style.display = hasCred ? "" : "none";

        if (hasCred) {
            const pct = resumo.percentualCreditoUtilizado || 0;
            document.getElementById("mdCreditoPct").textContent  = `${pct}%`;
            document.getElementById("mdCreditoLimite").textContent = resumo.limiteCredito > 0
                ? `de ${fmtBRL(resumo.limiteCredito)}` : "";
            const fill = document.getElementById("mdCreditoFill");
            fill.style.width      = `${Math.min(pct, 100)}%`;
            fill.style.background = pct > 80 ? "var(--red-700)" : pct > 50 ? "#f59e0b" : "var(--cor-principal)";
        }

        // Rótulo de "Total Crédito" no resumo da aba
        const mdCreditoLabel = document.querySelector("#tab-resumo .inst-stat-card:nth-child(3) .inst-stat-label");
        if (mdCreditoLabel) mdCreditoLabel.textContent = hasCred ? "Total Crédito" : "Gastos";

        // Config tab: campo de limite de crédito
        const campLimite = document.getElementById("campLimiteCredito");
        if (campLimite) campLimite.style.display = hasCred ? "" : "none";

        // Seção de pagamento de fatura (só para instituições com crédito)
        const secFatura = document.getElementById("secaoPagarFatura");
        if (secFatura) secFatura.style.display = hasCred ? "" : "none";

        // Aplica máscara no campo de fatura se ainda não foi aplicada
        const inputFatura = document.getElementById("inputValorFatura");
        if (inputFatura && !inputFatura.dataset.mascaraAplicada) {
            MainAPI.aplicarMascaraMoeda(inputFatura);
            inputFatura.dataset.mascaraAplicada = "1";
        }
        if (inputFatura) MainAPI.resetarMascaraMoeda(inputFatura);

        // Carrega distribuição por movimento (detalhe)
        carregarDetalheInstituicao(resumo.instUsuarioId);

        // Preenche aba Config
        if (!_inputLimiteCredito) {
            _inputLimiteCredito = document.getElementById("inputLimiteCredito");
            MainAPI.aplicarMascaraMoeda(_inputLimiteCredito);
        }
        MainAPI.resetarMascaraMoeda(_inputLimiteCredito);
        if (hasCred && resumo.limiteCredito > 0) {
            const centavos = Math.round(Number(resumo.limiteCredito) * 100);
            _inputLimiteCredito.dataset.centavos = String(centavos);
            const reais = Math.floor(centavos / 100);
            const cts   = String(centavos % 100).padStart(2, "0");
            _inputLimiteCredito.value = `R$ ${String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, ".")},${cts}`;
        }
        const taxaInput = document.getElementById("inputTaxaJuros");
        if (taxaInput) taxaInput.value = resumo.taxaJuros != null ? resumo.taxaJuros : "";

        // Preenche aba Poupança
        carregarPoupancasInstituicao(resumo.instUsuarioId);

        // Feedback
        const fb = document.getElementById("configFeedback");
        if (fb) { fb.style.display = "none"; fb.textContent = ""; }

        // Abre na aba resumo
        trocarAba("resumo");

        // Exibe overlay
        const overlay = document.getElementById("instModalOverlay");
        overlay.style.display = "flex";
        document.body.style.overflow = "hidden";
    }

    async function carregarDetalheInstituicao(instUsuarioId) {
        try {
            const p = periodoAtual();
            const url = `/instituicoes/${instUsuarioId}/detalhe?${buildPeriodoParams(p)}`;
            const res = await MainAPI.request(url, { method: "GET" });
            if (!res.ok) return;
            const detalhe = await res.json();

            const sec  = document.getElementById("mdDistribuicaoSection");
            const grid = document.getElementById("mdDistribuicao");

            if (detalhe.distribuicaoPorMovimento && detalhe.distribuicaoPorMovimento.length > 0) {
                sec.style.display = "";
                grid.innerHTML = detalhe.distribuicaoPorMovimento.map(d => `
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">${d.tipoMovimento}</span>
                        <span class="inst-stat-valor">${fmtBRL(d.valorTotal)}</span>
                    </div>
                `).join("");
            } else {
                sec.style.display = "none";
            }
        } catch (e) {
            console.warn("Erro ao carregar detalhe:", e);
        }
    }

    function carregarPoupancasInstituicao(instUsuarioId) {
        const lista   = _caixinhas.filter(c => {
            if (!c.instituicoes) return false;
            return c.instituicoes.some(i => i.id === instUsuarioId);
        });

        const listaEl   = document.getElementById("poupancaLista");
        const vazioEl   = document.getElementById("poupancaVazio");
        const qtdEl     = document.getElementById("poupQtd");
        const valorEl   = document.getElementById("poupValor");
        const metaEl    = document.getElementById("poupMeta");

        const totalValor = lista.reduce((a, c) => a + (Number(c.valorAtual) || 0), 0);
        const totalMeta  = lista.reduce((a, c) => a + (Number(c.valorMeta)  || 0), 0);

        qtdEl.textContent  = lista.length;
        valorEl.textContent = fmtBRL(totalValor);
        metaEl.textContent  = fmtBRL(totalMeta);

        if (lista.length === 0) {
            listaEl.innerHTML  = "";
            vazioEl.style.display = "flex";
        } else {
            vazioEl.style.display = "none";
            listaEl.innerHTML = lista.map(c => {
                const pct     = Math.min(c.percentualAtingido || 0, 100).toFixed(1);
                const corBrr  = pct >= 100 ? "var(--cor-principal)" : pct > 60 ? "#f59e0b" : "var(--cor-principal)";
                return `
                <div class="inst-poupanca-item">
                    <div class="inst-poupanca-header">
                        <span class="inst-poupanca-nome">${c.nome}</span>
                        <span class="inst-poupanca-valor">${fmtBRL(c.valorAtual)}</span>
                    </div>
                    <div class="inst-poupanca-meta">Meta: ${fmtBRL(c.valorMeta)}</div>
                    <div class="inst-progress-track" style="margin-top:6px;">
                        <div class="inst-progress-fill"
                             style="width:${pct}%; background:${corBrr};"></div>
                    </div>
                    <div style="font-size:0.72rem; color:var(--cor-texto-secundario); margin-top:3px;">
                        ${pct}% atingido${c.mesesRestantes != null ? ` · ${c.mesesRestantes} meses restantes` : ""}
                    </div>
                </div>`;
            }).join("");
        }
    }

    window.trocarAba = function (nomAba) {
        document.querySelectorAll(".inst-tab").forEach(btn => {
            btn.classList.toggle("ativo", btn.dataset.tab === nomAba);
        });
        document.querySelectorAll(".inst-tab-panel").forEach(panel => {
            panel.classList.toggle("ativo", panel.id === `tab-${nomAba}`);
        });
        // Lazy load da aba de parcelamentos
        if (nomAba === "parcelamentos" && _instAtual) {
            carregarParcelamentos(_instAtual.instUsuarioId);
        }
        // Lazy load da aba de recorrentes
        if (nomAba === "recorrentes" && _instAtual) {
            carregarRecorrentes(_instAtual.instUsuarioId);
        }
    };

    window.fecharModalInstituicao = function (event) {
        if (event && event.target !== document.getElementById("instModalOverlay")) return;
        _fecharModal();
    };

    window.fecharModalInstituicaoBtn = function () {
        _fecharModal();
    };

    function _fecharModal() {
        const overlay = document.getElementById("instModalOverlay");
        if (overlay) overlay.style.display = "none";
        document.body.style.overflow = "";
        _instAtual = null;
    }

    /* ── Fechar com ESC ────────────────────────────────────── */
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") _fecharModal();
    });

    /* ══════════════════════════════════════════════════════════
       ABA PARCELAMENTOS
    ══════════════════════════════════════════════════════════ */
    let _parcelamentosCarregados = false;

    async function carregarParcelamentos(instUsuarioId) {
        if (_parcelamentosCarregados) return;
        _parcelamentosCarregados = true;

        const loadEl   = document.getElementById("parcelamentosLoading");
        const listaEl  = document.getElementById("parcelamentosLista");
        const vazioEl  = document.getElementById("parcelamentosVazio");
        const resumoEl = document.getElementById("parcelamentosResumo");

        if (loadEl)  loadEl.style.display  = "flex";
        if (listaEl) listaEl.innerHTML     = "";
        if (vazioEl) vazioEl.style.display = "none";
        if (resumoEl) resumoEl.innerHTML   = "";

        try {
            const res = await MainAPI.request(
                `/registros/filtro/usuarios/${_userId}?tipo=Gasto`,
                { method: "GET" }
            );

            if (loadEl) loadEl.style.display = "none";

            if (!res.ok || res.status === 204) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            const registros = await res.json();
            if (!Array.isArray(registros) || registros.length === 0) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            // Filtra apenas eventos associados a ESTA instituição E com múltiplas EIs (parcelados)
            const parcs = [];
            registros.forEach(r => {
                const eis = r.eventoInstituicao || [];
                // Filtra EIs desta instituição usando instUsuarioId
                const eisDaInst = eis.filter(e => e.instUsuarioId === instUsuarioId);
                if (eisDaInst.length === 0) return;

                // Total de parcelas = número total de EIs desta instituição neste evento
                const totalParcelas = eisDaInst.length > 1
                    ? eisDaInst.length
                    : Math.max(...eis.map(e => e.parcelas || 1));

                if (totalParcelas > 1) {
                    parcs.push({ registro: r, totalParcelas, ei: eisDaInst[0] });
                }
            });

            if (parcs.length === 0) {
                if (vazioEl) vazioEl.style.display = "flex";
                return;
            }

            // Calcula resumo
            const hoje = new Date();
            const ativos = parcs.filter(p => {
                const dataEvt = parseDateField(p.registro.eventoFinanceiro?.dataEvento);
                if (!dataEvt) return false;
                const fim = new Date(dataEvt);
                fim.setMonth(fim.getMonth() + p.totalParcelas);
                return fim >= hoje;
            }).length;

            if (resumoEl) {
                resumoEl.innerHTML = `
                <div class="inst-poupanca-resumo" style="margin-bottom:16px;">
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Total</span>
                        <span class="inst-stat-valor">${parcs.length}</span>
                    </div>
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Ativos</span>
                        <span class="inst-stat-valor" style="color:var(--cor-principal);">${ativos}</span>
                    </div>
                    <div class="inst-stat-card">
                        <span class="inst-stat-label">Encerrados</span>
                        <span class="inst-stat-valor">${parcs.length - ativos}</span>
                    </div>
                </div>`;
            }

            if (listaEl) {
                listaEl.innerHTML = parcs.map(p => buildParcelamentoItemHTML(p)).join("");
                listaEl.querySelectorAll("[data-del-evento]").forEach(btn => {
                    btn.addEventListener("click", () => {
                        const id = btn.dataset.delEvento;
                        deletarParcelamento(id, btn.closest(".inst-parc-item"));
                    });
                });
            }

        } catch (e) {
            console.error("Erro ao carregar parcelamentos:", e);
            if (loadEl) loadEl.style.display = "none";
            if (vazioEl) vazioEl.style.display = "flex";
        }
    }

    /** Converte dataEvento (array ou string) em Date */
    function parseDateField(raw) {
        if (!raw) return null;
        if (Array.isArray(raw) && raw.length >= 3) {
            return new Date(raw[0], raw[1] - 1, raw[2]);
        }
        if (typeof raw === "string") return new Date(raw);
        return null;
    }

    function buildParcelamentoItemHTML({ registro, ei, totalParcelas }) {
        const ef     = registro.eventoFinanceiro || {};
        const titulo = registro.gastoDetalhe?.tituloGasto || ef.descricao || "Sem título";
        const dataEvt = parseDateField(ef.dataEvento);
        let dataFmt = "–";
        let isAtivo = false;

        const numParcelas = totalParcelas || ei.parcelas || 1;

        if (dataEvt) {
            const dia = String(dataEvt.getDate()).padStart(2, "0");
            const mes = String(dataEvt.getMonth() + 1).padStart(2, "0");
            const ano = dataEvt.getFullYear();
            dataFmt = `${dia}/${mes}/${ano}`;
            const fim = new Date(dataEvt);
            fim.setMonth(fim.getMonth() + numParcelas);
            isAtivo = fim >= new Date();
        }

        // Valor total = soma de todos os EIs, ou valor do EI x numParcelas
        const eis = registro.eventoInstituicao || [];
        const valorTotal = eis.length > 1
            ? eis.reduce((s, e) => s + (Number(e.valor) || 0), 0)
            : (Number(ei.valor) || 0) * numParcelas;
        const valorParcela  = numParcelas > 0 ? valorTotal / numParcelas : valorTotal;
        const statusCls     = isAtivo ? "verde" : "";
        const statusTxt     = isAtivo ? "Ativo" : "Encerrado";
        const badgeCls      = isAtivo ? "ativo" : "encerrado";

        return `
        <div class="inst-parc-item">
            <div class="inst-parc-info">
                <span class="inst-parc-titulo">${titulo}</span>
                <span class="inst-parc-data">${dataFmt}</span>
            </div>
            <div class="inst-parc-valores">
                <span class="inst-stat-valor ${statusCls}">${fmtBRL(valorTotal)}</span>
                <span class="inst-parc-parcelas">${numParcelas}x de ${fmtBRL(valorParcela)}</span>
            </div>
            <div class="inst-parc-actions">
                <span class="inst-parc-badge ${badgeCls}">${statusTxt}</span>
                <button class="inst-parc-del-btn" data-del-evento="${ef.id}" title="Excluir parcelamento">
                    <i class='bx bx-trash'></i>
                </button>
            </div>
        </div>`;
    }

    async function deletarParcelamento(eventoId, itemEl) {
        if (!confirm("Tem certeza que deseja excluir este parcelamento? Todos os dados serão removidos.")) return;
        try {
            const res = await MainAPI.request(`/registros/${eventoId}`, { method: "DELETE" });
            if (res.ok || res.status === 204) {
                if (itemEl) {
                    itemEl.style.animation = "inst-parc-fade-out 0.3s forwards";
                    setTimeout(() => {
                        itemEl.remove();
                        // Atualiza lista e KPIs
                        _parcelamentosCarregados = false;
                        carregarInstituicoes();
                        carregarParcelamentos(_instAtual?.instUsuarioId);
                    }, 300);
                }
            } else {
                alert("Erro ao excluir parcelamento. Tente novamente.");
            }
        } catch (e) {
            alert("Erro de conexão ao excluir.");
        }
    }

    /* ══════════════════════════════════════════════════════════
       ABA RECORRENTES
    ══════════════════════════════════════════════════════════ */
    let _recorrentesCarregados = false;

    async function carregarRecorrentes(instUsuarioId) {
        if (_recorrentesCarregados) return;
        _recorrentesCarregados = true;

        const painel = document.getElementById("tab-recorrentes");
        if (!painel) return;

        painel.innerHTML = `
            <div class="inst-loading" style="display:flex;">
                <i class='bx bx-loader-alt bx-spin'></i> Carregando recorrentes...
            </div>`;

        try {
            const res = await MainAPI.request(
                `/registros/recorrentes/instituicoes/${instUsuarioId}`,
                { method: "GET" }
            );

            if (!res.ok || res.status === 204) {
                painel.innerHTML = buildRecorrentesVazio();
                return;
            }

            const lista = await res.json();
            if (!Array.isArray(lista) || lista.length === 0) {
                painel.innerHTML = buildRecorrentesVazio();
                return;
            }

            // Armazena no cache para usar na edição
            _recorrenciasCache = lista;

            painel.innerHTML = `
                <p class="kpi-label" style="margin-bottom:12px;">Eventos Recorrentes desta Instituição</p>
                <div class="inst-rec-lista" id="recLista">
                    ${lista.map(r => buildRecorrenteItemHTML(r)).join("")}
                </div>`;

            painel.querySelectorAll("[data-del-rec]").forEach(btn => {
                btn.addEventListener("click", () => {
                    const id = btn.dataset.delRec;
                    deletarRecorrente(id, btn.closest(".inst-rec-item"), instUsuarioId);
                });
            });

        } catch (e) {
            console.error("Erro ao carregar recorrentes:", e);
            painel.innerHTML = buildRecorrentesVazio();
        }
    }

    function buildRecorrentesVazio() {
        return `
        <div class="inst-vazio" style="display:flex; flex-direction:column; align-items:center; gap:12px; padding:32px 0;">
            <i class='bx bx-repeat' style="font-size:2.5rem; color:var(--cor-texto-secundario);"></i>
            <h3>Nenhum evento recorrente</h3>
            <p style="color:var(--cor-texto-secundario);">Nenhuma recorrência vinculada a esta instituição.</p>
            <a href="adicionarRegistros.html" class="inst-btn-recorrente">
                <i class='bx bx-plus-circle'></i> Criar Evento Recorrente
            </a>
        </div>`;
    }

    function buildRecorrenteItemHTML(r) {
        const PERIODOS = {
            Diario: 'Diário', Semanal: 'Semanal', Mensal: 'Mensal', Anual: 'Anual'
        };
        const TIPOS_LABEL = {
            Gasto: 'Gasto', Recebimento: 'Recebimento'
        };
        const per = PERIODOS[r.periodicidade] || r.periodicidade || '–';
        const tipo = TIPOS_LABEL[r.tipo] || r.tipo || '–';
        const dataInicio = r.dataInicio ? new Date(r.dataInicio).toLocaleDateString('pt-BR') : '–';
        const dataFim    = r.dataFim    ? new Date(r.dataFim).toLocaleDateString('pt-BR')    : '–';
        const valor      = r.valor != null ? fmtBRL(r.valor) : '–';
        const descricao  = r.descricao || '';
        const corTipo = r.tipo === 'Gasto' ? 'var(--red-700, #b91c1c)' : 'var(--cor-principal)';

        return `
        <div class="inst-rec-item" onclick="abrirDetalhesRecorrencia('${r.id}')">
            <div style="flex:1;min-width:0;">
                <div style="font-weight:700;font-size:0.97rem;margin-bottom:4px;color:var(--cor-texto-principal);">${descricao || tipo}</div>
                <div style="font-size:0.83rem;color:var(--cor-texto-principal);">
                    <span style="color:${corTipo};font-weight:700;">${tipo}</span> · ${per} · ${valor}
                </div>
                <div style="font-size:0.8rem;color:var(--cor-texto-secundario);margin-top:3px;">
                    ${dataInicio} → ${dataFim}
                </div>
            </div>
            <div style="display:flex;gap:8px;align-items:center;">
                <button class="inst-parc-del-btn" data-edit-rec="${r.id}" title="Editar recorrência" onclick="event.stopPropagation();abrirModalEditarRecorrencia('${r.id}')" style="background:var(--cor-principal);color:white;">
                    <i class='bx bx-edit'></i>
                </button>
                <button class="inst-parc-del-btn" data-del-rec="${r.id}" title="Excluir recorrência" onclick="event.stopPropagation()">
                    <i class='bx bx-trash'></i>
                </button>
            </div>
        </div>`;
    }

    async function deletarRecorrente(recorrenciaId, itemEl, instUsuarioId) {
        if (!confirm("Excluir esta recorrência? Os eventos futuros vinculados serão removidos.")) return;
        try {
            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}`,
                { method: "DELETE" }
            );
            if (res.ok || res.status === 204) {
                if (itemEl) itemEl.remove();
                _recorrentesCarregados = false;
                carregarRecorrentes(instUsuarioId);
            } else {
                alert("Erro ao excluir recorrência. Tente novamente.");
            }
        } catch (e) {
            alert("Erro de conexão ao excluir.");
        }
    }

    /* ══════════════════════════════════════════════════════════
       MODAL DE DETALHES DA RECORRÊNCIA
    ══════════════════════════════════════════════════════════ */
    window.abrirDetalhesRecorrencia = async function(recorrenciaId) {
        try {
            // Busca os eventos da recorrência
            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}/eventos`,
                { method: "GET" }
            );

            if (!res.ok && res.status !== 204) {
                alert("Erro ao carregar eventos da recorrência.");
                return;
            }

            const eventos = res.status === 204 ? [] : await res.json();

            // Cria overlay do modal
            const overlay = document.createElement('div');
            overlay.className = 'inst-modal-overlay';
            overlay.style.display = 'flex';
            overlay.id = 'recorrenciaModalOverlay';

            const hoje = new Date();
            hoje.setHours(0, 0, 0, 0);

            const eventosFuturos = eventos.filter(e => {
                const dataEvento = parseDateField(e.eventoFinanceiro.dataEvento);
                return dataEvento && dataEvento >= hoje;
            });

            const eventosPassados = eventos.filter(e => {
                const dataEvento = parseDateField(e.eventoFinanceiro.dataEvento);
                return dataEvento && dataEvento < hoje;
            });

            overlay.innerHTML = `
                <div class="inst-modal-content" style="max-width:700px;">
                    <div class="inst-modal-header">
                        <h2>Detalhes da Recorrência</h2>
                        <button class="inst-modal-close" onclick="fecharModalRecorrencia()">
                            <i class='bx bx-x'></i>
                        </button>
                    </div>

                    <div style="padding:20px;">
                        <div style="display:flex;gap:16px;margin-bottom:20px;">
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Total de Eventos</span>
                                <span class="inst-stat-valor">${eventos.length}</span>
                            </div>
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Futuros</span>
                                <span class="inst-stat-valor" style="color:var(--cor-principal);">${eventosFuturos.length}</span>
                            </div>
                            <div class="inst-stat-card">
                                <span class="inst-stat-label">Passados</span>
                                <span class="inst-stat-valor">${eventosPassados.length}</span>
                            </div>
                        </div>

                        <div style="margin-bottom:16px;">
                            <h3 style="font-size:0.95rem;margin-bottom:8px;color:var(--cor-principal);">
                                <i class='bx bx-time-five'></i> Eventos Futuros (${eventosFuturos.length})
                            </h3>
                            ${eventosFuturos.length === 0 ? 
                                '<p style="color:var(--cor-texto-secundario);font-size:0.85rem;">Nenhum evento futuro</p>' :
                                `<div style="max-height:200px;overflow-y:auto;">${eventosFuturos.map(e => buildEventoItemHTML(e)).join('')}</div>`
                            }
                        </div>

                        <div>
                            <h3 style="font-size:0.95rem;margin-bottom:8px;">
                                <i class='bx bx-check-circle'></i> Eventos Passados (${eventosPassados.length})
                            </h3>
                            ${eventosPassados.length === 0 ? 
                                '<p style="color:var(--cor-texto-secundario);font-size:0.85rem;">Nenhum evento passado</p>' :
                                `<div style="max-height:200px;overflow-y:auto;">${eventosPassados.map(e => buildEventoItemHTML(e)).join('')}</div>`
                            }
                        </div>
                    </div>
                </div>
            `;

            document.body.appendChild(overlay);
            document.body.style.overflow = 'hidden';

            overlay.addEventListener('click', function(e) {
                if (e.target === overlay) {
                    fecharModalRecorrencia();
                }
            });

        } catch (e) {
            console.error("Erro ao abrir detalhes da recorrência:", e);
            alert("Erro ao carregar detalhes da recorrência.");
        }
    };

    function buildEventoItemHTML(evento) {
        const ef = evento.eventoFinanceiro || {};
        const dataEvento = parseDateField(ef.dataEvento);
        const dataFmt = dataEvento ?
            `${String(dataEvento.getDate()).padStart(2, '0')}/${String(dataEvento.getMonth() + 1).padStart(2, '0')}/${dataEvento.getFullYear()}` :
            '–';

        const valor = ef.valor != null ? fmtBRL(ef.valor) : '–';
        const descricao = ef.descricao || evento.gastoDetalhe?.tituloGasto || 'Sem descrição';

        return `
        <div style="background:var(--cor-fundo-card);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:10px 12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;">
            <div>
                <div style="font-weight:600;font-size:0.87rem;">${descricao}</div>
                <div style="font-size:0.8rem;color:var(--cor-texto-secundario);">${dataFmt}</div>
            </div>
            <div style="font-weight:700;font-size:0.9rem;color:${ef.tipo === 'Gasto' ? 'var(--red-700)' : 'var(--cor-principal)'};">
                ${valor}
            </div>
        </div>`;
    }

    window.fecharModalRecorrencia = function() {
        const overlay = document.getElementById('recorrenciaModalOverlay');
        if (overlay) {
            overlay.remove();
            document.body.style.overflow = '';
        }
    };

    /* ══════════════════════════════════════════════════════════
       EDITAR RECORRÊNCIA
    ══════════════════════════════════════════════════════════ */
    let _recorrenciasCache = [];

    window.abrirModalEditarRecorrencia = async function(recorrenciaId) {
        // Busca a recorrência do cache
        let recorrencia = _recorrenciasCache.find(r => r.id === recorrenciaId);

        if (!recorrencia) {
            alert('Erro: recorrência não encontrada.');
            return;
        }

        const overlay = document.createElement('div');
        overlay.className = 'inst-modal-overlay';
        overlay.style.display = 'flex';
        overlay.id = 'editRecorrenciaModalOverlay';

        const PERIODOS = ['Diario', 'Semanal', 'Mensal', 'Anual'];
        const dataFim = recorrencia.dataFim ? new Date(recorrencia.dataFim).toISOString().split('T')[0] : '';

        overlay.innerHTML = `
            <div class="inst-modal-content" style="max-width:600px;">
                <div class="inst-modal-header">
                    <h2>Editar Recorrência</h2>
                    <button class="inst-modal-close" onclick="fecharModalEditarRecorrencia()">
                        <i class='bx bx-x'></i>
                    </button>
                </div>

                <div style="padding:20px;">
                    <div style="background:var(--cor-fundo-secondary);border:1px solid var(--cor-tinte-borda);border-radius:8px;padding:12px;margin-bottom:16px;">
                        <p style="font-size:0.85rem;color:var(--cor-texto-secundario);margin:0;">
                            <strong style="color:var(--cor-principal);">⚠️ Atenção:</strong> Ao editar esta recorrência, 
                            todos os eventos futuros serão recriados com os novos dados. Os eventos passados não serão alterados.
                        </p>
                    </div>

                    <form id="formEditarRecorrencia" onsubmit="salvarEdicaoRecorrencia(event, '${recorrenciaId}')">
                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Descrição</label>
                            <input type="text" id="editRecDesc" class="inst-campo-input" 
                                   value="${(recorrencia.descricao || '').replace(/"/g, '&quot;')}" placeholder="Ex: Salário mensal" />
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Valor (R$)</label>
                            <input type="number" id="editRecValor" class="inst-campo-input" 
                                   value="${recorrencia.valor || ''}" step="0.01" min="0" required />
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Periodicidade</label>
                            <select id="editRecPeriodicidade" class="inst-campo-input" required>
                                ${PERIODOS.map(p => `<option value="${p}" ${p === recorrencia.periodicidade ? 'selected' : ''}>${p}</option>`).join('')}
                            </select>
                        </div>

                        <div class="inst-campo-wrap">
                            <label class="inst-campo-label">Data Final</label>
                            <input type="date" id="editRecDataFim" class="inst-campo-input" 
                                   value="${dataFim}" />
                        </div>

                        <div class="inst-campo-wrap" id="editRecDiaWrap" style="${recorrencia.periodicidade === 'Mensal' || recorrencia.periodicidade === 'Anual' ? '' : 'display:none;'}">
                            <label class="inst-campo-label">Dia do mês</label>
                            <input type="number" id="editRecDia" class="inst-campo-input" 
                                   value="${recorrencia.dia || ''}" min="1" max="31" />
                        </div>

                        <div class="inst-campo-wrap" id="editRecIntervaloWrap" style="${recorrencia.periodicidade === 'Semanal' || recorrencia.periodicidade === 'Mensal' ? '' : 'display:none;'}">
                            <label class="inst-campo-label">Intervalo (a cada X ${recorrencia.periodicidade === 'Semanal' ? 'semanas' : 'meses'})</label>
                            <input type="number" id="editRecIntervalo" class="inst-campo-input" 
                                   value="${recorrencia.intervalo || 1}" min="1" />
                        </div>

                        <div style="display:flex;gap:12px;margin-top:20px;">
                            <button type="button" onclick="fecharModalEditarRecorrencia()" 
                                    class="inst-btn-salvar" style="background:var(--cor-texto-secundario);">
                                <i class='bx bx-x'></i> Cancelar
                            </button>
                            <button type="submit" class="inst-btn-salvar" style="flex:1;">
                                <i class='bx bx-save'></i> Salvar Alterações
                            </button>
                        </div>

                        <div id="editRecFeedback" class="inst-feedback" style="display:none;margin-top:12px;"></div>
                    </form>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);
        document.body.style.overflow = 'hidden';

        // Listener para mudar campos baseado na periodicidade
        document.getElementById('editRecPeriodicidade').addEventListener('change', function(e) {
            const val = e.target.value;
            document.getElementById('editRecDiaWrap').style.display = 
                (val === 'Mensal' || val === 'Anual') ? '' : 'none';
            document.getElementById('editRecIntervaloWrap').style.display = 
                (val === 'Semanal' || val === 'Mensal') ? '' : 'none';
        });

        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) {
                fecharModalEditarRecorrencia();
            }
        });
    };

    window.salvarEdicaoRecorrencia = async function(event, recorrenciaId) {
        event.preventDefault();

        const feedback = document.getElementById('editRecFeedback');
        const btnSalvar = event.target.querySelector('button[type="submit"]');

        try {
            btnSalvar.disabled = true;
            btnSalvar.innerHTML = '<i class="bx bx-loader-alt bx-spin"></i> Salvando...';

            const payload = {
                recorrencia: {
                    descricao: document.getElementById('editRecDesc').value || null,
                    valor: parseFloat(document.getElementById('editRecValor').value),
                    periodicidade: document.getElementById('editRecPeriodicidade').value,
                    dataFim: document.getElementById('editRecDataFim').value || null,
                    dia: parseInt(document.getElementById('editRecDia').value) || null,
                    intervalo: parseInt(document.getElementById('editRecIntervalo').value) || 1
                },
                // Nota: Para simplificar, não estamos editando instituições e categorias
                // Isso pode ser adicionado posteriormente se necessário
                instituicao: [],
                detalhe: { categoriaUsuario_id: [] }
            };

            const res = await MainAPI.request(
                `/registros/recorrentes/${recorrenciaId}`,
                {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                }
            );

            if (res.ok) {
                feedback.textContent = '✔ Recorrência atualizada com sucesso!';
                feedback.className = 'inst-feedback sucesso';
                feedback.style.display = 'block';

                setTimeout(() => {
                    fecharModalEditarRecorrencia();
                    // Recarrega a lista de recorrências
                    _recorrentesCarregados = false;
                    if (_instAtual) {
                        carregarRecorrentes(_instAtual.instUsuarioId);
                    }
                }, 1500);
            } else {
                let msg = 'Erro ao atualizar recorrência.';
                try {
                    const errorData = await res.json();
                    msg = errorData.message || errorData.error || msg;
                } catch {}

                feedback.textContent = `✘ ${msg}`;
                feedback.className = 'inst-feedback erro';
                feedback.style.display = 'block';
                btnSalvar.disabled = false;
                btnSalvar.innerHTML = '<i class="bx bx-save"></i> Salvar Alterações';
            }
        } catch (e) {
            console.error('Erro ao salvar edição:', e);
            feedback.textContent = '✘ Erro de conexão ao salvar.';
            feedback.className = 'inst-feedback erro';
            feedback.style.display = 'block';
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = '<i class="bx bx-save"></i> Salvar Alterações';
        }
    };

    window.fecharModalEditarRecorrencia = function() {
        const overlay = document.getElementById('editRecorrenciaModalOverlay');
        if (overlay) {
            overlay.remove();
            document.body.style.overflow = '';
        }
    };

    /* ══════════════════════════════════════════════════════════
       PAGAMENTO DE FATURA
    ══════════════════════════════════════════════════════════ */
    window.pagarFaturaInstituicao = async function () {
        if (!_instAtual) return;

        const inputValor = document.getElementById("inputValorFatura");
        const feedback   = document.getElementById("faturaFeedback");
        const btnPagar   = document.getElementById("btnPagarFatura");

        const valor = window.MainAPI ? window.MainAPI.obterValorMoeda(inputValor) : Number(inputValor?.value);
        if (!valor || valor <= 0) {
            if (feedback) { feedback.textContent = "Informe um valor válido."; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
            return;
        }

        if (btnPagar) { btnPagar.disabled = true; btnPagar.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Pagando..."; }

        try {
            const res = await MainAPI.request(
                `/instituicoes/${_instAtual.instUsuarioId}/pagar-fatura`,
                {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ valor })
                }
            );

            if (res.ok) {
                if (feedback) { feedback.textContent = "✔ Pagamento registrado com sucesso!"; feedback.className = "inst-feedback sucesso"; feedback.style.display = "block"; }
                // Recarrega dados
                await carregarInstituicoes();
                const novo = _resumoList.find(r => r.instUsuarioId === _instAtual.instUsuarioId);
                if (novo) {
                    _instAtual = novo;
                    const badge = document.getElementById("instModalBadge");
                    const pct = novo.percentualCreditoUtilizado || 0;
                    if (badge) { badge.textContent = `${pct}% crédito usado`; badge.className = "inst-modal-badge" + (pct > 80 ? " vermelho" : pct > 50 ? " amarelo" : ""); }
                }
            } else {
                let msg = "Erro ao processar pagamento.";
                try {
                    const errorData = await res.json();
                    msg = errorData.message || errorData.error || msg;
                } catch {
                    // Se não for JSON, tenta pegar como texto
                    try {
                        const textMsg = await res.text();
                        if (textMsg) msg = textMsg;
                    } catch {}
                }
                if (feedback) { feedback.textContent = `✘ ${msg}`; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
            }
        } catch (e) {
            if (feedback) { feedback.textContent = "✘ Erro de conexão."; feedback.className = "inst-feedback erro"; feedback.style.display = "block"; }
        } finally {
            if (btnPagar) { btnPagar.disabled = false; btnPagar.innerHTML = "<i class='bx bx-credit-card'></i> Pagar Fatura"; }
        }
    };

    /* ══════════════════════════════════════════════════════════
       SALVAR CONFIGURAÇÃO
    ══════���═══════════════════════════════════════════════════ */
    window.salvarConfiguracaoInstituicao = async function () {
        if (!_instAtual) return;

        const btnSalvar = document.getElementById("btnSalvarConfig");
        const feedback  = document.getElementById("configFeedback");
        const taxaInput = document.getElementById("inputTaxaJuros");

        const limiteCredito = MainAPI.obterValorMoeda(_inputLimiteCredito);
        const taxaJuros     = taxaInput && taxaInput.value !== "" ? parseFloat(taxaInput.value) : null;

        btnSalvar.disabled = true;
        btnSalvar.innerHTML = "<i class='bx bx-loader-alt bx-spin'></i> Salvando...";

        try {
            const payload = {};
            if (limiteCredito > 0) payload.limiteCredito = limiteCredito;
            if (taxaJuros !== null && !isNaN(taxaJuros)) payload.taxaJuros = taxaJuros;

            const res = await MainAPI.request(
                `/instituicoes/${_instAtual.instUsuarioId}/configurar`,
                {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload)
                }
            );

            if (res.ok) {
                exibirFeedback(feedback, "✔ Configurações salvas com sucesso!", "sucesso");
                await carregarInstituicoes();
                const novo = _resumoList.find(r => r.instUsuarioId === _instAtual.instUsuarioId);
                if (novo) _instAtual = novo;
            } else {
                const msg = await res.text().catch(() => "Erro ao salvar.");
                exibirFeedback(feedback, `✘ ${msg}`, "erro");
            }
        } catch (e) {
            exibirFeedback(feedback, "✘ Erro de conexão.", "erro");
        } finally {
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = "<i class='bx bx-save'></i> Salvar Configurações";
        }
    };

    function exibirFeedback(el, msg, tipo) {
        if (!el) return;
        el.textContent = msg;
        el.className   = `inst-feedback ${tipo}`;
        el.style.display = "block";
        setTimeout(() => { el.style.display = "none"; }, 4000);
    }

    /* ══════════════════════════════════════════════════════════
       CARREGAMENTO PRINCIPAL
    ══════════════════════════════════════════════════════════ */
    window.carregarInstituicoes = async function () {
        if (!_userId) return;

        atualizarLabelPeriodo();

        const loading = document.getElementById("loadingInstituicoes");
        const grid    = document.getElementById("instituicoesGrid");
        if (loading) loading.style.display = "flex";
        if (grid) grid.innerHTML = "";

        try {
            const p   = periodoAtual();
            const url = `/instituicoes/resumo/usuarios/${_userId}?${buildPeriodoParams(p)}`;
            const res = await MainAPI.request(url, { method: "GET" });

            if (res.status === 204 || !res.ok) {
                _resumoList = [];
            } else {
                _resumoList = await res.json();
            }

            calcularEExibirKPIs(_resumoList);
            renderizarCards(_resumoList);
        } catch (e) {
            console.error("Erro ao carregar instituições:", e);
            if (loading) loading.style.display = "none";
        }
    };

    async function carregarCaixinhas() {
        if (!_userId) return;
        try {
            _caixinhas = await MainAPI.getCaixinhas(_userId);
        } catch (e) {
            _caixinhas = [];
            console.warn("Erro ao carregar caixinhas:", e);
        }
    }

    /* ══════════════════════════════════════════════════════════
       INICIALIZAÇÃO
    ══════════════════════════════════════════════════════════ */
    window.iniciarPagina = async function () {
        const usuario = JSON.parse(localStorage.getItem("usuarioLogado") || "null");
        if (!usuario || !usuario.id) {
            window.location.href = "index.html";
            return;
        }
        _userId = usuario.id;

        // Aplica tema salvo
        const temaSalvo = localStorage.getItem("tema");
        const modoSalvo = localStorage.getItem("modo");
        if (temaSalvo) document.body.setAttribute("data-tema", temaSalvo);
        if (modoSalvo === "dark") document.body.setAttribute("data-mode", "dark");

        inicializarPeriodo();

        await Promise.all([
            carregarInstituicoes(),
            carregarCaixinhas()
        ]);
    };

})();

(function () {
    const LOCAL_API = "http://localhost:8080";

    function buildUrl(path) {
        if (/^https?:\/\//i.test(path)) {
            return path;
        }
        return `${LOCAL_API}${path}`;
    }

    function request(path, options) {
        return fetch(buildUrl(path), options);
    }

    function get(path) {
        return request(path, { method: "GET" }).then(res => res.json());
    }

    function postJson(path, payload) {
        return request(path, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(payload)
        });
    }

    function chaveImagemLocal(userId) {
        return userId ? `usuarioImagemLocal:${userId}` : null;
    }

    function formatarLocalDateTime(valor, vazio = "-") {
        if (!valor) return vazio;

        if (Array.isArray(valor) && valor.length >= 5) {
            const [ano, mes, dia, hora = 0, min = 0] = valor;
            return `${String(dia).padStart(2, "0")}/${String(mes).padStart(2, "0")}/${ano} ${String(hora).padStart(2, "0")}:${String(min).padStart(2, "0")}`;
        }

        if (typeof valor === "string") {
            const dt = new Date(valor);
            if (!isNaN(dt.getTime())) {
                const d = String(dt.getDate()).padStart(2, "0");
                const m = String(dt.getMonth() + 1).padStart(2, "0");
                const y = dt.getFullYear();
                const h = String(dt.getHours()).padStart(2, "0");
                const mi = String(dt.getMinutes()).padStart(2, "0");
                return `${d}/${m}/${y} ${h}:${mi}`;
            }
        }

        if (typeof valor === "object") {
            const ano = valor.year ?? valor.ano;
            const mes = valor.monthValue ?? valor.mes;
            const dia = valor.dayOfMonth ?? valor.dia;
            const hora = valor.hour ?? valor.hora ?? 0;
            const min = valor.minute ?? valor.minuto ?? 0;
            if (ano && mes && dia) {
                return `${String(dia).padStart(2, "0")}/${String(mes).padStart(2, "0")}/${ano} ${String(hora).padStart(2, "0")}:${String(min).padStart(2, "0")}`;
            }
        }

        return vazio;
    }

    // ── MÁSCARA DE DATA (dd/mm/aaaa) ──────────────────────────────
    function aplicarMascaraData(input) {
        input.setAttribute("type", "text");
        input.setAttribute("placeholder", "dd/mm/aaaa");
        input.setAttribute("maxlength", "10");
        input.setAttribute("inputmode", "numeric");

        input.addEventListener("input", function () {
            const pos = this.selectionStart;
            let v = this.value.replace(/\D/g, "").slice(0, 8);
            let r = "";
            if (v.length > 0) r = v.slice(0, 2);
            if (v.length > 2) r += "/" + v.slice(2, 4);
            if (v.length > 4) r += "/" + v.slice(4, 8);
            this.value = r;
        });

        input.addEventListener("keydown", function (e) {
            // Backspace: se o cursor está após uma barra, apaga a barra junto
            if (e.key === "Backspace") {
                const cur = this.selectionStart;
                if (cur > 0 && this.value[cur - 1] === "/") {
                    this.value = this.value.slice(0, cur - 1) + this.value.slice(cur);
                    this.setSelectionRange(cur - 1, cur - 1);
                    e.preventDefault();
                }
            }
        });
    }

    function dataParaISO(dataBR) {
        // "dd/mm/aaaa" → "aaaa-mm-dd"
        const m = (dataBR || "").match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
        if (!m) return null;
        return `${m[3]}-${m[2]}-${m[1]}`;
    }

    function dataDeISO(dataISO) {
        // "aaaa-mm-dd" → "dd/mm/aaaa"
        const m = (dataISO || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (!m) return dataISO;
        return `${m[3]}/${m[2]}/${m[1]}`;
    }

    // ── MÁSCARA MONETÁRIA (estilo caixa registradora) ─────────────
    function aplicarMascaraMoeda(input) {
        input.setAttribute("type", "text");
        input.setAttribute("inputmode", "numeric");
        input.setAttribute("autocomplete", "off");

        // Armazena o valor em centavos
        input.dataset.centavos = "0";

        function _formatar(cents) {
            // Formata sem toLocaleString (compatibilidade JavaFX)
            var reais = Math.floor(cents / 100);
            var centsStr = String(cents % 100).padStart(2, "0");
            var reaisStr = String(reais).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
            return "R$ " + reaisStr + "," + centsStr;
        }

        function _atualizar() {
            input.value = _formatar(Number(input.dataset.centavos || 0));
        }

        _atualizar();

        input.addEventListener("keydown", function (e) {
            var centavos = Number(input.dataset.centavos || 0);

            // Normaliza e.key — fallback para e.keyCode (JavaFX WebView pode não ter e.key)
            var key = e.key;
            if (!key || key === "Unidentified") {
                var kc = e.keyCode || e.which || 0;
                if (kc >= 48 && kc <= 57)       key = String(kc - 48);   // 0-9
                else if (kc >= 96 && kc <= 105) key = String(kc - 96);   // Numpad 0-9
                else if (kc === 8)              key = "Backspace";
                else if (kc === 46)             key = "Delete";
                else if (kc === 27)             key = "Escape";
            }
            var isDigit = key && key.length === 1 && key >= "0" && key <= "9";

            if (isDigit) {
                e.preventDefault();
                if (centavos >= 999999999) return;
                centavos = centavos * 10 + parseInt(key, 10);
                input.dataset.centavos = String(centavos);
                _atualizar();

            } else if (key === "Backspace") {
                e.preventDefault();
                centavos = Math.floor(centavos / 10);
                input.dataset.centavos = String(centavos);
                _atualizar();

            } else if (key === "Delete" || key === "Escape") {
                e.preventDefault();
                input.dataset.centavos = "0";
                _atualizar();
            }
        });

        // Impede edição manual direta (paste, drag, etc.)
        input.addEventListener("paste", function (e) {
            e.preventDefault();
            var texto = (e.clipboardData || window.clipboardData || { getData: function () { return ""; } }).getData("text");
            // Extrai apenas dígitos
            var digitos = texto.replace(/\D/g, "").replace(/^0+/, "") || "0";
            input.dataset.centavos = String(Math.min(Number(digitos), 999999999));
            _atualizar();
        });

        // Garante que um clique no campo posicione o cursor no final
        input.addEventListener("click", function () {
            var len = input.value.length;
            input.setSelectionRange(len, len);
        });

        // Previne seleção e edição de trechos do valor
        input.addEventListener("input", function () {
            _atualizar();
        });
    }

    function obterValorMoeda(input) {
        return Number(input.dataset.centavos || 0) / 100;
    }

    function resetarMascaraMoeda(input) {
        input.dataset.centavos = "0";
        var reaisStr = "0";
        input.value = "R$ " + reaisStr + ",00";
    }

    // ── PAGINAÇÃO: busca todas as páginas de um endpoint paginado ──
    async function fetchTodasPaginas(path) {
        const allContent = [];
        let pagina = 0;
        let isLast = false;
        const LIMITE_PAGINAS = 100; // segurança

        while (!isLast && pagina < LIMITE_PAGINAS) {
            const sep = path.includes("?") ? "&" : "?";
            const res = await request(`${path}${sep}pagina=${pagina}`, { method: "GET" });

            if (res.status === 204) break;
            if (!res.ok) break;

            const data = await res.json();

            if (data && Array.isArray(data.content)) {
                allContent.push(...data.content);
                isLast = data.last === true;
            } else if (Array.isArray(data)) {
                allContent.push(...data);
                isLast = true;
            } else {
                // Resposta inesperada
                break;
            }
            pagina++;
        }

        return allContent;
    }

    window.MainAPI = {
        request,
        get,
        formatarLocalDateTime,
        aplicarMascaraData,
        dataParaISO,
        dataDeISO,
        fetchTodasPaginas,
        aplicarMascaraMoeda,
        obterValorMoeda,
        resetarMascaraMoeda,
        getTipos(userId) {
            // Endpoint paginado — busca todas as páginas
            return fetchTodasPaginas(`/categorias/usuario/${userId}`);
        },
        getInstituicoes(userId) {
            if (userId) {
                // Endpoint paginado — busca todas as páginas
                return fetchTodasPaginas(`/instituicoes/usuarios/${userId}`);
            }
            // Endpoint global também paginado
            return fetchTodasPaginas("/instituicoes");
        },
        registrarGasto(payload) {
            return postJson("/registros", payload);
        },
        registrarRecorrente(payload) {
            return postJson("/registros/recorrente", payload);
        },
        getCaixinhas(userId) {
            return request(`/caixinhas/ativas/usuarios/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        adicionarSaldo(payload) {
            return this.registrarGasto(payload);
        },
        atualizarSaldo(payload) {
            return this.registrarGasto(payload);
        },
        carregarRegistros(userId) {
            return request(`/registros/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        // ── PASSO 1: anos com registros ─────────────────────────────
        buscarAnosRegistros(userId) {
            return request(`/registros/anos/usuarios/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        // ── PASSO 2: meses (do ano) com registros ───────────────────
        buscarMesesRegistros(userId, ano) {
            return request(`/registros/meses/usuarios/${userId}?ano=${ano}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        // ── PASSO 3: registros do mês, paginados ────────────────────
        buscarRegistrosPorMes(userId, ano, mes, pagina = 0, tamanho = 20) {
            return request(`/registros/mes/usuarios/${userId}?ano=${ano}&mes=${mes}&pagina=${pagina}&tamanho=${tamanho}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) {
                        return { content: [], totalElements: 0, totalPages: 0, number: 0, size: tamanho, first: true, last: true, empty: true };
                    }
                    return res.json();
                });
        },
        filtrarRegistros(userId, filtros) {
            const params = new URLSearchParams();

            if (filtros.valor) params.append("valor", filtros.valor);
            if (filtros.dataEvento) params.append("dataEvento", filtros.dataEvento);
            if (filtros.descricao) params.append("descricao", filtros.descricao);
            if (filtros.titulo) params.append("titulo", filtros.titulo);

            (filtros.tipo || []).forEach(v => params.append("tipo", v));
            (filtros.tipoMovimento || []).forEach(v => params.append("tipoMovimento", v));
            (filtros.instituicaoUsuario || []).forEach(v => params.append("instituicaoUsuario", v));
            (filtros.categoriaUsuario || []).forEach(v => params.append("categoriaUsuario", v));

            const query = params.toString();
            const path = query
                ? `/registros/filtro/usuarios/${userId}?${query}`
                : `/registros/filtro/usuarios/${userId}`;

            return request(path, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        adicionarTipo(payload, userId) {
            return postJson(`/categorias/usuario/${userId}`, { titulo: payload.titulo });
        },
        buscarRegistrosPorData(userId, dataSelecionada) {
            return request(`/registros/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                })
                .then(registros => registros.filter(r => {
                    const dataEvento = r.eventoFinanceiro && r.eventoFinanceiro.dataEvento;
                    return dataEvento === dataSelecionada;
                }));
        },
        mostrarSaldoTotal(userId) {
            return request(`/registros/usuario/${userId}/saldo`, { method: "GET" })
                .then(res => res.json())
                .then(data => [{ valorTotal: data.valorTotal }]);
        },
        mostrarTodasInstituicoes(userId) {
            return request(`/registros/usuario/${userId}/saldo/instituicoes`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        cadastrarUsuario(payload) {
            return postJson("/usuarios", payload);
        },
        loginUsuario(payload) {
            return postJson("/usuarios/login", payload);
        },
        obterUsuario(userId) {
            return request(`/usuarios/${userId}`, { method: "GET" })
                .then(res => res.json());
        },
        enviarImagemUsuario(userId, file) {
            const formData = new FormData();
            formData.append("file", file);
            return request(`/usuarios/${userId}/upload-imagem`, {
                method: "PUT",
                body: formData
            });
        },
        salvarImagemLocal(userId, dataUrl) {
            const chave = chaveImagemLocal(userId);
            if (!chave || !dataUrl) return;
            try {
                localStorage.setItem(chave, dataUrl);
            } catch (_) {
            }
        },
        obterImagemLocal(userId) {
            const chave = chaveImagemLocal(userId);
            if (!chave) return null;
            return localStorage.getItem(chave);
        },
        resolverUrlImagem(caminhoImagem, userId) {
            // Tenta cache local primeiro (data URL)
            const local = this.obterImagemLocal(userId);
            if (local) return local;

            if (!caminhoImagem) return null;
            if (/^data:image\//i.test(caminhoImagem)) return caminhoImagem;
            if (/^https?:\/\//i.test(caminhoImagem)) return caminhoImagem;

            // Caminho relativo do servidor – constrói URL completa
            if (typeof caminhoImagem === "string" && caminhoImagem.trim()) {
                const path = caminhoImagem.startsWith("/") ? caminhoImagem : "/" + caminhoImagem;
                return `${LOCAL_API}${path}`;
            }

            return null;
        },
        editarRegistro(eventoId, payload) {
            return request(`/registros/${eventoId}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload)
            });
        },
        editarSenhaUsuario(userId, payload) {
            return request(`/usuarios/editar-senha/${userId}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload)
            });
        },
        excluirUsuario(userId) {
            return request(`/usuarios/${userId}`, { method: "DELETE" });
        },
        desvincularTodasInstituicoes(userId) {
            return request(`/instituicoes/desvincular-todas-as-instituicoes/usuarios/${userId}`, { method: "PUT" });
        },
        deletarTodosEventos(userId) {
            return request(`/configuracoes/usuarios/${userId}/dados/deletar-tudo`, { method: "DELETE" });
        },
        deletarRegistro(eventoId) {
            return request(`/registros/${eventoId}`, { method: "DELETE" });
        }
    };
})();

