            <div style="flex:1; min-width:0;">
                <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:6px;">
                    <h3 id="mf-toast-title" style="
                        font-size:1rem; font-weight:700; margin:0;
                        color:var(--cor-titulo);">
                        Atualizando...
                    </h3>
                    <button id="mf-toast-close" title="Fechar" style="
                        background:none; border:none; cursor:pointer;
                        color:var(--cor-texto-secundario); font-size:1.3rem;
                        padding:0; line-height:1; width:20px; height:20px;
                        display:flex; align-items:center; justify-content:center;
                        transition:color 0.2s;">✕</button>
                </div>
                <p id="mf-toast-message" style="
                    font-size:0.85rem; color:var(--cor-texto-secundario);
                    margin:0; line-height:1.5;">
                    Baixando nova versão...
                </p>
                <div id="mf-toast-progress-wrap" style="
                    margin-top:12px; width:100%; height:6px;
                    background:var(--cor-tinte-borda,#e2e8f0);
                    border-radius:3px; overflow:hidden;">
                    <div id="mf-toast-progress-bar" style="
                        height:100%; width:0%; border-radius:3px;
                        background:linear-gradient(90deg, var(--cor-principal,#6366f1), var(--cor-principal-hover,#4f46e5));
                        transition:width 0.4s ease;">
                    </div>
                </div>
                <span id="mf-toast-percentage" style="
                    display:block; margin-top:6px; font-size:0.75rem;
                    color:var(--cor-texto-secundario); font-weight:600;">
                    0%
                </span>
            </div>
        </div>
    </div>
    <style>
        @keyframes mfToastSlide {
            from { opacity:0; transform:translateX(100px); }
            to   { opacity:1; transform:translateX(0); }
        }
        @keyframes mfSpin {
            0%   { transform:rotate(0deg); }
            100% { transform:rotate(360deg); }
        }
        #mf-update-toast.success #mf-toast-spinner {
            border:3px solid transparent;
            background:var(--green-500,#22c55e);
            display:flex; align-items:center; justify-content:center;
            animation:none;
        }
        #mf-update-toast.success #mf-toast-spinner::after {
            content:'✓';
            color:#fff;
            font-size:1.4rem;
            font-weight:700;
        }
        #mf-toast-close:hover {
            color:var(--red-600,#dc2626);
        }
    </style>`;

    document.body.insertAdjacentHTML('beforeend', updateToastHtml);

    const toast = document.getElementById('mf-update-toast');
    const toastTitle = document.getElementById('mf-toast-title');
    const toastMessage = document.getElementById('mf-toast-message');
    const toastProgress = document.getElementById('mf-toast-progress-bar');
    const toastPercentage = document.getElementById('mf-toast-percentage');
    const toastSpinner = document.getElementById('mf-toast-spinner');
    const toastClose = document.getElementById('mf-toast-close');

    // Botão X para fechar manualmente
    toastClose.addEventListener('click', function() {
        hideUpdateToast();
    });

    // Verifica se há atualização em progresso ao carregar a página
    async function checkUpdateInProgress() {
        const updateStatus = localStorage.getItem('mf-update-status');
        if (updateStatus) {
            const status = JSON.parse(updateStatus);

            // Verifica se a versão armazenada mudou (indica que a atualização foi concluída)
            try {
                const res = await fetch('http://localhost:8080/api/update/check');
                if (res.ok) {
                    const info = await res.json();
                    const currentVersion = info.currentVersion;
                    const storedVersion = localStorage.getItem('mf-app-version');

                    if (currentVersion && storedVersion && currentVersion !== storedVersion) {
                        // Versão mudou! A atualização foi bem-sucedida
                        localStorage.setItem('mf-app-version', currentVersion);
                        localStorage.removeItem('mf-update-status');
                        return; // Não mostra o toast
                    }

                    // Armazena a versão atual se ainda não foi armazenada
                    if (currentVersion && !storedVersion) {
                        localStorage.setItem('mf-app-version', currentVersion);
                    }
                }
            } catch (e) {
                // Se falhar ao buscar a versão, continua com a lógica de timeout
            }

            // Se a versão não mudou mas já passou tempo suficiente, limpa o status
            if (status.timestamp) {
                const elapsed = Date.now() - status.timestamp;
                if (elapsed > 60000) { // 60 segundos
                    localStorage.removeItem('mf-update-status');
                    return;
                }
            }

            if (status.inProgress) {
                showUpdateToast(status.title, status.message, status.progress);
            }
        }
    }

    function showUpdateToast(title, message, progress) {
        toast.style.display = 'block';
        toastTitle.textContent = title;
        toastMessage.textContent = message;
        toastProgress.style.width = progress + '%';
        toastPercentage.textContent = Math.round(progress) + '%';

        // Salva o estado no localStorage com timestamp
        localStorage.setItem('mf-update-status', JSON.stringify({
            inProgress: true,
            title: title,
            message: message,
            progress: progress,
            timestamp: Date.now()
        }));
    }

    function updateToastProgress(progress) {
        toastProgress.style.width = progress + '%';
        toastPercentage.textContent = Math.round(progress) + '%';

        const status = JSON.parse(localStorage.getItem('mf-update-status') || '{}');
        status.progress = progress;
        localStorage.setItem('mf-update-status', JSON.stringify(status));
    }

    function completeUpdateToast() {
        toast.classList.add('success');
        toastTitle.textContent = 'Atualização Concluída!';
        toastMessage.textContent = 'Reiniciando aplicação...';
        toastProgress.style.width = '100%';
        toastPercentage.textContent = '100%';

        localStorage.removeItem('mf-update-status');

        setTimeout(function() {
            toast.style.display = 'none';
            toast.classList.remove('success');
        }, 3000);
    }

    function hideUpdateToast() {
        toast.style.display = 'none';
        localStorage.removeItem('mf-update-status');
    }

    // Exporta funções globalmente
    window._showUpdateToast = showUpdateToast;
    window._updateToastProgress = updateToastProgress;
    window._completeUpdateToast = completeUpdateToast;
    window._hideUpdateToast = hideUpdateToast;

    // Verifica ao carregar
    checkUpdateInProgress();
})();

/*---------------- Ícone de Notificações ----------------*/
(function () {
    // Cria o ícone de notificações dinamicamente
    const notificationIconHtml = `
    <div id="mf-notification-icon" style="
        position:relative; cursor:pointer; margin-right:12px;
        width:40px; height:40px; border-radius:50%;
        display:flex; align-items:center; justify-content:center;
        background:var(--cor-fundo-card,#fff);
        border:1.5px solid var(--cor-tinte-borda,#e2e8f0);
        transition:all 0.2s ease;">
        <i class='bx bx-bell' style="font-size:1.3rem; color:var(--cor-texto-principal);"></i>
        <span id="mf-notification-badge" style="
            position:absolute; top:-4px; right:-4px;
            background:var(--red-600,#dc2626); color:#fff;
            border-radius:50%; width:20px; height:20px;
            display:none; align-items:center; justify-content:center;
            font-size:0.7rem; font-weight:700; border:2px solid var(--cor-fundo-pagina,#fff);">
            0
        </span>
    </div>
    <style>
        #mf-notification-icon:hover {
            background:var(--cor-hover,#f1f5f9);
            border-color:var(--cor-principal,#6366f1);
        }
        #mf-notification-icon:hover i {
            color:var(--cor-principal,#6366f1);
        }
    </style>`;

    // Injeta o ícone ao lado do user widget em todas as páginas
    function injectNotificationIcon() {
        const topActions = document.querySelector('.top-actions');
        if (topActions) {
            topActions.insertAdjacentHTML('afterbegin', notificationIconHtml);

            const notifIcon = document.getElementById('mf-notification-icon');
            if (notifIcon) {
                notifIcon.addEventListener('click', function() {
                    window._showUpdateNotifications();
                });
            }
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injectNotificationIcon);
    } else {
        injectNotificationIcon();
    }

    // Função global para atualizar contador de notificações
    window._updateNotificationBadge = function(count) {
        const badge = document.getElementById('mf-notification-badge');
        if (badge) {
            if (count > 0) {
                badge.textContent = count > 9 ? '9+' : count;
                badge.style.display = 'flex';
            } else {
                badge.style.display = 'none';
            }
        }
    };
})();

/*---------------- Auto-Update: verificação e notificação ----------------*/
(function () {
    const CHECK_INTERVAL_MS = 30 * 60 * 1000; // 30 minutos
    const SNOOZE_DURATION_MS = 12 * 60 * 60 * 1000; // 12 horas
    const API_BASE = 'http://localhost:8080';

    let _updateInfo = null;
    let _isDismissed = false;

    // ── Injeta o banner de atualização no DOM ──
    const bannerHtml = `
    <div id="mf-update-banner" style="
        display:none; position:fixed; bottom:24px; right:24px; z-index:99998;
        background:var(--cor-fundo-card,#fff);
        border:1.5px solid var(--cor-principal,#6366f1);
        border-radius:16px;
        box-shadow:0 8px 32px rgba(0,0,0,0.18);
        padding:18px 22px 16px;
        min-width:300px; max-width:360px;
        animation:mfBannerIn 0.25s ease;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">
            <span style="
                background:var(--cor-principal,#6366f1);
                color:#fff; border-radius:50%; width:34px;height:34px;
                display:flex;align-items:center;justify-content:center;flex-shrink:0;">
                <i class='bx bx-cloud-download' style="font-size:1.2rem;"></i>
            </span>
            <div>
                <div style="font-weight:700;font-size:0.95rem;color:var(--cor-titulo);">Nova versão disponível!</div>
                <div id="mf-update-versions" style="font-size:0.78rem;color:var(--cor-texto-secundario);margin-top:2px;"></div>
            </div>
            <button id="mf-update-close" title="Fechar" style="
                margin-left:auto;background:none;border:none;cursor:pointer;
                color:var(--cor-texto-secundario);font-size:1.2rem;padding:2px 4px;line-height:1;">✕</button>
        </div>
        <p style="font-size:0.83rem;color:var(--cor-texto-secundario);margin:0 0 14px;line-height:1.5;">
            Clique em <strong>Atualizar agora</strong> para baixar e reiniciar automaticamente.
        </p>
        <button id="mf-update-toggle" style="
            display:none;align-items:center;gap:6px;background:none;border:none;padding:0;
            margin:0 0 10px;cursor:pointer;font-size:0.82rem;font-weight:600;
            color:var(--cor-principal,#6366f1);">
            <span id="mf-update-toggle-text">Mostrar mais detalhes</span>
            <span id="mf-update-arrow" aria-hidden="true" style="font-size:0.9rem;line-height:1;transition:transform 0.18s ease;">
                <i class='bx bx-chevron-down'></i>
            </span>
        </button>
        <div id="mf-update-details" style="
            display:none;max-height:160px;overflow:auto;
            border:1px solid var(--cor-tinte-borda,#e2e8f0);border-radius:8px;
            padding:10px 12px;margin:0 0 12px;
            background:var(--cor-fundo-pagina,#f8fafc);font-size:0.8rem;
            color:var(--cor-texto-secundario);line-height:1.45;white-space:pre-line;"></div>
        <div style="display:flex;gap:8px;">
            <button id="mf-update-btn" style="
                flex:1;padding:9px 0;border-radius:9px;border:none;cursor:pointer;
                background:var(--cor-principal,#6366f1);color:#fff;
                font-size:0.88rem;font-weight:600;transition:opacity 0.18s;">
                <i class='bx bx-refresh'></i> Atualizar agora
            </button>
            <button id="mf-update-later" style="
                padding:9px 14px;border-radius:9px;cursor:pointer;
                background:var(--cor-fundo-pagina);color:var(--cor-texto-principal);
                font-size:0.88rem;font-weight:600;border:1px solid var(--cor-tinte-borda,#ccc);
                transition:background 0.18s;">
                Depois
            </button>
        </div>
        <div id="mf-update-progress" style="display:none;margin-top:12px;text-align:center;">
            <div style="
                width:100%;height:6px;border-radius:3px;
                background:var(--cor-tinte-borda,#e2e8f0);overflow:hidden;">
                <div id="mf-update-bar" style="
                    height:100%;width:0%;border-radius:3px;
                    background:var(--cor-principal,#6366f1);
                    transition:width 0.4s ease;"></div>
            </div>
            <span id="mf-update-status" style="font-size:0.78rem;color:var(--cor-texto-secundario);margin-top:6px;display:block;">
                Baixando atualização...
            </span>
        </div>
    </div>
    <style>
        @keyframes mfBannerIn {
            from { opacity:0; transform:translateY(16px) scale(0.97); }
            to   { opacity:1; transform:translateY(0)   scale(1);     }
        }
        #mf-update-btn:hover   { opacity:0.85; }
        #mf-update-later:hover { background:var(--cor-hover,#e2e8f0)!important; }
    </style>`;

    document.body.insertAdjacentHTML('beforeend', bannerHtml);

    const banner        = document.getElementById('mf-update-banner');
    const btnAtualizar  = document.getElementById('mf-update-btn');
    const btnDepois     = document.getElementById('mf-update-later');
    const btnFechar     = document.getElementById('mf-update-close');
    const versionsEl    = document.getElementById('mf-update-versions');
    const btnDetalhes   = document.getElementById('mf-update-toggle');
    const txtDetalhes   = document.getElementById('mf-update-toggle-text');
    const setaDetalhes  = document.getElementById('mf-update-arrow');
    const detailsEl     = document.getElementById('mf-update-details');
    const progressArea  = document.getElementById('mf-update-progress');
    const progressBar   = document.getElementById('mf-update-bar');
    const statusEl      = document.getElementById('mf-update-status');

    let _downloadUrl = null;
    let _showingDetails = false;

    function setDetalhesVisiveis(visible) {
        _showingDetails = !!visible;
        detailsEl.style.display = _showingDetails ? 'block' : 'none';
        setaDetalhes.style.transform = _showingDetails ? 'rotate(180deg)' : 'rotate(0deg)';
        txtDetalhes.textContent = _showingDetails
            ? 'Ocultar detalhes'
            : 'Mostrar mais detalhes';
    }

    function mostrarBanner(info) {
        _updateInfo = info;
        versionsEl.textContent = 'Atual: v' + info.currentVersion + '  →  Nova: v' + info.latestVersion;
        _downloadUrl = info.downloadUrl || null;

        const releaseNotes = (info.releaseNotes || '').trim();
        if (releaseNotes) {
            detailsEl.textContent = releaseNotes;
            btnDetalhes.style.display = 'inline-flex';
            setDetalhesVisiveis(false);
        } else {
            detailsEl.textContent = '';
            btnDetalhes.style.display = 'none';
            setDetalhesVisiveis(false);
        }

        banner.style.display = 'block';

        // Remove a notificação do badge quando o banner é mostrado
        if (_isDismissed) {
            _isDismissed = false;
            localStorage.removeItem('mf-update-dismissed');
            window._updateNotificationBadge(0);
        }
    }

    function ocultarBanner() {
        banner.style.display = 'none';
    }

    function dismissarAtualizacao() {
        _isDismissed = true;
        localStorage.setItem('mf-update-dismissed', 'true');
        ocultarBanner();

        // Adiciona ao contador de notificações
        if (_updateInfo) {
            window._updateNotificationBadge(1);
        }
    }

    function adiarAtualizacao() {
        localStorage.setItem('mf-update-snoozed', Date.now().toString());
        ocultarBanner();
    }

    btnFechar.addEventListener('click', dismissarAtualizacao);
    btnDepois.addEventListener('click', adiarAtualizacao);
    btnDetalhes.addEventListener('click', function () {
        setDetalhesVisiveis(!_showingDetails);
    });

    btnAtualizar.addEventListener('click', async function () {
        if (!_downloadUrl) return;

        // Desabilita botões e esconde o banner
        btnAtualizar.disabled = true;
        btnDepois.disabled    = true;
        btnFechar.disabled    = true;
        ocultarBanner();

        // Mostra toast de atualização persistente
        window._showUpdateToast('Atualizando MyFinance', 'Iniciando download da nova versão...', 0);

        // Simula progresso visual enquanto o download ocorre no backend
        let pct = 0;
        const interval = setInterval(function() {
            pct = Math.min(pct + Math.random() * 5, 85);
            window._updateToastProgress(pct);
        }, 500);

        try {
            // Aguarda 800ms para dar tempo do toast aparecer
            await new Promise(resolve => setTimeout(resolve, 800));

            window._showUpdateToast('Baixando Atualização', 'Fazendo download do servidor...', pct);

            const res = await fetch(API_BASE + '/api/update/apply', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ downloadUrl: _downloadUrl })
            });

            clearInterval(interval);

            if (res.ok) {
                window._showUpdateToast('Download Concluído', 'Preparando atualização...', 90);

                await new Promise(resolve => setTimeout(resolve, 1000));

                window._completeUpdateToast();

                // Monitora se a aplicação realmente fechou
                setTimeout(function() {
                    // Se ainda estiver aqui após 10s, mostra mensagem
                    window._showUpdateToast('Aguardando Fechamento', 'Aguarde o aplicativo reiniciar...', 100);
                }, 10000);
            } else {
                throw new Error('Falha na requisição: ' + res.status);
            }
        } catch (e) {
            clearInterval(interval);
            window._hideUpdateToast();

            // Reativa botões do banner
            btnAtualizar.disabled = false;
            btnDepois.disabled    = false;
            btnFechar.disabled    = false;
            mostrarBanner(_updateInfo);

            // Mostra erro no banner original
            progressBar.style.width = '0%';
            progressBar.style.background = '#ef4444';
            statusEl.textContent = 'Erro ao atualizar. Tente novamente.';
            progressArea.style.display = 'block';

            console.error('[Update] Erro:', e);
        }
    });

    // ── Verifica se há atualização disponível ──
    async function verificarAtualizacao() {
        try {
            const res = await fetch(API_BASE + '/api/update/check');
            if (!res.ok) return;
            const info = await res.json();

            if (info.hasUpdate && info.downloadUrl) {
                _updateInfo = info;

                // Verifica se o usuário clicou em X (dismissed)
                const dismissed = localStorage.getItem('mf-update-dismissed');
                if (dismissed === 'true') {
                    _isDismissed = true;
                    window._updateNotificationBadge(1);
                    return; // Não mostra o banner automaticamente
                }

                // Verifica se o usuário clicou em "depois" recentemente
                const snoozed = localStorage.getItem('mf-update-snoozed');
                if (snoozed) {
                    const snoozedTime = parseInt(snoozed, 10);
                    const elapsed = Date.now() - snoozedTime;
                    if (elapsed < SNOOZE_DURATION_MS) {
                        return; // Ainda no período de adiamento
                    }
                    localStorage.removeItem('mf-update-snoozed');
                }

                // Mostra o banner se não foi dismissed nem snoozed
                mostrarBanner(info);
            } else {
                // Se não há atualização, limpa o dismissed e badge
                _isDismissed = false;
                _updateInfo = null;
                localStorage.removeItem('mf-update-dismissed');
                window._updateNotificationBadge(0);
            }
        } catch (e) {
            // Silencioso: sem internet ou backend ainda não inicializado
        }
    }

    // ── Função para mostrar notificações quando clicar no sino ──
    window._showUpdateNotifications = function() {
        if (_updateInfo && _isDismissed) {
            mostrarBanner(_updateInfo);
        }
    };

    // Primeira verificação após 10s (dá tempo ao Spring Boot inicializar)
    setTimeout(verificarAtualizacao, 10000);
    // Verificações subsequentes a cada 30 minutos
    setInterval(verificarAtualizacao, CHECK_INTERVAL_MS);
})();

/* ═══════════════════════════════════════════════════════════════
   caixinhas.css — Tela de Poupança / Caixinhas
   ═══════════════════════════════════════════════════════════════ */

/* ── Page header ─────────────────────────────────────────── */
.cxh-page-header {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
    flex-wrap: wrap;
    gap: 12px;
}
.cxh-page-header h1 { margin-bottom: 0; }

.cxh-header-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cxh-header-subtitle {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    font-weight: 400;
}

.btn-nova-caixinha {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.18s, transform 0.15s;
    text-decoration: none;
}
.btn-nova-caixinha:hover { opacity: 0.88; transform: translateY(-1px); }

/* ── KPI grid ────────────────────────────────────────────── */
.cxh-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}

.cxh-kpi-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid var(--cor-tinte-borda);
    transition: transform 0.18s, box-shadow 0.18s;
}
.cxh-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--sombra-card); }

.cxh-kpi-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cxh-kpi-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.cxh-kpi-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--cor-principal);
}
.cxh-kpi-valor {
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.1;
}
.cxh-kpi-sub {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
}

/* ── Barra de progresso consolidada ─────────────────────── */
.cxh-progresso-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 16px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1px solid var(--cor-tinte-borda);
    margin-bottom: 20px;
}
.cxh-progresso-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}
.cxh-progresso-label {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-progresso-pct {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-progress-track {
    height: 10px;
    background: var(--cor-tinte-suave);
    border-radius: 6px;
    overflow: hidden;
}
.cxh-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    border-radius: 6px;
    transition: width 0.5s ease;
}

/* ── Filtros / Abas ─────────────────────────────────────── */
.cxh-filtros {
    display: flex;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.cxh-filtro-btn {
    padding: 8px 18px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-secundario);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s;
}
.cxh-filtro-btn:hover {
    background: var(--cor-tinte-suave);
    color: var(--cor-titulo);
}
.cxh-filtro-btn.ativo {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border-color: var(--cor-principal);
}

/* ── Grid de cards ──────────────────────────────────────── */
.cxh-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

/* ── Card individual de caixinha ────────────────────────── */
.cxh-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1.5px solid var(--cor-tinte-borda);
    cursor: pointer;
    transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative;
    overflow: hidden;
}
.cxh-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px var(--sombra-card);
    border-color: var(--cor-principal);
}
.cxh-card.encerrada {
    opacity: 0.72;
}
.cxh-card.encerrada::after {
    content: "ENCERRADA";
    position: absolute;
    top: 12px;
    right: -22px;
    background: var(--cor-texto-secundario);
    color: #fff;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    padding: 3px 30px;
    transform: rotate(45deg);
}

.cxh-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}
.cxh-card-nome {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.3;
}
.cxh-card-desc {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
    margin-top: 2px;
}

/* Badge de tipo de rendimento */
.cxh-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 12px;
    white-space: nowrap;
    letter-spacing: 0.04em;
}
.cxh-badge-CDI       { background: rgba(54,115,115,0.12);  color: var(--cor-principal); }
.cxh-badge-SELIC     { background: rgba(59,130,246,0.12);  color: #3B82F6; }
.cxh-badge-POUPANCA  { background: rgba(16,185,129,0.12);  color: #10B981; }
.cxh-badge-PREFIXADO { background: rgba(139,92,246,0.12);  color: #8B5CF6; }
.cxh-badge-PERSONALIZADO { background: rgba(245,158,11,0.12); color: #F59E0B; }

/* Valores */
.cxh-card-valores {
    display: flex;
    align-items: baseline;
    gap: 6px;
}
.cxh-card-valor-atual {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-card-meta {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
}

/* Barra de progresso do card */
.cxh-card-progress-track {
    height: 7px;
    background: var(--cor-tinte-suave);
    border-radius: 4px;
    overflow: hidden;
}
.cxh-card-progress-fill {
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    transition: width 0.5s ease;
}
.cxh-card-progress-fill.atingida {
    background: linear-gradient(90deg, var(--green-700), #22c55e);
}

.cxh-card-progress-info {
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-pct { font-weight: 700; color: var(--cor-titulo); }

/* Footer do card */
.cxh-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 8px;
    border-top: 1px solid var(--cor-tinte-suave);
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-meta-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--green-700);
}
.cxh-card-meta-alcancavel.nao { color: var(--red-700); }

/* ── Estado vazio ────────────────────────────────────────── */
.cxh-vazio {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 60px 20px;
    color: var(--cor-texto-secundario);
    text-align: center;
}
.cxh-vazio i { font-size: 3rem; opacity: 0.4; }
.cxh-vazio h3 { font-size: 1.1rem; color: var(--cor-titulo); }
.cxh-vazio p { font-size: 0.88rem; }

/* Loading */
.cxh-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 40px;
    color: var(--cor-texto-secundario);
    font-size: 0.95rem;
}

/* ── Insight card ─────────────────────────────────────────── */
.cxh-insight {
    background: var(--cor-tinte-suave);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 12px;
    padding: 14px 18px;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 24px;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.55;
}
.cxh-insight i {
    font-size: 1.3rem;
    color: var(--cor-principal);
    flex-shrink: 0;
    margin-top: 1px;
}

/* ═══════════════════════════════════════════════════════════════
   MODAL BASE
   ═══════════════════════════════════════════════════════════════ */
.cxh-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 9000;
    background: var(--cor-overlay);
    backdrop-filter: blur(3px);
    align-items: center;
    justify-content: center;
    padding: 16px;
}
.cxh-modal-overlay.aberto { display: flex; }

.cxh-modal {
    background: var(--cor-fundo-card);
    border-radius: 20px;
    box-shadow: 0 20px 60px var(--sombra-caixa);
    width: 100%;
    max-width: 580px;
    max-height: 90vh;
    overflow-y: auto;
    animation: cxhModalIn 0.22s ease;
    display: flex;
    flex-direction: column;
}
.cxh-modal-lg { max-width: 720px; }

@keyframes cxhModalIn {
    from { opacity: 0; transform: scale(0.93) translateY(14px); }
    to   { opacity: 1; transform: scale(1)    translateY(0); }
}

.cxh-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px 24px 16px;
    border-bottom: 1px solid var(--cor-tinte-borda);
    flex-shrink: 0;
}
.cxh-modal-header h2 {
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}
.cxh-modal-close {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: none;
    background: var(--cor-tinte-suave);
    color: var(--cor-texto-secundario);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: background 0.15s;
    padding: 0;
    margin: 0;
}
.cxh-modal-close:hover { background: var(--cor-tinte-medio); }

.cxh-modal-body {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    flex: 1;
}

.cxh-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid var(--cor-tinte-borda);
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* ── Seções do modal de criação ──────────────────────────── */
.cxh-secao-titulo {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--cor-principal);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-secao-titulo::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--cor-tinte-borda);
}

/* ── Campos de formulário ─────────────────────────────────── */
.cxh-campo-wrap {
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.cxh-campo-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-campo-input {
    padding: 10px 12px;
    border-radius: 9px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-campo);
    color: var(--cor-texto-principal);
    font-size: 0.9rem;
    width: 100%;
    transition: border-color 0.15s;
    outline: none;
}
.cxh-campo-input:focus {
    border-color: var(--cor-principal);
    background: var(--cor-fundo-card);
}
.cxh-campo-input::placeholder { color: var(--cor-texto-secundario); opacity: 0.6; }

.cxh-campo-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

/* ── Tipo de rendimento – botões inline ──────────────────── */
.cxh-rendimento-btns {
    display: flex;
    gap: 7px;
    flex-wrap: wrap;
    margin-bottom: 14px;
}
.cxh-rend-btn {
    padding: 7px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    color: var(--cor-texto-secundario);
    margin: 0;
}
.cxh-rend-btn:hover { background: var(--cor-tinte-suave); }
.cxh-rend-btn.ativo-CDI       { background: rgba(54,115,115,0.14);  color: var(--cor-principal); border-color: var(--cor-principal); }
.cxh-rend-btn.ativo-SELIC     { background: rgba(59,130,246,0.14);  color: #3B82F6;  border-color: #3B82F6; }
.cxh-rend-btn.ativo-POUPANCA  { background: rgba(16,185,129,0.14);  color: #10B981;  border-color: #10B981; }
.cxh-rend-btn.ativo-PREFIXADO { background: rgba(139,92,246,0.14);  color: #8B5CF6;  border-color: #8B5CF6; }
.cxh-rend-btn.ativo-PERSONALIZADO { background: rgba(245,158,11,0.14); color: #F59E0B; border-color: #F59E0B; }

/* Campos condicionais de rendimento */
.cxh-rend-campos { display: none; }
.cxh-rend-campos.visivel { display: flex; flex-direction: column; gap: 10px; }

/* Linha resumo taxa efetiva */
.cxh-taxa-resumo {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    background: var(--cor-tinte-suave);
    border-radius: 7px;
    padding: 7px 11px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-taxa-resumo strong { color: var(--cor-titulo); }

/* ── Seleção de Instituições ─────────────────────────────── */
.cxh-inst-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    max-height: 160px;
    overflow-y: auto;
    padding: 4px 2px;
}
.cxh-inst-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 7px 12px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    transition: all 0.15s;
    user-select: none;
}
.cxh-inst-item:hover { background: var(--cor-tinte-suave); }
.cxh-inst-item.selecionada {
    background: var(--cor-tinte-medio);
    border-color: var(--cor-principal);
    color: var(--cor-titulo);
}
.cxh-inst-item input[type="checkbox"] { display: none; }
.cxh-inst-check {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 0.65rem;
    color: transparent;
}
.cxh-inst-item.selecionada .cxh-inst-check {
    background: var(--cor-principal);
    border-color: var(--cor-principal);
    color: #fff;
}

/* ── Botões do modal ─────────────────────────────────────── */
.btn-cxh-salvar {
    padding: 10px 22px;
    border-radius: 10px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    transition: opacity 0.18s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-salvar:hover:not(:disabled) { opacity: 0.85; }
.btn-cxh-salvar:disabled { opacity: 0.45; cursor: not-allowed; }

.btn-cxh-cancelar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-texto-secundario);
    border: 1.5px solid var(--cor-tinte-borda);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-cancelar:hover { background: var(--cor-tinte-suave); }

.btn-cxh-encerrar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: #F59E0B;
    border: 1.5px solid #F59E0B;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-encerrar:hover { background: rgba(245,158,11,0.1); }

.btn-cxh-deletar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--red-700);
    border: 1.5px solid var(--red-700);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-deletar:hover { background: var(--red-100); }

.btn-cxh-editar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-acao-editar);
    border: 1.5px solid var(--cor-acao-editar);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-editar:hover { background: var(--cor-acao-editar-suave); }

/* ═══════════════════════════════════════════════════════════════
   MODAL DE DETALHES
   ═══════════════════════════════════════════════════════════════ */
.cxh-det-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.cxh-det-stat {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.cxh-det-stat-label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--cor-texto-secundario);
}
.cxh-det-stat-val {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-det-stat-val.positivo { color: var(--green-700); }
.cxh-det-stat-val.negativo { color: var(--red-700); }

.cxh-det-projecao {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 14px;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    line-height: 1.65;
    border: 1px solid var(--cor-tinte-borda);
}
.cxh-det-projecao strong { color: var(--cor-titulo); }

.cxh-det-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 20px;
    font-size: 0.82rem;
    font-weight: 700;
    background: var(--green-100);
    color: var(--green-700);
}
.cxh-det-alcancavel.nao {
    background: var(--red-100);
    color: var(--red-700);
}

/* Instituições no detalhe */
.cxh-det-inst-lista {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.cxh-det-inst-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 12px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    font-size: 0.82rem;
}
.cxh-det-inst-nome { font-weight: 600; color: var(--cor-titulo); }
.cxh-det-inst-val { color: var(--cor-texto-secundario); }

/* ── Feedback / Toast ─────────────────────────────────────── */
.cxh-toast {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 18px;
    border-radius: 12px;
    font-size: 0.88rem;
    font-weight: 600;
    background: var(--cor-fundo-card);
    box-shadow: 0 6px 24px var(--sombra-caixa);
    border: 1px solid var(--cor-tinte-borda);
    animation: cxhToastIn 0.22s ease;
    max-width: 340px;
}
.cxh-toast.sucesso { border-color: var(--green-700); color: var(--green-700); }
.cxh-toast.erro    { border-color: var(--red-700);   color: var(--red-700);   }

@keyframes cxhToastIn {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Responsivo ──────────────────────────────────────────── */
@media (max-width: 600px) {
    .cxh-campo-row { grid-template-columns: 1fr; }
    .cxh-det-grid  { grid-template-columns: 1fr; }
    .cxh-modal-footer { flex-direction: column; }
    .cxh-modal-footer button { width: 100%; justify-content: center; }
    .cxh-rendimento-btns { gap: 5px; }
    .cxh-rend-btn { font-size: 0.72rem; padding: 6px 10px; }
}

/* ═══════════════════════════════════════════════════════════════
   caixinhas.css — Tela de Poupança / Caixinhas
   ═══════════════════════════════════════════════════════════════ */

/* ── Page header ─────────────────────────────────────────── */
.cxh-page-header {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
    flex-wrap: wrap;
    gap: 12px;
}
.cxh-page-header h1 { margin-bottom: 0; }

.cxh-header-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cxh-header-subtitle {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    font-weight: 400;
}

.btn-nova-caixinha {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.18s, transform 0.15s;
    text-decoration: none;
}
.btn-nova-caixinha:hover { opacity: 0.88; transform: translateY(-1px); }

/* ── KPI grid ────────────────────────────────────────────── */
.cxh-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}

.cxh-kpi-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid var(--cor-tinte-borda);
    transition: transform 0.18s, box-shadow 0.18s;
}
.cxh-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--sombra-card); }

.cxh-kpi-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cxh-kpi-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.cxh-kpi-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--cor-principal);
}
.cxh-kpi-valor {
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.1;
}
.cxh-kpi-sub {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
}

/* ── Barra de progresso consolidada ─────────────────────── */
.cxh-progresso-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 16px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1px solid var(--cor-tinte-borda);
    margin-bottom: 20px;
}
.cxh-progresso-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}
.cxh-progresso-label {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-progresso-pct {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-progress-track {
    height: 10px;
    background: var(--cor-tinte-suave);
    border-radius: 6px;
    overflow: hidden;
}
.cxh-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    border-radius: 6px;
    transition: width 0.5s ease;
}

/* ── Filtros / Abas ─────────────────────────────────────── */
.cxh-filtros {
    display: flex;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.cxh-filtro-btn {
    padding: 8px 18px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-secundario);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s;
}
.cxh-filtro-btn:hover {
    background: var(--cor-tinte-suave);
    color: var(--cor-titulo);
}
.cxh-filtro-btn.ativo {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border-color: var(--cor-principal);
}

/* ── Grid de cards ──────────────────────────────────────── */
.cxh-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

/* ── Card individual de caixinha ────────────────────────── */
.cxh-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1.5px solid var(--cor-tinte-borda);
    cursor: pointer;
    transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative;
    overflow: hidden;
}
.cxh-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px var(--sombra-card);
    border-color: var(--cor-principal);
}
.cxh-card.encerrada {
    opacity: 0.72;
}
.cxh-card.encerrada::after {
    content: "ENCERRADA";
    position: absolute;
    top: 12px;
    right: -22px;
    background: var(--cor-texto-secundario);
    color: #fff;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    padding: 3px 30px;
    transform: rotate(45deg);
}

.cxh-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}
.cxh-card-nome {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.3;
}
.cxh-card-desc {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
    margin-top: 2px;
}

/* Badge de tipo de rendimento */
.cxh-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 12px;
    white-space: nowrap;
    letter-spacing: 0.04em;
}
.cxh-badge-CDI       { background: rgba(54,115,115,0.12);  color: var(--cor-principal); }
.cxh-badge-SELIC     { background: rgba(59,130,246,0.12);  color: #3B82F6; }
.cxh-badge-POUPANCA  { background: rgba(16,185,129,0.12);  color: #10B981; }
.cxh-badge-PREFIXADO { background: rgba(139,92,246,0.12);  color: #8B5CF6; }
.cxh-badge-PERSONALIZADO { background: rgba(245,158,11,0.12); color: #F59E0B; }

/* Valores */
.cxh-card-valores {
    display: flex;
    align-items: baseline;
    gap: 6px;
}
.cxh-card-valor-atual {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-card-meta {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
}

/* Barra de progresso do card */
.cxh-card-progress-track {
    height: 7px;
    background: var(--cor-tinte-suave);
    border-radius: 4px;
    overflow: hidden;
}
.cxh-card-progress-fill {
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    transition: width 0.5s ease;
}
.cxh-card-progress-fill.atingida {
    background: linear-gradient(90deg, var(--green-700), #22c55e);
}

.cxh-card-progress-info {
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-pct { font-weight: 700; color: var(--cor-titulo); }

/* Footer do card */
.cxh-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 8px;
    border-top: 1px solid var(--cor-tinte-suave);
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-meta-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--green-700);
}
.cxh-card-meta-alcancavel.nao { color: var(--red-700); }

/* ── Estado vazio ────────────────────────────────────────── */
.cxh-vazio {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 60px 20px;
    color: var(--cor-texto-secundario);
    text-align: center;
}
.cxh-vazio i { font-size: 3rem; opacity: 0.4; }
.cxh-vazio h3 { font-size: 1.1rem; color: var(--cor-titulo); }
.cxh-vazio p { font-size: 0.88rem; }

/* Loading */
.cxh-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 40px;
    color: var(--cor-texto-secundario);
    font-size: 0.95rem;
}

/* ── Insight card ─────────────────────────────────────────── */
.cxh-insight {
    background: var(--cor-tinte-suave);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 12px;
    padding: 14px 18px;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 24px;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.55;
}
.cxh-insight i {
    font-size: 1.3rem;
    color: var(--cor-principal);
    flex-shrink: 0;
    margin-top: 1px;
}

/* ═══════════════════════════════════════════════════════════════
   MODAL BASE
   ═══════════════════════════════════════════════════════════════ */
.cxh-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 9000;
    background: var(--cor-overlay);
    backdrop-filter: blur(3px);
    align-items: center;
    justify-content: center;
    padding: 16px;
}
.cxh-modal-overlay.aberto { display: flex; }

.cxh-modal {
    background: var(--cor-fundo-card);
    border-radius: 20px;
    box-shadow: 0 20px 60px var(--sombra-caixa);
    width: 100%;
    max-width: 580px;
    max-height: 90vh;
    overflow-y: auto;
    animation: cxhModalIn 0.22s ease;
    display: flex;
    flex-direction: column;
}
.cxh-modal-lg { max-width: 720px; }

@keyframes cxhModalIn {
    from { opacity: 0; transform: scale(0.93) translateY(14px); }
    to   { opacity: 1; transform: scale(1)    translateY(0); }
}

.cxh-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px 24px 16px;
    border-bottom: 1px solid var(--cor-tinte-borda);
    flex-shrink: 0;
}
.cxh-modal-header h2 {
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}
.cxh-modal-close {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: none;
    background: var(--cor-tinte-suave);
    color: var(--cor-texto-secundario);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: background 0.15s;
    padding: 0;
    margin: 0;
}
.cxh-modal-close:hover { background: var(--cor-tinte-medio); }

.cxh-modal-body {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    flex: 1;
}

.cxh-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid var(--cor-tinte-borda);
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* ── Seções do modal de criação ──────────────────────────── */
.cxh-secao-titulo {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--cor-principal);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-secao-titulo::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--cor-tinte-borda);
}

/* ── Campos de formulário ─────────────────────────────────── */
.cxh-campo-wrap {
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.cxh-campo-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-campo-input {
    padding: 10px 12px;
    border-radius: 9px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-campo);
    color: var(--cor-texto-principal);
    font-size: 0.9rem;
    width: 100%;
    transition: border-color 0.15s;
    outline: none;
}
.cxh-campo-input:focus {
    border-color: var(--cor-principal);
    background: var(--cor-fundo-card);
}
.cxh-campo-input::placeholder { color: var(--cor-texto-secundario); opacity: 0.6; }

.cxh-campo-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

/* ── Tipo de rendimento – botões inline ──────────────────── */
.cxh-rendimento-btns {
    display: flex;
    gap: 7px;
    flex-wrap: wrap;
    margin-bottom: 14px;
}
.cxh-rend-btn {
    padding: 7px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    color: var(--cor-texto-secundario);
    margin: 0;
}
.cxh-rend-btn:hover { background: var(--cor-tinte-suave); }
.cxh-rend-btn.ativo-CDI       { background: rgba(54,115,115,0.14);  color: var(--cor-principal); border-color: var(--cor-principal); }
.cxh-rend-btn.ativo-SELIC     { background: rgba(59,130,246,0.14);  color: #3B82F6;  border-color: #3B82F6; }
.cxh-rend-btn.ativo-POUPANCA  { background: rgba(16,185,129,0.14);  color: #10B981;  border-color: #10B981; }
.cxh-rend-btn.ativo-PREFIXADO { background: rgba(139,92,246,0.14);  color: #8B5CF6;  border-color: #8B5CF6; }
.cxh-rend-btn.ativo-PERSONALIZADO { background: rgba(245,158,11,0.14); color: #F59E0B; border-color: #F59E0B; }

/* Campos condicionais de rendimento */
.cxh-rend-campos { display: none; }
.cxh-rend-campos.visivel { display: flex; flex-direction: column; gap: 10px; }

/* Linha resumo taxa efetiva */
.cxh-taxa-resumo {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    background: var(--cor-tinte-suave);
    border-radius: 7px;
    padding: 7px 11px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-taxa-resumo strong { color: var(--cor-titulo); }

/* ── Seleção de Instituições ─────────────────────────────── */
.cxh-inst-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    max-height: 160px;
    overflow-y: auto;
    padding: 4px 2px;
}
.cxh-inst-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 7px 12px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    transition: all 0.15s;
    user-select: none;
}
.cxh-inst-item:hover { background: var(--cor-tinte-suave); }
.cxh-inst-item.selecionada {
    background: var(--cor-tinte-medio);
    border-color: var(--cor-principal);
    color: var(--cor-titulo);
}
.cxh-inst-item input[type="checkbox"] { display: none; }
.cxh-inst-check {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 0.65rem;
    color: transparent;
}
.cxh-inst-item.selecionada .cxh-inst-check {
    background: var(--cor-principal);
    border-color: var(--cor-principal);
    color: #fff;
}

/* ── Botões do modal ─────────────────────────────────────── */
.btn-cxh-salvar {
    padding: 10px 22px;
    border-radius: 10px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    transition: opacity 0.18s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-salvar:hover:not(:disabled) { opacity: 0.85; }
.btn-cxh-salvar:disabled { opacity: 0.45; cursor: not-allowed; }

.btn-cxh-cancelar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-texto-secundario);
    border: 1.5px solid var(--cor-tinte-borda);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-cancelar:hover { background: var(--cor-tinte-suave); }

.btn-cxh-encerrar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: #F59E0B;
    border: 1.5px solid #F59E0B;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-encerrar:hover { background: rgba(245,158,11,0.1); }

.btn-cxh-deletar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--red-700);
    border: 1.5px solid var(--red-700);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-deletar:hover { background: var(--red-100); }

.btn-cxh-editar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-acao-editar);
    border: 1.5px solid var(--cor-acao-editar);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-editar:hover { background: var(--cor-acao-editar-suave); }

.btn-cxh-reabrir {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 9px 18px; border: 1.5px solid #059669; border-radius: 8px;
    background: transparent; color: #059669;
    font-size: 0.88rem; font-weight: 600; cursor: pointer; transition: background 0.15s;
}
.btn-cxh-reabrir:hover { background: rgba(5,150,105,0.08); }

.btn-cxh-reabrir-confirmar {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 9px 18px; border: none; border-radius: 8px;
    background: #059669; color: #fff;
    font-size: 0.88rem; font-weight: 600; cursor: pointer; transition: opacity 0.15s;
}
.btn-cxh-reabrir-confirmar:hover { opacity: 0.85; }

/* Footer de confirmação inline */
.cxh-footer-confirmacao {
    background: var(--cor-tinte-suave);
    border-top: 1px solid var(--cor-tinte-borda);
    border-radius: 0 0 16px 16px;
    animation: fadeIn 0.15s ease;
    gap: 10px;
    align-items: center;
}

.btn-cxh-encerrar-confirmar,
.btn-cxh-deletar-confirmar {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 18px;
    border: none;
    border-radius: 8px;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn-cxh-encerrar-confirmar {
    background: #f59e0b;
    color: #fff;
}
.btn-cxh-encerrar-confirmar:hover { opacity: 0.85; }

.btn-cxh-deletar-confirmar {
    background: var(--red-600, #dc2626);
    color: #fff;
}
.btn-cxh-deletar-confirmar:hover { opacity: 0.85; }


   MODAL DE DETALHES
   ═══════════════════════════════════════════════════════════════ */
.cxh-det-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.cxh-det-stat {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.cxh-det-stat-label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--cor-texto-secundario);
}
.cxh-det-stat-val {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-det-stat-val.positivo { color: var(--green-700); }
.cxh-det-stat-val.negativo { color: var(--red-700); }

.cxh-det-projecao {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 14px;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    line-height: 1.65;
    border: 1px solid var(--cor-tinte-borda);
}
.cxh-det-projecao strong { color: var(--cor-titulo); }

.cxh-det-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 20px;
    font-size: 0.82rem;
    font-weight: 700;
    background: var(--green-100);
    color: var(--green-700);
}
.cxh-det-alcancavel.nao {
    background: var(--red-100);
    color: var(--red-700);
}

/* Instituições no detalhe */
.cxh-det-inst-lista {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.cxh-det-inst-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 12px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    font-size: 0.82rem;
}
.cxh-det-inst-nome { font-weight: 600; color: var(--cor-titulo); }
.cxh-det-inst-val { color: var(--cor-texto-secundario); }

/* ── Feedback / Toast ─────────────────────────────────────── */
.cxh-toast {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 18px;
    border-radius: 12px;
    font-size: 0.88rem;
    font-weight: 600;
    background: var(--cor-fundo-card);
    box-shadow: 0 6px 24px var(--sombra-caixa);
    border: 1px solid var(--cor-tinte-borda);
    animation: cxhToastIn 0.22s ease;
    max-width: 340px;
}
.cxh-toast.sucesso { border-color: var(--green-700); color: var(--green-700); }
.cxh-toast.erro    { border-color: var(--red-700);   color: var(--red-700);   }

@keyframes cxhToastIn {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Responsivo ──────────────────────────────────────────── */
@media (max-width: 600px) {
    .cxh-campo-row { grid-template-columns: 1fr; }
    .cxh-det-grid  { grid-template-columns: 1fr; }
    .cxh-modal-footer { flex-direction: column; }
    .cxh-modal-footer button { width: 100%; justify-content: center; }
    .cxh-rendimento-btns { gap: 5px; }
    .cxh-rend-btn { font-size: 0.72rem; padding: 6px 10px; }
}

/* ============================================================================
   EMPRÉSTIMOS - Estilos
   ============================================================================ */

.emprestimos-resumo-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.emprestimo-resumo-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    display: flex;
    align-items: center;
    gap: 1.25rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.emprestimo-resumo-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-resumo-card.receber .resumo-icon {
    background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}

.emprestimo-resumo-card.pagar .resumo-icon {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
}

.resumo-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 1.8rem;
    flex-shrink: 0;
}

.resumo-info {
    flex: 1;
}

.resumo-label {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    margin: 0 0 0.25rem 0;
    font-weight: 500;
}

.resumo-valor {
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.resumo-detalhes {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    margin: 0;
}

/* ── Ações e Filtros ── */
.emprestimos-acoes {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

.filtros-emprestimo {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-filtro {
    padding: 0.5rem 1rem;
    border: 2px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-principal);
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-filtro:hover {
    background: var(--cor-hover);
    border-color: var(--cor-principal);
}

.btn-filtro.ativo {
    background: var(--cor-principal);
    color: #fff;
    border-color: var(--cor-principal);
}

/* ── Lista de Empréstimos ── */
.emprestimos-lista {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.emprestimo-item {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    border-left: 4px solid;
}

.emprestimo-item.emprestei {
    border-left-color: #10b981;
}

.emprestimo-item.pedi-emprestado {
    border-left-color: #ef4444;
}

.emprestimo-item.quitado {
    opacity: 0.7;
    border-left-color: #6b7280;
}

.emprestimo-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1rem;
}

.emprestimo-info {
    flex: 1;
}

.emprestimo-tipo {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.emprestimo-tipo.emprestei {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-tipo.pedi-emprestado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-pessoa {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.emprestimo-data {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.emprestimo-status {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.9rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
}

.emprestimo-status.pendente {
    background: #fef3c7;
    color: #92400e;
}

.emprestimo-status.pago-parcial {
    background: #dbeafe;
    color: #1e40af;
}

.emprestimo-status.quitado {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-status.atrasado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-valores {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 1rem;
    margin-bottom: 1rem;
}

.emprestimo-valor-item {
    display: flex;
    flex-direction: column;
}

.emprestimo-valor-label {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.emprestimo-valor-numero {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}

.emprestimo-progresso {
    margin-bottom: 1rem;
}

.progresso-bar-container {
    width: 100%;
    height: 8px;
    background: var(--cor-fundo-pagina);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.progresso-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal) 0%, var(--cor-hover) 100%);
    border-radius: 4px;
    transition: width 0.3s ease;
}

.progresso-texto {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    text-align: right;
}

.emprestimo-observacoes {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 0.75rem;
    margin-bottom: 1rem;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.5;
}

.emprestimo-acoes-item {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-acao {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: all 0.2s ease;
}

.btn-acao.registrar {
    background: #3b82f6;
    color: #fff;
}

.btn-acao.registrar:hover {
    background: #2563eb;
}

.btn-acao.quitar {
    background: #10b981;
    color: #fff;
}

.btn-acao.quitar:hover {
    background: #059669;
}

.btn-acao.editar {
    background: #f59e0b;
    color: #fff;
}

.btn-acao.editar:hover {
    background: #d97706;
}

.btn-acao.deletar {
    background: #ef4444;
    color: #fff;
}

.btn-acao.deletar:hover {
    background: #dc2626;
}

.btn-acao.reabrir {
    background: #8b5cf6;
    color: #fff;
}

.btn-acao.reabrir:hover {
    background: #7c3aed;
}

/* ── Modais ── */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    z-index: 10000;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(4px);
    animation: fadeIn 0.2s ease;
}

.modal.aberto {
    display: flex;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

.modal-content {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    max-width: 600px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3);
    animation: slideUp 0.3s ease;
}

.modal-content.modal-pequeno {
    max-width: 400px;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(40px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--cor-tinte-borda);
}

.modal-header h2 {
    margin: 0;
    font-size: 1.5rem;
    color: var(--cor-titulo);
}

.btn-fechar {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    color: var(--cor-texto-secundario);
    padding: 0;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.2s ease;
}

.btn-fechar:hover {
    background: var(--cor-hover);
    color: var(--cor-titulo);
}

.modal-body {
    padding: 1.5rem;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.info-pagamento {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    color: var(--cor-texto-secundario);
    line-height: 1.6;
}

/* ── Botões Gerais ── */
.btn-primario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-principal);
    color: #fff;
    border: none;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: all 0.2s ease;
}

.btn-primario:hover {
    opacity: 0.9;
    transform: translateY(-2px);
}

.btn-secundario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-fundo-pagina);
    color: var(--cor-texto-principal);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-secundario:hover {
    background: var(--cor-hover);
}

/* ── Estado Vazio ── */
.estado-vazio {
    text-align: center;
    padding: 4rem 2rem;
    color: var(--cor-texto-secundario);
}

.estado-vazio i {
    font-size: 4rem;
    color: var(--cor-tinte-borda);
    margin-bottom: 1rem;
}

.estado-vazio h3 {
    font-size: 1.25rem;
    color: var(--cor-titulo);
    margin: 0 0 0.5rem 0;
}

.estado-vazio p {
    font-size: 0.95rem;
    margin: 0;
}

/* ── Campos do modal ── */
.campo input,
.campo select {
    width: 100%;
}

.campo textarea {
    width: 100%;
    padding: 10px;
    border-radius: 10px;
    border: solid 1px var(--cor-principal);
    background-color: transparent;
    color: var(--cor-texto-principal);
    resize: vertical;
    font-size: 0.95rem;
    transition: border 0.2s;
}

.campo textarea:focus {
    outline: none;
    border: solid 2px var(--cor-principal);
}

.campo textarea:focus + label,
.campo textarea:not(:placeholder-shown) + label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.campo-label-static {
    display: block;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    margin-bottom: 6px;
    font-weight: 500;
}

/* ── Responsividade ── */
@media (max-width: 768px) {
    .emprestimos-acoes {
        flex-direction: column;
        align-items: stretch;
    }

    .filtros-emprestimo {
        justify-content: center;
    }

    .emprestimo-header {
        flex-direction: column;
        gap: 0.75rem;
    }

    .emprestimo-valores {
        grid-template-columns: 1fr;
    }

    .emprestimo-acoes-item {
        flex-direction: column;
    }

    .btn-acao {
        width: 100%;
        justify-content: center;
    }
}

/* ============================================================================
   EMPRÉSTIMOS - Estilos
   ============================================================================ */

/* ── Tabs (reusa .ar-tabs / .ar-tab do registro.css, mas definido aqui como fallback) ── */
.ar-tabs {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
    border-bottom: 2px solid var(--cor-tinte-borda, #e5e7eb);
    padding-bottom: 0;
}
.ar-tab {
    background: transparent;
    border: none;
    padding: 0.75rem 1.25rem;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    cursor: pointer;
    border-bottom: 3px solid transparent;
    margin-bottom: -2px;
    border-radius: 8px 8px 0 0;
    transition: color 0.2s, border-color 0.2s;
}
.ar-tab:hover { color: var(--cor-principal); }
.ar-tab.ativo { color: var(--cor-principal); border-bottom-color: var(--cor-principal); }

